--
-- TOC entry 848 (class 1255 OID 23683)
-- Name: fn_auditar_linha(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_auditar_linha() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE
  c_uuid     CONSTANT text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_ignorar  text[] := ARRAY['updated_at', 'updated_by'];
  v_mascarar text[] := ARRAY[]::text[];
  v_i        int;
  v_reg      jsonb;
  v_old      jsonb;
  v_new      jsonb;
  v_antes    jsonb;
  v_depois   jsonb;
  v_campos   text[] := ARRAY[]::text[];
  v_k        text;
  v_acao     text;
  v_pk       text[];
  v_id       text;
  v_txt      text;
  v_usuario  uuid;
BEGIN
  -- Argumentos: "coluna" = ignorar; "!coluna" = mascarar.
  FOR v_i IN 0 .. TG_NARGS - 1 LOOP
    IF left(TG_ARGV[v_i], 1) = '!' THEN
      v_mascarar := v_mascarar || substr(TG_ARGV[v_i], 2);
    ELSE
      v_ignorar := v_ignorar || TG_ARGV[v_i];
    END IF;
  END LOOP;
  IF TG_OP = 'INSERT' THEN
    v_reg    := to_jsonb(NEW);
    v_acao   := 'criar';
    v_depois := v_reg - v_ignorar;
  ELSIF TG_OP = 'DELETE' THEN
    v_reg    := to_jsonb(OLD);
    v_acao   := 'excluir';
    v_antes  := v_reg - v_ignorar;
  ELSE
    v_reg    := to_jsonb(NEW);
    v_old    := to_jsonb(OLD) - v_ignorar;
    v_new    := v_reg - v_ignorar;
    v_antes  := '{}'::jsonb;
    v_depois := '{}'::jsonb;
    FOR v_k IN SELECT jsonb_object_keys(v_new) LOOP
      IF (v_new -> v_k) IS DISTINCT FROM (v_old -> v_k) THEN
        v_campos := v_campos || v_k;
        v_antes  := v_antes  || jsonb_build_object(v_k, v_old -> v_k);
        v_depois := v_depois || jsonb_build_object(v_k, v_new -> v_k);
      END IF;
    END LOOP;
    IF cardinality(v_campos) = 0 THEN
      RETURN NULL;  -- nada (fora as colunas ignoradas) mudou: não grava
    END IF;
    v_acao := CASE
                WHEN v_old ? 'deleted_at'
                 AND jsonb_typeof(v_old -> 'deleted_at') = 'null'
                 AND jsonb_typeof(v_new -> 'deleted_at') <> 'null' THEN 'excluir'  -- exclusão lógica
                ELSE 'editar'
              END;
  END IF;
  FOREACH v_k IN ARRAY v_mascarar LOOP
    IF v_antes ? v_k AND jsonb_typeof(v_antes -> v_k) <> 'null' THEN
      v_antes := jsonb_set(v_antes, ARRAY[v_k], '"***"'::jsonb);
    END IF;
    IF v_depois ? v_k AND jsonb_typeof(v_depois -> v_k) <> 'null' THEN
      v_depois := jsonb_set(v_depois, ARRAY[v_k], '"***"'::jsonb);
    END IF;
  END LOOP;
  -- Chave primária da linha (lida do catálogo: serve para qualquer tabela).
  SELECT array_agg(a.attname::text ORDER BY k.ord) INTO v_pk
    FROM pg_index i
    CROSS JOIN LATERAL unnest(i.indkey::int2[]) WITH ORDINALITY AS k(attnum, ord)
    JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum
   WHERE i.indrelid = TG_RELID AND i.indisprimary;
  IF cardinality(v_pk) = 1 THEN
    v_id := v_reg ->> v_pk[1];
  ELSIF cardinality(v_pk) > 1 THEN
    SELECT jsonb_object_agg(c, v_reg -> c)::text INTO v_id FROM unnest(v_pk) AS c;
  END IF;
  -- Autor: GUC da transação (SET LOCAL avhub.usuario_id = '<uuid>'), senão a linha.
  v_txt := nullif(current_setting('avhub.usuario_id', true), '');
  IF v_txt IS NULL OR v_txt !~* c_uuid THEN
    v_txt := CASE
               WHEN TG_OP = 'INSERT'   THEN v_reg ->> 'created_by'
               WHEN TG_OP = 'DELETE'   THEN v_reg ->> 'deleted_by'
               WHEN v_acao = 'excluir' THEN COALESCE(v_reg ->> 'deleted_by', v_reg ->> 'updated_by')
               ELSE v_reg ->> 'updated_by'
             END;
  END IF;
  IF v_txt ~* c_uuid THEN
    v_usuario := v_txt::uuid;
  END IF;
  INSERT INTO auth.auditoria (usuario_id, identidade_origem, acao, entidade, entidade_id,
                              campos, antes, depois, chave_servico)
  VALUES (v_usuario, 'banco', v_acao, left(TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME, 100),
          left(v_id, 200),
          CASE WHEN cardinality(v_campos) > 0 THEN to_jsonb(v_campos) END,
          v_antes, v_depois, left(current_user::text, 100));
  RETURN NULL;
END $_$;


--
-- TOC entry 7112 (class 0 OID 0)
-- Dependencies: 848
-- Name: FUNCTION fn_auditar_linha(); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.fn_auditar_linha() IS 'Contrato 51 (S17): trigger AFTER INSERT/UPDATE/DELETE FOR EACH ROW genérica. Grava em auth.auditoria (identidade_origem = banco): acao criar/editar/excluir (UPDATE que preenche deleted_at = excluir), entidade schema.tabela, entidade_id = PK (composta = objeto JSON), antes/depois (UPDATE: só o que mudou; sem mudança não grava), campos = colunas alteradas, usuario_id = GUC avhub.usuario_id ou created_by/updated_by/deleted_by, chave_servico = current_user. Argumentos: "col" ignora a coluna, "!col" grava "***". updated_at e updated_by sempre ignorados. SECURITY INVOKER: quem escreve na tabela precisa de INSERT em auth.auditoria (o avhub_api tem).';


