-- TOC entry 869 (class 1255 OID 20493)
-- Name: fn_auditoria_imutavel(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_auditoria_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND current_setting('avhub.auditoria_expurgo', true) = 'on' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'auth.auditoria é somente inserção (% barrado)', TG_OP
    USING ERRCODE = '23514';
END $$;


