--
-- TOC entry 863 (class 1255 OID 20514)
-- Name: fn_autorizar(uuid, integer, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_autorizar(p_usuario uuid, p_versao integer, p_metodo text, p_caminho text) RETURNS TABLE(status integer, motivo text, rota text, escopo_vendedores text, telas text[])
    LANGUAGE plpgsql STABLE
    AS $$
#variable_conflict use_column
DECLARE
  v_metodo  text := upper(COALESCE(p_metodo, 'GET'));
  v_ativo   boolean;
  v_deleted timestamptz;
  v_versao  integer;
  v_melhor  integer;
  v_rota    text;
  v_telas   text[];
  v_livre   boolean;
  v_todos   boolean;
BEGIN
  IF v_metodo = 'HEAD' THEN v_metodo := 'GET'; END IF;

  SELECT u.ativo, u.deleted_at, u.token_versao INTO v_ativo, v_deleted, v_versao
    FROM auth.usuarios u WHERE u.id = p_usuario;
  IF NOT FOUND OR NOT v_ativo OR v_deleted IS NOT NULL THEN
    RETURN QUERY SELECT 401, 'usuario_invalido'::text, NULL::text, NULL::text, NULL::text[];
    RETURN;
  END IF;
  IF p_versao IS DISTINCT FROM v_versao THEN
    RETURN QUERY SELECT 401, 'token_revogado'::text, NULL::text, NULL::text, NULL::text[];
    RETURN;
  END IF;

  WITH cand AS (
    SELECT r.rota, r.slug_tela,
           COALESCE(r.acao, CASE v_metodo WHEN 'GET' THEN 'pode_visualizar' WHEN 'POST' THEN 'pode_criar'
                                          WHEN 'DELETE' THEN 'pode_deletar' ELSE 'pode_editar' END) AS acao,
           r.escopo_vendedor,
           auth.fn_rota_casa(r.rota, p_caminho, p_usuario, v_metodo) AS pontos
      FROM auth.rotas_telas r
     WHERE r.ativo AND r.metodo IN (v_metodo, '*')
  ),
  melhor AS (
    SELECT * FROM cand WHERE pontos IS NOT NULL AND pontos = (SELECT max(pontos) FROM cand)
  ),
  concedidas AS (
    SELECT m.* FROM melhor m
     WHERE m.slug_tela IS NULL
        OR EXISTS (
             SELECT 1
               FROM auth.usuarios_perfis up
               JOIN auth.perfis p      ON p.id = up.id_perfil AND p.deleted_at IS NULL
               JOIN auth.permissoes pm ON pm.id_perfil = p.id AND pm.deleted_at IS NULL
               -- 04/11/2026: sem "AND t.ativo". Tela inativa só some do menu
               -- (vw_permissoes_usuario); a permissão continua valendo na API.
               JOIN auth.telas t       ON t.id = pm.id_tela AND t.deleted_at IS NULL
              WHERE up.id_usuario = p_usuario
                AND t.slug = m.slug_tela
                AND CASE m.acao
                      WHEN 'pode_visualizar' THEN pm.pode_visualizar
                      WHEN 'pode_criar'      THEN pm.pode_criar
                      WHEN 'pode_editar'     THEN pm.pode_editar
                      WHEN 'pode_deletar'    THEN pm.pode_deletar
                      WHEN 'pode_aprovar'    THEN pm.pode_aprovar
                      WHEN 'pode_exportar'   THEN pm.pode_exportar
                      ELSE false
                    END)
  )
  SELECT (SELECT max(pontos) FROM melhor),
         (SELECT min(m.rota) FROM melhor m),
         (SELECT array_agg(DISTINCT m.slug_tela || ':' || m.acao) FROM melhor m WHERE m.slug_tela IS NOT NULL),
         (SELECT count(*) > 0 FROM concedidas),
         (SELECT bool_or(NOT c.escopo_vendedor) FROM concedidas c)
    INTO v_melhor, v_rota, v_telas, v_livre, v_todos;

  IF v_melhor IS NULL THEN
    RETURN QUERY SELECT 403, 'rota_sem_mapa'::text, NULL::text, NULL::text, NULL::text[];
    RETURN;
  END IF;
  IF NOT v_livre THEN
    RETURN QUERY SELECT 403, 'sem_permissao'::text, v_rota, NULL::text, v_telas;
    RETURN;
  END IF;

  RETURN QUERY SELECT 200, 'ok'::text, v_rota,
    CASE WHEN v_todos THEN 'todos' ELSE auth.fn_escopo_vendedores_usuario(p_usuario) END,
    v_telas;
END $$;


--
-- TOC entry 7114 (class 0 OID 0)
-- Dependencies: 863
-- Name: FUNCTION fn_autorizar(p_usuario uuid, p_versao integer, p_metodo text, p_caminho text); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.fn_autorizar(p_usuario uuid, p_versao integer, p_metodo text, p_caminho text) IS 'Decide, a cada requisição com token de usuário, se p_usuario pode p_metodo em p_caminho (contrato 06, S1). 401 usuario_invalido (inexistente/inativo/excluído) ou token_revogado (versão diferente de usuarios.token_versao); 403 rota_sem_mapa (fail-closed) ou sem_permissao (telas = as telas:ações que liberariam); 200 com escopo_vendedores: "todos" se alguma tela concedida não tem escopo de vendedor, senão o escopo dos perfis. Lê a matriz ao vivo: remover a permissão bloqueia a próxima requisição. Desde 04/11/2026, tela INATIVA (telas.ativo = false) continua valendo aqui: inativa só some do menu; para bloquear, tire a permissão do perfil ou desligue a rota (rotas_telas.ativo).';


--
-- TOC entry 779 (class 1255 OID 22621)
-- Name: fn_caminho_normalizado(text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_caminho_normalizado(p_caminho text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT left('/' || COALESCE(string_agg(
           CASE
             WHEN s ~ '^[0-9]+$' THEN '*'
             WHEN s ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN '*'
             WHEN length(s) >= 20 THEN '*'
             ELSE s
           END, '/' ORDER BY n), ''), 200)
    FROM unnest(string_to_array(btrim(lower(split_part(COALESCE(p_caminho, ''), '?', 1)), '/'), '/'))
         WITH ORDINALITY AS t(s, n)
   WHERE s <> '';
$_$;


