-- TOC entry 7115 (class 0 OID 0)
-- Dependencies: 779
-- Name: FUNCTION fn_caminho_normalizado(p_caminho text); Type: COMMENT; Schema: auth; Owner: -
--

COMMENT ON FUNCTION auth.fn_caminho_normalizado(p_caminho text) IS 'Contrato 51: caminho para auth.chaves_servico_uso — minúsculo, sem query, e segmento numérico, uuid ou com 20+ caracteres vira "*" (/pedidos_liberados/27240/importado -> /pedidos_liberados/*/importado). Até 200 caracteres.';


--
-- TOC entry 998 (class 1255 OID 22623)
-- Name: fn_chave_rota_decidir(uuid, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_chave_rota_decidir(p_id_chave uuid, p_metodo text, p_caminho text) RETURNS TABLE(modo text, permitida boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_modo    text;
  v_ok      boolean;
  v_metodo  text := left(upper(COALESCE(p_metodo, 'GET')), 7);
  v_caminho text := auth.fn_caminho_normalizado(p_caminho);
BEGIN
  SELECT c.modo_rotas INTO v_modo FROM auth.chaves_servico c WHERE c.id = p_id_chave;
  IF v_modo IS NULL OR v_modo = 'livre' THEN
    -- Chave sem lista (ou que sumiu entre a validação e aqui): como antes.
    RETURN QUERY SELECT COALESCE(v_modo, 'livre'), true;
    RETURN;
  END IF;

  v_ok := auth.fn_chave_rota_permitida(p_id_chave, p_metodo, p_caminho);

  UPDATE auth.chaves_servico_uso u
     SET quantidade = u.quantidade + 1, ultima_em = now(), permitida = v_ok
   WHERE u.id_chave = p_id_chave AND u.metodo = v_metodo AND u.caminho = v_caminho;
  IF NOT FOUND
     AND (SELECT count(*) FROM auth.chaves_servico_uso u WHERE u.id_chave = p_id_chave) < 1000 THEN
    INSERT INTO auth.chaves_servico_uso (id_chave, metodo, caminho, permitida)
    VALUES (p_id_chave, v_metodo, v_caminho, v_ok)
    ON CONFLICT (id_chave, metodo, caminho) DO UPDATE
      SET quantidade = auth.chaves_servico_uso.quantidade + 1,
          ultima_em  = now(),
          permitida  = EXCLUDED.permitida;
  END IF;

  RETURN QUERY SELECT v_modo, v_ok;
END $$;


