--

CREATE FUNCTION auth.fn_chave_rota_permitida(p_id_chave uuid, p_metodo text, p_caminho text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM auth.chaves_servico_rotas r
      CROSS JOIN LATERAL (
        SELECT CASE WHEN upper(COALESCE(p_metodo, 'GET')) IN ('HEAD', 'OPTIONS') THEN 'GET'
                    ELSE upper(COALESCE(p_metodo, 'GET')) END AS m) x
     WHERE r.id_chave = p_id_chave
       AND (r.metodo = '*' OR r.metodo = x.m)
       AND auth.fn_rota_casa(r.rota, p_caminho, NULL, x.m) IS NOT NULL);
$$;


