CREATE FUNCTION auth.fn_criar_chave_servico(p_nome text, p_acesso text, p_exige_usuario boolean DEFAULT true, p_expira_em timestamp with time zone DEFAULT NULL::timestamp with time zone, p_criado_por uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_chave text := 'avk_' || encode(public.gen_random_bytes(24), 'hex');
BEGIN
  INSERT INTO auth.chaves_servico (nome, prefixo, hash_sha256, acesso, exige_usuario, expira_em, created_by)
  VALUES (p_nome, left(v_chave, 12), encode(sha256(convert_to(v_chave, 'UTF8')), 'hex'),
          p_acesso, COALESCE(p_exige_usuario, true), p_expira_em, p_criado_por);
  RETURN v_chave;
END $$;


