CREATE FUNCTION auth.fn_escopo_vendedores_usuario(p_usuario uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE
           WHEN bool_or(p.escopo_vendedores = 'todos')      THEN 'todos'
           WHEN bool_or(p.escopo_vendedores = 'vinculados') THEN 'vinculados'
           ELSE 'proprios'
         END
    FROM auth.usuarios_perfis up
    JOIN auth.perfis p ON p.id = up.id_perfil AND p.deleted_at IS NULL
   WHERE up.id_usuario = p_usuario;
$$;


