-- TOC entry 935 (class 1255 OID 17285)
-- Name: fn_hash_senha(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_hash_senha() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
  IF NEW.senha IS NULL OR (TG_OP = 'UPDATE' AND OLD.senha IS NOT DISTINCT FROM NEW.senha) THEN
    RETURN NEW;
  END IF;
  -- Hash bcrypt pronto: só do dono da tabela (DBA / migração / carga), nunca da API.
  IF NEW.senha ~ '^\$2[aby]\$[0-9]{2}\$[./A-Za-z0-9]{53}$'
     AND current_user::text <> 'avhub_api'
     AND pg_has_role(current_user, (SELECT c.relowner FROM pg_catalog.pg_class c WHERE c.oid = TG_RELID), 'MEMBER') THEN
    RETURN NEW;
  END IF;
  IF NEW.senha LIKE '$2%' THEN
    RAISE EXCEPTION 'senha não pode estar em formato de hash'
      USING ERRCODE = '23514',
            DETAIL  = 'Mande a senha em claro: o banco faz o hash. Hash pronto só é aceito do dono da tabela (DBA/migração).';
  END IF;
  IF octet_length(NEW.senha) < 8 OR octet_length(NEW.senha) > 72 THEN
    RAISE EXCEPTION 'senha deve ter de 8 a 72 bytes (tem %)', octet_length(NEW.senha)
      USING ERRCODE = '23514',
            DETAIL  = 'Mínimo 8; máximo 72 bytes porque o bcrypt ignora o que passa disso (acentos contam 2 bytes).';
  END IF;
  NEW.senha := public.crypt(NEW.senha, public.gen_salt('bf', 12));
  RETURN NEW;
END $_$;


