--

CREATE FUNCTION auth.fn_login_bloqueado(p_chaves text[], p_max integer, p_janela_segundos integer) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(max(GREATEST(CEIL(EXTRACT(EPOCH FROM
           (t.janela_inicio + make_interval(secs => p_janela_segundos) - now())))::int, 1)), 0)
    FROM auth.login_tentativas t
   WHERE t.chave = ANY (p_chaves)
     AND t.tentativas >= p_max
     AND t.janela_inicio + make_interval(secs => p_janela_segundos) > now();
$$;


