--

COMMENT ON FUNCTION auth.fn_login_bloqueado(p_chaves text[], p_max integer, p_janela_segundos integer) IS 'Segundos até liberar se alguma das chaves já tem p_max (ou mais) falhas na janela atual; 0 = liberado. Com p_max = 5, a 6ª tentativa é recusada. Só lê: quem conta é fn_login_falha. A API (contrato 41) passa max = 5 e janela = 900, fixos no código.';


--
-- TOC entry 856 (class 1255 OID 20507)
-- Name: fn_login_falha(text[], integer); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_login_falha(p_chaves text[], p_janela_segundos integer) RETURNS void
    LANGUAGE sql
    AS $$
  INSERT INTO auth.login_tentativas AS t (chave, janela_inicio, tentativas)
  SELECT DISTINCT c, now(), 1 FROM unnest(p_chaves) c WHERE c IS NOT NULL AND c <> ''
  ON CONFLICT (chave) DO UPDATE
    SET tentativas    = CASE WHEN t.janela_inicio + make_interval(secs => p_janela_segundos) <= now()
                             THEN 1 ELSE t.tentativas + 1 END,
        janela_inicio = CASE WHEN t.janela_inicio + make_interval(secs => p_janela_segundos) <= now()
                             THEN now() ELSE t.janela_inicio END;
$$;


