-- Name: fn_me_permissoes(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_me_permissoes(p_usuario uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  WITH u AS (
    SELECT id, email, username, id_funcionario, setor_irrestrito, token_versao
      FROM auth.usuarios
     WHERE id = p_usuario AND ativo AND deleted_at IS NULL
  ),
  perfis AS (
    SELECT p.id, p.nome, p.escopo_vendedores, p.tela_inicial_id, t.slug AS tela_inicial_slug
      FROM auth.usuarios_perfis up
      JOIN auth.perfis p ON p.id = up.id_perfil AND p.deleted_at IS NULL
      LEFT JOIN auth.telas t ON t.id = p.tela_inicial_id AND t.deleted_at IS NULL AND t.ativo
     WHERE up.id_usuario = p_usuario
  ),
  telas AS (
    SELECT t.id, t.slug, t.nome, t.id_parent, t.ordem,
           bool_or(pm.pode_visualizar) AS pode_visualizar,
           bool_or(pm.pode_criar)      AS pode_criar,
           bool_or(pm.pode_editar)     AS pode_editar,
           bool_or(pm.pode_deletar)    AS pode_deletar,
           bool_or(pm.pode_aprovar)    AS pode_aprovar,
           bool_or(pm.pode_exportar)   AS pode_exportar
      FROM perfis p
      JOIN auth.permissoes pm ON pm.id_perfil = p.id AND pm.deleted_at IS NULL
      JOIN auth.telas t       ON t.id = pm.id_tela AND t.deleted_at IS NULL AND t.ativo
     GROUP BY t.id, t.slug, t.nome, t.id_parent, t.ordem
  ),
  unid AS (
    SELECT array_agg(uu.codigo_empresa ORDER BY uu.codigo_empresa) AS lista
      FROM auth.usuarios_unidades uu WHERE uu.id_usuario = p_usuario
  )
  SELECT jsonb_build_object(
           'usuario', jsonb_build_object('id', u.id, 'email', u.email, 'username', u.username,
                                         'id_funcionario', u.id_funcionario,
                                         'setor_irrestrito', u.setor_irrestrito),
           'perfis', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                         'id', p.id, 'nome', p.nome, 'escopo_vendedores', p.escopo_vendedores,
                         'tela_inicial_id', p.tela_inicial_id, 'tela_inicial_slug', p.tela_inicial_slug)
                         ORDER BY p.nome) FROM perfis p), '[]'::jsonb),
           'tela_inicial', (SELECT jsonb_build_object('id', p.tela_inicial_id, 'slug', p.tela_inicial_slug)
                              FROM perfis p WHERE p.tela_inicial_slug IS NOT NULL
                             ORDER BY p.nome LIMIT 1),
           'escopo_vendedores', auth.fn_escopo_vendedores_usuario(u.id),
           -- Contrato 49 (D1): + nome_exibicao e ativo do cadastro. LEFT JOIN pela
           -- PK (codigo_empresa, codigo_vendedor_omie): a lista é exatamente a de
           -- fn_vendedores_do_usuario (D2), sem perder nem duplicar item.
           'vendedores', COALESCE((SELECT jsonb_agg(
                                            to_jsonb(v) || jsonb_build_object(
                                              'nome_exibicao', vd.nome_exibicao,
                                              'ativo', vd.ativo)
                                            ORDER BY v.codigo_empresa, v.codigo_vendedor_omie)
                                     FROM auth.fn_vendedores_do_usuario(u.id) v
                                     LEFT JOIN core_vendas_faturamento.vendedores vd
                                       ON vd.codigo_empresa = v.codigo_empresa
                                      AND vd.codigo_vendedor_omie = v.codigo_vendedor_omie), '[]'::jsonb),
           'unidades', (SELECT to_jsonb(lista) FROM unid),
           'telas', COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.ordem, t.slug) FROM telas t), '[]'::jsonb),
           'token_versao', u.token_versao
         )
    FROM u;
$$;


