-- TOC entry 928 (class 1255 OID 20509)
-- Name: fn_rota_casa(text, text, uuid, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_rota_casa(p_padrao text, p_caminho text, p_usuario uuid, p_metodo text DEFAULT 'GET'::text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  pp text[] := string_to_array(btrim(lower(p_padrao), '/'), '/');
  cc text[] := string_to_array(btrim(lower(split_part(p_caminho, '?', 1)), '/'), '/');
  np integer := COALESCE(array_length(pp, 1), 0);
  nc integer := COALESCE(array_length(cc, 1), 0);
  pontos integer := 0;
  i integer;
BEGIN
  IF np > nc THEN RETURN NULL; END IF;
  -- Escrita casa só o caminho inteiro; leitura casa por prefixo.
  IF np < nc AND upper(COALESCE(p_metodo, 'GET')) NOT IN ('GET', 'HEAD') THEN RETURN NULL; END IF;
  FOR i IN 1 .. np LOOP
    IF pp[i] = '*' THEN
      pontos := pontos + 1;
    ELSIF pp[i] = ':usuario' THEN
      IF p_usuario IS NULL OR cc[i] IS DISTINCT FROM lower(p_usuario::text) THEN RETURN NULL; END IF;
      pontos := pontos + 2;
    ELSIF pp[i] = cc[i] THEN
      pontos := pontos + 2;
    ELSE
      RETURN NULL;
    END IF;
  END LOOP;
  RETURN np * 10 + pontos;
END $$;


