--
-- TOC entry 713 (class 1255 OID 20512)
-- Name: fn_vendedores_do_usuario(uuid); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.fn_vendedores_do_usuario(p_usuario uuid) RETURNS TABLE(codigo_empresa uuid, codigo_vendedor_omie character varying, id_funcionario uuid, nome character varying, origem text)
    LANGUAGE sql STABLE
    AS $$
  WITH u AS (
    SELECT us.id_funcionario, auth.fn_escopo_vendedores_usuario(us.id) AS escopo
      FROM auth.usuarios us
     WHERE us.id = p_usuario AND us.ativo AND us.deleted_at IS NULL AND us.id_funcionario IS NOT NULL
  ),
  vinc AS (
    -- próprios: vendedores.id_funcionario = funcionário do usuário
    SELECT v.codigo_empresa, v.codigo_vendedor_omie, v.id_funcionario, v.nome, 'proprio'::text AS origem, 1 AS ordem
      FROM u JOIN core_vendas_faturamento.vendedores v
        ON v.id_funcionario = u.id_funcionario AND v.deleted_at IS NULL
    UNION ALL
    -- titulares que o usuário auxilia (auxiliar_vendedor)
    SELECT v.codigo_empresa, v.codigo_vendedor_omie, v.id_funcionario, v.nome, 'titular', 2
      FROM u
      JOIN core_vendas_faturamento.auxiliar_vendedor a
        ON a.id_funcionario_auxiliar = u.id_funcionario AND a.deleted_at IS NULL
      JOIN core_vendas_faturamento.vendedores v
        ON v.id_funcionario = a.id_funcionario_titular AND v.deleted_at IS NULL
    UNION ALL
    -- vendedores que o usuário diligencia (Portal do PCP) — só escopo vinculados/todos
    SELECT v.codigo_empresa, v.codigo_vendedor_omie, v.id_funcionario, v.nome, 'diligenciado', 3
      FROM u
      JOIN core_vendas_faturamento.diligenciador_vendedor d
        ON d.id_funcionario_diligenciador = u.id_funcionario AND d.deleted_at IS NULL
      JOIN core_vendas_faturamento.vendedores v
        ON v.id_funcionario = d.id_funcionario_vendedor AND v.deleted_at IS NULL
     WHERE u.escopo IN ('vinculados', 'todos')
  )
  SELECT DISTINCT ON (codigo_empresa, codigo_vendedor_omie)
         codigo_empresa, codigo_vendedor_omie, id_funcionario, nome, origem
    FROM vinc
   ORDER BY codigo_empresa, codigo_vendedor_omie, ordem;
$$;


