-- TOC entry 715 (class 1255 OID 17288)
-- Name: propagate_telas_ativo(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.propagate_telas_ativo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Só executa se o campo "ativo" foi alterado
    IF OLD.ativo IS DISTINCT FROM NEW.ativo THEN
        UPDATE auth.telas
        SET ativo = NEW.ativo
        WHERE id_parent = NEW.id;
    END IF;

    RETURN NEW;
END;
$$;


--
-- TOC entry 700 (class 1255 OID 17289)
-- Name: propagate_telas_ordem(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.propagate_telas_ordem() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_delta int2;
BEGIN
  -- Nada mudou: saída antecipada
  v_delta := NEW.ordem - OLD.ordem;
  IF v_delta = 0 THEN
    RETURN NEW;
  END IF;
 
  -- Percorre todos os descendentes recursivamente e aplica o delta
  WITH RECURSIVE descendentes AS (
    -- nível 1: filhas diretas da tela atualizada
    SELECT id
      FROM auth.telas
     WHERE id_parent = NEW.id
 
    UNION ALL
 
    -- níveis seguintes: filhas das filhas, etc.
    SELECT t.id
      FROM auth.telas t
      JOIN descendentes d ON t.id_parent = d.id
  )
  UPDATE auth.telas
     SET ordem = ordem + v_delta
   WHERE id IN (SELECT id FROM descendentes);
 
  RETURN NEW;
END;
$$;


