--

CREATE FUNCTION core.fn_check_cargo_nivel_pessoa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_categoria text;
BEGIN
  SELECT categoria INTO v_categoria
    FROM core_organograma.nivel_hierarquico
   WHERE nivel = NEW.nvl_permissao;

  IF v_categoria = 'estrutural' THEN
    RAISE EXCEPTION
      'Cargo não pode usar o nível % — ele é estrutural (nó de Setor/Sub-setor, sem pessoa associada). Use um nível de categoria "pessoa".',
      NEW.nvl_permissao;
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 605 (class 1255 OID 17291)
-- Name: fn_check_setor_parent_empresa(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.fn_check_setor_parent_empresa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.parent_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM core.setores p
    WHERE p.id = NEW.parent_id AND p.codigo_empresa = NEW.codigo_empresa
  ) THEN
    RAISE EXCEPTION 'Setor % não pode ter como pai um setor de outra unidade (codigo_empresa deve ser igual ao do pai)', NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


