CREATE FUNCTION core.fn_norm_texto_produto(descricao text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
  SELECT
    btrim(regexp_replace(regexp_replace(
    regexp_replace(regexp_replace(regexp_replace(
    regexp_replace(regexp_replace(regexp_replace(
    regexp_replace(regexp_replace(regexp_replace(regexp_replace(
      lower(core.fn_unaccent_imm(regexp_replace(descricao, '[øØ⌀]', ' diam ', 'g'))),
      '(\d)\s*("|''''|polegadas?\M|pol\M|in\M)', '\1 pol ', 'g'),
      '(\mdiametro\M|\mdiam\M|\mdia\M)\.?', ' diam ', 'g'),
      '(\d)\s*[x×*]\s*(?=\d)', '\1 x ', 'g'),
      '[^a-z0-9.,\s]', ' ', 'g'),
      '(\d),(?=\d)', '\1.', 'g'),
      '(\d)(?=[a-z])', '\1 ', 'g'),
      '([a-z])(?=\d)', '\1 ', 'g'),
      '(?<![0-9.])0+(?=[0-9])', '', 'g'),
      '(\d)\.0+(?![0-9])', '\1', 'g'),
      '(\d\.\d*?[1-9])0+(?![0-9])', '\1', 'g'),
      '(?<![0-9])[.,]|[.,](?![0-9])', ' ', 'g'),
      '\s+', ' ', 'g'))
$$;


