--
-- TOC entry 871 (class 1255 OID 24035)
-- Name: fn_produtos_duplicatas_pares(uuid, integer, boolean); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.fn_produtos_duplicatas_pares(p_empresa uuid, p_limiar integer DEFAULT 70, p_somente_ativos boolean DEFAULT true) RETURNS TABLE(id_a uuid, id_b uuid, nota integer, nota_nome integer, nota_codigo integer, motivos text[])
    LANGUAGE sql STABLE
    SET "pg_trgm.similarity_threshold" TO '0.45'
    AS $$
  WITH cand AS (
    -- (1) nome parecido (trigramas >= 0,45) e MESMOS números no nome.
    --     Par de nome parecido com números diferentes perde 40 pontos e, sem
    --     bônus de código, fica no máximo em 65: não passa do limiar padrão.
    --     Por isso ele só entra pelo código (2); comparar todos os nomes
    --     parecidos da Vital daria ~21 milhões de candidatos (minutos).
    SELECT a.id AS id_a, b.id AS id_b,
           -- semelhanças calculadas aqui (uma vez por par, nos workers paralelos)
           public.similarity(a.descricao_norm, b.descricao_norm)::numeric AS sim_trgm,
           (SELECT count(*) FROM unnest(a.tokens_nome) t WHERE t = ANY (b.tokens_nome)) AS comuns,
           cardinality(a.tokens_nome) + cardinality(b.tokens_nome) AS total_tokens,
           CASE WHEN length(a.codigo_norm_sem_zeros) >= 4 AND length(b.codigo_norm_sem_zeros) >= 4
                THEN public.similarity(a.codigo_norm_sem_zeros, b.codigo_norm_sem_zeros)::numeric ELSE 0 END AS sim_cod,
           a.codigo_norm AS ac, b.codigo_norm AS bc,
           a.codigo_norm_sem_zeros AS acz, b.codigo_norm_sem_zeros AS bcz,
           a.numeros_nome AS anum, b.numeros_nome AS bnum,
           nullif(btrim(a.ncm), '') AS ancm, nullif(btrim(b.ncm), '') AS bncm,
           upper(nullif(btrim(a.unidade_medida), '')) AS au, upper(nullif(btrim(b.unidade_medida), '')) AS bu,
           a.familias_produtos AS af, b.familias_produtos AS bf
      FROM core.produtos a
      JOIN core.produtos b
        ON b.codigo_empresa = a.codigo_empresa
       AND b.numeros_nome = a.numeros_nome
       AND b.id > a.id
       AND b.deleted_at IS NULL
       AND b.descricao_norm OPERATOR(public.%) a.descricao_norm
     WHERE a.codigo_empresa = p_empresa
       AND a.deleted_at IS NULL
       AND a.descricao_norm <> ''
       AND a.numeros_nome <> '{}'::text[]
       AND (NOT coalesce(p_somente_ativos, true) OR (a.ativo AND b.ativo))
    UNION ALL
    -- (1b) nomes sem nenhum número: trigrama pelo índice parcial
    SELECT a.id AS id_a, b.id AS id_b,
           -- semelhanças calculadas aqui (uma vez por par, nos workers paralelos)
           public.similarity(a.descricao_norm, b.descricao_norm)::numeric AS sim_trgm,
           (SELECT count(*) FROM unnest(a.tokens_nome) t WHERE t = ANY (b.tokens_nome)) AS comuns,
           cardinality(a.tokens_nome) + cardinality(b.tokens_nome) AS total_tokens,
           CASE WHEN length(a.codigo_norm_sem_zeros) >= 4 AND length(b.codigo_norm_sem_zeros) >= 4
                THEN public.similarity(a.codigo_norm_sem_zeros, b.codigo_norm_sem_zeros)::numeric ELSE 0 END AS sim_cod,
           a.codigo_norm AS ac, b.codigo_norm AS bc,
           a.codigo_norm_sem_zeros AS acz, b.codigo_norm_sem_zeros AS bcz,
           a.numeros_nome AS anum, b.numeros_nome AS bnum,
           nullif(btrim(a.ncm), '') AS ancm, nullif(btrim(b.ncm), '') AS bncm,
           upper(nullif(btrim(a.unidade_medida), '')) AS au, upper(nullif(btrim(b.unidade_medida), '')) AS bu,
           a.familias_produtos AS af, b.familias_produtos AS bf
      FROM core.produtos a
      JOIN core.produtos b
        ON b.codigo_empresa = a.codigo_empresa
       AND b.numeros_nome = '{}'::text[]
       AND b.id > a.id
       AND b.deleted_at IS NULL
       AND b.descricao_norm OPERATOR(public.%) a.descricao_norm
     WHERE a.codigo_empresa = p_empresa
       AND a.deleted_at IS NULL
       AND a.descricao_norm <> ''
       AND a.numeros_nome = '{}'::text[]
       AND (NOT coalesce(p_somente_ativos, true) OR (a.ativo AND b.ativo))
    UNION ALL
    -- (2) ou código igual sem zeros, com qualquer nome (índice unidade + código),
    --     tirando os pares que (1)/(1b) já trouxeram
    SELECT a.id AS id_a, b.id AS id_b,
           -- semelhanças calculadas aqui (uma vez por par, nos workers paralelos)
           public.similarity(a.descricao_norm, b.descricao_norm)::numeric AS sim_trgm,
           (SELECT count(*) FROM unnest(a.tokens_nome) t WHERE t = ANY (b.tokens_nome)) AS comuns,
           cardinality(a.tokens_nome) + cardinality(b.tokens_nome) AS total_tokens,
           CASE WHEN length(a.codigo_norm_sem_zeros) >= 4 AND length(b.codigo_norm_sem_zeros) >= 4
                THEN public.similarity(a.codigo_norm_sem_zeros, b.codigo_norm_sem_zeros)::numeric ELSE 0 END AS sim_cod,
           a.codigo_norm AS ac, b.codigo_norm AS bc,
           a.codigo_norm_sem_zeros AS acz, b.codigo_norm_sem_zeros AS bcz,
           a.numeros_nome AS anum, b.numeros_nome AS bnum,
           nullif(btrim(a.ncm), '') AS ancm, nullif(btrim(b.ncm), '') AS bncm,
           upper(nullif(btrim(a.unidade_medida), '')) AS au, upper(nullif(btrim(b.unidade_medida), '')) AS bu,
           a.familias_produtos AS af, b.familias_produtos AS bf
      FROM core.produtos a
      JOIN core.produtos b
        ON b.codigo_empresa = a.codigo_empresa
       AND b.codigo_norm_sem_zeros = a.codigo_norm_sem_zeros
       AND b.id > a.id
       AND b.deleted_at IS NULL
       AND b.codigo_norm_sem_zeros <> ''
     WHERE a.codigo_empresa = p_empresa
       AND a.deleted_at IS NULL
       AND a.codigo_norm_sem_zeros <> ''
       AND (NOT coalesce(p_somente_ativos, true) OR (a.ativo AND b.ativo))
       AND NOT (a.descricao_norm <> '' AND b.numeros_nome = a.numeros_nome
                AND b.descricao_norm OPERATOR(public.%) a.descricao_norm)
  ), pont AS MATERIALIZED (
    SELECT c.*,
      -- nome: o maior entre trigrama e sobreposição de palavras (Jaccard)
      greatest(c.sim_trgm, c.comuns::numeric / NULLIF(c.total_tokens - c.comuns, 0)) AS sim_nome,
      -- código: igual normalizado = 100; igual sem zeros = 90; parecido (trigrama >= 0,6) = 48..80
      CASE
        WHEN c.ac <> '' AND c.ac = c.bc THEN 100
        WHEN c.acz <> '' AND c.acz = c.bcz THEN 90
        WHEN c.sim_cod >= 0.6 THEN round(c.sim_cod * 80)::int
        ELSE 0
      END AS n_codigo,
      (c.anum IS DISTINCT FROM c.bnum) AS numeros_diferentes,
      (c.ancm IS NOT NULL AND c.ancm = c.bncm) AS mesmo_ncm,
      (c.au IS NOT DISTINCT FROM c.bu) AS mesma_unidade,
      (c.af = c.bf) AS mesma_familia
    FROM cand c
  ), calc AS MATERIALIZED (
    SELECT p.id_a, p.id_b,
           round(p.sim_nome * 100)::int AS nota_nome,
           p.n_codigo AS nota_codigo,
           greatest(0, least(100,
               round(p.sim_nome * 100)::int
             + CASE WHEN p.n_codigo >= 90 THEN 20 WHEN p.n_codigo >= 60 THEN 8 ELSE 0 END
             + CASE WHEN p.mesmo_ncm THEN 5 ELSE 0 END
             - CASE WHEN NOT p.mesma_unidade THEN 10 ELSE 0 END
             - CASE WHEN NOT p.mesma_familia THEN 5 ELSE 0 END
             - CASE WHEN p.numeros_diferentes THEN 40 ELSE 0 END
           ))::int AS nota,
           array_remove(ARRAY[
             CASE WHEN p.sim_nome >= 0.9 THEN 'nome_quase_igual'
                  WHEN p.sim_nome >= 0.45 THEN 'nome_parecido' END,
             CASE WHEN p.n_codigo = 100 THEN 'codigo_igual_normalizado'
                  WHEN p.n_codigo = 90  THEN 'codigo_igual_sem_zeros'
                  WHEN p.n_codigo >= 60 THEN 'codigo_parecido' END,
             CASE WHEN p.mesmo_ncm THEN 'mesmo_ncm' END,
             CASE WHEN p.mesma_unidade THEN 'mesma_unidade' ELSE 'unidade_diferente' END,
             CASE WHEN p.mesma_familia THEN 'mesma_familia' ELSE 'familia_diferente' END,
             CASE WHEN p.numeros_diferentes THEN 'numeros_diferentes' END
           ], NULL) AS motivos
      FROM pont p
  )
  SELECT id_a, id_b, nota, nota_nome, nota_codigo, motivos
    FROM calc
   WHERE nota >= greatest(50, least(100, coalesce(p_limiar, 70)))
   ORDER BY nota DESC, id_a, id_b
$$;


