-- Name: FUNCTION fn_produtos_duplicatas_pares(p_empresa uuid, p_limiar integer, p_somente_ativos boolean); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.fn_produtos_duplicatas_pares(p_empresa uuid, p_limiar integer, p_somente_ativos boolean) IS 'Pares (id_a < id_b) de produtos da mesma unidade com nome parecido (trigramas >= 0,45) e os mesmos números no nome, ou com código igual sem zeros (qualquer nome): candidatos a duplicata, com nota 0-100 e motivos. Nota = semelhança do nome x100 (maior entre trigrama e palavras em comum) +20 código igual (ou +8 parecido) +5 mesmo NCM -10 unidade diferente -5 família diferente -40 números do nome diferentes, entre 0 e 100. Só sai par com nota >= p_limiar (50 a 100, padrão 70). Só leitura. Contrato SQL-013 (rota GET /produtos/duplicatas, API-012).';


--
-- TOC entry 714 (class 1255 OID 24037)
-- Name: fn_produtos_uso(uuid, uuid[]); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.fn_produtos_uso(p_empresa uuid, p_ids uuid[]) RETURNS TABLE(id_produto uuid, vendas_itens bigint, vendas_quantidade numeric, vendas_valor_total numeric, vendas_ultima_data date, oc_itens bigint, oc_quantidade numeric, oc_ultima_data date, pedidos_compra_omie_itens bigint, requisicoes bigint, estoque_saldo numeric, estoque_fisico numeric, estoque_reservado numeric, estoque_data_posicao date, fornecedores_qtd bigint, cotacao_ultima_data date, cotacao_ultimo_valor numeric, fornecedores_top jsonb)
    LANGUAGE sql STABLE
    AS $_$
  SELECT p.id,
         v.itens, v.qtd, v.valor, v.ultima,
         oc.itens, oc.qtd, oc.ultima,
         pc.itens,
         rq.qtd,
         es.saldo, es.fisico, es.reservado, es.data_pos,
         fo.qtd, fo.ultima_data, fo.ultimo_valor, fo.top
    FROM core.produtos p
    -- vendas: itens de pedido de venda (não cancelado, não excluído)
    LEFT JOIN LATERAL (
        SELECT count(*) AS itens,
               coalesce(sum(pv.quantidade), 0)::numeric AS qtd,
               coalesce(sum(pv.valor_total), 0)::numeric AS valor,
               max(coalesce(
                 CASE WHEN pd.data_faturamento ~ '^\d{4}-\d{2}-\d{2}$' THEN to_date(pd.data_faturamento, 'YYYY-MM-DD')
                      WHEN pd.data_faturamento ~ '^\d{2}/\d{2}/\d{4}$' THEN to_date(pd.data_faturamento, 'DD/MM/YYYY') END,
                 CASE WHEN pd.data_inclusao ~ '^\d{4}-\d{2}-\d{2}$' THEN to_date(pd.data_inclusao, 'YYYY-MM-DD')
                      WHEN pd.data_inclusao ~ '^\d{2}/\d{2}/\d{4}$' THEN to_date(pd.data_inclusao, 'DD/MM/YYYY') END
               )) AS ultima
          FROM core_vendas_faturamento.produto_vendas pv
          LEFT JOIN core_vendas_faturamento.pedidos_vendas pd
                 ON pd.codigo_empresa = pv.codigo_empresa AND pd.codigo_pedido_omie = pv.codigo_pedido_omie
         WHERE pv.codigo_empresa = p.codigo_empresa
           AND pv.codigo_produto_omie = p.codigo_produto_omie
           AND pv.deleted_at IS NULL
           AND pd.deleted_at IS NULL
           AND NOT coalesce(pd.cancelado, false)
    ) v ON true
    -- OC do hub: aguardando aprovação ou aprovada (fora rascunho e cancelada)
    LEFT JOIN LATERAL (
        SELECT count(*) AS itens, coalesce(sum(i.quantidade), 0)::numeric AS qtd, max(o.created_at)::date AS ultima
          FROM core_vendas_faturamento.ordens_compra_itens i
          JOIN core_vendas_faturamento.ordens_compra o ON o.id = i.id_ordem_compra
         WHERE i.codigo_empresa = p.codigo_empresa
           AND i.codigo_produto = p.codigo_produto
           AND o.deleted_at IS NULL
           AND o.status IN ('aguardando_aprovacao', 'aprovado')
    ) oc ON true
    -- pedidos de compra espelhados do Omie
    LEFT JOIN LATERAL (
        SELECT count(*) AS itens
          FROM core_vendas_faturamento.pedidos_compras_itens i
          JOIN core_vendas_faturamento.pedidos_compras c ON c.id = i.id_pedido_compra
         WHERE i.codigo_empresa = p.codigo_empresa
           AND i.codigo_produto_omie = p.codigo_produto_omie
           AND c.deleted_at IS NULL
    ) pc ON true
    -- requisições do Compras (material = código do cadastro, API-010)
    LEFT JOIN LATERAL (
        SELECT count(*) AS qtd
          FROM core_vendas_faturamento.requisicoes_compra r
         WHERE r.codigo_empresa = p.codigo_empresa
           AND r.material = p.codigo_produto
           AND r.deleted_at IS NULL
    ) rq ON true
    -- estoque: uma linha por produto + local (uq_estoque_saldo_produto_local)
    LEFT JOIN LATERAL (
        SELECT coalesce(sum(s.saldo), 0)::numeric AS saldo,
               coalesce(sum(s.fisico), 0)::numeric AS fisico,
               coalesce(sum(s.reservado), 0)::numeric AS reservado,
               max(s.data_posicao) AS data_pos
          FROM core.estoque_saldo s
         WHERE s.codigo_empresa = p.codigo_empresa
           AND s.codigo_produto_omie = p.codigo_produto_omie
           AND s.deleted_at IS NULL
    ) es ON true
    -- fornecedores: última cotação de cada parceiro (mesma ligação do vw_catalogo_de_produtos)
    LEFT JOIN LATERAL (
        WITH ult AS (
          SELECT DISTINCT ON (pp.id_parceiro)
                 pp.id_parceiro, pp.valor_unidade, pp.data_cotacao, pp.created_at
            FROM core.parceiros_produtos pp
           WHERE pp.codigo_empresa = p.codigo_empresa
             AND pp.id_produto = p.codigo_produto_omie
             AND pp.deleted_at IS NULL
           ORDER BY pp.id_parceiro, pp.data_cotacao DESC NULLS LAST, pp.created_at DESC
        )
        SELECT count(*) AS qtd,
               max(ult.data_cotacao) AS ultima_data,
               (SELECT u2.valor_unidade FROM ult u2
                 ORDER BY u2.data_cotacao DESC NULLS LAST, u2.created_at DESC LIMIT 1) AS ultimo_valor,
               coalesce((SELECT jsonb_agg(jsonb_build_object(
                         'codigo_parceiro_omie', t.id_parceiro,
                         'nome_fantasia', pa.nome_fantasia,
                         'ultimo_valor', t.valor_unidade,
                         'ultima_data', t.data_cotacao)
                         ORDER BY t.data_cotacao DESC NULLS LAST, t.created_at DESC)
                  FROM (SELECT * FROM ult ORDER BY data_cotacao DESC NULLS LAST, created_at DESC LIMIT 5) t
                  LEFT JOIN core.parceiros pa
                         ON pa.codigo_parceiro_omie = t.id_parceiro AND pa.codigo_empresa = p.codigo_empresa
                        AND pa.deleted_at IS NULL), '[]'::jsonb) AS top
          FROM ult
    ) fo ON true
   WHERE p.codigo_empresa = p_empresa
     AND p.id = ANY (p_ids)
     AND p.deleted_at IS NULL
$_$;


