CREATE FUNCTION core.fn_set_nivel_setor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.parent_id IS NULL THEN
        NEW.nivel := 2;
    ELSE
        NEW.nivel := 3;
    END IF;
    RETURN NEW;
END;
$$;


