-- TOC entry 999 (class 1255 OID 24748)
-- Name: fn_sigla_unidade(text); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.fn_sigla_unidade(p_nome text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  -- Acentos fora (Ç -> C), sufixo societário fora (LTDA, ME, EPP, EIRELI, S/A,
  -- S.A., SA) e palavras separadas por qualquer coisa que não seja letra/número.
  WITH n AS (
    SELECT regexp_replace(
             translate(btrim(COALESCE(p_nome, '')),
                       'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑáàâãäéèêëíìîïóòôõöúùûüçñ',
                       'AAAAAEEEEIIIIOOOOOUUUUCNaaaaaeeeeiiiiooooouuuucn'),
             '[[:space:]]+(LTDA|ME|EPP|EIRELI|S/A|S\.A\.?|SA)\.?$', '', 'i') AS nome
  ), p AS (
    SELECT w, ord, (SELECT nome ~ '[a-z]' FROM n) AS tem_minuscula
      FROM n, regexp_split_to_table(n.nome, '[^A-Za-z0-9]+') WITH ORDINALITY AS t(w, ord)
     WHERE w <> ''
       AND upper(w) NOT IN ('DE', 'DA', 'DO', 'DAS', 'DOS', 'E', 'LTDA')
  )
  SELECT NULLIF(string_agg(
           CASE
             -- Palavra toda em maiúsculas num nome que tem minúsculas = sigla: entra inteira
             -- ("HRM Caldeiraria" -> HRM + C). Nome todo em maiúsculas: só a palavra
             -- única entra inteira ("HRM" -> HRM; "ACOS VITAL" -> AV).
             WHEN w ~ '^[A-Z0-9]{2,}$' AND (tem_minuscula OR (SELECT count(*) FROM p) = 1) THEN w
             ELSE upper(left(w, 1))
           END, '' ORDER BY ord), '')
    FROM p;
$_$;


--
-- TOC entry 7146 (class 0 OID 0)
-- Dependencies: 999
-- Name: FUNCTION fn_sigla_unidade(p_nome text); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.fn_sigla_unidade(p_nome text) IS 'Pedido do Robert (10/11/2026): sigla da unidade (AV, AU, HRM) gerada das iniciais do nome fantasia. Tira acentos, o sufixo societário (LTDA, ME, EPP, EIRELI, S/A, SA) e os conectivos (de, da, do, das, dos, e); de cada palavra fica a inicial, menos a palavra toda em maiúsculas (sigla), que entra inteira — num nome todo em maiúsculas, só se for a única palavra. Ex.: "Aços Vital" -> AV, "Aços Uberaba" -> AU, "HRM" -> HRM, "HRM Caldeiraria" -> HRMC, "AÇOS VITAL" -> AV. Usada pela coluna gerada core.unidades.sigla: se a regra mudar, rodar UPDATE core.unidades SET nome_fantasia = nome_fantasia para recalcular.';


