--
-- TOC entry 780 (class 1255 OID 20360)
-- Name: fn_decidir_vaga(uuid, text, text, uuid); Type: FUNCTION; Schema: core_aprovacao_de_vagas; Owner: -
--

CREATE FUNCTION core_aprovacao_de_vagas.fn_decidir_vaga(p_vaga uuid, p_situacao text, p_observacao text, p_usuario uuid) RETURNS core_aprovacao_de_vagas.vagas_decisoes
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_anterior varchar(50);
  v_obs      text := NULLIF(btrim(p_observacao), '');
  v_hist     core_aprovacao_de_vagas.vagas_decisoes;
BEGIN
  IF p_situacao IS NULL OR p_situacao NOT IN ('aprovado', 'reprovado', 'pendente') THEN
    RAISE EXCEPTION 'situacao inválida: "%". Valores aceitos: aprovado, reprovado, pendente.', p_situacao
      USING ERRCODE = 'AV011';
  END IF;
  IF p_usuario IS NULL THEN
    RAISE EXCEPTION 'A decisão exige o usuário que decide.' USING ERRCODE = 'AV011';
  END IF;

  SELECT v.situacao INTO v_anterior
    FROM core_aprovacao_de_vagas.vaga v
   WHERE v.id = p_vaga AND v.deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vaga não encontrada' USING ERRCODE = 'AV010';
  END IF;

  -- Autoriza as triggers de proteção só durante este UPDATE.
  PERFORM set_config('avhub.vaga_decisao', 'on', true);
  UPDATE core_aprovacao_de_vagas.vaga
     SET situacao            = p_situacao,
         observacao_situacao = v_obs,
         decidido_por        = CASE WHEN p_situacao = 'pendente' THEN NULL ELSE p_usuario END,
         decidido_em         = CASE WHEN p_situacao = 'pendente' THEN NULL ELSE now() END,
         updated_at          = now() AT TIME ZONE 'UTC'
   WHERE id = p_vaga;
  PERFORM set_config('avhub.vaga_decisao', 'off', true);

  INSERT INTO core_aprovacao_de_vagas.vagas_decisoes
         (id_vaga, situacao_anterior, situacao_nova, observacao, decidido_por, origem)
  VALUES (p_vaga, v_anterior, p_situacao, v_obs, p_usuario, 'decisao')
  RETURNING * INTO v_hist;

  RETURN v_hist;
END $$;


