-- Name: fn_vaga_historico_legado(); Type: FUNCTION; Schema: core_aprovacao_de_vagas; Owner: -
--

CREATE FUNCTION core_aprovacao_de_vagas.fn_vaga_historico_legado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('avhub.vaga_decisao', true) = 'on' THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.situacao IS DISTINCT FROM 'pendente' THEN
      INSERT INTO core_aprovacao_de_vagas.vagas_decisoes
             (id_vaga, situacao_anterior, situacao_nova, observacao, decidido_por, origem)
      VALUES (NEW.id, NULL, NEW.situacao, NEW.observacao_situacao, NULL, 'legado');
    END IF;
  ELSIF NEW.situacao IS DISTINCT FROM OLD.situacao THEN
    INSERT INTO core_aprovacao_de_vagas.vagas_decisoes
           (id_vaga, situacao_anterior, situacao_nova, observacao, decidido_por, origem)
    VALUES (NEW.id, OLD.situacao, NEW.situacao, NEW.observacao_situacao, NULL, 'legado');
  END IF;
  RETURN NULL;
END $$;


