COMMENT ON FUNCTION core_aprovacao_de_vagas.fn_vaga_historico_legado() IS 'Contrato 04: registra em vagas_decisoes (origem legado) toda mudança de situação que NÃO passou por fn_decidir_vaga.';


--
-- TOC entry 833 (class 1255 OID 20361)
-- Name: fn_vaga_proteger_decisao(); Type: FUNCTION; Schema: core_aprovacao_de_vagas; Owner: -
--

CREATE FUNCTION core_aprovacao_de_vagas.fn_vaga_proteger_decisao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('avhub.vaga_decisao', true) = 'on' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.decidido_por := NULL;
    NEW.decidido_em  := CASE WHEN NEW.situacao IN ('aprovado', 'reprovado') THEN now() END;
    RETURN NEW;
  END IF;

  IF NEW.situacao IS DISTINCT FROM OLD.situacao THEN
    -- Mudança de situação por caminho legado: carimba quando, sem autor.
    NEW.decidido_por := NULL;
    NEW.decidido_em  := CASE WHEN NEW.situacao IN ('aprovado', 'reprovado') THEN now() END;
  ELSE
    NEW.decidido_por := OLD.decidido_por;
    NEW.decidido_em  := OLD.decidido_em;
  END IF;
  RETURN NEW;
END $$;


