--

COMMENT ON FUNCTION core_aprovacao_de_vagas.fn_vaga_proteger_decisao() IS 'Contrato 04: decidido_por/decidido_em só são gravados por fn_decidir_vaga. Mudança de situação por outro caminho carimba decidido_em = now() e decidido_por = NULL.';


--
-- TOC entry 849 (class 1255 OID 20707)
-- Name: fn_vaga_reabrir_por_edicao(uuid, uuid, text[]); Type: FUNCTION; Schema: core_aprovacao_de_vagas; Owner: -
--

CREATE FUNCTION core_aprovacao_de_vagas.fn_vaga_reabrir_por_edicao(p_vaga uuid, p_usuario uuid, p_campos text[]) RETURNS core_aprovacao_de_vagas.vagas_decisoes
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_anterior     varchar(50);
  v_obs_anterior text;
  v_ultima       core_aprovacao_de_vagas.vagas_decisoes;
  v_campos       text;
  v_obs          text;
  v_hist         core_aprovacao_de_vagas.vagas_decisoes;
BEGIN
  SELECT string_agg(DISTINCT btrim(c), ', ')
    INTO v_campos
    FROM unnest(p_campos) AS c
   WHERE NULLIF(btrim(c), '') IS NOT NULL;
  IF v_campos IS NULL THEN
    RAISE EXCEPTION 'Informe os campos alterados.' USING ERRCODE = 'AV011';
  END IF;

  SELECT v.situacao, v.observacao_situacao
    INTO v_anterior, v_obs_anterior
    FROM core_aprovacao_de_vagas.vaga v
   WHERE v.id = p_vaga AND v.deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vaga não encontrada' USING ERRCODE = 'AV010';
  END IF;

  IF v_anterior NOT IN ('aprovado', 'reprovado') THEN
    RETURN NULL;  -- já pendente: nada a reabrir
  END IF;

  v_obs := 'Dados alterados: ' || v_campos;

  -- A observação da decisão que caiu já está no histórico? (decisões feitas
  -- antes da migration 004 não têm linha em vagas_decisoes)
  v_obs_anterior := NULLIF(btrim(v_obs_anterior), '');
  IF v_obs_anterior IS NOT NULL THEN
    SELECT d.* INTO v_ultima
      FROM core_aprovacao_de_vagas.vagas_decisoes d
     WHERE d.id_vaga = p_vaga
     ORDER BY d.decidido_em DESC, d.id DESC
     LIMIT 1;
    IF v_ultima.id IS NULL
       OR v_ultima.situacao_nova IS DISTINCT FROM v_anterior
       OR NULLIF(btrim(v_ultima.observacao), '') IS DISTINCT FROM v_obs_anterior THEN
      v_obs := v_obs || E'\nObservação da decisão anterior (' || v_anterior || '): ' || v_obs_anterior;
    END IF;
  END IF;

  -- Mesma autorização da fn_decidir_vaga: as triggers de proteção deixam
  -- gravar decidido_* e não geram a linha 'legado'.
  PERFORM set_config('avhub.vaga_decisao', 'on', true);
  UPDATE core_aprovacao_de_vagas.vaga
     SET situacao            = 'pendente',
         observacao_situacao = NULL,
         decidido_por        = NULL,
         decidido_em         = NULL,
         updated_at          = now() AT TIME ZONE 'UTC'
   WHERE id = p_vaga;
  PERFORM set_config('avhub.vaga_decisao', 'off', true);

  INSERT INTO core_aprovacao_de_vagas.vagas_decisoes
         (id_vaga, situacao_anterior, situacao_nova, observacao, decidido_por, origem)
  VALUES (p_vaga, v_anterior, 'pendente', v_obs, p_usuario, 'edicao')
  RETURNING * INTO v_hist;

  RETURN v_hist;
END $$;


--
-- TOC entry 7154 (class 0 OID 0)
-- Dependencies: 849
-- Name: FUNCTION fn_vaga_reabrir_por_edicao(p_vaga uuid, p_usuario uuid, p_campos text[]); Type: COMMENT; Schema: core_aprovacao_de_vagas; Owner: -
--

COMMENT ON FUNCTION core_aprovacao_de_vagas.fn_vaga_reabrir_por_edicao(p_vaga uuid, p_usuario uuid, p_campos text[]) IS 'Contrato 04 (§3.3.1): editar dados de uma vaga aprovada/reprovada a devolve para pendente. Chamada pela API na mesma transação do PUT/PATCH (depois de gravar os dados): situacao = pendente, observacao_situacao/decidido_por/decidido_em = NULL e UMA linha em vagas_decisoes (origem edicao, decidido_por = quem editou, observacao = "Dados alterados: <campos>"). Vaga já pendente: devolve NULL e não faz nada. AV010 = vaga inexistente, AV011 = campos vazios.';


--
-- TOC entry 503 (class 1255 OID 24840)
-- Name: fn_carteira_vendedores(uuid, boolean); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_carteira_vendedores(p_usuario uuid, p_incluir_titulares boolean DEFAULT true) RETURNS TABLE(codigo_empresa uuid, codigo_vendedor_omie character varying, origem text)
    LANGUAGE sql STABLE
    AS $$
  SELECT vd.codigo_empresa, vd.codigo_vendedor_omie, 'proprio'::text
    FROM auth.usuarios u
    JOIN core_vendas_faturamento.vendedores vd
      ON (vd.id_funcionario = u.id_funcionario OR vd.id_usuario = u.id) AND vd.deleted_at IS NULL
   WHERE u.id = p_usuario
  UNION
  SELECT vd.codigo_empresa, vd.codigo_vendedor_omie, 'titular'
    FROM auth.usuarios u
    JOIN core_vendas_faturamento.auxiliar_vendedor a
      ON a.id_funcionario_auxiliar = u.id_funcionario AND a.deleted_at IS NULL
    JOIN core_vendas_faturamento.vendedores vd
      ON vd.deleted_at IS NULL
     AND (vd.id_funcionario = a.id_funcionario_titular
          OR vd.id_usuario IN (SELECT t.id FROM auth.usuarios t WHERE t.id_funcionario = a.id_funcionario_titular))
   WHERE u.id = p_usuario AND u.id_funcionario IS NOT NULL AND p_incluir_titulares;
$$;


--
-- TOC entry 7155 (class 0 OID 0)
