--

CREATE FUNCTION core_comercial.fn_chaves_idempotencia_limpar(p_horas integer DEFAULT 24) RETURNS integer
    LANGUAGE sql
    AS $$
  WITH apagadas AS (
    DELETE FROM core_comercial.chaves_idempotencia
     WHERE criada_em < now() - make_interval(hours => GREATEST(p_horas, 1))
    RETURNING 1
  )
  SELECT count(*)::int FROM apagadas;
$$;


