-- TOC entry 887 (class 1255 OID 24842)
-- Name: fn_cliente_cadastro_conferir(uuid, uuid, text); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_cliente_cadastro_conferir(p_usuario uuid, p_codigo_empresa uuid, p_documento text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_doc text := core_comercial.fn_documento_normalizado(p_documento);
  v_par uuid;
  v_sit text;
BEGIN
  SELECT pa.id INTO v_par
    FROM core.parceiros pa
   WHERE pa.codigo_empresa = p_codigo_empresa AND pa.deleted_at IS NULL
     AND core_comercial.fn_documento_normalizado(pa.cpf_cnpj) = v_doc
   ORDER BY pa.inativo, pa.updated_at DESC NULLS LAST, pa.id
   LIMIT 1;
  IF v_par IS NULL THEN
    RETURN 'novo';
  END IF;
  v_sit := core_comercial.fn_cliente_carteira(p_codigo_empresa, v_par, p_usuario, true);
  IF v_sit = 'outra' AND auth.fn_escopo_vendedores_usuario(p_usuario) IS DISTINCT FROM 'todos' THEN
    RAISE EXCEPTION 'Este cliente já está cadastrado e está na carteira de outro vendedor. Fale com a gerência.'
      USING ERRCODE = 'AV547', DETAIL = v_par::text;
  END IF;
  RETURN v_sit;
END
$$;


