-- Name: fn_cliente_carteira(uuid, uuid, uuid, boolean, uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_cliente_carteira(p_codigo_empresa uuid, p_id_parceiro uuid, p_de uuid, p_incluir_titulares boolean DEFAULT false, p_ignorar_proposta uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE
           WHEN c.id_parceiro IS NULL THEN 'livre'
           WHEN EXISTS (SELECT 1 FROM core_comercial.fn_carteira_vendedores(p_de, p_incluir_titulares) m
                         WHERE m.codigo_empresa = c.codigo_empresa AND m.codigo_vendedor_omie = c.codigo_vendedor_omie)
             THEN 'carteira'
           WHEN c.origem = 'PROPOSTA' AND c.id_usuario = p_de THEN 'carteira'
           ELSE 'outra'
         END
    FROM (SELECT 1) x
    LEFT JOIN core_vendas_faturamento.fn_carteira_clientes(p_codigo_empresa, p_id_parceiro, p_ignorar_proposta) c ON true
   LIMIT 1;
$$;


