-- TOC entry 793 (class 1255 OID 24310)
-- Name: fn_cliente_omie_registrar(uuid, text, jsonb, uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_cliente_omie_registrar(p_codigo_empresa uuid, p_codigo_parceiro_omie text, p_dados jsonb, p_usuario uuid) RETURNS TABLE(id uuid, criado boolean)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_codigo   text := btrim(COALESCE(p_codigo_parceiro_omie, ''));
  v_doc      text;
  v_doc_fmt  text;
  v_razao    text := NULLIF(btrim(COALESCE(p_dados->>'razao_social', '')), '');
  v_fantasia text := NULLIF(btrim(COALESCE(p_dados->>'nome_fantasia', '')), '');
  v_email    text := NULLIF(btrim(COALESCE(p_dados->>'email', '')), '');
  v_telefone text := NULLIF(btrim(COALESCE(p_dados->>'telefone', '')), '');
  v_logr     text := NULLIF(btrim(COALESCE(p_dados->>'logradouro', '')), '');
  v_numero   text := NULLIF(btrim(COALESCE(p_dados->>'numero', '')), '');
  v_estado   text := NULLIF(upper(btrim(COALESCE(p_dados->>'estado', ''))), '');
  v_tipo     uuid;
  v_id       uuid;
  v_criado   boolean;
BEGIN
  IF p_codigo_empresa IS NULL
     OR NOT EXISTS (SELECT 1 FROM core.unidades u WHERE u.id = p_codigo_empresa AND u.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Unidade (codigo_empresa) não encontrada.' USING ERRCODE = '23514';
  END IF;
  IF v_codigo !~ '^[1-9][0-9]{0,14}$' THEN
    RAISE EXCEPTION 'Código do cliente no Omie inválido: "%".', v_codigo USING ERRCODE = '23514';
  END IF;
  IF NOT core_comercial.fn_documento_valido(p_dados->>'cpf_cnpj') THEN
    RAISE EXCEPTION 'CPF/CNPJ inválido.' USING ERRCODE = '23514';
  END IF;
  IF v_razao IS NULL THEN
    RAISE EXCEPTION 'Razão social é obrigatória.' USING ERRCODE = '23514';
  END IF;
  IF v_estado IS NOT NULL AND v_estado !~ '^[A-Z]{2}$' THEN
    RAISE EXCEPTION 'UF inválida: "%".', v_estado USING ERRCODE = '23514';
  END IF;

  -- Máscara igual à que a pipeline grava (vem do Omie): 00.000.000/0000-00 e 000.000.000-00.
  v_doc := core_comercial.fn_documento_normalizado(p_dados->>'cpf_cnpj');
  v_doc_fmt := CASE length(v_doc)
    WHEN 14 THEN substr(v_doc,1,2)||'.'||substr(v_doc,3,3)||'.'||substr(v_doc,6,3)||'/'||substr(v_doc,9,4)||'-'||substr(v_doc,13,2)
    ELSE substr(v_doc,1,3)||'.'||substr(v_doc,4,3)||'.'||substr(v_doc,7,3)||'-'||substr(v_doc,10,2)
  END;

  SELECT t.id INTO v_tipo FROM core.tipos_parceiro t
   WHERE t.tipo = 'Cliente' AND t.deleted_at IS NULL
   ORDER BY t.created_at LIMIT 1;
  IF v_tipo IS NULL THEN
    RAISE EXCEPTION 'Tipo de parceiro ''Cliente'' não cadastrado.' USING ERRCODE = '23514';
  END IF;

  -- Duas chamadas para o mesmo cliente da mesma conta (duplo clique, dois
  -- vendedores) passam uma de cada vez.
  PERFORM pg_advisory_xact_lock(hashtextextended('fn_cliente_omie_registrar:' || p_codigo_empresa::text || ':' || v_codigo, 0));

  INSERT INTO core.parceiros AS p
         (codigo_empresa, codigo_parceiro_omie, cpf_cnpj, razao_social, nome_fantasia,
          email, telefone, logradouro, numero, estado, created_by, updated_by)
  VALUES (p_codigo_empresa, v_codigo, v_doc_fmt, left(v_razao, 100), left(COALESCE(v_fantasia, v_razao), 500),
          v_email, left(v_telefone, 20), left(v_logr, 100), left(v_numero, 10), v_estado, p_usuario, p_usuario)
  ON CONFLICT ON CONSTRAINT uq_parceiros_codigo_omie DO UPDATE SET
         cpf_cnpj      = EXCLUDED.cpf_cnpj,
         razao_social  = EXCLUDED.razao_social,
         nome_fantasia = CASE WHEN v_fantasia IS NULL THEN p.nome_fantasia ELSE EXCLUDED.nome_fantasia END,
         email         = COALESCE(EXCLUDED.email, p.email),
         telefone      = COALESCE(EXCLUDED.telefone, p.telefone),
         logradouro    = COALESCE(EXCLUDED.logradouro, p.logradouro),
         numero        = CASE WHEN EXCLUDED.logradouro IS NULL THEN p.numero ELSE EXCLUDED.numero END,
         estado        = COALESCE(EXCLUDED.estado, p.estado),
         deleted_at    = NULL,
         deleted_by    = NULL,
         updated_by    = p_usuario
  RETURNING p.id, (p.xmax = 0) INTO v_id, v_criado;

  INSERT INTO core.parceiros_tipos AS pt (id_parceiro, id_tipo_parceiro, created_by, updated_by)
  VALUES (v_id, v_tipo, p_usuario, p_usuario)
  ON CONFLICT ON CONSTRAINT uq_parceiros_tipos DO UPDATE SET
         deleted_at = NULL, deleted_by = NULL, updated_by = p_usuario
   WHERE pt.deleted_at IS NOT NULL;

  RETURN QUERY SELECT v_id, v_criado;
END
$_$;


