CREATE FUNCTION core_comercial.fn_comercial_codigos_omie_conferir(p_codigo_empresa uuid, p_condicao text, p_categoria text) RETURNS void
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v jsonb := core_comercial.fn_comercial_codigos_omie_problemas(p_codigo_empresa, p_condicao, p_categoria);
BEGIN
  IF v IS NOT NULL THEN
    RAISE EXCEPTION '%', (SELECT string_agg(e->>'mensagem', ' ') FROM jsonb_array_elements(v) e)
      USING ERRCODE = 'AV539', DETAIL = v::text;
  END IF;
END
$$;


