--

CREATE FUNCTION core_comercial.fn_comercial_codigos_omie_problemas(p_codigo_empresa uuid, p_condicao text, p_categoria text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_agg(x.p ORDER BY x.o)
    FROM (
      SELECT 1 AS o, jsonb_build_object('campo', 'codigo_condicao_pagamento', 'valor', p_condicao,
               'mensagem', format('A condição de pagamento %s não existe (ou está inativa) no Omie desta unidade.', p_condicao)) AS p
       WHERE p_condicao IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.condicoes_pagamento_compras c
                          WHERE c.codigo_empresa = p_codigo_empresa AND c.codigo_omie = p_condicao AND c.ativo)
      UNION ALL
      SELECT 2, jsonb_build_object('campo', 'codigo_categoria', 'valor', p_categoria,
               'mensagem', format('A categoria %s não é uma categoria de receita ativa e lançável no Omie desta unidade.', p_categoria))
       WHERE p_categoria IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM core.categorias c
                          WHERE c.codigo_empresa = p_codigo_empresa AND c.codigo_categoria = p_categoria
                            AND c.deleted_at IS NULL AND c.ativo AND c.conta_receita IS TRUE
                            AND c.totalizadora IS NOT TRUE AND c.nao_exibir IS NOT TRUE)
    ) x;
$$;


