--
-- TOC entry 845 (class 1255 OID 25007)
-- Name: fn_divergencia_compra_decidir(uuid, uuid, boolean, text); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_divergencia_compra_decidir(p_id uuid, p_usuario uuid, p_aprovar boolean, p_comentario text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_oc  uuid;
  v_div record;
BEGIN
  SELECT d.id_ordem_compra INTO v_oc FROM core_comercial.divergencias_compra d WHERE d.id = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Divergência de compra não encontrada' USING ERRCODE = 'P0002';
  END IF;
  -- Trava a OC antes da divergência (mesma ordem em todas as funções): duas
  -- decisões na mesma OC ficam em fila e a última vê a primeira gravada.
  PERFORM 1 FROM core_vendas_faturamento.ordens_compra o WHERE o.id = v_oc FOR UPDATE;
  SELECT d.* INTO v_div FROM core_comercial.divergencias_compra d WHERE d.id = p_id FOR UPDATE;

  IF v_div.id_vendedor IS DISTINCT FROM p_usuario THEN
    RAISE EXCEPTION 'Só o vendedor do pedido decide esta divergência' USING ERRCODE = 'AV574';
  END IF;
  IF v_div.estado <> 'PENDENTE' THEN
    RAISE EXCEPTION 'A divergência não está mais pendente (estado atual: %)', v_div.estado
      USING ERRCODE = 'AV573', DETAIL = v_div.estado;
  END IF;

  UPDATE core_comercial.divergencias_compra
     SET estado = CASE WHEN p_aprovar THEN 'APROVADO' ELSE 'REPROVADO' END,
         decidido_por = p_usuario,
         decidido_em = now(),
         comentario_vendedor = NULLIF(btrim(p_comentario), '')
   WHERE id = p_id;

  IF p_aprovar THEN
    PERFORM core_comercial.fn_oc_liberar_apos_divergencia(v_oc);
  END IF;
  RETURN v_oc;
END
$$;


--
-- TOC entry 7164 (class 0 OID 0)
-- Dependencies: 845
-- Name: FUNCTION fn_divergencia_compra_decidir(p_id uuid, p_usuario uuid, p_aprovar boolean, p_comentario text); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_divergencia_compra_decidir(p_id uuid, p_usuario uuid, p_aprovar boolean, p_comentario text) IS 'LOG-57 R4/R5/R6: o vendedor do pedido (id_vendedor; outro usuário -> AV574) aprova ou reprova uma divergência PENDENTE (outro estado -> AV573, sem efeito). Aprovar chama fn_oc_liberar_apos_divergencia (a OC aprova sozinha abaixo do limite quando não há outra aberta). Reprovar leva à lista de Compras. Devolve o id da OC.';


--
-- TOC entry 584 (class 1255 OID 25008)
-- Name: fn_divergencia_compra_resolver(uuid, uuid, text, text); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_divergencia_compra_resolver(p_id uuid, p_usuario uuid, p_tipo text, p_motivo text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_oc     uuid;
  v_div    record;
  v_motivo text := NULLIF(btrim(p_motivo), '');
BEGIN
  IF p_tipo IS NULL OR p_tipo NOT IN ('MANTIDO', 'NOVO_VALOR', 'NOVO_FORNECEDOR', 'PEDIDO_CANCELADO') THEN
    RAISE EXCEPTION 'tipo deve ser MANTIDO, NOVO_VALOR, NOVO_FORNECEDOR ou PEDIDO_CANCELADO'
      USING ERRCODE = 'AV575';
  END IF;
  IF v_motivo IS NULL OR char_length(v_motivo) > 1000 THEN
    RAISE EXCEPTION 'motivo é obrigatório (até 1000 caracteres)' USING ERRCODE = 'AV575';
  END IF;

  SELECT d.id_ordem_compra INTO v_oc FROM core_comercial.divergencias_compra d WHERE d.id = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Divergência de compra não encontrada' USING ERRCODE = 'P0002';
  END IF;
  PERFORM 1 FROM core_vendas_faturamento.ordens_compra o WHERE o.id = v_oc FOR UPDATE;
  SELECT d.* INTO v_div FROM core_comercial.divergencias_compra d WHERE d.id = p_id FOR UPDATE;

  IF v_div.estado <> 'REPROVADO' THEN
    RAISE EXCEPTION 'Só divergência reprovada pelo vendedor recebe solução (estado atual: %)', v_div.estado
      USING ERRCODE = 'AV573', DETAIL = v_div.estado;
  END IF;

  UPDATE core_comercial.divergencias_compra
     SET estado = 'RESOLVIDO',
         solucao_tipo = p_tipo,
         solucao_motivo = v_motivo,
         resolvido_por = (SELECT u.id FROM auth.usuarios u WHERE u.id = p_usuario),
         resolvido_em = now()
   WHERE id = p_id;

  IF p_tipo = 'MANTIDO' THEN
    -- A Gerência autorizou: a OC segue como em R5.
    PERFORM core_comercial.fn_oc_liberar_apos_divergencia(v_oc);
  ELSE
    -- NOVO_VALOR / NOVO_FORNECEDOR / PEDIDO_CANCELADO: a OC é cancelada aqui
    -- (decisão do Gustavo, 12/11/2026); Compras emite outra, que passa de novo
    -- por R1. As outras divergências abertas da OC viram OC_CANCELADA (R11).
    UPDATE core_vendas_faturamento.ordens_compra
       SET status = 'cancelado',
           updated_by = (SELECT u.id FROM auth.usuarios u WHERE u.id = p_usuario),
           motivo_reprovacao = left(format('Divergência de compra (%s): %s', p_tipo, v_motivo), 2000)
     WHERE id = v_oc AND status <> 'cancelado';
  END IF;
  RETURN v_oc;
END
$$;


