--

COMMENT ON FUNCTION core_comercial.fn_divergencia_compra_resolver(p_id uuid, p_usuario uuid, p_tipo text, p_motivo text) IS 'LOG-57 R7: Compras registra a solução de uma divergência REPROVADO (outro estado -> AV573; tipo ou motivo inválido -> AV575). MANTIDO libera a OC (R5); NOVO_VALOR, NOVO_FORNECEDOR e PEDIDO_CANCELADO cancelam a OC na mesma transação (cancelado_por = quem registrou). Devolve o id da OC.';


--
-- TOC entry 768 (class 1255 OID 25000)
-- Name: fn_divergencias_compra_estado(); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_divergencias_compra_estado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- O que nasceu com a OC não muda (R10: o histórico é do que foi decidido).
  IF NEW.id_ordem_compra IS DISTINCT FROM OLD.id_ordem_compra
     OR NEW.id_ordem_compra_item IS DISTINCT FROM OLD.id_ordem_compra_item
     OR NEW.tipo IS DISTINCT FROM OLD.tipo
     OR NEW.valor_cotado IS DISTINCT FROM OLD.valor_cotado
     OR NEW.valor_compra IS DISTINCT FROM OLD.valor_compra
     OR NEW.id_vendedor IS DISTINCT FROM OLD.id_vendedor
     OR NEW.numero_pedido_venda IS DISTINCT FROM OLD.numero_pedido_venda
     OR NEW.codigo_produto_pv IS DISTINCT FROM OLD.codigo_produto_pv
     OR NEW.motivo_compras IS DISTINCT FROM OLD.motivo_compras THEN
    RAISE EXCEPTION 'Os dados da divergência de compra não mudam depois de criada'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.estado IS DISTINCT FROM OLD.estado THEN
    IF NOT (
         (OLD.estado = 'PENDENTE'  AND NEW.estado IN ('APROVADO', 'REPROVADO'))
      OR (OLD.estado = 'PENDENTE'  AND NEW.estado = 'RESOLVIDO' AND NEW.solucao_tipo = 'OC_CANCELADA')
      OR (OLD.estado = 'REPROVADO' AND NEW.estado = 'RESOLVIDO')
    ) THEN
      RAISE EXCEPTION 'A divergência não está mais pendente (estado atual: %)', OLD.estado
        USING ERRCODE = 'AV573', DETAIL = OLD.estado;
    END IF;
  ELSIF NEW.decidido_por IS DISTINCT FROM OLD.decidido_por
        OR NEW.solucao_tipo IS DISTINCT FROM OLD.solucao_tipo THEN
    RAISE EXCEPTION 'A divergência não está mais pendente (estado atual: %)', OLD.estado
      USING ERRCODE = 'AV573', DETAIL = OLD.estado;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END
$$;


--
-- TOC entry 698 (class 1255 OID 25002)
-- Name: fn_divergencias_compra_eventos(); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_divergencias_compra_eventos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_por uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.estado IS NOT DISTINCT FROM OLD.estado THEN
    RETURN NULL;
  END IF;

  v_por := CASE
             WHEN TG_OP = 'INSERT' THEN
               (SELECT o.created_by FROM core_vendas_faturamento.ordens_compra o WHERE o.id = NEW.id_ordem_compra)
             WHEN NEW.estado IN ('APROVADO', 'REPROVADO') THEN NEW.decidido_por
             WHEN NEW.estado = 'RESOLVIDO' THEN NEW.resolvido_por
           END;

  INSERT INTO core_comercial.divergencias_compra_eventos (id_divergencia, de_estado, para_estado, por, detalhe)
  VALUES (
    NEW.id,
    CASE WHEN TG_OP = 'UPDATE' THEN OLD.estado END,
    NEW.estado,
    (SELECT u.id FROM auth.usuarios u WHERE u.id = v_por),
    jsonb_strip_nulls(jsonb_build_object(
      'tipo', NEW.tipo,
      'valor_cotado', NEW.valor_cotado,
      'valor_compra', NEW.valor_compra,
      'motivo_compras', CASE WHEN TG_OP = 'INSERT' THEN NEW.motivo_compras END,
      'comentario_vendedor', CASE WHEN NEW.estado IN ('APROVADO', 'REPROVADO') THEN NEW.comentario_vendedor END,
      'solucao_tipo', CASE WHEN NEW.estado = 'RESOLVIDO' THEN NEW.solucao_tipo END,
      'solucao_motivo', CASE WHEN NEW.estado = 'RESOLVIDO' THEN NEW.solucao_motivo END))
  );
  RETURN NULL;
END
$$;


--
-- TOC entry 809 (class 1255 OID 25005)
-- Name: fn_divergencias_compra_gerar(uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_divergencias_compra_gerar(p_oc uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_oc       record;
  c          record;
  v_pend     integer;
BEGIN
  SELECT o.id, o.codigo_empresa, o.moeda, o.status
    INTO v_oc
    FROM core_vendas_faturamento.ordens_compra o
   WHERE o.id = p_oc
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ordem de compra % não encontrada', p_oc USING ERRCODE = 'P0002';
  END IF;

  -- Moeda estrangeira na OC: nada (R1).
  IF COALESCE(v_oc.moeda, 'BRL') = 'BRL' THEN
    -- Um candidato por vínculo (item da OC x PV x produto do PV), com o item
    -- do pedido do Hub que nasceu de proposta e a cotação de compra do item.
    -- Na ordem dos itens: o primeiro acima do cotado sem motivo é o do erro.
    FOR c IN
      SELECT q.*,
             CASE WHEN q.valor_compra > q.valor_cotado THEN 'ACIMA'
                  WHEN q.valor_compra < q.valor_cotado THEN 'ABAIXO' END AS tipo
        FROM (
          SELECT i.id AS id_ordem_compra_item, i.ordem, v.codigo_empresa_pv,
                 v.numero_pedido_venda, prod.codigo AS codigo_produto_pv,
                 hub.id AS id_pedido_hub, pvi.id_proposta_item,
                 pi.preco_unit_compra::numeric(15,4) AS valor_cotado,
                 round(i.valor_unitario * (1 - i.desconto / 100), 4)::numeric(15,4) AS valor_compra,
                 i.unidade_medida, v.quantidade,
                 COALESCE(pi.margem_item_pct, pr.margem_liquida_pct) AS margem,
                 NULLIF(btrim(i.motivo_divergencia), '') AS motivo,
                 COALESCE(hub.id_responsavel, pr.id_responsavel) AS id_vendedor
            FROM core_vendas_faturamento.ordens_compra_itens_vinculos v
            JOIN core_vendas_faturamento.ordens_compra_itens i ON i.id = v.id_ordem_compra_item
            -- Produto do PV: o do vínculo; sem ele, o do item da OC quando o
            -- PV é da mesma conta Omie da OC (o código do produto é por conta).
            CROSS JOIN LATERAL (
              SELECT COALESCE(v.codigo_produto_pv,
                              CASE WHEN v.codigo_empresa_pv = v_oc.codigo_empresa THEN i.codigo_produto END) AS codigo
            ) prod
            -- Pedido do Hub do PV (mesma regra da API-019, R9: o mais recente).
            JOIN LATERAL (
              SELECT pv.id, pv.id_proposta, pv.id_responsavel
                FROM core_comercial.pedidos_venda pv
               WHERE pv.codigo_empresa_omie = v.codigo_empresa_pv
                 AND NULLIF(ltrim(btrim(pv.numero_pedido_omie::text), '0'), '')
                     = NULLIF(ltrim(btrim(v.numero_pedido_venda), '0'), '')
                 AND pv.deleted_at IS NULL
                 AND pv.numero_pedido_omie IS NOT NULL
               ORDER BY pv.created_at DESC, pv.id DESC
               LIMIT 1
            ) hub ON true
            -- Item do pedido do Hub com o produto (o de menor ordem, como na API-019).
            JOIN LATERAL (
              SELECT x.id_proposta_item
                FROM core_comercial.pedidos_venda_itens x
               WHERE x.id_pedido = hub.id AND x.codigo_produto_omie = prod.codigo
               ORDER BY x.ordem, x.id
               LIMIT 1
            ) pvi ON true
            JOIN core_comercial.propostas_itens pi ON pi.id = pvi.id_proposta_item
            JOIN core_comercial.propostas pr       ON pr.id = hub.id_proposta
           WHERE v.id_ordem_compra = p_oc
             AND prod.codigo IS NOT NULL
             AND pi.preco_unit_compra IS NOT NULL
             -- Proposta em moeda estrangeira: nada (R1).
             AND COALESCE(pr.moeda, 'BRL') = 'BRL'
             -- Mesma unidade de medida da cotação (unidade de compra; sem ela,
             -- a do item da proposta). Unidade diferente: nada (R1).
             AND upper(btrim(i.unidade_medida))
                 = upper(btrim(COALESCE(NULLIF(btrim(pi.unidade_compra), ''), pi.unidade_medida)))
        ) q
       ORDER BY q.ordem, q.numero_pedido_venda, q.codigo_produto_pv
    LOOP
      CONTINUE WHEN c.tipo IS NULL;                       -- igual ao cotado: nada

      -- R9: acima do cotado exige o motivo de Compras, item a item.
      IF c.tipo = 'ACIMA' AND c.motivo IS NULL THEN
        RAISE EXCEPTION 'Item %: escreva o motivo da compra acima do cotado', c.ordem
          USING ERRCODE = 'AV571', DETAIL = c.ordem::text;
      END IF;

      -- Sem vendedor (pedido e proposta sem responsável): não há quem decida.
      IF c.id_vendedor IS NULL THEN
        RAISE WARNING 'LOG-57: OC %, item %: pedido % sem responsável; divergência não criada.',
          p_oc, c.ordem, c.numero_pedido_venda;
        CONTINUE;
      END IF;

      INSERT INTO core_comercial.divergencias_compra (
        codigo_empresa, codigo_empresa_pv, numero_pedido_venda, codigo_produto_pv,
        id_pedido_hub, id_proposta_item, id_ordem_compra, id_ordem_compra_item,
        tipo, estado, valor_cotado, valor_compra, unidade_medida, quantidade,
        margem_proposta_pct, motivo_compras, id_vendedor)
      VALUES (
        v_oc.codigo_empresa, c.codigo_empresa_pv, c.numero_pedido_venda, c.codigo_produto_pv,
        c.id_pedido_hub, c.id_proposta_item, p_oc, c.id_ordem_compra_item,
        c.tipo, CASE c.tipo WHEN 'ACIMA' THEN 'PENDENTE' ELSE 'INFORMATIVA' END,
        c.valor_cotado, c.valor_compra, c.unidade_medida, c.quantidade,
        c.margem, c.motivo, c.id_vendedor)
      ON CONFLICT (id_ordem_compra_item, codigo_empresa_pv, numero_pedido_venda, codigo_produto_pv) DO NOTHING;
    END LOOP;
  END IF;

  SELECT count(*) INTO v_pend
    FROM core_comercial.divergencias_compra d
   WHERE d.id_ordem_compra = p_oc AND d.estado = 'PENDENTE';

  -- R3/R5: com pendente a OC fica em aguardando_aprovacao; sem, segue o fluxo de hoje.
  PERFORM core_comercial.fn_oc_liberar_apos_divergencia(p_oc);
  RETURN v_pend;
END
$$;


--
-- TOC entry 7166 (class 0 OID 0)
-- Dependencies: 809
-- Name: FUNCTION fn_divergencias_compra_gerar(p_oc uuid); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_divergencias_compra_gerar(p_oc uuid) IS 'LOG-57 R1/R2/R9: na emissão da OC (mesma transação, depois dos itens e vínculos), compara o valor unitário do item da OC com desconto com o preco_unit_compra do item da proposta de onde nasceu o pedido do Hub do PV do vínculo (conta Omie + número sem zeros; mais recente; item de menor ordem com o produto). Acima -> PENDENTE (exige ordens_compra_itens.motivo_divergencia: AV571 "Item N: ..."); abaixo -> INFORMATIVA; igual, unidade diferente, moeda estrangeira, PV sem proposta ou item sem cotado -> nada. No fim chama fn_oc_liberar_apos_divergencia. Devolve quantas PENDENTE a OC tem.';


--
-- TOC entry 925 (class 1255 OID 22659)
-- Name: fn_documento_normalizado(text); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_documento_normalizado(p_documento text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT NULLIF(regexp_replace(upper(COALESCE(p_documento, '')), '[^0-9A-Z]', '', 'g'), '');
$$;


--
-- TOC entry 7167 (class 0 OID 0)
-- Dependencies: 925
-- Name: FUNCTION fn_documento_normalizado(p_documento text); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_documento_normalizado(p_documento text) IS 'Contrato 52 (§10 item 4): CPF/CNPJ só com [0-9A-Z] maiúsculo (tira ponto, barra, hífen e espaço; NÃO tira letras, por causa do CNPJ alfanumérico). Vazio vira NULL.';


--
-- TOC entry 1011 (class 1255 OID 22660)
-- Name: fn_documento_valido(text); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_documento_valido(p_documento text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $_$
DECLARE
  d     text := core_comercial.fn_documento_normalizado(p_documento);
  pesos int[];
  soma  int;
  resto int;
  dv1   int;
  dv2   int;
  i     int;
BEGIN
  IF d IS NULL THEN RETURN false; END IF;

  IF length(d) = 11 THEN
    -- CPF: só dígitos, módulo 11, sequência repetida é inválida.
    IF d !~ '^[0-9]{11}$' OR d ~ '^(.)\1{10}$' THEN RETURN false; END IF;
    soma := 0;
    FOR i IN 1..9 LOOP soma := soma + substr(d, i, 1)::int * (11 - i); END LOOP;
    resto := (soma * 10) % 11; dv1 := CASE WHEN resto = 10 THEN 0 ELSE resto END;
    soma := 0;
    FOR i IN 1..10 LOOP soma := soma + substr(d, i, 1)::int * (12 - i); END LOOP;
    resto := (soma * 10) % 11; dv2 := CASE WHEN resto = 10 THEN 0 ELSE resto END;
    RETURN substr(d, 10, 1)::int = dv1 AND substr(d, 11, 1)::int = dv2;
  END IF;

  IF length(d) = 14 THEN
    -- CNPJ (numérico ou alfanumérico): 12 posições [0-9A-Z] + 2 dígitos.
    -- Valor de cada posição = código ASCII - 48 (0-9 -> 0-9, A -> 17 ... Z -> 42).
    IF d !~ '^[0-9A-Z]{12}[0-9]{2}$' OR d ~ '^(.)\1{13}$' THEN RETURN false; END IF;
    pesos := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2];
    soma := 0;
    FOR i IN 1..12 LOOP soma := soma + (ascii(substr(d, i, 1)) - 48) * pesos[i]; END LOOP;
    resto := soma % 11; dv1 := CASE WHEN resto < 2 THEN 0 ELSE 11 - resto END;
    pesos := ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
    soma := 0;
    FOR i IN 1..12 LOOP soma := soma + (ascii(substr(d, i, 1)) - 48) * pesos[i]; END LOOP;
    soma := soma + dv1 * pesos[13];
    resto := soma % 11; dv2 := CASE WHEN resto < 2 THEN 0 ELSE 11 - resto END;
    RETURN substr(d, 13, 1)::int = dv1 AND substr(d, 14, 1)::int = dv2;
  END IF;

  RETURN false;
END $_$;


