--
-- TOC entry 815 (class 1255 OID 24833)
-- Name: fn_emissao_opcoes(uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_emissao_opcoes(p_usuario uuid) RETURNS TABLE(codigo_empresa uuid, sigla text, nome_curto text, id_usuario uuid, nome text, email text, origem text)
    LANGUAGE sql STABLE
    AS $$
  WITH cand AS (
    SELECT p_usuario AS id, 'proprio'::text AS origem, 1 AS ordem
    UNION ALL
    SELECT t.id, 'titular', 2
      FROM auth.usuarios eu
      JOIN core_vendas_faturamento.auxiliar_vendedor a
        ON a.id_funcionario_auxiliar = eu.id_funcionario AND a.deleted_at IS NULL
      JOIN auth.usuarios t
        ON t.id_funcionario = a.id_funcionario_titular AND t.deleted_at IS NULL AND t.ativo
     WHERE eu.id = p_usuario AND eu.id_funcionario IS NOT NULL AND t.id <> p_usuario
  ),
  unico AS (
    SELECT DISTINCT ON (c.id) c.id, c.origem, c.ordem FROM cand c ORDER BY c.id, c.ordem
  )
  SELECT un.id, un.sigla, cab.nome_documento, us.id, auth.fn_nome_usuario(us.id)::text, us.email::text, c.origem
    FROM core.unidades un
    JOIN core.vw_unidades_cabecalho cab ON cab.id = un.id
    CROSS JOIN unico c
    JOIN auth.usuarios us ON us.id = c.id
   WHERE un.deleted_at IS NULL
     AND core_comercial.fn_emissao_responsavel_situacao(p_usuario, un.id, c.id) = 'OK'
   ORDER BY un.sigla, c.ordem, 5, us.id;
$$;


--
-- TOC entry 7169 (class 0 OID 0)
-- Dependencies: 815
-- Name: FUNCTION fn_emissao_opcoes(p_usuario uuid); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_emissao_opcoes(p_usuario uuid) IS 'Pedido do Robert (11/11/2026), GET /comercial/emissao: para cada unidade, quem p_usuario pode pôr como responsável de uma proposta nova — ele mesmo (proprio) e os titulares que ele auxilia (titular), só os com situação OK em fn_emissao_responsavel_situacao (vendedor ativo no Omie da unidade e em fn_responsaveis_proposta). Unidade sem ninguém não sai. Delegação não entra na lista (o front não usa a tela propostas-delegacao), mas a gravação aceita. Ordem: sigla; o próprio usuário primeiro, depois os titulares por nome.';


--
-- TOC entry 1021 (class 1255 OID 24832)
-- Name: fn_emissao_responsavel_situacao(uuid, uuid, uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_emissao_responsavel_situacao(p_usuario uuid, p_codigo_empresa uuid, p_responsavel uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_sigla text;
BEGIN
  IF core_comercial.fn_emissao_vinculo(p_usuario, p_responsavel) IS NULL THEN
    RETURN 'FORA_DO_VINCULO';
  END IF;
  IF core_comercial.fn_pedido_venda_vendedor(p_responsavel, p_codigo_empresa) IS NULL THEN
    RETURN 'SEM_VENDEDOR';
  END IF;
  SELECT u.sigla INTO v_sigla FROM core.unidades u WHERE u.id = p_codigo_empresa AND u.deleted_at IS NULL;
  IF v_sigla IS NULL
     OR NOT EXISTS (SELECT 1 FROM core_comercial.fn_responsaveis_proposta(v_sigla) r WHERE r.id_usuario = p_responsavel) THEN
    RETURN 'NAO_HABILITADO';
  END IF;
  RETURN 'OK';
END
$$;


