--

CREATE FUNCTION core_comercial.fn_frete_modalidade_omie(p_incoterm text) RETURNS character varying
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT (CASE
            WHEN upper(btrim(p_incoterm)) IN ('CIF', 'CFR', 'CPT', 'CIP', 'DAP', 'DPU', 'DDP') THEN '0'
            WHEN upper(btrim(p_incoterm)) IN ('FOB', 'FCA', 'EXW') THEN '1'
          END)::character varying(1);
$$;


