-- TOC entry 803 (class 1255 OID 25004)
-- Name: fn_oc_liberar_apos_divergencia(uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_oc_liberar_apos_divergencia(p_oc uuid) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_oc     record;
  v_limite numeric(15,2);
BEGIN
  SELECT o.id, o.status, o.codigo_empresa, o.valor_total_brl
    INTO v_oc
    FROM core_vendas_faturamento.ordens_compra o
   WHERE o.id = p_oc
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ordem de compra % não encontrada', p_oc USING ERRCODE = 'P0002';
  END IF;

  IF v_oc.status <> 'aguardando_aprovacao' OR core_comercial.fn_oc_divergencia_aberta(p_oc) THEN
    RETURN v_oc.status;
  END IF;

  SELECT COALESCE(max(p.limite_aprovacao), 30000.00)
    INTO v_limite
    FROM core_vendas_faturamento.parametros_compras p
   WHERE p.codigo_empresa = v_oc.codigo_empresa;

  IF v_oc.valor_total_brl > v_limite THEN
    RETURN v_oc.status;
  END IF;

  -- Igual à aprovação automática da fn_ordens_compra_recalcular: aprovado_por
  -- nulo (o histórico registra "automática: valor abaixo do limite").
  UPDATE core_vendas_faturamento.ordens_compra
     SET status = 'aprovado'
   WHERE id = p_oc;
  RETURN 'aprovado';
END
$$;


