CREATE FUNCTION core_comercial.fn_ordens_compra_divergencias_cancelar() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE core_comercial.divergencias_compra d
     SET estado = 'RESOLVIDO',
         solucao_tipo = 'OC_CANCELADA',
         solucao_motivo = NULLIF(btrim(COALESCE(NEW.motivo_reprovacao, '')), ''),
         resolvido_por = NEW.cancelado_por,
         resolvido_em = now()
   WHERE d.id_ordem_compra = NEW.id
     AND d.estado IN ('PENDENTE', 'REPROVADO');
  RETURN NULL;
END
$$;


