--
-- TOC entry 666 (class 1255 OID 23528)
-- Name: fn_parametros_custo_salvar(jsonb, jsonb, integer, integer, integer, uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_parametros_custo_salvar(p_icms_recuperar jsonb, p_densidades jsonb, p_validade_dias integer, p_dias_historico integer, p_versao_esperada integer, p_usuario uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  c_origens  CONSTANT text[] := ARRAY['SP', 'SP_REDUZIDA', 'OUTRA_UF', 'IMPORTACAO_SP', 'IMPORTACAO_OUTRA_UF', 'SIMPLES'];
  v_hoje     date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_atual    core_comercial.parametros_custo%ROWTYPE;
  v_versao   integer;
  v_novo     uuid;
  v_chave    text;
  v_valor    jsonb;
  v_dens     jsonb;
BEGIN
  -- ICMS: exatamente as 6 origens, número de 0 a 100.
  IF p_icms_recuperar IS NULL OR jsonb_typeof(p_icms_recuperar) <> 'object' THEN
    RAISE EXCEPTION 'icms_recuperar deve ser um objeto com as origens %.', array_to_string(c_origens, ', ') USING ERRCODE = '23514';
  END IF;
  IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_icms_recuperar) k)
     IS DISTINCT FROM (SELECT array_agg(o ORDER BY o) FROM unnest(c_origens) o) THEN
    RAISE EXCEPTION 'icms_recuperar deve ter exatamente as origens %.', array_to_string(c_origens, ', ') USING ERRCODE = '23514';
  END IF;
  FOR v_chave, v_valor IN SELECT * FROM jsonb_each(p_icms_recuperar) LOOP
    IF jsonb_typeof(v_valor) <> 'number' OR (v_valor #>> '{}')::numeric NOT BETWEEN 0 AND 100 THEN
      RAISE EXCEPTION 'icms_recuperar.% deve ser um número de 0 a 100.', v_chave USING ERRCODE = '23514';
    END IF;
  END LOOP;
  IF p_densidades IS NOT NULL THEN
    IF jsonb_typeof(p_densidades) <> 'object' THEN
      RAISE EXCEPTION 'densidades deve ser um objeto (material -> g/cm³).' USING ERRCODE = '23514';
    END IF;
    FOR v_chave, v_valor IN SELECT * FROM jsonb_each(p_densidades) LOOP
      IF jsonb_typeof(v_valor) <> 'number' OR (v_valor #>> '{}')::numeric <= 0 THEN
        RAISE EXCEPTION 'densidades.% deve ser um número maior que zero.', v_chave USING ERRCODE = '23514';
      END IF;
    END LOOP;
  END IF;

  -- Uma gravação por vez (duas abas salvando juntas: a segunda vê a versão nova e leva AV521).
  PERFORM pg_advisory_xact_lock(hashtext('core_comercial.parametros_custo'));

  SELECT * INTO v_atual
    FROM core_comercial.parametros_custo
   WHERE substituida_em IS NULL AND vigencia_fim IS NULL
   ORDER BY vigencia_inicio DESC
   LIMIT 1;

  IF p_versao_esperada IS DISTINCT FROM COALESCE(v_atual.versao, 0) THEN
    RAISE EXCEPTION 'VERSAO_DESATUALIZADA'
      USING ERRCODE = 'AV521', DETAIL = COALESCE(v_atual.versao, 0)::text,
            HINT = 'Os parâmetros foram alterados por outra pessoa. Recarregue para ver a versão atual.';
  END IF;

  v_dens := COALESCE(p_densidades, v_atual.densidades, '{}'::jsonb);
  SELECT COALESCE(max(versao), 0) + 1 INTO v_versao FROM core_comercial.parametros_custo;

  IF v_atual.id IS NOT NULL THEN
    IF v_atual.vigencia_inicio >= v_hoje THEN
      -- Mesmo dia: a do dia vira substituída (fica no histórico).
      UPDATE core_comercial.parametros_custo SET substituida_em = now() WHERE id = v_atual.id;
    ELSE
      UPDATE core_comercial.parametros_custo SET vigencia_fim = v_hoje - 1 WHERE id = v_atual.id;
    END IF;
  END IF;

  INSERT INTO core_comercial.parametros_custo
    (versao, vigencia_inicio, icms_recuperar, densidades, validade_padrao_dias, dias_historico, created_by)
  VALUES
    (v_versao, GREATEST(v_hoje, COALESCE(v_atual.vigencia_inicio, v_hoje)), p_icms_recuperar, v_dens,
     p_validade_dias, p_dias_historico, p_usuario)
  RETURNING id INTO v_novo;

  IF v_atual.id IS NOT NULL AND v_atual.vigencia_inicio >= v_hoje THEN
    UPDATE core_comercial.parametros_custo SET substituida_por = v_novo WHERE id = v_atual.id;
  END IF;

  RETURN v_novo;
END $$;


--
-- TOC entry 7177 (class 0 OID 0)
-- Dependencies: 666
-- Name: FUNCTION fn_parametros_custo_salvar(p_icms_recuperar jsonb, p_densidades jsonb, p_validade_dias integer, p_dias_historico integer, p_versao_esperada integer, p_usuario uuid); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_parametros_custo_salvar(p_icms_recuperar jsonb, p_densidades jsonb, p_validade_dias integer, p_dias_historico integer, p_versao_esperada integer, p_usuario uuid) IS 'Contrato 52: grava uma nova versão dos parâmetros de custo. p_versao_esperada = versão atual que o cliente viu (If-Match; 0 = ainda não há nenhuma): diferente -> ERRCODE AV521 (DETAIL = versão atual; a API devolve 409 VERSAO_DESATUALIZADA). Valida o ICMS (as 6 origens, 0 a 100) e as densidades (> 0) -> 23514. p_densidades NULL = copia as da versão atual. Hoje (America/Sao_Paulo) > início da atual: fecha a atual em ontem e abre a nova hoje; mesmo dia: marca a atual como substituída. Devolve o id da nova versão.';


