--

CREATE FUNCTION core_comercial.fn_parametros_pedido_venda_omie_regras() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM core.contas_correntes cc
                  WHERE cc.codigo_empresa = NEW.codigo_empresa AND cc.codigo_conta_omie = NEW.codigo_conta_corrente
                    AND cc.deleted_at IS NULL AND cc.ativo) THEN
    RAISE EXCEPTION 'A conta corrente % não existe (ou está inativa) no Omie da unidade %.',
      NEW.codigo_conta_corrente, COALESCE((SELECT u.nome_fantasia FROM core.unidades u WHERE u.id = NEW.codigo_empresa), NEW.codigo_empresa::text)
      USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.created_at := OLD.created_at;
    NEW.created_by := OLD.created_by;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;


