CREATE FUNCTION core_comercial.fn_pedido_venda_conta_corrente_checar(p_id uuid, p_conta bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v  core_comercial.pedidos_venda%ROWTYPE;
  v_fat record;
BEGIN
  SELECT * INTO v FROM core_comercial.pedidos_venda WHERE id = p_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pedido não encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF v.status <> 'ABERTO' THEN
    RAISE EXCEPTION 'O pedido % está %: a conta corrente não muda.', v.numero_pedido, v.status
      USING ERRCODE = 'AV544', DETAIL = v.status;
  END IF;
  IF v.codigo_pedido_omie IS NOT NULL THEN
    SELECT p.faturado, p.cancelado INTO v_fat
      FROM core_vendas_faturamento.pedidos_vendas p
     WHERE p.codigo_empresa = COALESCE(v.codigo_empresa_omie, v.codigo_empresa) AND p.codigo_pedido_omie = v.codigo_pedido_omie;
    IF v_fat.faturado IS TRUE OR v_fat.cancelado IS TRUE THEN
      RAISE EXCEPTION 'O pedido % (número % no Omie) já está %: a conta corrente só muda antes do faturamento.',
        v.numero_pedido, v.numero_pedido_omie, CASE WHEN v_fat.faturado THEN 'faturado' ELSE 'cancelado' END
        USING ERRCODE = 'AV544', DETAIL = CASE WHEN v_fat.faturado THEN 'FATURADO' ELSE 'CANCELADO' END;
    END IF;
  END IF;
  IF v.status_sincronizacao_omie <> 'sincronizado' AND v.envio_omie_iniciado_em IS NOT NULL
     AND v.envio_omie_iniciado_em > now() - interval '3 minutes' THEN
    RAISE EXCEPTION 'O pedido % está sendo enviado ao Omie agora. Tente de novo em instantes.', v.numero_pedido USING ERRCODE = 'AV541';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM core.contas_correntes cc
                  WHERE cc.codigo_empresa = COALESCE(v.codigo_empresa_omie, v.codigo_empresa)
                    AND cc.codigo_conta_omie = p_conta AND cc.deleted_at IS NULL AND cc.ativo) THEN
    RAISE EXCEPTION 'A conta corrente % não existe (ou está inativa) no Omie da unidade deste pedido.', p_conta
      USING ERRCODE = 'AV543', DETAIL = p_conta::text;
  END IF;
  RETURN jsonb_build_object('id', v.id, 'numero_pedido', v.numero_pedido, 'codigo_empresa', COALESCE(v.codigo_empresa_omie, v.codigo_empresa),
                            'codigo_pedido_omie', v.codigo_pedido_omie::text, 'no_omie', v.status_sincronizacao_omie = 'sincronizado',
                            'conta_atual', v.codigo_conta_corrente::text,
                            'mesma', v.codigo_conta_corrente IS NOT DISTINCT FROM p_conta);
END $$;


