-- Name: FUNCTION fn_pedido_venda_conta_corrente_checar(p_id uuid, p_conta bigint); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_pedido_venda_conta_corrente_checar(p_id uuid, p_conta bigint) IS 'LOG-56 §8.2: regras da troca da conta corrente — pedido ABERTO e não faturado/cancelado no espelho do Omie (AV544 -> 409 PEDIDO_FATURADO), sem envio ao Omie em andamento (AV541 -> 409), conta existente e ativa na conta Omie do pedido (AV543 -> 422 CONTA_CORRENTE_FORA_DA_UNIDADE). Só leitura; usada por _iniciar e _gravar.';


--
-- TOC entry 945 (class 1255 OID 24736)
-- Name: fn_pedido_venda_conta_corrente_gravar(uuid, bigint, uuid, boolean); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_pedido_venda_conta_corrente_gravar(p_id uuid, p_conta bigint, p_usuario uuid, p_no_omie boolean) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_c jsonb;
BEGIN
  IF p_usuario IS NULL THEN RAISE EXCEPTION 'Usuário obrigatório.' USING ERRCODE = '23514'; END IF;
  PERFORM 1 FROM core_comercial.pedidos_venda WHERE id = p_id FOR UPDATE;
  v_c := core_comercial.fn_pedido_venda_conta_corrente_checar(p_id, p_conta);
  -- O pedido mudou de estado entre o início e a gravação (ex.: o envio terminou):
  -- gravar agora deixaria Hub e Omie diferentes.
  IF (v_c->>'no_omie')::boolean IS DISTINCT FROM p_no_omie THEN
    RAISE EXCEPTION 'O pedido % mudou enquanto a conta era trocada (envio ao Omie). Recarregue e tente de novo.', v_c->>'numero_pedido'
      USING ERRCODE = 'AV541';
  END IF;
  UPDATE core_comercial.pedidos_venda
     SET codigo_conta_corrente = p_conta, conta_corrente_troca_em = NULL,
         versao = CASE WHEN codigo_conta_corrente IS DISTINCT FROM p_conta THEN versao + 1 ELSE versao END,
         updated_by = p_usuario
   WHERE id = p_id;
  RETURN v_c;
END $$;


