--

COMMENT ON FUNCTION core_comercial.fn_pedido_venda_conta_corrente_gravar(p_id uuid, p_conta bigint, p_usuario uuid, p_no_omie boolean) IS 'LOG-56 §8.2, depois que o Omie aceitou (ou direto, se o pedido ainda não está no Omie): confere de novo, sob trava de linha, grava a conta e solta a trava da troca. O histórico sai pela trigger trg_pedidos_venda_conta_corrente_historico. p_no_omie = o que _iniciar devolveu: se o estado mudou no meio, AV541.';


--
-- TOC entry 1009 (class 1255 OID 24735)
-- Name: fn_pedido_venda_conta_corrente_iniciar(uuid, bigint); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_pedido_venda_conta_corrente_iniciar(p_id uuid, p_conta bigint) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_trava timestamptz;
  v_c     jsonb;
BEGIN
  SELECT conta_corrente_troca_em INTO v_trava FROM core_comercial.pedidos_venda WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  v_c := core_comercial.fn_pedido_venda_conta_corrente_checar(p_id, p_conta);
  IF (v_c->>'mesma')::boolean THEN
    RETURN v_c;   -- nada a trocar: não trava nem chama o Omie
  END IF;
  IF v_trava IS NOT NULL AND v_trava > now() - interval '2 minutes' THEN
    RAISE EXCEPTION 'A conta corrente do pedido % já está sendo trocada por outra pessoa. Recarregue e tente de novo.', v_c->>'numero_pedido'
      USING ERRCODE = 'AV541';
  END IF;
  UPDATE core_comercial.pedidos_venda SET conta_corrente_troca_em = clock_timestamp() WHERE id = p_id;
  RETURN v_c;
END $$;


