--
-- TOC entry 536 (class 1255 OID 24660)
-- Name: fn_pedido_venda_envio_iniciar(uuid, uuid, jsonb); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_pedido_venda_envio_iniciar(p_id uuid, p_usuario uuid, p_dados jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v       core_comercial.pedidos_venda%ROWTYPE;
  v_dados jsonb := COALESCE(p_dados, '{}'::jsonb);
  v_pend  jsonb;
  v_pay   jsonb;
BEGIN
  IF p_usuario IS NULL THEN RAISE EXCEPTION 'Usuário obrigatório.' USING ERRCODE = '23514'; END IF;
  SELECT * INTO v FROM core_comercial.pedidos_venda WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pedido não encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF v.status <> 'ABERTO' THEN
    RAISE EXCEPTION 'Pedido % não pode ir ao Omie.', v.status USING ERRCODE = 'AV532', DETAIL = v.status;
  END IF;
  IF v.status_sincronizacao_omie = 'sincronizado' THEN
    RAISE EXCEPTION 'O pedido % já está no Omie (número %).', v.numero_pedido, v.numero_pedido_omie
      USING ERRCODE = 'AV542', DETAIL = COALESCE(v.numero_pedido_omie, '');
  END IF;
  IF v.envio_omie_iniciado_em IS NOT NULL AND v.envio_omie_iniciado_em > now() - interval '3 minutes' THEN
    RAISE EXCEPTION 'O pedido % já está sendo enviado ao Omie. Aguarde o resultado.', v.numero_pedido USING ERRCODE = 'AV541';
  END IF;

  UPDATE core_comercial.pedidos_venda pv
     SET data_previsao = COALESCE(core_comercial.fn_data_do_corpo(v_dados->>'data_previsao'), pv.data_previsao),
         numero_pedido_cliente = CASE WHEN v_dados ? 'numero_pedido_cliente' THEN NULLIF(btrim(v_dados->>'numero_pedido_cliente'), '')
                                      ELSE pv.numero_pedido_cliente END,
         bloqueado = COALESCE((v_dados->>'bloqueado')::boolean, pv.bloqueado),
         codigo_categoria = COALESCE(NULLIF(btrim(v_dados->>'codigo_categoria'), ''), pv.codigo_categoria),
         numero_contrato = CASE WHEN v_dados ? 'numero_contrato' THEN NULLIF(upper(btrim(v_dados->>'numero_contrato')), '')
                                ELSE pv.numero_contrato END,
         frete_modalidade = COALESCE(NULLIF(btrim(v_dados->>'frete_modalidade'), ''), pv.frete_modalidade),
         dados_adicionais_nf = CASE WHEN v_dados ? 'dados_adicionais_nf' THEN NULLIF(btrim(v_dados->>'dados_adicionais_nf'), '')
                                    ELSE pv.dados_adicionais_nf END,
         -- LOG-56 §7.1: ausente = mantém (pedido antigo reenvia com NULL).
         qualidade_acompanha = COALESCE((v_dados->>'qualidade_acompanha')::boolean, pv.qualidade_acompanha),
         faturar_em_partes = COALESCE((v_dados->>'faturar_em_partes')::boolean, pv.faturar_em_partes),
         -- LOG-56 R11: pedido anterior à regra ganha a conta padrão da conta Omie.
         codigo_conta_corrente = COALESCE(pv.codigo_conta_corrente, core_comercial.fn_conta_corrente_padrao(pv.codigo_empresa)),
         codigo_parcela = COALESCE(pv.codigo_parcela, (SELECT p.codigo_condicao_pagamento FROM core_comercial.propostas p WHERE p.id = pv.id_proposta)),
         codigo_vendedor_omie = COALESCE(core_comercial.fn_pedido_venda_vendedor(pv.id_responsavel, pv.codigo_empresa), pv.codigo_vendedor_omie),
         codigo_cliente_omie = COALESCE((SELECT pa.codigo_parceiro_omie FROM core.parceiros pa WHERE pa.id = pv.id_cliente), pv.codigo_cliente_omie),
         codigo_empresa_omie = pv.codigo_empresa,
         updated_by = p_usuario
   WHERE pv.id = p_id;

  v_pend := core_comercial.fn_pedido_venda_pendencias(p_id);
  IF jsonb_array_length(v_pend) > 0 THEN
    RAISE EXCEPTION '%', 'O pedido não pode ir ao Omie: ' || (SELECT string_agg(e->>'mensagem', ' ') FROM jsonb_array_elements(v_pend) e)
      USING ERRCODE = 'AV540', DETAIL = v_pend::text;
  END IF;

  v_pay := core_comercial.fn_pedido_venda_payload_omie(p_id);
  UPDATE core_comercial.pedidos_venda
     SET envio_omie_iniciado_em = now(), tentativas_envio_omie = tentativas_envio_omie + 1, payload_omie = v_pay,
         updated_by = p_usuario
   WHERE id = p_id;
  RETURN jsonb_build_object('id', v.id, 'numero_pedido', v.numero_pedido, 'id_proposta', v.id_proposta,
                            'codigo_empresa', v.codigo_empresa, 'payload', v_pay);
END
$$;


--
-- TOC entry 7182 (class 0 OID 0)
-- Dependencies: 536
-- Name: FUNCTION fn_pedido_venda_envio_iniciar(p_id uuid, p_usuario uuid, p_dados jsonb); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_pedido_venda_envio_iniciar(p_id uuid, p_usuario uuid, p_dados jsonb) IS 'Começo do envio ao Omie (transformar e "Tentar novamente"): trava, aplica os campos do corpo (ausente = mantém), confere a prontidão (AV540), um envio por vez (AV541), não reenvia o sincronizado (AV542), grava a trava e devolve o payload. LOG-56: aceita qualidade_acompanha e faturar_em_partes (opcionais, §7.1) e completa a conta corrente padrão no pedido anterior à regra.';


