-- TOC entry 612 (class 1255 OID 24662)
-- Name: fn_pedido_venda_omie_erro(uuid, text, uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_pedido_venda_omie_erro(p_id uuid, p_mensagem text, p_usuario uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v     core_comercial.pedidos_venda%ROWTYPE;
  v_msg text := left(COALESCE(NULLIF(btrim(p_mensagem), ''), 'Falha no envio ao Omie (sem mensagem).'), 2000);
BEGIN
  SELECT * INTO v FROM core_comercial.pedidos_venda WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado.' USING ERRCODE = 'P0002'; END IF;
  IF v.status_sincronizacao_omie = 'sincronizado' THEN
    UPDATE core_comercial.pedidos_venda SET envio_omie_iniciado_em = NULL WHERE id = p_id;
    RETURN;  -- não desfaz um sucesso
  END IF;
  UPDATE core_comercial.pedidos_venda
     SET status_sincronizacao_omie = 'erro', erro_sincronizacao_omie = v_msg, envio_omie_iniciado_em = NULL,
         versao = versao + 1, updated_by = p_usuario
   WHERE id = p_id;
  INSERT INTO core_comercial.propostas_eventos (id_proposta, tipo, dados, id_usuario)
  VALUES (v.id_proposta, 'PEDIDO_ERRO',
          jsonb_build_object('id_pedido', v.id, 'numero_pedido', v.numero_pedido, 'mensagem', v_msg, 'tentativa', v.tentativas_envio_omie),
          p_usuario);
END
$$;


--
-- TOC entry 7183 (class 0 OID 0)
-- Dependencies: 612
-- Name: FUNCTION fn_pedido_venda_omie_erro(p_id uuid, p_mensagem text, p_usuario uuid); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_pedido_venda_omie_erro(p_id uuid, p_mensagem text, p_usuario uuid) IS 'Retorno de falha do envio ao Omie: status_sincronizacao_omie = erro com a mensagem (a description/faultstring do Omie como veio, até 2000), trava solta, evento PEDIDO_ERRO. O pedido do Hub permanece e pode ser reenviado (POST /comercial/pedidos/{id}/enviar-omie). Não desfaz pedido já sincronizado.';


--
-- TOC entry 571 (class 1255 OID 24661)
-- Name: fn_pedido_venda_omie_registrar(uuid, bigint, text, uuid, boolean); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_pedido_venda_omie_registrar(p_id uuid, p_codigo_pedido_omie bigint, p_numero_pedido_omie text, p_usuario uuid, p_ja_existia boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v        core_comercial.pedidos_venda%ROWTYPE;
  v_numero text := NULLIF(left(btrim(COALESCE(p_numero_pedido_omie, '')), 15), '');
BEGIN
  IF p_codigo_pedido_omie IS NULL OR p_codigo_pedido_omie <= 0 THEN
    RAISE EXCEPTION 'codigo_pedido_omie obrigatório.' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO v FROM core_comercial.pedidos_venda WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado.' USING ERRCODE = 'P0002'; END IF;
  IF v.status_sincronizacao_omie = 'sincronizado' THEN
    IF v.codigo_pedido_omie = p_codigo_pedido_omie THEN RETURN; END IF;
    RAISE EXCEPTION 'O pedido % já está sincronizado com outro código do Omie (%).', v.numero_pedido, v.codigo_pedido_omie
      USING ERRCODE = 'AV542', DETAIL = COALESCE(v.numero_pedido_omie, '');
  END IF;

  UPDATE core_comercial.pedidos_venda
     SET status_sincronizacao_omie = 'sincronizado', codigo_pedido_omie = p_codigo_pedido_omie,
         numero_pedido_omie = COALESCE(v_numero, numero_pedido_omie), sincronizado_em = now(),
         erro_sincronizacao_omie = NULL, envio_omie_iniciado_em = NULL, versao = versao + 1, updated_by = p_usuario
   WHERE id = p_id;

  -- A v1 passa a ter o número do Omie: é por ele que a comissão encontra o faturamento.
  UPDATE core_comissionamento.simulacoes s
     SET numero_pedido = COALESCE(v_numero, s.numero_pedido), codigo_pedido_omie = p_codigo_pedido_omie, updated_by = p_usuario
   WHERE s.deleted_at IS NULL
     AND (s.id = v.id_simulacao
          OR (v.id_simulacao IS NULL AND s.origem = 'VENDEDOR' AND s.codigo_empresa = v.codigo_empresa_omie
              AND s.numero_pedido = v.numero_pedido));

  INSERT INTO core_comercial.propostas_eventos (id_proposta, tipo, dados, id_usuario)
  VALUES (v.id_proposta, 'PEDIDO_ENVIADO',
          jsonb_build_object('id_pedido', v.id, 'numero_pedido', v.numero_pedido, 'numero_pedido_omie', v_numero,
                             'codigo_pedido_omie', p_codigo_pedido_omie, 'ja_existia_no_omie', COALESCE(p_ja_existia, false),
                             'tentativa', v.tentativas_envio_omie),
          p_usuario);
END
$$;


