-- Name: FUNCTION fn_pedido_venda_omie_registrar(p_id uuid, p_codigo_pedido_omie bigint, p_numero_pedido_omie text, p_usuario uuid, p_ja_existia boolean); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_pedido_venda_omie_registrar(p_id uuid, p_codigo_pedido_omie bigint, p_numero_pedido_omie text, p_usuario uuid, p_ja_existia boolean) IS 'Retorno de sucesso do Omie (IncluirPedido, ou ConsultarPedido que achou o pedido pelo codigo_pedido_integracao): pedido sincronizado com codigo_pedido_omie / numero_pedido_omie / sincronizado_em, erro limpo, trava solta; simulação v1 (id_simulacao) com numero_pedido = número do Omie e codigo_pedido_omie; evento PEDIDO_ENVIADO {numero_pedido_omie, codigo_pedido_omie, ja_existia_no_omie}. Idempotente para o mesmo código; outro código num pedido já sincronizado = AV542.';


--
-- TOC entry 586 (class 1255 OID 24656)
-- Name: fn_pedido_venda_payload_omie(uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_pedido_venda_payload_omie(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $_$
  SELECT jsonb_build_object(
           'cabecalho', jsonb_strip_nulls(jsonb_build_object(
             'codigo_cliente', CASE WHEN btrim(pa.codigo_parceiro_omie) ~ '^[0-9]+$' THEN btrim(pa.codigo_parceiro_omie)::bigint END,
             'codigo_pedido_integracao', pv.numero_pedido,
             'data_previsao', to_char(pv.data_previsao, 'DD/MM/YYYY'),
             'etapa', pv.etapa,
             'codigo_parcela', pv.codigo_parcela,
             'bloqueado', CASE WHEN pv.bloqueado THEN 'S' ELSE 'N' END,
             'quantidade_itens', (SELECT count(*) FROM core_comercial.pedidos_venda_itens i WHERE i.id_pedido = pv.id))),
           'det', COALESCE((
             SELECT jsonb_agg(jsonb_build_object(
                      'ide', jsonb_build_object('codigo_item_integracao', i.ordem::text),
                      'produto', jsonb_strip_nulls(jsonb_build_object(
                        'codigo_produto', CASE WHEN btrim(pr.codigo_produto_omie) ~ '^[0-9]+$' THEN btrim(pr.codigo_produto_omie)::bigint END,
                        'descricao', left(i.descricao, 120),
                        'quantidade', i.quantidade,
                        'unidade', i.unidade_medida,
                        'valor_unitario', i.preco_unitario,
                        'tipo_desconto', CASE WHEN i.desconto_pct > 0 THEN 'P' END,
                        'percentual_desconto', CASE WHEN i.desconto_pct > 0 THEN i.desconto_pct END))) ORDER BY i.ordem)
               FROM core_comercial.pedidos_venda_itens i
               LEFT JOIN core.produtos pr ON pr.id = i.id_produto
              WHERE i.id_pedido = pv.id), '[]'::jsonb),
           'informacoes_adicionais', jsonb_strip_nulls(jsonb_build_object(
             'codVend', CASE WHEN btrim(pv.codigo_vendedor_omie) ~ '^[0-9]+$' THEN btrim(pv.codigo_vendedor_omie)::bigint END,
             'codigo_categoria', pv.codigo_categoria,
             'codigo_conta_corrente', pv.codigo_conta_corrente,
             'numero_pedido_cliente', NULLIF(left(btrim(pv.numero_pedido_cliente), 15), ''),
             'numero_contrato', pv.numero_contrato,
             'dados_adicionais_nf', NULLIF(btrim(pv.dados_adicionais_nf), ''),
             'consumidor_final', CASE WHEN pv.finalidade = 'CONSUMO_FINAL' THEN 'S' ELSE 'N' END,
             'enviar_email', 'N')))
         || CASE WHEN NULLIF(btrim(pv.observacoes), '') IS NOT NULL
                 THEN jsonb_build_object('observacoes', jsonb_build_object('obs_venda', btrim(pv.observacoes)))
                 ELSE '{}'::jsonb END
         || CASE WHEN pv.frete_modalidade IS NOT NULL
                 THEN jsonb_build_object('frete', jsonb_build_object('modalidade', pv.frete_modalidade))
                 ELSE '{}'::jsonb END
    FROM core_comercial.pedidos_venda pv
    LEFT JOIN core.parceiros pa ON pa.id = pv.id_cliente
   WHERE pv.id = p_id;
$_$;


