--
-- TOC entry 725 (class 1255 OID 24655)
-- Name: fn_pedido_venda_pendencias(uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_pedido_venda_pendencias(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  v       core_comercial.pedidos_venda%ROWTYPE;
  v_pa    record;
  v_n     integer;
  v_hoje  date := core_comercial.fn_hoje();
  r       jsonb := '[]'::jsonb;
  v_cod   jsonb;
BEGIN
  SELECT * INTO v FROM core_comercial.pedidos_venda WHERE id = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pedido não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF v.data_previsao IS NULL THEN
    r := r || jsonb_build_object('campo', 'data_previsao', 'mensagem', 'Informe a previsão de faturamento.');
  ELSIF v.data_previsao < v_hoje THEN
    r := r || jsonb_build_object('campo', 'data_previsao',
      'mensagem', format('A previsão de faturamento (%s) é anterior a hoje: o Omie não aceita.', to_char(v.data_previsao, 'DD/MM/YYYY')));
  END IF;

  SELECT pa.codigo_empresa, pa.codigo_parceiro_omie, pa.deleted_at, pa.inativo, pa.razao_social INTO v_pa
    FROM core.parceiros pa WHERE pa.id = v.id_cliente;
  IF v_pa IS NULL OR v_pa.deleted_at IS NOT NULL OR v_pa.codigo_empresa <> v.codigo_empresa
     OR COALESCE(btrim(v_pa.codigo_parceiro_omie), '') !~ '^[0-9]+$' THEN
    r := r || jsonb_build_object('campo', 'cliente', 'mensagem', 'O cliente não tem cadastro no Omie desta unidade (codigo_parceiro_omie).');
  ELSIF v_pa.inativo IS TRUE THEN
    r := r || jsonb_build_object('campo', 'cliente', 'mensagem', format('O cliente %s está inativo no Omie desta unidade.', v_pa.razao_social));
  END IF;

  SELECT count(*) INTO v_n FROM core_comercial.pedidos_venda_itens WHERE id_pedido = p_id;
  IF v_n = 0 THEN
    r := r || jsonb_build_object('campo', 'itens', 'mensagem', 'O pedido não tem itens.');
  ELSIF v_n > 199 THEN
    r := r || jsonb_build_object('campo', 'itens', 'mensagem', format('O Omie aceita até 199 itens por pedido (este tem %s).', v_n));
  END IF;
  r := r || COALESCE((
    SELECT jsonb_agg(jsonb_build_object('campo', 'itens', 'item', i.ordem, 'id_produto', i.id_produto,
             'mensagem', format('item %s — %s ', i.ordem, left(i.descricao, 80)) ||
               CASE
                 WHEN pr.id IS NULL OR pr.deleted_at IS NOT NULL OR pr.codigo_empresa <> v.codigo_empresa
                   THEN 'não está no catálogo desta unidade.'
                 WHEN NOT pr.ativo THEN 'está inativo no catálogo desta unidade.'
                 ELSE 'não tem código do Omie (codigo_produto_omie).'
               END) ORDER BY i.ordem)
      FROM core_comercial.pedidos_venda_itens i
      LEFT JOIN core.produtos pr ON pr.id = i.id_produto
     WHERE i.id_pedido = p_id
       AND (pr.id IS NULL OR pr.deleted_at IS NOT NULL OR pr.codigo_empresa <> v.codigo_empresa OR NOT pr.ativo
            OR COALESCE(btrim(pr.codigo_produto_omie), '') !~ '^[0-9]+$')), '[]'::jsonb);

  IF v.codigo_parcela IS NULL THEN
    r := r || jsonb_build_object('campo', 'codigo_condicao_pagamento',
      'mensagem', 'A proposta não tem a condição de pagamento do Omie: revise a proposta e escolha a condição.');
  END IF;
  IF v.codigo_categoria IS NULL THEN
    r := r || jsonb_build_object('campo', 'codigo_categoria', 'mensagem', 'Escolha a categoria (receita) do Omie.');
  END IF;
  v_cod := core_comercial.fn_comercial_codigos_omie_problemas(v.codigo_empresa, v.codigo_parcela, v.codigo_categoria);
  IF v_cod IS NOT NULL THEN r := r || v_cod; END IF;
  IF v.frete_modalidade IS NULL THEN
    r := r || jsonb_build_object('campo', 'frete_modalidade', 'mensagem', 'Escolha a modalidade do frete.');
  END IF;

  IF core_comercial.fn_pedido_venda_vendedor(v.id_responsavel, v.codigo_empresa) IS NULL THEN
    r := r || jsonb_build_object('campo', 'vendedor',
      'mensagem', format('O responsável (%s) não tem vendedor ativo no Omie desta unidade: sem ele o pedido some do Hub e da comissão.',
                         COALESCE(auth.fn_nome_usuario(v.id_responsavel), v.id_responsavel::text)));
  END IF;

  IF v.moeda <> 'BRL' THEN
    r := r || jsonb_build_object('campo', 'moeda',
      'mensagem', format('Pedido em %s: o Omie não tem moeda e a conversão para reais ainda não existe.', v.moeda));
  END IF;

  -- LOG-56 R11 (§7.4/§7.8): sem conta corrente o Omie recusa o pedido. A falta é da
  -- configuração da unidade, não do vendedor: a mensagem diz qual unidade e com quem resolver.
  IF v.codigo_conta_corrente IS NULL THEN
    r := r || jsonb_build_object('campo', 'codigo_conta_corrente', 'codigo', 'UNIDADE_SEM_CONFIG',
      'codigo_empresa', COALESCE(v.codigo_empresa_omie, v.codigo_empresa),
      'unidade', (SELECT u.nome_fantasia FROM core.unidades u WHERE u.id = COALESCE(v.codigo_empresa_omie, v.codigo_empresa)),
      'mensagem', format('A unidade %s não tem a conta corrente padrão do Omie configurada. Não é o vendedor que resolve: avise o Gustavo (configuração do banco).',
                         COALESCE((SELECT u.nome_fantasia FROM core.unidades u WHERE u.id = COALESCE(v.codigo_empresa_omie, v.codigo_empresa)), 'do pedido')));
  ELSIF NOT EXISTS (SELECT 1 FROM core.contas_correntes cc
                     WHERE cc.codigo_empresa = COALESCE(v.codigo_empresa_omie, v.codigo_empresa)
                       AND cc.codigo_conta_omie = v.codigo_conta_corrente AND cc.deleted_at IS NULL AND cc.ativo) THEN
    r := r || jsonb_build_object('campo', 'codigo_conta_corrente', 'codigo', 'CONTA_CORRENTE_INATIVA',
      'valor', v.codigo_conta_corrente::text,
      'mensagem', format('A conta corrente %s do pedido não está ativa no Omie desta unidade: o financeiro precisa trocar a conta do pedido.', v.codigo_conta_corrente));
  END IF;
  RETURN r;
END
$_$;


