COMMENT ON FUNCTION core_comercial.fn_pedido_venda_pendencias(p_id uuid) IS 'Prontidão do pedido do Hub para o Omie: lista {campo, mensagem, ...} de tudo o que falta, de uma vez (pedido do Robert de 05/11). LOG-56: + codigo_conta_corrente (codigo UNIDADE_SEM_CONFIG quando a conta Omie não tem a conta padrão; CONTA_CORRENTE_INATIVA quando a conta do pedido saiu do cadastro). Usada por fn_proposta_transformar (AV540, nada fica) e fn_pedido_venda_envio_iniciar.';


--
-- TOC entry 963 (class 1255 OID 24654)
-- Name: fn_pedido_venda_vendedor(uuid, uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_pedido_venda_vendedor(p_responsavel uuid, p_codigo_empresa uuid) RETURNS character varying
    LANGUAGE sql STABLE
    AS $$
  SELECT vd.codigo_vendedor_omie
    FROM auth.usuarios u
    JOIN core_vendas_faturamento.vendedores vd
      ON (vd.id_funcionario = u.id_funcionario OR vd.id_usuario = u.id)
     AND vd.deleted_at IS NULL AND vd.ativo IS TRUE
   WHERE u.id = p_responsavel
     AND vd.codigo_empresa = p_codigo_empresa
     AND NULLIF(btrim(vd.codigo_vendedor_omie), '') IS NOT NULL
   ORDER BY (vd.id_funcionario = u.id_funcionario) DESC NULLS LAST, vd.updated_at DESC
   LIMIT 1;
$$;


