CREATE FUNCTION core_comercial.fn_pedidos_venda_conta_corrente_historico() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO core_comercial.pedidos_venda_conta_corrente_historico
    (id_pedido, numero_pedido, conta_anterior, conta_nova, no_omie, usuario)
  VALUES (NEW.id, NEW.numero_pedido, OLD.codigo_conta_corrente, NEW.codigo_conta_corrente,
