--
-- TOC entry 763 (class 1255 OID 24708)
-- Name: fn_pedidos_venda_conta_corrente_valida(); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_pedidos_venda_conta_corrente_valida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.codigo_conta_corrente IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND NEW.codigo_conta_corrente IS NOT DISTINCT FROM OLD.codigo_conta_corrente
     AND NEW.codigo_empresa_omie IS NOT DISTINCT FROM OLD.codigo_empresa_omie THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM core.contas_correntes cc
                  WHERE cc.codigo_empresa = COALESCE(NEW.codigo_empresa_omie, NEW.codigo_empresa)
                    AND cc.codigo_conta_omie = NEW.codigo_conta_corrente AND cc.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'A conta corrente % não é da conta Omie deste pedido.', NEW.codigo_conta_corrente
      USING ERRCODE = 'AV543', DETAIL = NEW.codigo_conta_corrente::text;
  END IF;
  RETURN NEW;
END $$;


