--

CREATE FUNCTION core_comercial.fn_proposta_analise_gravar(p_id uuid, p jsonb) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE core_comercial.propostas x
     SET estado_destino           = NULLIF(btrim(p->>'estado_destino'), ''),
         condicao_pagamento_chave = NULLIF(btrim(p->>'condicao_pagamento_chave'), ''),
         encargo_pagamento        = CASE WHEN p ? 'encargo_pagamento'
                                         THEN NULLIF(btrim(p->>'encargo_pagamento'), '')::numeric
                                         ELSE x.encargo_pagamento END,
         frete_compra_tipo        = COALESCE(NULLIF(p->>'frete_compra_tipo', ''), 'RATEIO'),
         imposto_retido_difal     = COALESCE(NULLIF(p->>'imposto_retido_difal', '')::numeric, 0),
         frete_compra_valor       = COALESCE(NULLIF(p->>'frete_compra_valor', '')::numeric, 0),
         id_parametros            = NULLIF(p->'analise'->>'id_parametros', '')::uuid,
         margem_liquida_pct       = NULLIF(p->'analise'->>'margem_liquida_pct', '')::numeric,
         letra                    = NULLIF(p->'analise'->>'letra', ''),
         markup_bruto             = NULLIF(p->'analise'->>'markup_bruto', '')::numeric,
         custo_total              = NULLIF(p->'analise'->>'custo_total', '')::numeric,
         venda_sugerida           = NULLIF(p->'analise'->>'venda_sugerida', '')::numeric,
         total_nf                 = NULLIF(p->'analise'->>'total_nf', '')::numeric,
         valor_liquido            = NULLIF(p->'analise'->>'valor_liquido', '')::numeric,
         markup_projetado         = NULLIF(p->'analise'->>'markup_projetado', '')::numeric,
         markup_real              = NULLIF(p->'analise'->>'markup_real', '')::numeric,
         pct_opex                 = NULLIF(p->'analise'->>'pct_opex', '')::numeric,
         lucro                    = NULLIF(p->'analise'->>'lucro', '')::numeric,
         pct_comissao_efetivo     = NULLIF(p->'analise'->>'pct_comissao_efetivo', '')::numeric,
         valor_comissao_total     = NULLIF(p->'analise'->>'valor_comissao_total', '')::numeric,
         qtd_itens_prejuizo       = NULLIF(p->'analise'->>'qtd_itens_prejuizo', '')::integer
   WHERE x.id = p_id;
$$;


