--
-- TOC entry 579 (class 1255 OID 24392)
-- Name: fn_proposta_aprovar(uuid, uuid, integer); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_aprovar(p_id uuid, p_usuario uuid, p_versao integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v core_comercial.propostas%ROWTYPE;
BEGIN
  IF p_usuario IS NULL THEN RAISE EXCEPTION 'Usuário obrigatório.' USING ERRCODE = '23514'; END IF;
  v := core_comercial.fn_proposta_trava(p_id, p_versao);
  IF v.status <> 'ABERTA' THEN
    RAISE EXCEPTION 'Só proposta ABERTA pode ser aprovada (esta está %).', v.status USING ERRCODE = 'AV532', DETAIL = v.status;
  END IF;
  PERFORM core_comercial.fn_proposta_exigir_validade(v);
  UPDATE core_comercial.propostas SET status = 'APROVADA', versao = v.versao + 1, updated_by = p_usuario WHERE id = p_id;
  INSERT INTO core_comercial.propostas_eventos (id_proposta, tipo, dados, id_usuario)
  VALUES (p_id, 'APROVADA', jsonb_build_object('revisao', v.revisao, 'numero_completo', v.numero_completo, 'total_geral', v.total_geral,
                                                'registrado_por', auth.fn_nome_usuario(p_usuario)), p_usuario);
END
$$;


--
-- TOC entry 7190 (class 0 OID 0)
-- Dependencies: 579
-- Name: FUNCTION fn_proposta_aprovar(p_id uuid, p_usuario uuid, p_versao integer); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_proposta_aprovar(p_id uuid, p_usuario uuid, p_versao integer) IS 'POST /comercial/propostas/{id}/aprovar: registra a aprovação do cliente. Só ABERTA (AV532), com validade (AV536) e dentro dela (AV533 — checado na hora, não depende do agendador). Versão opcional (If-Match). Evento APROVADA {revisao, numero_completo, total_geral, registrado_por}.';


--
-- TOC entry 820 (class 1255 OID 24393)
-- Name: fn_proposta_cancelar(uuid, text, uuid, integer); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_cancelar(p_id uuid, p_motivo text, p_usuario uuid, p_versao integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v core_comercial.propostas%ROWTYPE;
BEGIN
  IF p_usuario IS NULL THEN RAISE EXCEPTION 'Usuário obrigatório.' USING ERRCODE = '23514'; END IF;
  IF NULLIF(btrim(p_motivo), '') IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE = '23514';
  END IF;
  v := core_comercial.fn_proposta_trava(p_id, p_versao);
  IF v.status NOT IN ('ABERTA', 'APROVADA') THEN
    RAISE EXCEPTION 'Só proposta ABERTA ou APROVADA pode ser cancelada (esta está %).', v.status USING ERRCODE = 'AV532', DETAIL = v.status;
  END IF;
  UPDATE core_comercial.propostas SET status = 'CANCELADA', versao = v.versao + 1, updated_by = p_usuario WHERE id = p_id;
  INSERT INTO core_comercial.propostas_eventos (id_proposta, tipo, dados, id_usuario)
  VALUES (p_id, 'CANCELADA', jsonb_build_object('motivo', btrim(p_motivo), 'status_anterior', v.status), p_usuario);
END
$$;


