--

COMMENT ON FUNCTION core_comercial.fn_proposta_cancelar(p_id uuid, p_motivo text, p_usuario uuid, p_versao integer) IS 'POST /comercial/propostas/{id}/cancelar: ABERTA ou APROVADA -> CANCELADA, motivo obrigatório. Evento CANCELADA {motivo, status_anterior}.';


