-- TOC entry 1051 (class 1255 OID 24381)
-- Name: fn_proposta_cliente_resolver(uuid, text, jsonb); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_cliente_resolver(p_id_unidade uuid, p_codigo_emissora text, p_cliente jsonb, OUT id_parceiro uuid, OUT snapshot jsonb) RETURNS record
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_doc     text := core_comercial.fn_documento_normalizado(p_cliente->>'documento');
  v_mascara text;
  v_omie    text;
BEGIN
  IF v_doc IS NULL OR length(v_doc) NOT IN (11, 14) THEN
    RAISE EXCEPTION 'Documento do cliente inválido.' USING ERRCODE = '23514';
  END IF;
  v_mascara := CASE length(v_doc)
    WHEN 14 THEN substr(v_doc,1,2)||'.'||substr(v_doc,3,3)||'.'||substr(v_doc,6,3)||'/'||substr(v_doc,9,4)||'-'||substr(v_doc,13,2)
    ELSE substr(v_doc,1,3)||'.'||substr(v_doc,4,3)||'.'||substr(v_doc,7,3)||'-'||substr(v_doc,10,2) END;
  SELECT pa.id, pa.codigo_parceiro_omie INTO id_parceiro, v_omie
    FROM core.parceiros pa
   WHERE pa.codigo_empresa = p_id_unidade
     AND pa.deleted_at IS NULL
     AND pa.cpf_cnpj IN (v_mascara, v_doc)
   ORDER BY pa.inativo,
            NOT EXISTS (SELECT 1 FROM core.parceiros_tipos pt JOIN core.tipos_parceiro t ON t.id = pt.id_tipo_parceiro
                         WHERE pt.id_parceiro = pa.id AND pt.deleted_at IS NULL AND t.tipo = 'Cliente'),
            pa.updated_at DESC
   LIMIT 1;
  IF id_parceiro IS NULL THEN
    RAISE EXCEPTION 'Cliente % não está cadastrado na unidade %.', v_mascara, p_codigo_emissora
      USING ERRCODE = 'AV531', DETAIL = v_mascara, HINT = 'Cadastre o cliente pelo card Cliente (POST /comercial/clientes) e salve de novo.';
  END IF;
  snapshot := p_cliente || jsonb_build_object('documento', v_doc, 'id_parceiro', id_parceiro, 'codigo_parceiro_omie', v_omie);
END
$$;


--
-- TOC entry 7192 (class 0 OID 0)
-- Dependencies: 1051
-- Name: FUNCTION fn_proposta_cliente_resolver(p_id_unidade uuid, p_codigo_emissora text, p_cliente jsonb, OUT id_parceiro uuid, OUT snapshot jsonb); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_proposta_cliente_resolver(p_id_unidade uuid, p_codigo_emissora text, p_cliente jsonb, OUT id_parceiro uuid, OUT snapshot jsonb) IS 'Acha o cliente da proposta em core.parceiros da unidade da emissora pelo CPF/CNPJ (com ou sem máscara; ativo e com tipo Cliente primeiro). Não achou: AV531 (API: 422 CLIENTE_NAO_CADASTRADO). Usada por fn_proposta_criar e fn_proposta_revisar.';


