--
-- TOC entry 592 (class 1255 OID 24559)
-- Name: fn_proposta_copiar(uuid, uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_copiar(p_id uuid, p_usuario uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v        core_comercial.propostas%ROWTYPE;
  v_ano    integer := extract(year FROM (now() AT TIME ZONE 'America/Sao_Paulo'))::integer;
  v_seq    integer;
  v_numero text;
  v_codigo text;
  v_novo   uuid;
BEGIN
  IF p_usuario IS NULL THEN RAISE EXCEPTION 'Usuário obrigatório.' USING ERRCODE = '23514'; END IF;
  SELECT * INTO v FROM core_comercial.propostas WHERE id = p_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Proposta não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  SELECT u.sigla INTO v_codigo FROM core.unidades u WHERE u.id = v.codigo_empresa;
  -- [Pedido do Robert 11/11/2026 — emissão/carteira, decisão 3] Se o responsável da
  -- original não vale para quem copia (fn_emissao_responsavel_situacao), a cópia sai
  -- em nome de quem copiou; a trigger trg_propostas_conferir_emissao confere.
  IF core_comercial.fn_emissao_responsavel_situacao(p_usuario, v.codigo_empresa, v.id_responsavel) <> 'OK' THEN
    v.id_responsavel := p_usuario;
    v.responsavel_snapshot := (SELECT jsonb_build_object('id_usuario', u.id, 'nome', auth.fn_nome_usuario(u.id), 'email', u.email)
                                 FROM auth.usuarios u WHERE u.id = p_usuario);
  END IF;
  v_seq := core_comercial.fn_proxima_sequencia_proposta(v.codigo_empresa, v_ano);
  v_numero := format('%s%s-%s-R00', v_codigo, v_ano, lpad(v_seq::text, 4, '0'));

  INSERT INTO core_comercial.propostas (
    codigo_empresa, ano, sequencial, revisao, numero_completo, status,
    id_cliente, cliente_snapshot, numero_requisicao, finalidade, isento_impostos, isento_pis_cofins,
    requisitos_qualidade, tipo_venda, moeda, cotacao_moeda, incoterm, valor_frete, condicao_pagamento,
    validade, validade_ate, observacoes, subtotal, total_desconto, total_icms, total_ipi, total_st, total_geral, valor_aberto,
    id_responsavel, responsavel_snapshot, id_proposta_origem,
    estado_destino, condicao_pagamento_chave, frete_compra_tipo, imposto_retido_difal, frete_compra_valor,
    codigo_condicao_pagamento, encargo_pagamento,
    created_by, updated_by)
  VALUES (
    v.codigo_empresa, v_ano, v_seq, 0, v_numero, 'ABERTA',
    v.id_cliente, v.cliente_snapshot, NULL, v.finalidade, v.isento_impostos, v.isento_pis_cofins,
    v.requisitos_qualidade, v.tipo_venda, v.moeda, NULL, v.incoterm, 0, v.condicao_pagamento,
    '', NULL, NULL, 0, 0, 0, 0, 0, 0, 0,
    v.id_responsavel, v.responsavel_snapshot, v.id,
    v.estado_destino, v.condicao_pagamento_chave, 'RATEIO', 0, 0,
    v.codigo_condicao_pagamento, v.encargo_pagamento,  -- 12/11/2026: o encargo vai junto com as condições
    p_usuario, p_usuario)
  RETURNING id INTO v_novo;

  -- Itens: estrutura e dados técnicos; preço de venda 0 (cota-se de novo), sem desconto,
  -- sem custo, sem compra e sem análise. Alíquotas de venda (ICMS/IPI/ST) vêm junto: são
  -- regra fiscal do item, não custo. O produto vem como está: se tiver sido desativado,
  -- a revisão (PUT, obrigatória antes de aprovar) recusa com AV538.
  INSERT INTO core_comercial.propostas_itens (
    id_proposta, ordem, id_produto, codigo, descricao, observacao, ncm, quantidade, unidade_medida,
    preco_unitario, desconto_pct, icms_pct, ipi_pct, st_pct, prazo_dias_uteis,
    preco_unitario_liquido, subtotal_bruto, valor_desconto, base, valor_icms, valor_ipi, valor_st,
    kg_m, metragem, configuracao, tec_norma, tec_material, tec_certificados, tec_ensaios, tipo_item)
  SELECT v_novo, i.ordem, i.id_produto, i.codigo, i.descricao, i.observacao, i.ncm, i.quantidade, i.unidade_medida,
         0, 0, i.icms_pct, i.ipi_pct, i.st_pct, i.prazo_dias_uteis,
         0, 0, 0, 0, 0, 0, 0,
         i.kg_m, i.metragem, i.configuracao, i.tec_norma, i.tec_material, i.tec_certificados, i.tec_ensaios, i.tipo_item
    FROM core_comercial.propostas_itens i
   WHERE i.id_proposta = v.id;

  INSERT INTO core_comercial.propostas_eventos (id_proposta, tipo, dados, id_usuario) VALUES
    (v_novo, 'CRIADA', jsonb_build_object('numero_completo', v_numero, 'id_responsavel', v.id_responsavel,
                                          'copiada_de', v.id, 'numero_origem', v.numero_completo), p_usuario),
    (v.id, 'COPIADA', jsonb_build_object('id_nova', v_novo, 'numero_nova', v_numero), p_usuario);
  RETURN v_novo;
END
$$;


--
-- TOC entry 7194 (class 0 OID 0)
-- Dependencies: 592
-- Name: FUNCTION fn_proposta_copiar(p_id uuid, p_usuario uuid); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_proposta_copiar(p_id uuid, p_usuario uuid) IS 'POST /comercial/propostas/{id}/copiar (pedido do Robert, 29/10/2026): nova proposta ABERTA a partir de qualquer proposta (o caso de uso é a EXPIRADA). Copia cliente, responsável, finalidade, isenções, requisitos, tipo de venda, moeda, incoterm, condição de pagamento (texto, chave e código do Omie), estado de destino e os itens (produto, código, descrição, observação, NCM, quantidade, unidade, prazo, alíquotas de venda, tipo do item, kg/m, metragem, configuração e dados técnicos). NÃO copia: preço de venda (fica 0), desconto, cotação, frete, custo, compra (preço, origem, IPI/ST, frete), nenhum campo da análise de margem, nº da requisição do cliente, observações. Número novo, revisão 0, validade em branco (validade_ate NULL: não aprova nem transforma antes de revisar). id_proposta_origem = a original. Eventos CRIADA (na nova, com copiada_de) e COPIADA (na original, {id_nova, numero_nova}). 05/11/2026: sem oferta/produto pendente (limpeza do core_comercial); copia também o código do Omie da condição de pagamento.';


--
-- TOC entry 904 (class 1255 OID 24352)
-- Name: fn_proposta_criar(jsonb, uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_criar(p jsonb, p_usuario uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_unidade   core.unidades%ROWTYPE;
  v_cli       record;
  v_val       record;
  v_resp      uuid  := COALESCE(NULLIF(p->>'id_responsavel', '')::uuid, p_usuario);
  v_resp_snap jsonb;
  v_ano       integer := extract(year FROM (now() AT TIME ZONE 'America/Sao_Paulo'))::integer;
  v_seq       integer;
  v_numero    text;
  v_id        uuid;
BEGIN
  IF p_usuario IS NULL THEN
    RAISE EXCEPTION 'Usuário obrigatório.' USING ERRCODE = '23514';
  END IF;
  -- Pedido do Robert (10/11/2026): a emissora é a própria unidade, pela sigla.
  SELECT * INTO v_unidade FROM core.unidades u
   WHERE u.sigla = upper(btrim(COALESCE(p->>'empresa', ''))) AND u.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Empresa emissora inválida: "%".', p->>'empresa' USING ERRCODE = '23514';
  END IF;
  IF jsonb_typeof(p->'itens') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'itens') = 0 THEN
    RAISE EXCEPTION 'A proposta precisa de pelo menos um item.' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO v_val FROM core_comercial.fn_proposta_validade_do_corpo(p, core_comercial.fn_hoje());
  SELECT * INTO v_cli FROM core_comercial.fn_proposta_cliente_resolver(v_unidade.id, v_unidade.sigla, COALESCE(p->'cliente', '{}'::jsonb));

  SELECT jsonb_build_object('id_usuario', u.id, 'nome', auth.fn_nome_usuario(u.id), 'email', u.email)
    INTO v_resp_snap
    FROM auth.usuarios u WHERE u.id = v_resp AND u.ativo AND u.deleted_at IS NULL;
  IF v_resp_snap IS NULL THEN
    RAISE EXCEPTION 'Responsável da proposta não encontrado ou inativo.' USING ERRCODE = '23514';
  END IF;

  v_seq := core_comercial.fn_proxima_sequencia_proposta(v_unidade.id, v_ano);
  v_numero := format('%s%s-%s-R00', v_unidade.sigla, v_ano, lpad(v_seq::text, 4, '0'));

  INSERT INTO core_comercial.propostas (
    codigo_empresa, ano, sequencial, revisao, numero_completo, status,
    id_cliente, cliente_snapshot, numero_requisicao, finalidade, isento_impostos, isento_pis_cofins,
    requisitos_qualidade, tipo_venda, moeda, cotacao_moeda, incoterm, valor_frete, condicao_pagamento,
    validade, validade_ate, observacoes, subtotal, total_desconto, total_icms, total_ipi, total_st, total_geral, valor_aberto,
    id_responsavel, responsavel_snapshot, created_by, updated_by)
  VALUES (
    v_unidade.id, v_ano, v_seq, 0, v_numero, 'ABERTA',
    v_cli.id_parceiro, v_cli.snapshot,
    NULLIF(btrim(p->>'numero_requisicao'), ''), p->>'finalidade',
    COALESCE((p->>'isento_impostos')::boolean, false), COALESCE((p->>'isento_pis_cofins')::boolean, false),
    CASE WHEN jsonb_typeof(p->'requisitos_qualidade') = 'array'
         THEN ARRAY(SELECT jsonb_array_elements_text(p->'requisitos_qualidade')) END,
    COALESCE(p->>'tipo_venda', 'NACIONAL'), COALESCE(p->>'moeda', 'BRL'), NULLIF(p->>'cotacao_moeda', '')::numeric,
    p->>'incoterm', COALESCE(NULLIF(p->>'valor_frete', '')::numeric, 0), p->>'condicao_pagamento',
    v_val.validade, v_val.validade_ate, NULLIF(btrim(p->>'observacoes'), ''),
    0, 0, 0, 0, 0, 0, 0,
    v_resp, v_resp_snap, p_usuario, p_usuario)
  RETURNING id INTO v_id;

  PERFORM core_comercial.fn_proposta_analise_gravar(v_id, p);
  PERFORM core_comercial.fn_proposta_codigos_omie_gravar(v_id, p);  -- 05/11/2026: código do Omie da condição de pagamento
  PERFORM core_comercial.fn_proposta_itens_gravar(v_id, p->'itens');
  PERFORM core_comercial.fn_proposta_totais_atualizar(v_id);

  INSERT INTO core_comercial.propostas_eventos (id_proposta, tipo, dados, id_usuario)
  VALUES (v_id, 'CRIADA', jsonb_build_object('numero_completo', v_numero, 'id_responsavel', v_resp,
                                              'validade_ate', v_val.validade_ate), p_usuario);
  RETURN v_id;
END
$$;


