CREATE FUNCTION core_comercial.fn_proposta_exigir_validade(v core_comercial.propostas) RETURNS void
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  IF v.validade_ate IS NULL THEN
    RAISE EXCEPTION 'A proposta não tem validade: revise a proposta e informe a data.' USING ERRCODE = 'AV536';
  END IF;
  IF v.validade_ate < core_comercial.fn_hoje() THEN
    RAISE EXCEPTION 'A validade da proposta venceu em %: copie a proposta e cote de novo.', to_char(v.validade_ate, 'DD/MM/YYYY')
      USING ERRCODE = 'AV533', DETAIL = v.validade_ate::text;
  END IF;
END
$$;


--
-- TOC entry 805 (class 1255 OID 24351)
-- Name: fn_proposta_item_calcular(numeric, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_item_calcular(p_quantidade numeric, p_preco_unitario numeric, p_desconto_pct numeric, p_icms_pct numeric, p_ipi_pct numeric, p_st_pct numeric, OUT preco_unitario_liquido numeric, OUT subtotal_bruto numeric, OUT valor_desconto numeric, OUT base numeric, OUT valor_icms numeric, OUT valor_ipi numeric, OUT valor_st numeric) RETURNS record
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  -- Entradas nas casas das colunas (quantidade 4, preço 2, percentuais 4): o
  -- cálculo usa o MESMO valor que fica gravado no item.
  WITH e AS (
    SELECT round(p_quantidade, 4) AS qtd, round(p_preco_unitario, 2) AS preco,
           round(COALESCE(p_desconto_pct, 0), 4) AS dsc
  ), v AS (
    SELECT e.preco, e.dsc,
           round(e.qtd * e.preco, 2) AS bruto,
           round(e.qtd * e.preco * e.dsc / 100, 2) AS desconto
      FROM e
  )
  SELECT round(v.preco * (1 - v.dsc / 100), 2),
         v.bruto,
         v.desconto,
         v.bruto - v.desconto,
         round((v.bruto - v.desconto) * round(COALESCE(p_icms_pct, 0), 4) / 100, 2),
         round((v.bruto - v.desconto) * round(COALESCE(p_ipi_pct, 0), 4) / 100, 2),
         round((v.bruto - v.desconto) * round(COALESCE(p_st_pct, 0), 4) / 100, 2)
    FROM v
$$;


--
-- TOC entry 7213 (class 0 OID 0)
-- Dependencies: 805
-- Name: FUNCTION fn_proposta_item_calcular(p_quantidade numeric, p_preco_unitario numeric, p_desconto_pct numeric, p_icms_pct numeric, p_ipi_pct numeric, p_st_pct numeric, OUT preco_unitario_liquido numeric, OUT subtotal_bruto numeric, OUT valor_desconto numeric, OUT base numeric, OUT valor_icms numeric, OUT valor_ipi numeric, OUT valor_st numeric); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_proposta_item_calcular(p_quantidade numeric, p_preco_unitario numeric, p_desconto_pct numeric, p_icms_pct numeric, p_ipi_pct numeric, p_st_pct numeric, OUT preco_unitario_liquido numeric, OUT subtotal_bruto numeric, OUT valor_desconto numeric, OUT base numeric, OUT valor_icms numeric, OUT valor_ipi numeric, OUT valor_st numeric) IS 'Valores fiscais do item da proposta (mapa do Robert §4, colunas NOT NULL do cálculo). subtotal_bruto = qtd × preço; valor_desconto = subtotal × desconto%; base = subtotal - desconto; ICMS = base × icms% (INCLUSO no preço, a tela mostra "ICMS (incluso)"); IPI = base × ipi% e ST = base × st% (POR FORA). Tudo arredondado a 2 casas (meio para cima) por item. Os percentuais são os que o vendedor digitou (N16-95). ⚠ Fórmula reconstruída (o domínio do api-comercial não estava disponível): conferir com o Robert/Nathan; trocar só esta função se mudar.';


--
-- TOC entry 1025 (class 1255 OID 24382)
-- Name: fn_proposta_itens_gravar(uuid, jsonb); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_itens_gravar(p_id uuid, p_itens jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_n       integer;
  v_empresa uuid;
BEGIN
  IF jsonb_typeof(p_itens) IS DISTINCT FROM 'array' OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'A proposta precisa de pelo menos um item.' USING ERRCODE = '23514';
  END IF;
  SELECT p.codigo_empresa INTO v_empresa FROM core_comercial.propostas p WHERE p.id = p_id;
  PERFORM core_comercial.fn_proposta_itens_produtos_conferir(v_empresa, p_itens);

  INSERT INTO core_comercial.propostas_itens (
    id_proposta, ordem, id_produto, codigo, descricao, observacao, ncm, quantidade, unidade_medida,
    preco_unitario, desconto_pct, icms_pct, ipi_pct, st_pct, prazo_dias_uteis,
    preco_unitario_liquido, subtotal_bruto, valor_desconto, base, valor_icms, valor_ipi, valor_st,
    custo, kg_m, metragem, pintura, margem_pct, origem_custo, fornecedor, custo_liquido_unit,
    custo_justificativa, margem_real_pct, configuracao, tec_norma, tec_material, tec_certificados, tec_ensaios,
    tipo_item, qtd_compra, unidade_compra, preco_unit_compra, origem_compra, ipi_compra_pct, st_compra_valor,
    frete_compra_valor, custo_liquido_total, preco_unit_sugerido, margem_item_pct, letra, regra_aplicada, icms_sugerido_pct,
    icms_efetivo, pct_impostos, pct_comissao)
  SELECT p_id, x.ordem::integer, (it->>'id_produto')::uuid, NULLIF(btrim(it->>'codigo'), ''), btrim(it->>'descricao'),
         NULLIF(btrim(it->>'observacao'), ''), NULLIF(btrim(it->>'ncm'), ''),
         (it->>'quantidade')::numeric, it->>'unidade_medida',
         (it->>'preco_unitario')::numeric, COALESCE((it->>'desconto_pct')::numeric, 0),
         (it->>'icms_pct')::numeric, (it->>'ipi_pct')::numeric, COALESCE((it->>'st_pct')::numeric, 0), it->>'prazo_dias_uteis',
         c.preco_unitario_liquido, c.subtotal_bruto, c.valor_desconto, c.base, c.valor_icms, c.valor_ipi, c.valor_st,
         NULLIF(it->>'custo', '')::numeric, NULLIF(it->>'kg_m', '')::numeric, NULLIF(it->>'metragem', '')::numeric,
         NULLIF(it->>'pintura', '')::numeric, NULLIF(it->>'margem_pct', '')::numeric,
         COALESCE(NULLIF(it->>'origem_custo', ''), 'SEM_CUSTO'),
         NULLIF(btrim(it->>'fornecedor'), ''), NULLIF(it->>'custo_liquido_unit', '')::numeric,
         NULLIF(btrim(it->>'custo_justificativa'), ''), NULLIF(it->>'margem_real_pct', '')::numeric,
         CASE WHEN jsonb_typeof(it->'configuracao') = 'object' THEN it->'configuracao' END,
         NULLIF(btrim(it->>'tec_norma'), ''), NULLIF(btrim(it->>'tec_material'), ''),
         CASE WHEN jsonb_typeof(it->'tec_certificados') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(it->'tec_certificados')) END,
         CASE WHEN jsonb_typeof(it->'tec_ensaios') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(it->'tec_ensaios')) END,
         COALESCE(NULLIF(it->>'tipo_item', ''), 'REVENDA'), NULLIF(it->>'qtd_compra', '')::double precision,
         NULLIF(btrim(it->>'unidade_compra'), ''), NULLIF(it->>'preco_unit_compra', '')::numeric,
         NULLIF(btrim(it->>'origem_compra'), ''), COALESCE(NULLIF(it->>'ipi_compra_pct', '')::numeric, 0),
         COALESCE(NULLIF(it->>'st_compra_valor', '')::numeric, 0), COALESCE(NULLIF(it->>'frete_compra_valor', '')::numeric, 0),
         NULLIF(it->'analise'->>'custo_liquido_total', '')::numeric, NULLIF(it->'analise'->>'preco_unit_sugerido', '')::numeric,
         NULLIF(it->'analise'->>'margem_item_pct', '')::numeric, NULLIF(it->'analise'->>'letra', ''),
         NULLIF(it->'analise'->>'regra_aplicada', ''), NULLIF(it->'analise'->>'icms_sugerido_pct', '')::numeric,
         NULLIF(it->'analise'->>'icms_efetivo', '')::numeric, NULLIF(it->'analise'->>'pct_impostos', '')::numeric,
         NULLIF(it->'analise'->>'pct_comissao', '')::numeric
    FROM jsonb_array_elements(p_itens) WITH ORDINALITY AS x(it, ordem),
         LATERAL core_comercial.fn_proposta_item_calcular(
           (it->>'quantidade')::numeric, (it->>'preco_unitario')::numeric, COALESCE((it->>'desconto_pct')::numeric, 0),
           (it->>'icms_pct')::numeric, (it->>'ipi_pct')::numeric, COALESCE((it->>'st_pct')::numeric, 0)) c;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END
$$;


