COMMENT ON FUNCTION core_comercial.fn_proposta_itens_gravar(p_id uuid, p_itens jsonb) IS 'Grava os itens do corpo (POST/PUT) na proposta, na ordem do corpo (1..n), com os valores fiscais de fn_proposta_item_calcular e a análise do item como veio (analise.custo_liquido_total ... pct_comissao). Antes de gravar, fn_proposta_itens_produtos_conferir exige produto do catálogo da unidade em TODOS os itens (AV538). Desde 05/11/2026 (limpeza do core_comercial) não há oferta nem produto pendente. Não apaga nada: quem revisa apaga os itens antes.';


--
-- TOC entry 746 (class 1255 OID 24622)
-- Name: fn_proposta_itens_produtos_conferir(uuid, jsonb); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_itens_produtos_conferir(p_codigo_empresa uuid, p_itens jsonb) RETURNS void
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  v_sigla     text;
  v_problemas jsonb;
  v_msg       text;
BEGIN
  SELECT COALESCE((SELECT u.sigla::text FROM core.unidades u WHERE u.id = p_codigo_empresa), 'unidade da proposta')
    INTO v_sigla;

  SELECT jsonb_agg(jsonb_build_object('item', x.ordem, 'id_produto', x.id_txt,
                                      'descricao', COALESCE(pr.descricao, btrim(x.it->>'descricao')),
                                      'motivo', x.motivo) ORDER BY x.ordem)
    INTO v_problemas
    FROM (
      SELECT o.ordem, o.it, o.id_txt, pr.id AS id_pr,
             CASE
               WHEN o.id_txt IS NULL THEN 'SEM_PRODUTO'
               WHEN pr.id IS NULL OR pr.deleted_at IS NOT NULL THEN 'NAO_CADASTRADO'
               WHEN pr.codigo_empresa <> p_codigo_empresa THEN 'OUTRA_UNIDADE'
               WHEN NOT pr.ativo THEN 'INATIVO'
             END AS motivo
        FROM (SELECT x.ordem, x.it, NULLIF(btrim(x.it->>'id_produto'), '') AS id_txt
                FROM jsonb_array_elements(p_itens) WITH ORDINALITY AS x(it, ordem)) o
        LEFT JOIN core.produtos pr
               ON o.id_txt ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              AND pr.id = o.id_txt::uuid
    ) x
    LEFT JOIN core.produtos pr ON pr.id = x.id_pr
   WHERE x.motivo IS NOT NULL;

  IF v_problemas IS NULL THEN RETURN; END IF;

  SELECT string_agg(format('item %s — %s %s', p->>'item', left(p->>'descricao', 80),
                           CASE p->>'motivo'
                             WHEN 'SEM_PRODUTO'    THEN 'não tem produto do catálogo (escolha o produto na lista)'
                             WHEN 'NAO_CADASTRADO' THEN format('não está cadastrado na %s', v_sigla)
                             WHEN 'OUTRA_UNIDADE'  THEN format('não está cadastrado na %s (é de outra unidade)', v_sigla)
                             WHEN 'INATIVO'        THEN format('está inativo no cadastro da %s', v_sigla)
                           END), '; ' ORDER BY (p->>'item')::int)
    INTO v_msg
    FROM jsonb_array_elements(v_problemas) p;
  RAISE EXCEPTION '%', 'Produto fora do catálogo da unidade: ' || v_msg || '.'
    USING ERRCODE = 'AV538', DETAIL = v_problemas::text;
END
$_$;


--
-- TOC entry 7215 (class 0 OID 0)
-- Dependencies: 746
-- Name: FUNCTION fn_proposta_itens_produtos_conferir(p_codigo_empresa uuid, p_itens jsonb); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_proposta_itens_produtos_conferir(p_codigo_empresa uuid, p_itens jsonb) IS 'Item 3 do pedido do Robert de 03/11/2026 (garantia de integridade, não UX): todo item da proposta usa produto de core.produtos, não excluído, ATIVO e da MESMA unidade da proposta. Confere todos os itens de uma vez; falha = ERRCODE AV538 (API: 422 PRODUTO_FORA_DA_UNIDADE), mensagem "item N — descrição não está cadastrado na AV" e DETAIL = jsonb [{item, id_produto, descricao, motivo: SEM_PRODUTO|NAO_CADASTRADO|OUTRA_UNIDADE|INATIVO}]. Chamada por fn_proposta_itens_gravar (POST e PUT). Motivo: códigos do Omie só são únicos por conta; produto de outra unidade vira produto errado na nota.';


--
-- TOC entry 781 (class 1255 OID 24733)
-- Name: fn_proposta_prontidao_omie(uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_prontidao_omie(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  v      core_comercial.propostas%ROWTYPE;
  v_pa   record;
  v_un   text;
  v_cod  jsonb;
  r      jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v FROM core_comercial.propostas WHERE id = p_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Proposta não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  SELECT u.nome_fantasia INTO v_un FROM core.unidades u WHERE u.id = v.codigo_empresa;

  IF core_comercial.fn_pedido_venda_vendedor(v.id_responsavel, v.codigo_empresa) IS NULL THEN
    r := r || jsonb_build_object('codigo', 'VENDEDOR_SEM_OMIE', 'campo', 'vendedor',
      'mensagem', format('O responsável (%s) não tem vendedor ativo no Omie da unidade %s.',
                         COALESCE(auth.fn_nome_usuario(v.id_responsavel), v.id_responsavel::text), COALESCE(v_un, '?')));
  END IF;

  SELECT pa.codigo_empresa, pa.codigo_parceiro_omie, pa.deleted_at, pa.inativo, pa.razao_social INTO v_pa
    FROM core.parceiros pa WHERE pa.id = v.id_cliente;
  IF v_pa IS NULL OR v_pa.deleted_at IS NOT NULL OR v_pa.codigo_empresa <> v.codigo_empresa
     OR COALESCE(btrim(v_pa.codigo_parceiro_omie), '') !~ '^[0-9]+$' THEN
    r := r || jsonb_build_object('codigo', 'CLIENTE_SEM_OMIE', 'campo', 'cliente',
      'mensagem', format('O cliente não tem cadastro no Omie da unidade %s.', COALESCE(v_un, '?')));
  ELSIF v_pa.inativo IS TRUE THEN
    r := r || jsonb_build_object('codigo', 'CLIENTE_SEM_OMIE', 'campo', 'cliente',
      'mensagem', format('O cliente %s está inativo no Omie da unidade %s.', v_pa.razao_social, COALESCE(v_un, '?')));
  END IF;

  r := r || COALESCE((
    SELECT jsonb_agg(jsonb_build_object('codigo', 'PRODUTO_SEM_OMIE', 'campo', 'itens', 'item', i.ordem, 'id_produto', i.id_produto,
             'mensagem', format('item %s — %s ', i.ordem, left(i.descricao, 80)) ||
               CASE
                 WHEN pr.id IS NULL OR pr.deleted_at IS NOT NULL OR pr.codigo_empresa <> v.codigo_empresa
                   THEN 'não está no catálogo desta unidade.'
                 WHEN NOT pr.ativo THEN 'está inativo no catálogo desta unidade.'
                 ELSE 'não tem código do Omie (codigo_produto_omie).'
               END) ORDER BY i.ordem)
      FROM core_comercial.propostas_itens i
      LEFT JOIN core.produtos pr ON pr.id = i.id_produto
     WHERE i.id_proposta = v.id
       AND (pr.id IS NULL OR pr.deleted_at IS NOT NULL OR pr.codigo_empresa <> v.codigo_empresa OR NOT pr.ativo
            OR COALESCE(btrim(pr.codigo_produto_omie), '') !~ '^[0-9]+$')), '[]'::jsonb);

  IF v.codigo_condicao_pagamento IS NULL THEN
    r := r || jsonb_build_object('codigo', 'CONDICAO_SEM_OMIE', 'campo', 'codigo_condicao_pagamento',
      'mensagem', 'A proposta não tem a condição de pagamento do Omie: revise a proposta e escolha a condição.');
  ELSE
    v_cod := core_comercial.fn_comercial_codigos_omie_problemas(v.codigo_empresa, v.codigo_condicao_pagamento, NULL);
    IF v_cod IS NOT NULL THEN
      r := r || (SELECT jsonb_agg(e || jsonb_build_object('codigo', 'CONDICAO_SEM_OMIE')) FROM jsonb_array_elements(v_cod) e);
    END IF;
  END IF;

  IF core_comercial.fn_conta_corrente_padrao(v.codigo_empresa) IS NULL THEN
    r := r || jsonb_build_object('codigo', 'UNIDADE_SEM_CONFIG', 'campo', 'codigo_conta_corrente',
      'codigo_empresa', v.codigo_empresa, 'unidade', v_un,
      'mensagem', format('A unidade %s não tem a conta corrente padrão do Omie configurada. Não é o vendedor que resolve: avise o Gustavo (configuração do banco).',
                         COALESCE(v_un, '?')));
  END IF;

  RETURN jsonb_build_object('pronto', jsonb_array_length(r) = 0, 'id_proposta', v.id, 'status', v.status,
                            'codigo_empresa', v.codigo_empresa, 'unidade', v_un, 'pendencias', r);
END $_$;


--
-- TOC entry 7216 (class 0 OID 0)
-- Dependencies: 781
-- Name: FUNCTION fn_proposta_prontidao_omie(p_id uuid); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_proposta_prontidao_omie(p_id uuid) IS 'LOG-56 §8.1: o que impede a proposta de virar pedido no Omie, antes do modal. Só leitura. Cinco códigos: VENDEDOR_SEM_OMIE, CLIENTE_SEM_OMIE, PRODUTO_SEM_OMIE (um por item), CONDICAO_SEM_OMIE e UNIDADE_SEM_CONFIG (conta Omie sem conta corrente padrão, com o nome da unidade). Os campos do modal (previsão, categoria, frete) e a moeda continuam na fn_pedido_venda_pendencias. Devolve {pronto, id_proposta, status, codigo_empresa, unidade, pendencias[{codigo, campo, mensagem, ...}]}.';


--
-- TOC entry 677 (class 1255 OID 24388)
-- Name: fn_proposta_revisar(uuid, jsonb, uuid, integer); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_revisar(p_id uuid, p jsonb, p_usuario uuid, p_versao integer) RETURNS uuid
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_prop      core_comercial.propostas%ROWTYPE;
  v_unidade   core.unidades%ROWTYPE;
  v_cli       record;
  v_val       record;
  v_resp      uuid;
  v_resp_snap jsonb;
  v_numero    text;
  v_total     numeric;
BEGIN
  IF p_usuario IS NULL THEN
    RAISE EXCEPTION 'Usuário obrigatório.' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO v_prop FROM core_comercial.propostas WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Proposta não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF p_versao IS DISTINCT FROM v_prop.versao THEN
    RAISE EXCEPTION 'A proposta foi alterada por outra pessoa (versão atual %).', v_prop.versao
      USING ERRCODE = 'AV521', DETAIL = v_prop.versao::text;
  END IF;
  IF v_prop.status <> 'ABERTA' THEN
    RAISE EXCEPTION 'Só proposta ABERTA pode ser revisada (esta está %).', v_prop.status
      USING ERRCODE = 'AV532', DETAIL = v_prop.status;
  END IF;
  IF v_prop.validade_ate IS NOT NULL AND v_prop.validade_ate < core_comercial.fn_hoje() THEN
    RAISE EXCEPTION 'A validade da proposta venceu em %: copie a proposta e cote de novo.', to_char(v_prop.validade_ate, 'DD/MM/YYYY')
      USING ERRCODE = 'AV533', DETAIL = v_prop.validade_ate::text;
  END IF;
  SELECT * INTO v_unidade FROM core.unidades u WHERE u.id = v_prop.codigo_empresa;
  IF upper(btrim(COALESCE(p->>'empresa', v_unidade.sigla))) <> v_unidade.sigla THEN
    RAISE EXCEPTION 'A empresa emissora não muda na revisão (é %): copie a proposta para emitir por outra empresa.', v_unidade.sigla
      USING ERRCODE = 'AV537', DETAIL = v_unidade.sigla;
  END IF;
  IF jsonb_typeof(p->'itens') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'itens') = 0 THEN
    RAISE EXCEPTION 'A proposta precisa de pelo menos um item.' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO v_val FROM core_comercial.fn_proposta_validade_do_corpo(p, core_comercial.fn_hoje());
  SELECT * INTO v_cli FROM core_comercial.fn_proposta_cliente_resolver(v_unidade.id, v_unidade.sigla, COALESCE(p->'cliente', '{}'::jsonb));

  v_resp := COALESCE(NULLIF(p->>'id_responsavel', '')::uuid, v_prop.id_responsavel);
  IF v_resp = v_prop.id_responsavel THEN
    v_resp_snap := v_prop.responsavel_snapshot;
  ELSE
    SELECT jsonb_build_object('id_usuario', u.id, 'nome', auth.fn_nome_usuario(u.id), 'email', u.email)
      INTO v_resp_snap
      FROM auth.usuarios u WHERE u.id = v_resp AND u.ativo AND u.deleted_at IS NULL;
    IF v_resp_snap IS NULL THEN
      RAISE EXCEPTION 'Responsável da proposta não encontrado ou inativo.' USING ERRCODE = '23514';
    END IF;
  END IF;

  -- A revisão anterior, inteira (cabeçalho, itens e análise), para a história da negociação.
  INSERT INTO core_comercial.propostas_versoes (id_proposta, revisao, numero, snapshot, id_usuario)
  VALUES (p_id, v_prop.revisao, v_prop.numero_completo, core_comercial.fn_proposta_snapshot(p_id), p_usuario)
  ON CONFLICT (id_proposta, revisao) DO NOTHING;

  -- 10/11/2026: o prefixo ({sigla}{ano}-{nnnn}) sai do número atual, não da
  -- sigla de hoje: se o nome fantasia (e com ele a sigla) mudar, a proposta
  -- mantém o número e só a revisão sobe. Pedido do Robert (10/11): sem o "CO-"
  -- na frente; número antigo que ainda o tenha perde o "CO-" na revisão.
  v_numero := format('%s-R%s', regexp_replace(regexp_replace(v_prop.numero_completo, '-R[0-9]+$', ''), '^CO-', ''),
                     lpad((v_prop.revisao + 1)::text, 2, '0'));

  UPDATE core_comercial.propostas
     SET revisao = v_prop.revisao + 1, numero_completo = v_numero,
         id_cliente = v_cli.id_parceiro, cliente_snapshot = v_cli.snapshot,
         numero_requisicao = NULLIF(btrim(p->>'numero_requisicao'), ''), finalidade = p->>'finalidade',
         isento_impostos = COALESCE((p->>'isento_impostos')::boolean, false),
         isento_pis_cofins = COALESCE((p->>'isento_pis_cofins')::boolean, false),
         requisitos_qualidade = CASE WHEN jsonb_typeof(p->'requisitos_qualidade') = 'array'
                                     THEN ARRAY(SELECT jsonb_array_elements_text(p->'requisitos_qualidade')) END,
         tipo_venda = COALESCE(p->>'tipo_venda', 'NACIONAL'), moeda = COALESCE(p->>'moeda', 'BRL'),
         cotacao_moeda = NULLIF(p->>'cotacao_moeda', '')::numeric, incoterm = p->>'incoterm',
         valor_frete = COALESCE(NULLIF(p->>'valor_frete', '')::numeric, 0), condicao_pagamento = p->>'condicao_pagamento',
         validade = v_val.validade, validade_ate = v_val.validade_ate, observacoes = NULLIF(btrim(p->>'observacoes'), ''),
         id_responsavel = v_resp, responsavel_snapshot = v_resp_snap,
         versao = v_prop.versao + 1, updated_by = p_usuario
   WHERE id = p_id;

  DELETE FROM core_comercial.propostas_itens WHERE id_proposta = p_id;
  PERFORM core_comercial.fn_proposta_analise_gravar(p_id, p);
  PERFORM core_comercial.fn_proposta_codigos_omie_gravar(p_id, p);  -- 05/11/2026: código do Omie da condição de pagamento
  PERFORM core_comercial.fn_proposta_itens_gravar(p_id, p->'itens');
  v_total := core_comercial.fn_proposta_totais_atualizar(p_id);

  INSERT INTO core_comercial.propostas_eventos (id_proposta, tipo, dados, id_usuario)
  VALUES (p_id, 'REVISADA',
          jsonb_build_object('revisao', v_prop.revisao + 1, 'numero_anterior', v_prop.numero_completo, 'numero_completo', v_numero,
                             'total_anterior', v_prop.total_geral, 'total_novo', v_total, 'validade_ate', v_val.validade_ate),
          p_usuario);
  RETURN p_id;
END
$_$;


--
-- TOC entry 7217 (class 0 OID 0)
-- Dependencies: 677
-- Name: FUNCTION fn_proposta_revisar(p_id uuid, p jsonb, p_usuario uuid, p_versao integer); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_proposta_revisar(p_id uuid, p jsonb, p_usuario uuid, p_versao integer) IS 'PUT /comercial/propostas/{id} (pedido do Robert, 29/10/2026; 05/11: condição de pagamento do Omie e produto da unidade): revisão durante a negociação. Trava a linha; versão esperada (AV521); só ABERTA (AV532) e dentro da validade (AV533); a empresa emissora não muda (AV537). Guarda a revisão anterior inteira em propostas_versoes (snapshot com itens e análise); regrava cabeçalho, código do Omie da condição, se vier (fn_proposta_codigos_omie_gravar, AV539), itens (apaga e recria; produto da unidade, AV538) e análise como vieram, recalcula os totais; revisao + 1 e numero_completo -R{rr}; versao + 1; evento REVISADA {revisao, numero_anterior, numero_completo, total_anterior, total_novo, validade_ate}. "N DIAS" conta da data da revisão.';


--
-- TOC entry 613 (class 1255 OID 24387)
-- Name: fn_proposta_snapshot(uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_snapshot(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT (to_jsonb(p) - 'legado')
         || jsonb_build_object('itens', COALESCE((SELECT jsonb_agg(to_jsonb(i) - 'id_proposta' ORDER BY i.ordem)
                                                    FROM core_comercial.propostas_itens i WHERE i.id_proposta = p.id), '[]'::jsonb))
    FROM core_comercial.propostas p WHERE p.id = p_id;
$$;


--
-- TOC entry 513 (class 1255 OID 24383)
-- Name: fn_proposta_totais_atualizar(uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_totais_atualizar(p_id uuid) RETURNS numeric
    LANGUAGE sql
    AS $$
  WITH t AS (
    SELECT COALESCE(sum(i.subtotal_bruto), 0) AS subtotal, COALESCE(sum(i.valor_desconto), 0) AS desconto,
           COALESCE(sum(i.base), 0) AS base, COALESCE(sum(i.valor_icms), 0) AS icms,
           COALESCE(sum(i.valor_ipi), 0) AS ipi, COALESCE(sum(i.valor_st), 0) AS st
      FROM core_comercial.propostas_itens i WHERE i.id_proposta = p_id
  )
  UPDATE core_comercial.propostas p
     SET subtotal = t.subtotal, total_desconto = t.desconto, total_icms = t.icms, total_ipi = t.ipi, total_st = t.st,
         total_geral = t.base + t.ipi + t.st + p.valor_frete,
         valor_aberto = t.base + t.ipi + t.st + p.valor_frete
    FROM t
   WHERE p.id = p_id
  RETURNING p.total_geral;
$$;


--
-- TOC entry 7218 (class 0 OID 0)
-- Dependencies: 513
-- Name: FUNCTION fn_proposta_totais_atualizar(p_id uuid); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_proposta_totais_atualizar(p_id uuid) IS 'Totais da proposta = soma dos itens; total_geral = base + IPI + ST + frete; valor_aberto = total_geral (mesma regra de fn_proposta_criar desde 29/10).';


--
-- TOC entry 843 (class 1255 OID 24658)
-- Name: fn_proposta_transformar(uuid, uuid, integer, jsonb); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_transformar(p_id uuid, p_usuario uuid, p_versao integer DEFAULT NULL::integer, p_dados jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v          core_comercial.propostas%ROWTYPE;
  v_numero   text;
  v_pedido   uuid;
  v_sim      uuid;
  v_vendedor varchar(11);
  v_cli_omie varchar(15);
  v_hoje     date := core_comercial.fn_hoje();
  v_qtd      integer;
  v_prejuizo integer;
  v_dados    jsonb := COALESCE(p_dados, '{}'::jsonb);
  v_pend     jsonb;
  v_cond_sim varchar(40);
BEGIN
  IF p_usuario IS NULL THEN RAISE EXCEPTION 'Usuário obrigatório.' USING ERRCODE = '23514'; END IF;
  v := core_comercial.fn_proposta_trava(p_id, p_versao);
  IF v.status <> 'APROVADA' THEN
    RAISE EXCEPTION 'Só proposta APROVADA vira pedido (esta está %).', v.status USING ERRCODE = 'AV532', DETAIL = v.status;
  END IF;
  PERFORM core_comercial.fn_proposta_exigir_validade(v);
  IF v.id_parametros IS NULL THEN
    RAISE EXCEPTION 'A proposta não tem análise de margem gravada (id_parametros): sem ela não há simulação de comissão v1. Revise a proposta com a análise.'
      USING ERRCODE = 'AV534';
  END IF;

  -- Conta Omie = unidade da proposta (core.unidades; N16-80). A HRM tem conta própria.
  v_vendedor := core_comercial.fn_pedido_venda_vendedor(v.id_responsavel, v.codigo_empresa);
  SELECT pa.codigo_parceiro_omie INTO v_cli_omie FROM core.parceiros pa WHERE pa.id = v.id_cliente;

  v_numero := 'PV-' || lpad(core_comercial.fn_proxima_sequencia_documento('PV', 0)::text, 6, '0');

  INSERT INTO core_comercial.pedidos_venda (
    numero_pedido, id_proposta, numero_proposta, codigo_empresa, codigo_empresa_omie,
    id_cliente, codigo_cliente_omie, cliente_snapshot, id_responsavel, codigo_vendedor_omie, data_pedido,
    numero_pedido_cliente, finalidade, tipo_venda, moeda, cotacao_moeda, incoterm, condicao_pagamento,
    condicao_pagamento_chave, estado_destino, isento_impostos, isento_pis_cofins, requisitos_qualidade, observacoes,
    valor_frete, subtotal, total_desconto, total_icms, total_ipi, total_st, total_geral,
    data_previsao, etapa, codigo_parcela, codigo_categoria, numero_contrato, frete_modalidade, bloqueado,
    dados_adicionais_nf, qualidade_acompanha, faturar_em_partes, codigo_conta_corrente, created_by, updated_by)
  VALUES (
    v_numero, v.id, v.numero_completo, v.codigo_empresa, v.codigo_empresa,
    v.id_cliente, v_cli_omie, v.cliente_snapshot, v.id_responsavel, v_vendedor, v_hoje,
    CASE WHEN v_dados ? 'numero_pedido_cliente' THEN NULLIF(btrim(v_dados->>'numero_pedido_cliente'), '') ELSE v.numero_requisicao END,
    v.finalidade, v.tipo_venda, v.moeda, v.cotacao_moeda, v.incoterm, v.condicao_pagamento,
    v.condicao_pagamento_chave, v.estado_destino, v.isento_impostos, v.isento_pis_cofins, v.requisitos_qualidade, v.observacoes,
    v.valor_frete, v.subtotal, v.total_desconto, v.total_icms, v.total_ipi, v.total_st, v.total_geral,
    core_comercial.fn_data_do_corpo(v_dados->>'data_previsao'), '10', v.codigo_condicao_pagamento,
    NULLIF(btrim(v_dados->>'codigo_categoria'), ''), NULLIF(upper(btrim(v_dados->>'numero_contrato')), ''),
    COALESCE(NULLIF(btrim(v_dados->>'frete_modalidade'), ''), core_comercial.fn_frete_modalidade_omie(v.incoterm)),
    COALESCE((v_dados->>'bloqueado')::boolean, true),
    NULLIF(btrim(v_dados->>'dados_adicionais_nf'), ''),
    (v_dados->>'qualidade_acompanha')::boolean, (v_dados->>'faturar_em_partes')::boolean,
    core_comercial.fn_conta_corrente_padrao(v.codigo_empresa),
    p_usuario, p_usuario)
  RETURNING id INTO v_pedido;

  INSERT INTO core_comercial.pedidos_venda_itens (
    id_pedido, ordem, id_proposta_item, id_produto, codigo, codigo_produto_omie, descricao, observacao, ncm,
    quantidade, unidade_medida, preco_unitario, desconto_pct, preco_unitario_liquido, icms_pct, ipi_pct, st_pct,
    subtotal_bruto, valor_desconto, base, valor_icms, valor_ipi, valor_st, prazo_dias_uteis,
    tec_norma, tec_material, tec_certificados, tec_ensaios)
  SELECT v_pedido, row_number() OVER (ORDER BY i.ordem, i.id), i.id, i.id_produto, COALESCE(i.codigo, pr.codigo_produto),
         pr.codigo_produto_omie, i.descricao, i.observacao, i.ncm,
         i.quantidade, i.unidade_medida, i.preco_unitario, i.desconto_pct, i.preco_unitario_liquido, i.icms_pct, i.ipi_pct, i.st_pct,
         i.subtotal_bruto, i.valor_desconto, i.base, i.valor_icms, i.valor_ipi, i.valor_st, i.prazo_dias_uteis,
         i.tec_norma, i.tec_material, i.tec_certificados, i.tec_ensaios
    FROM core_comercial.propostas_itens i
    LEFT JOIN core.produtos pr ON pr.id = i.id_produto
   WHERE i.id_proposta = v.id;
  GET DIAGNOSTICS v_qtd = ROW_COUNT;

  -- Prontidão (item 6b): com qualquer pendência, nada fica (pedido, número PV, simulação, status).
  v_pend := core_comercial.fn_pedido_venda_pendencias(v_pedido);
  IF jsonb_array_length(v_pend) > 0 THEN
    RAISE EXCEPTION '%', 'O pedido não pode ir ao Omie: ' || (SELECT string_agg(e->>'mensagem', ' ') FROM jsonb_array_elements(v_pend) e)
      USING ERRCODE = 'AV540', DETAIL = v_pend::text;
  END IF;

  SELECT count(*) FILTER (WHERE i.regra_aplicada = 'PREJUIZO') INTO v_prejuizo
    FROM core_comercial.propostas_itens i WHERE i.id_proposta = v.id;

  -- [Pedido do Robert, 12/11/2026 — encargo da condição de pagamento] Com encargo gravado,
  -- o texto da simulação é só rótulo: a descrição da condição do Omie, cortada em 40 (a coluna
  -- é varchar(40)). Proposta antiga (encargo nulo): o nome da condição do simulador, como antes,
  -- para o front reencontrar o percentual em simulador_parametros.encargos_pagamento.
  IF v.encargo_pagamento IS NOT NULL THEN
    SELECT left(btrim(c.descricao), 40) INTO v_cond_sim
      FROM core_vendas_faturamento.condicoes_pagamento_compras c
     WHERE c.codigo_empresa = v.codigo_empresa AND c.codigo_omie = v.codigo_condicao_pagamento;
    v_cond_sim := COALESCE(NULLIF(v_cond_sim, ''), left(NULLIF(btrim(v.condicao_pagamento), ''), 40), v.condicao_pagamento_chave);
  ELSE
    v_cond_sim := v.condicao_pagamento_chave;
  END IF;

  -- Simulação v1: copiada da análise da proposta, sem recalcular. numero_pedido nasce com o
  -- PV do Hub e vira o número do Omie quando o envio dá certo (fn_pedido_venda_omie_registrar).
  INSERT INTO core_comissionamento.simulacoes (
    codigo_empresa, numero_pedido, sequencial, codigo_pedido_omie, origem, versao, status, submitted_at,
    codigo_vendedor_omie, codigo_cliente, data_pedido, estado_destino, condicao_pagamento, isento_imposto,
    frete_compra_tipo, frete_compra_valor, valor_st_venda, imposto_retido_difal, frete_venda, id_parametros,
    custo_total, venda_sugerida, total_nf, valor_liquido, markup_projetado, markup_real, markup_bruto, pct_opex, lucro,
    margem_liquida, letra_equivalente, pct_comissao_efetivo, valor_comissao_total, qtd_itens, qtd_itens_prejuizo,
    observacao, encargo_pagamento, codigo_condicao_pagamento, created_by, updated_by)
  VALUES (
    v.codigo_empresa, v_numero, NULL, NULL, 'VENDEDOR', 1, 'ENVIADO', now(),
    v_vendedor, v_cli_omie, v_hoje, v.estado_destino, v_cond_sim, v.isento_impostos,
    v.frete_compra_tipo, v.frete_compra_valor, v.total_st, v.imposto_retido_difal, v.valor_frete, v.id_parametros,
    v.custo_total, v.venda_sugerida, COALESCE(v.total_nf, v.total_geral), v.valor_liquido, v.markup_projetado, v.markup_real,
    v.markup_bruto, v.pct_opex, v.lucro,
    v.margem_liquida_pct, v.letra, v.pct_comissao_efetivo, v.valor_comissao_total, v_qtd, COALESCE(v.qtd_itens_prejuizo, v_prejuizo),
    format('v1 da proposta %s (revisão %s), gerada ao transformar em pedido.', v.numero_completo, v.revisao),
    v.encargo_pagamento, v.codigo_condicao_pagamento,
    p_usuario, p_usuario)
  RETURNING id INTO v_sim;

  INSERT INTO core_comissionamento.simulacao_itens (
    id_simulacao, ordem, codigo_item_omie, codigo_produto_omie, codigo_produto, descricao, qtd, unidade, tipo_item,
    preco_unit_compra, fornecedor, origem_compra, pct_ipi, valor_st, preco_unit_venda, custo_liquido, preco_unit_sugerido,
    icms_efetivo, pct_impostos, margem_item, letra_item, pct_comissao, regra_aplicada, frete_compra_valor, qtd_compra,
    unidade_compra, created_by, updated_by)
  SELECT v_sim, row_number() OVER (ORDER BY i.ordem, i.id), NULL, pr.codigo_produto_omie, COALESCE(i.codigo, pr.codigo_produto),
         i.descricao, i.quantidade::double precision, i.unidade_medida, i.tipo_item,
         COALESCE(i.preco_unit_compra, 0), left(i.fornecedor, 120), i.origem_compra, i.ipi_compra_pct, i.st_compra_valor,
         i.preco_unitario_liquido, i.custo_liquido_total, i.preco_unit_sugerido,
         i.icms_efetivo, i.pct_impostos, i.margem_item_pct, i.letra, i.pct_comissao, i.regra_aplicada, i.frete_compra_valor,
         i.qtd_compra, i.unidade_compra, p_usuario, p_usuario
    FROM core_comercial.propostas_itens i
    LEFT JOIN core.produtos pr ON pr.id = i.id_produto
   WHERE i.id_proposta = v.id;

  UPDATE core_comercial.pedidos_venda SET id_simulacao = v_sim WHERE id = v_pedido;
  UPDATE core_comercial.propostas SET status = 'TRANSFORMADA', versao = v.versao + 1, updated_by = p_usuario WHERE id = p_id;
  INSERT INTO core_comercial.propostas_eventos (id_proposta, tipo, dados, id_usuario)
  VALUES (p_id, 'TRANSFORMADA', jsonb_build_object('numero_pedido', v_numero, 'id_pedido', v_pedido, 'id_simulacao', v_sim,
                                                    'total_geral', v.total_geral,
                                                    'data_previsao', core_comercial.fn_data_do_corpo(v_dados->>'data_previsao'),
                                                    'qualidade_acompanha', (v_dados->>'qualidade_acompanha')::boolean,
                                                    'faturar_em_partes', (v_dados->>'faturar_em_partes')::boolean), p_usuario);

  RETURN jsonb_build_object('id_pedido', v_pedido, 'numero_pedido', v_numero, 'id_simulacao', v_sim,
                            'codigo_empresa_omie', v.codigo_empresa, 'codigo_vendedor_omie', v_vendedor);
END
$$;


