--

CREATE FUNCTION core_comercial.fn_proposta_trava(p_id uuid, p_versao integer) RETURNS core_comercial.propostas
    LANGUAGE plpgsql
    AS $$
DECLARE
  v core_comercial.propostas%ROWTYPE;
BEGIN
  SELECT * INTO v FROM core_comercial.propostas WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Proposta não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF p_versao IS NOT NULL AND p_versao IS DISTINCT FROM v.versao THEN
    RAISE EXCEPTION 'A proposta foi alterada por outra pessoa (versão atual %).', v.versao
      USING ERRCODE = 'AV521', DETAIL = v.versao::text;
  END IF;
  RETURN v;
END
$$;


--
-- TOC entry 1054 (class 1255 OID 24372)
-- Name: fn_proposta_validade_ate(text, date); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_validade_ate(p_validade text, p_base date) RETURNS date
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $_$
DECLARE
  v text := upper(btrim(COALESCE(p_validade, '')));
  m text[];
BEGIN
  IF v = '' THEN RETURN NULL; END IF;
  m := regexp_match(v, '^(\d{4})-(\d{1,2})-(\d{1,2})(T.*)?$');                 -- 2026-11-15 (ou ISO com hora)
  IF m IS NOT NULL THEN
    BEGIN RETURN make_date(m[1]::int, m[2]::int, m[3]::int); EXCEPTION WHEN others THEN RETURN NULL; END;
  END IF;
  m := regexp_match(v, '^(\d{1,2})/(\d{1,2})/(\d{4})$');                       -- 15/11/2026
  IF m IS NOT NULL THEN
    BEGIN RETURN make_date(m[3]::int, m[2]::int, m[1]::int); EXCEPTION WHEN others THEN RETURN NULL; END;
  END IF;
  m := regexp_match(v, '^(\d{1,3})\s*(DIAS?|D)?(\s+CORRIDOS)?\.?$');            -- 10 / 10 DIAS / 10 DIAS CORRIDOS
  IF m IS NOT NULL AND p_base IS NOT NULL AND m[1]::int > 0 THEN
    RETURN p_base + m[1]::int;
  END IF;
  RETURN NULL;
END
$_$;


