-- Name: FUNCTION fn_proposta_validade_ate(p_validade text, p_base date); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_proposta_validade_ate(p_validade text, p_base date) IS 'Lê a validade da proposta como data: "aaaa-mm-dd" (também ISO com hora), "dd/mm/aaaa" ou "N", "N DIAS", "N DIAS CORRIDOS" contados de p_base (emissão ou revisão). Qualquer outra coisa (inclusive dias úteis) devolve NULL.';


--
-- TOC entry 646 (class 1255 OID 24385)
-- Name: fn_proposta_validade_do_corpo(jsonb, date); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_proposta_validade_do_corpo(p jsonb, p_base date, OUT validade text, OUT validade_ate date) RETURNS record
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  validade_ate := COALESCE(core_comercial.fn_proposta_validade_ate(p->>'validade_ate', NULL),
                           core_comercial.fn_proposta_validade_ate(p->>'validade', p_base));
  IF validade_ate IS NULL THEN
    RAISE EXCEPTION 'Validade inválida: "%". Use a data (aaaa-mm-dd ou dd/mm/aaaa) ou "N DIAS".', COALESCE(p->>'validade_ate', p->>'validade', '')
      USING ERRCODE = 'AV535';
  END IF;
  IF validade_ate < core_comercial.fn_hoje() THEN
    RAISE EXCEPTION 'Validade no passado (%).', to_char(validade_ate, 'DD/MM/YYYY') USING ERRCODE = 'AV535';
  END IF;
  validade := COALESCE(NULLIF(btrim(p->>'validade'), ''), to_char(validade_ate, 'YYYY-MM-DD'));
END
$$;


--
-- TOC entry 897 (class 1255 OID 24843)
-- Name: fn_propostas_conferir_emissao(); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_propostas_conferir_emissao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_usuario      uuid;
  v_resp_mudou   boolean;
  v_cli_mudou    boolean;
  v_situacao     text;
  v_sigla        text;
  v_carteira     text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_usuario    := NEW.created_by;
    v_resp_mudou := true;
    v_cli_mudou  := true;
  ELSE
    v_usuario    := NEW.updated_by;
    v_resp_mudou := NEW.id_responsavel IS DISTINCT FROM OLD.id_responsavel
                    OR NEW.codigo_empresa IS DISTINCT FROM OLD.codigo_empresa;
    v_cli_mudou  := v_resp_mudou OR NEW.id_cliente IS DISTINCT FROM OLD.id_cliente;
  END IF;
  IF NOT v_resp_mudou AND NOT v_cli_mudou THEN
    RETURN NEW;
  END IF;
  SELECT u.sigla INTO v_sigla FROM core.unidades u WHERE u.id = NEW.codigo_empresa;

  IF v_resp_mudou THEN
    v_situacao := core_comercial.fn_emissao_responsavel_situacao(v_usuario, NEW.codigo_empresa, NEW.id_responsavel);
    IF v_situacao = 'FORA_DO_VINCULO' THEN
      RAISE EXCEPTION 'Você só pode emitir proposta em seu nome ou no de um vendedor titular que você auxilia.'
        USING ERRCODE = 'AV546', DETAIL = NEW.id_responsavel::text;
    ELSIF v_situacao = 'SEM_VENDEDOR' THEN
      RAISE EXCEPTION 'O responsável % não tem vendedor ativo no Omie da %: não pode ser responsável por proposta desta empresa.',
                      auth.fn_nome_usuario(NEW.id_responsavel), COALESCE(v_sigla, 'unidade')
        USING ERRCODE = 'AV545', DETAIL = COALESCE(v_sigla, '');
    ELSIF v_situacao = 'NAO_HABILITADO' THEN
      RAISE EXCEPTION 'O usuário % não pode ser responsável por proposta da % (sem permissão de criar propostas, fora da unidade ou desligado no perfil comercial).',
                      auth.fn_nome_usuario(NEW.id_responsavel), COALESCE(v_sigla, 'unidade')
        USING ERRCODE = 'AV548', DETAIL = COALESCE(v_sigla, '');
    END IF;
  END IF;

  -- Carteira: a gerência (escopo todos) não tem filtro (regra 5).
  IF v_cli_mudou AND auth.fn_escopo_vendedores_usuario(v_usuario) IS DISTINCT FROM 'todos' THEN
    -- Dois vendedores salvando proposta para o mesmo cliente livre ao mesmo
    -- tempo: o segundo espera o primeiro terminar e já vê a reserva dele.
    PERFORM pg_advisory_xact_lock(hashtextextended('core_comercial.carteira:' || NEW.id_cliente::text, 0));
    v_carteira := core_comercial.fn_cliente_carteira(NEW.codigo_empresa, NEW.id_cliente, NEW.id_responsavel, false, NEW.id);
    IF v_carteira = 'outra' THEN
      RAISE EXCEPTION 'Este cliente está na carteira de outro vendedor. Fale com a gerência.'
        USING ERRCODE = 'AV547', DETAIL = NEW.id_cliente::text;
    END IF;
  END IF;
  RETURN NEW;
END
$$;


--
-- TOC entry 7221 (class 0 OID 0)
-- Dependencies: 897
-- Name: FUNCTION fn_propostas_conferir_emissao(); Type: COMMENT; Schema: core_comercial; Owner: -
--

COMMENT ON FUNCTION core_comercial.fn_propostas_conferir_emissao() IS 'Pedido do Robert (11/11/2026): trigger de core_comercial.propostas. Quem age = created_by (INSERT) ou updated_by (UPDATE). Responsável (quando ele ou a unidade mudam): fn_emissao_responsavel_situacao -> AV546 fora do vínculo, AV545 sem vendedor ativo na unidade, AV548 fora de fn_responsaveis_proposta. Carteira (quando o cliente, o responsável ou a unidade mudam; gerência passa): fn_cliente_carteira do responsável, sem a própria proposta -> AV547 se o cliente é de outro vendedor; trava (advisory) por cliente, para duas propostas simultâneas do mesmo cliente livre não ficarem as duas. Revisar sem mudar responsável nem cliente não confere nada (decisões 2 e 10 do Robert).';


--
-- TOC entry 929 (class 1255 OID 24394)
-- Name: fn_propostas_expirar(date, uuid); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_propostas_expirar(p_hoje date DEFAULT NULL::date, p_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_hoje date := COALESCE(p_hoje, core_comercial.fn_hoje());
  v_n    integer;
BEGIN
  WITH alvo AS (
    SELECT p.id FROM core_comercial.propostas p
     WHERE p.status = 'ABERTA' AND p.deleted_at IS NULL AND p.validade_ate < v_hoje
       AND (p_id IS NULL OR p.id = p_id)
     FOR UPDATE SKIP LOCKED
  ), upd AS (
    UPDATE core_comercial.propostas p
       SET status = 'EXPIRADA', versao = p.versao + 1
      FROM alvo WHERE p.id = alvo.id
    RETURNING p.id, p.validade, p.validade_ate, p.numero_completo, p.total_geral
  ), ev AS (
    INSERT INTO core_comercial.propostas_eventos (id_proposta, tipo, dados, id_usuario)
    SELECT u.id, 'EXPIRADA',
           jsonb_build_object('validade', u.validade, 'validade_ate', u.validade_ate, 'numero_completo', u.numero_completo,
                              'total_geral', u.total_geral, 'automatica', true),
           NULL
      FROM upd u
    RETURNING 1
  )
  SELECT count(*) INTO v_n FROM ev;
  RETURN v_n;
END
$$;


--
-- TOC entry 7222 (class 0 OID 0)
