--

CREATE FUNCTION core_comercial.fn_responsaveis_proposta(p_codigo_emissora text DEFAULT NULL::text) RETURNS TABLE(id_usuario uuid, nome text, email text)
    LANGUAGE sql STABLE
    AS $$
  SELECT u.id, auth.fn_nome_usuario(u.id)::text, u.email::text
    FROM auth.usuarios u
    LEFT JOIN core_comercial.perfis_comerciais pc ON pc.id_usuario = u.id
   WHERE u.ativo AND u.deleted_at IS NULL
     AND COALESCE(pc.responsavel_proposta, true)
     AND EXISTS (
           SELECT 1
             FROM auth.usuarios_perfis up
             JOIN auth.perfis p      ON p.id = up.id_perfil AND p.deleted_at IS NULL
             JOIN auth.permissoes pm ON pm.id_perfil = p.id AND pm.deleted_at IS NULL AND pm.pode_criar
             JOIN auth.telas t       ON t.id = pm.id_tela AND t.deleted_at IS NULL AND t.ativo AND t.slug = 'propostas'
            WHERE up.id_usuario = u.id)
     AND (p_codigo_emissora IS NULL
          OR NOT EXISTS (SELECT 1 FROM auth.usuarios_unidades uu WHERE uu.id_usuario = u.id)
          OR EXISTS (SELECT 1
                       FROM auth.usuarios_unidades uu
                       JOIN core.unidades un ON un.id = uu.codigo_empresa
                      WHERE uu.id_usuario = u.id AND un.sigla = upper(p_codigo_emissora)))
   ORDER BY 2, 1;
$$;


