-- Name: fn_versionado_imutavel(); Type: FUNCTION; Schema: core_comercial; Owner: -
--

CREATE FUNCTION core_comercial.fn_versionado_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_livres text[] := ARRAY['vigencia_fim', 'substituida_em', 'substituida_por'];
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION '%: versão de parâmetro não pode ser apagada (o custo antigo precisa continuar explicável).', TG_TABLE_NAME
      USING ERRCODE = '23514';
  END IF;
  IF (to_jsonb(NEW) - v_livres) IS DISTINCT FROM (to_jsonb(OLD) - v_livres) THEN
    RAISE EXCEPTION '%: versão gravada não muda; salve uma nova versão.', TG_TABLE_NAME USING ERRCODE = '23514';
  END IF;
  IF OLD.vigencia_fim IS NOT NULL AND NEW.vigencia_fim IS DISTINCT FROM OLD.vigencia_fim THEN
    RAISE EXCEPTION '%: vigência já fechada não muda.', TG_TABLE_NAME USING ERRCODE = '23514';
  END IF;
  IF (OLD.substituida_em IS NOT NULL AND NEW.substituida_em IS DISTINCT FROM OLD.substituida_em)
     OR (OLD.substituida_por IS NOT NULL AND NEW.substituida_por IS DISTINCT FROM OLD.substituida_por) THEN
    RAISE EXCEPTION '%: versão já substituída não muda.', TG_TABLE_NAME USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


