    AS $$ SELECT lower(public.unaccent('public.unaccent'::regdictionary, btrim(COALESCE(p_texto, '')))) $$;


--
-- TOC entry 7233 (class 0 OID 0)
-- Dependencies: 882
-- Name: FUNCTION fn_orc_normalizar(p_texto text); Type: COMMENT; Schema: core_compras; Owner: -
--

COMMENT ON FUNCTION core_compras.fn_orc_normalizar(p_texto text) IS 'Contrato 07: texto sem espaços nas pontas, em minúsculas e sem acento (mesma regra do normalizeText do av-hub), usado na busca de Orçamento. Declarada IMMUTABLE (dicionário fixo) para poder entrar em coluna gerada — por isso NÃO mude o corpo depois de carregar dados (as colunas geradas não seriam recalculadas). NULL vira ''''.';


