--
-- TOC entry 590 (class 1255 OID 22329)
-- Name: fn_feed_aplicar(text, jsonb); Type: FUNCTION; Schema: core_fluxo; Owner: -
--

CREATE FUNCTION core_fluxo.fn_feed_aplicar(p_fonte text, p_eventos jsonb) RETURNS TABLE(recebidos integer, aplicados integer, novos integer, ignorados_velhos integer, invalidos jsonb, cursor_anterior bigint, novo_cursor bigint)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  r              record;
  e              jsonb;
  cur            core_fluxo.item_estado_projetado%ROWTYPE;
  v_achou        boolean;
  v_motivo       text;
  v_seq          bigint;
  v_max_seq      bigint := 0;
  v_cursor       bigint;
  v_empresa      uuid;
  v_pedido       text;
  v_item         bigint;
  v_ocorrido     timestamptz;
  v_tipo         text;
  v_etapa        text;
  v_setor        text;
  v_entrou       timestamptz;
  v_tem_resp     boolean;
  v_resp         text;
  v_resp_nome    text;
  v_resp_setor   text;
  v_fila         text;
  v_encerrado    timestamptz;
  v_encerramento text;
  v_campo        text;
  v_rec          integer := 0;
  v_apl          integer := 0;
  v_novos        integer := 0;
  v_velhos       integer := 0;
  v_inv          jsonb := '[]'::jsonb;
  -- tamanho máximo de cada campo de texto opcional (a coluna que recebe)
  c_limites CONSTANT jsonb := '{
    "origem": 20, "tipo": 60, "etapa_de": 80, "etapa_para": 80, "setor_fluxo": 80,
    "estado_macro": 40, "id_item_acompanhado": 64, "id_responsavel_depois": 64,
    "responsavel_depois": 64, "responsavel_depois_nome": 200, "responsavel_depois_setor": 120,
    "ator_id": 64, "ator_nome": 200, "ator_setor": 120, "passou_para_id": 64, "passou_para_fila": 80
  }'::jsonb;
BEGIN
  IF p_fonte IS NULL OR p_fonte !~ '^[a-z][a-z0-9_-]*$' THEN
    RAISE EXCEPTION 'fn_feed_aplicar: fonte inválida (%)', p_fonte USING ERRCODE = '22023';
  END IF;
  IF p_eventos IS NULL OR jsonb_typeof(p_eventos) <> 'array' THEN
    RAISE EXCEPTION 'fn_feed_aplicar: eventos deve ser um array JSON' USING ERRCODE = '22023';
  END IF;

  SELECT c.ultimo_seq INTO v_cursor FROM core_fluxo.feed_cursor c WHERE c.fonte = p_fonte;
  v_cursor := COALESCE(v_cursor, 0);

  -- Em ordem de seq (inválidos sem seq primeiro, só para o log).
  FOR r IN
    SELECT x.ev, x.ord
      FROM jsonb_array_elements(p_eventos) WITH ORDINALITY AS x(ev, ord)
     ORDER BY CASE WHEN jsonb_typeof(x.ev) = 'object' AND (x.ev->>'seq') ~ '^[0-9]{1,18}$'
                   THEN (x.ev->>'seq')::bigint END NULLS FIRST,
              x.ord
  LOOP
    v_rec := v_rec + 1;
    e := r.ev;
    v_motivo := NULL;
    v_seq := NULL;

    -- ---- validação do envelope (seção 3.1) ----
    IF jsonb_typeof(e) <> 'object' THEN
      v_motivo := 'evento não é um objeto JSON';
    ELSIF COALESCE(e->>'seq', '') !~ '^[0-9]{1,18}$' OR (e->>'seq')::bigint = 0 THEN
      v_motivo := 'seq ausente ou inválido (inteiro positivo)';
    ELSE
      v_seq := (e->>'seq')::bigint;
      v_max_seq := GREATEST(v_max_seq, v_seq);
      IF NOT pg_input_is_valid(COALESCE(e->>'id', ''), 'uuid') THEN
        v_motivo := 'id ausente ou não é uuid';
      ELSIF NOT pg_input_is_valid(COALESCE(e->>'codigo_empresa', ''), 'uuid') THEN
        v_motivo := 'codigo_empresa ausente ou não é uuid';
      ELSIF NOT EXISTS (SELECT 1 FROM core.unidades u WHERE u.id = (e->>'codigo_empresa')::uuid) THEN
        v_motivo := 'codigo_empresa não é uma unidade do av-hub';
      ELSIF btrim(COALESCE(e->>'numero_pedido', '')) = '' THEN
        v_motivo := 'numero_pedido ausente';
      ELSIF length(btrim(e->>'numero_pedido')) > 40 THEN
        v_motivo := 'numero_pedido com mais de 40 caracteres';
      ELSIF btrim(COALESCE(e->>'codigo_item_omie', '')) !~ '^[0-9]{1,18}$'
            OR btrim(e->>'codigo_item_omie')::bigint = 0 THEN
        v_motivo := 'codigo_item_omie ausente ou não é inteiro positivo';
      ELSIF COALESCE(e->>'ocorrido_em', '') = '' OR NOT pg_input_is_valid(e->>'ocorrido_em', 'timestamptz') THEN
        v_motivo := 'ocorrido_em ausente ou inválido';
      ELSIF e ? 'prazo_pedido' AND e->>'prazo_pedido' IS NOT NULL
            AND NOT pg_input_is_valid(substr(e->>'prazo_pedido', 1, 10), 'date') THEN
        v_motivo := 'prazo_pedido inválido';
      ELSIF e ? 'entrou_etapa_em' AND e->>'entrou_etapa_em' IS NOT NULL
            AND NOT pg_input_is_valid(e->>'entrou_etapa_em', 'timestamptz') THEN
        v_motivo := 'entrou_etapa_em inválido';
      ELSIF e ? 'terminal' AND jsonb_typeof(e->'terminal') NOT IN ('boolean', 'null') THEN
        v_motivo := 'terminal deve ser booleano';
      ELSE
        SELECT k INTO v_campo
          FROM jsonb_each_text(c_limites) AS l(k, lim)
         WHERE length(e->>l.k) > l.lim::int
         LIMIT 1;
        IF v_campo IS NOT NULL THEN
          v_motivo := format('%s com mais de %s caracteres', v_campo, c_limites->>v_campo);
          v_campo := NULL;
        END IF;
      END IF;
    END IF;

    IF v_motivo IS NOT NULL THEN
      v_inv := v_inv || jsonb_build_array(jsonb_build_object(
        'seq', CASE WHEN jsonb_typeof(e) = 'object' THEN e->'seq' END,
        'id', CASE WHEN jsonb_typeof(e) = 'object' THEN e->'id' END,
        'motivo', v_motivo));
      CONTINUE;
    END IF;

    v_empresa  := (e->>'codigo_empresa')::uuid;
    v_pedido   := btrim(e->>'numero_pedido');
    v_item     := btrim(e->>'codigo_item_omie')::bigint;
    v_ocorrido := (e->>'ocorrido_em')::timestamptz;
    v_tipo     := NULLIF(btrim(COALESCE(e->>'tipo', '')), '');

    SELECT * INTO cur
      FROM core_fluxo.item_estado_projetado p
     WHERE p.codigo_empresa = v_empresa AND p.numero_pedido = v_pedido AND p.codigo_item_omie = v_item
       FOR UPDATE;
    v_achou := FOUND;

    -- Só aplica evento MAIS NOVO que o último aplicado ao item (seção 3.1).
    IF v_achou AND cur.ultimo_seq >= v_seq THEN
      v_velhos := v_velhos + 1;
      CONTINUE;
    END IF;

    -- etapa e entrada na etapa
    v_etapa := COALESCE(NULLIF(btrim(COALESCE(e->>'etapa_para', '')), ''),
                        CASE WHEN v_achou THEN cur.etapa_fluxo END);
    IF NULLIF(e->>'entrou_etapa_em', '') IS NOT NULL THEN
      v_entrou := (e->>'entrou_etapa_em')::timestamptz;
    ELSIF NOT v_achou OR v_etapa IS DISTINCT FROM cur.etapa_fluxo THEN
      v_entrou := v_ocorrido;
    ELSE
      v_entrou := cur.entrou_etapa_em;
    END IF;
    v_setor := COALESCE(NULLIF(btrim(COALESCE(e->>'setor_fluxo', '')), ''),
                        CASE WHEN v_achou THEN cur.setor_fluxo END);

    -- responsável depois do evento: chave presente (mesmo null) muda; ausente mantém
    v_tem_resp := e ? 'id_responsavel_depois' OR e ? 'responsavel_depois';
    IF v_tem_resp THEN
      v_resp := NULLIF(btrim(COALESCE(e->>'id_responsavel_depois', e->>'responsavel_depois', '')), '');
      IF v_resp IS NULL THEN
        v_resp_nome := NULL;
        v_resp_setor := NULL;
        v_fila := COALESCE(NULLIF(btrim(COALESCE(e->>'passou_para_fila', '')), ''), v_setor);
      ELSE
        v_resp_nome := COALESCE(NULLIF(e->>'responsavel_depois_nome', ''),
                                CASE WHEN v_resp = e->>'ator_id' THEN NULLIF(e->>'ator_nome', '') END);
        v_resp_setor := COALESCE(NULLIF(e->>'responsavel_depois_setor', ''),
                                 CASE WHEN v_resp = e->>'ator_id' THEN NULLIF(e->>'ator_setor', '') END);
        v_fila := NULL;
      END IF;
    ELSIF v_achou THEN
      v_resp := cur.id_responsavel_atual;
      v_resp_nome := cur.responsavel_nome;
      v_resp_setor := cur.responsavel_setor;
      v_fila := cur.fila_setor_fluxo;
    ELSE
      v_resp := NULL;
      v_resp_nome := NULL;
      v_resp_setor := NULL;
      v_fila := v_setor;
    END IF;

    -- encerramento (PROVISÓRIO: pergunta 2)
    IF lower(COALESCE(v_tipo, '')) = 'cancelamento' THEN
      v_encerrado := v_ocorrido;
      v_encerramento := 'cancelado';
    ELSIF lower(COALESCE(v_tipo, '')) = 'reabertura' THEN
      v_encerrado := NULL;
      v_encerramento := NULL;
    ELSIF (e->>'terminal') = 'true' THEN
      v_encerrado := v_ocorrido;
      v_encerramento := 'concluido';
    ELSIF v_achou THEN
      v_encerrado := cur.encerrado_em;
      v_encerramento := cur.encerramento;
    ELSE
      v_encerrado := NULL;
      v_encerramento := NULL;
    END IF;

    IF v_achou THEN
      UPDATE core_fluxo.item_estado_projetado p
         SET id_item_mes          = COALESCE(NULLIF(btrim(COALESCE(e->>'id_item_acompanhado', '')), ''), cur.id_item_mes),
             etapa_fluxo          = v_etapa,
             estado_macro         = COALESCE(NULLIF(btrim(COALESCE(e->>'estado_macro', '')), ''), cur.estado_macro),
             setor_fluxo          = v_setor,
             id_responsavel_atual = v_resp,
             responsavel_nome     = v_resp_nome,
             responsavel_setor    = v_resp_setor,
             fila_setor_fluxo     = v_fila,
             entrou_etapa_em      = v_entrou,
             prazo_pedido         = COALESCE(substr(NULLIF(e->>'prazo_pedido', ''), 1, 10)::date, cur.prazo_pedido),
             encerrado_em         = v_encerrado,
             encerramento         = v_encerramento,
             ultimo_seq           = v_seq,
             ultimo_evento_id     = (e->>'id')::uuid,
             ultimo_evento_tipo   = v_tipo,
             ultimo_evento_em     = v_ocorrido,
             atualizado_em        = now()
       WHERE p.id = cur.id;
    ELSE
      INSERT INTO core_fluxo.item_estado_projetado (
        codigo_empresa, numero_pedido, codigo_item_omie, id_item_mes, etapa_fluxo, estado_macro, setor_fluxo,
        id_responsavel_atual, responsavel_nome, responsavel_setor, fila_setor_fluxo, entrou_etapa_em,
        prazo_pedido, encerrado_em, encerramento, ultimo_seq, ultimo_evento_id, ultimo_evento_tipo, ultimo_evento_em)
      VALUES (
        v_empresa, v_pedido, v_item, NULLIF(btrim(COALESCE(e->>'id_item_acompanhado', '')), ''), v_etapa,
        NULLIF(btrim(COALESCE(e->>'estado_macro', '')), ''), v_setor,
        v_resp, v_resp_nome, v_resp_setor, v_fila, v_entrou,
        substr(NULLIF(e->>'prazo_pedido', ''), 1, 10)::date, v_encerrado, v_encerramento,
        v_seq, (e->>'id')::uuid, v_tipo, v_ocorrido);
      v_novos := v_novos + 1;
    END IF;
    v_apl := v_apl + 1;
  END LOOP;

  -- Cursor: maior seq lido (inclusive de evento inválido); nunca volta. Página
  -- vazia só marca a leitura (lido_em).
  INSERT INTO core_fluxo.feed_cursor AS c (fonte, ultimo_seq, atualizado_em)
  VALUES (p_fonte, GREATEST(v_cursor, v_max_seq), now())
  ON CONFLICT (fonte) DO UPDATE
     SET ultimo_seq = GREATEST(c.ultimo_seq, EXCLUDED.ultimo_seq),
         atualizado_em = now();

  RETURN QUERY SELECT v_rec, v_apl, v_novos, v_velhos, v_inv, v_cursor, GREATEST(v_cursor, v_max_seq);
END $_$;


