--
-- TOC entry 432 (class 1259 OID 22331)
-- Name: vw_item_estado_atual; Type: VIEW; Schema: core_fluxo; Owner: -
--

CREATE VIEW core_fluxo.vw_item_estado_atual AS
 SELECT p.id,
    p.codigo_empresa,
    p.numero_pedido,
    p.codigo_item_omie,
    pv.codigo_produto,
    p.id_item_mes,
    p.etapa_fluxo,
    p.estado_macro,
    p.setor_fluxo,
    p.id_responsavel_atual,
    p.responsavel_nome,
    p.responsavel_setor,
    p.fila_setor_fluxo,
    p.entrou_etapa_em,
    COALESCE(p.prazo_pedido,
        CASE
            WHEN ((ped.data_previsao)::text ~ '^\d{4}-\d{2}-\d{2}'::text) THEN to_date(substr((ped.data_previsao)::text, 1, 10), 'YYYY-MM-DD'::text)
            ELSE NULL::date
        END) AS prazo_pedido,
    p.encerrado_em,
    p.encerramento,
    p.ultimo_seq,
    p.ultimo_evento_tipo,
    p.ultimo_evento_em,
    p.atualizado_em,
    (p.id_responsavel_atual IS NULL) AS sem_dono,
    ((p.encerrado_em IS NULL) AND (COALESCE(p.prazo_pedido,
        CASE
            WHEN ((ped.data_previsao)::text ~ '^\d{4}-\d{2}-\d{2}'::text) THEN to_date(substr((ped.data_previsao)::text, 1, 10), 'YYYY-MM-DD'::text)
            ELSE NULL::date
        END) < ((now() AT TIME ZONE 'America/Sao_Paulo'::text))::date)) AS fora_do_prazo,
    round((GREATEST(EXTRACT(epoch FROM (now() - p.entrou_etapa_em)), (0)::numeric) / 3600.0), 2) AS horas_na_etapa
   FROM ((core_fluxo.item_estado_projetado p
     LEFT JOIN core_vendas_faturamento.produto_vendas pv ON (((pv.codigo_empresa = p.codigo_empresa) AND (pv.codigo_item_omie = p.codigo_item_omie) AND (pv.deleted_at IS NULL))))
     LEFT JOIN core_vendas_faturamento.pedidos_vendas ped ON (((ped.codigo_empresa = pv.codigo_empresa) AND (ped.codigo_pedido_omie = pv.codigo_pedido_omie) AND (ped.deleted_at IS NULL))))
  WHERE (p.deleted_at IS NULL);


--
-- TOC entry 7262 (class 0 OID 0)
-- Dependencies: 432
-- Name: VIEW vw_item_estado_atual; Type: COMMENT; Schema: core_fluxo; Owner: -
--

COMMENT ON VIEW core_fluxo.vw_item_estado_atual IS 'Contrato 46: a projeção pronta para a Torre. codigo_produto vem de produto_vendas (item do Omie); prazo_pedido = o do MES ou, sem ele, data_previsao da parcela do pedido (pedidos_vendas) que contém o item. fora_do_prazo = item não encerrado com prazo antes de hoje (America/Sao_Paulo); sem_dono = na fila do setor; horas_na_etapa = horas corridas desde entrou_etapa_em, nunca negativas (relógio do MES adiantado vira 0; a pausa do MES não é descontada aqui; o tempo fino vem de /fluxo/itens/{id}/tempo do MES).';


--
-- TOC entry 813 (class 1255 OID 22336)
-- Name: fn_torre_filtrar(uuid[], uuid, text, text, text, text); Type: FUNCTION; Schema: core_fluxo; Owner: -
--

CREATE FUNCTION core_fluxo.fn_torre_filtrar(p_unidades uuid[], p_codigo_empresa uuid, p_setor text, p_etapa text, p_situacao text, p_q text) RETURNS SETOF core_fluxo.vw_item_estado_atual
    LANGUAGE sql STABLE
    AS $$
  SELECT v.*
    FROM core_fluxo.vw_item_estado_atual v
   WHERE v.encerrado_em IS NULL
     AND (p_unidades IS NULL OR v.codigo_empresa = ANY (p_unidades))
     AND (p_codigo_empresa IS NULL OR v.codigo_empresa = p_codigo_empresa)
     AND (p_setor IS NULL OR v.setor_fluxo = p_setor)
     AND (p_etapa IS NULL OR v.etapa_fluxo = p_etapa)
     AND (p_situacao IS NULL
          OR (p_situacao = 'fora_do_prazo' AND v.fora_do_prazo)
          OR (p_situacao = 'no_prazo' AND NOT COALESCE(v.fora_do_prazo, false))
          OR (p_situacao = 'sem_dono' AND v.sem_dono))
     AND (p_q IS NULL
          OR v.numero_pedido ILIKE '%' || replace(replace(replace(p_q, '\', '\\'), '%', '\%'), '_', '\_') || '%'
          OR v.codigo_item_omie::text = p_q
          OR v.codigo_produto ILIKE '%' || replace(replace(replace(p_q, '\', '\\'), '%', '\%'), '_', '\_') || '%');
$$;


