COMMENT ON FUNCTION core_fluxo.fn_torre_filtrar(p_unidades uuid[], p_codigo_empresa uuid, p_setor text, p_etapa text, p_situacao text, p_q text) IS 'Contrato 46: o filtro único da Torre (lista e mapa usam o mesmo, para a contagem do mapa conferir com a lista). Só itens não encerrados. p_unidades = escopo do usuário (NULL = irrestrito). p_situacao: no_prazo | fora_do_prazo | sem_dono (em_risco não existe enquanto não houver meta por etapa). p_q: parte do número do pedido ou do código do produto, ou o codigo_item_omie exato.';


--
-- TOC entry 750 (class 1255 OID 22337)
-- Name: fn_torre_itens(uuid[], uuid, text, text, text, text, integer, integer); Type: FUNCTION; Schema: core_fluxo; Owner: -
--

CREATE FUNCTION core_fluxo.fn_torre_itens(p_unidades uuid[], p_codigo_empresa uuid, p_setor text, p_etapa text, p_situacao text, p_q text, p_limit integer, p_offset integer) RETURNS TABLE(item jsonb, total bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
           'id', f.id,
           'codigo_empresa', f.codigo_empresa,
           'numero_pedido', f.numero_pedido,
           'codigo_item_omie', f.codigo_item_omie::text,
           'codigo_produto', f.codigo_produto,
           'etapa_fluxo', f.etapa_fluxo,
           'estado_macro', f.estado_macro,
           'setor_fluxo', f.setor_fluxo,
           'responsavel', CASE WHEN f.id_responsavel_atual IS NULL
                               THEN jsonb_build_object('tipo', 'fila', 'nome', f.fila_setor_fluxo)
                               ELSE jsonb_build_object('tipo', 'pessoa', 'nome', f.responsavel_nome,
                                                       'setor', f.responsavel_setor) END,
           'entrou_etapa_em', f.entrou_etapa_em,
           'horas_na_etapa', f.horas_na_etapa,
           'prazo_pedido', f.prazo_pedido,
           'fora_do_prazo', COALESCE(f.fora_do_prazo, false),
           'sem_dono', f.sem_dono,
           'ultimo_evento_em', f.ultimo_evento_em),
         count(*) OVER ()
    FROM core_fluxo.fn_torre_filtrar(p_unidades, p_codigo_empresa, p_setor, p_etapa, p_situacao, p_q) f
   ORDER BY f.entrou_etapa_em NULLS LAST, f.numero_pedido, f.codigo_item_omie
   LIMIT GREATEST(COALESCE(p_limit, 50), 1) OFFSET GREATEST(COALESCE(p_offset, 0), 0);
$$;


