COMMENT ON FUNCTION core_fluxo.fn_torre_itens(p_unidades uuid[], p_codigo_empresa uuid, p_setor text, p_etapa text, p_situacao text, p_q text, p_limit integer, p_offset integer) IS 'Contrato 46: lista de itens da Torre (GET /fluxo/torre), com o filtro de fn_torre_filtrar, do que está parado há mais tempo na etapa para o mais recente. total = itens do filtro (sem paginar). responsavel: {tipo: pessoa, nome, setor} ou {tipo: fila, nome: setor da fila}; sem id de pessoa (LGPD).';


--
-- TOC entry 506 (class 1255 OID 22338)
-- Name: fn_torre_setores(uuid[], uuid, text, text, text, text); Type: FUNCTION; Schema: core_fluxo; Owner: -
--

CREATE FUNCTION core_fluxo.fn_torre_setores(p_unidades uuid[], p_codigo_empresa uuid, p_setor text, p_etapa text, p_situacao text, p_q text) RETURNS TABLE(setor_fluxo text, total bigint, fora_do_prazo bigint, sem_dono bigint, horas_paradas_total numeric, horas_paradas_sem_dono numeric, horas_paradas_com_dono numeric, mais_antigo_desde timestamp with time zone, etapas jsonb)
    LANGUAGE sql STABLE
    AS $$
  WITH f AS (
    SELECT * FROM core_fluxo.fn_torre_filtrar(p_unidades, p_codigo_empresa, p_setor, p_etapa, p_situacao, p_q)
  ),
  et AS (
    SELECT f.setor_fluxo, f.etapa_fluxo, count(*) AS total,
           count(*) FILTER (WHERE f.fora_do_prazo) AS fora_do_prazo,
           count(*) FILTER (WHERE f.sem_dono) AS sem_dono
      FROM f
     GROUP BY f.setor_fluxo, f.etapa_fluxo
  ),
  com_item AS (
    SELECT f.setor_fluxo::text AS setor_fluxo,
           count(*) AS total,
           count(*) FILTER (WHERE f.fora_do_prazo) AS fora_do_prazo,
           count(*) FILTER (WHERE f.sem_dono) AS sem_dono,
           COALESCE(sum(f.horas_na_etapa), 0) AS horas_paradas_total,
           COALESCE(sum(f.horas_na_etapa) FILTER (WHERE f.sem_dono), 0) AS horas_paradas_sem_dono,
           COALESCE(sum(f.horas_na_etapa) FILTER (WHERE NOT f.sem_dono), 0) AS horas_paradas_com_dono,
           min(f.entrou_etapa_em) AS mais_antigo_desde,
           (SELECT jsonb_agg(jsonb_build_object('etapa_fluxo', et.etapa_fluxo, 'total', et.total,
                                                'fora_do_prazo', et.fora_do_prazo, 'sem_dono', et.sem_dono)
                             ORDER BY et.etapa_fluxo NULLS LAST)
              FROM et WHERE et.setor_fluxo IS NOT DISTINCT FROM f.setor_fluxo) AS etapas
      FROM f
     GROUP BY f.setor_fluxo
  ),
  -- Setores que a projeção já viu nas unidades pedidas (itens vivos ou
  -- encerrados), com os filtros de unidade, setor e etapa; situação e texto
  -- NÃO restringem: é o que faz o setor "não sumir" do mapa.
  conhecidos AS (
    SELECT DISTINCT p.setor_fluxo::text AS setor_fluxo
      FROM core_fluxo.item_estado_projetado p
     WHERE p.deleted_at IS NULL
       AND p.setor_fluxo IS NOT NULL
       AND (p_unidades IS NULL OR p.codigo_empresa = ANY (p_unidades))
       AND (p_codigo_empresa IS NULL OR p.codigo_empresa = p_codigo_empresa)
       AND (p_setor IS NULL OR p.setor_fluxo = p_setor)
       AND (p_etapa IS NULL OR p.etapa_fluxo = p_etapa)
  )
  SELECT c.setor_fluxo, c.total, c.fora_do_prazo, c.sem_dono,
         c.horas_paradas_total, c.horas_paradas_sem_dono, c.horas_paradas_com_dono,
         c.mais_antigo_desde, c.etapas
    FROM com_item c
  UNION ALL
  SELECT k.setor_fluxo, 0::bigint, 0::bigint, 0::bigint,
         0::numeric, 0::numeric, 0::numeric,
         NULL::timestamptz, '[]'::jsonb
    FROM conhecidos k
   WHERE NOT EXISTS (SELECT 1 FROM com_item c WHERE c.setor_fluxo = k.setor_fluxo)
   ORDER BY 1 NULLS LAST;
$$;


