--

COMMENT ON FUNCTION core_fluxo.fn_torre_setores(p_unidades uuid[], p_codigo_empresa uuid, p_setor text, p_etapa text, p_situacao text, p_q text) IS 'Contrato 46: mapa por setor (T.3) com o MESMO filtro da lista: total, fora do prazo e sem dono por setor e por etapa; e os números do ranking de gargalos (T.5b) tirados da projeção: horas paradas na etapa atual, somadas, separadas em sem dono (fila) e com pessoa, e a entrada mais antiga. Sem média histórica (essa vem do MES). Migration 046b (seção 7.3): setor que a projeção já conhece nas unidades/setor/etapa pedidos e que não tem item no filtro aparece com zero (etapas = [], mais_antigo_desde = null), em vez de sumir; situação e texto não restringem essa lista. Setor que o hub nunca viu não aparece (o catálogo completo é do MES, /fluxo/setores/catalogo).';


--
-- TOC entry 716 (class 1255 OID 17293)
-- Name: fn_default_parent_pessoa(uuid); Type: FUNCTION; Schema: core_organograma; Owner: -
--

CREATE FUNCTION core_organograma.fn_default_parent_pessoa(p_funcionario_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_id_setor        uuid;
  v_nivel           integer;
  v_sub_nivel       smallint;
  v_sup_nivel       integer;
  v_sup_sub_nivel   smallint;
  v_superiores      uuid[];
  v_pos             integer;
BEGIN
  SELECT f.id_setor, c.nvl_permissao, c.sub_nivel
  INTO v_id_setor, v_nivel, v_sub_nivel
  FROM core.funcionarios f
  JOIN core.cargos c ON c.id = f.id_cargo
  WHERE f.id = p_funcionario_id AND f.data_desligamento IS NULL;

  IF v_id_setor IS NULL OR v_nivel < 4 THEN
    RETURN NULL; -- diretoria/gerência geral não têm "setor pai" por essa regra
  END IF;

  -- par (nível, sub-nível) elegível mais próximo ACIMA desta pessoa, no
  -- mesmo setor. Compara como par ordenado — não só nvl_permissao — pra
  -- sub-níveis de mentoria (ex.: Júnior 1→2→3→Pleno→Sênior) encadearem
  -- entre si em vez de todos caírem juntos no mesmo grupo.
  SELECT c2.nvl_permissao, c2.sub_nivel
  INTO v_sup_nivel, v_sup_sub_nivel
  FROM core.funcionarios f2
  JOIN core.cargos c2 ON c2.id = f2.id_cargo
  WHERE f2.id_setor = v_id_setor
    AND f2.data_desligamento IS NULL
    AND c2.nvl_permissao >= 4
    AND (c2.nvl_permissao, c2.sub_nivel) < (v_nivel, v_sub_nivel)
  ORDER BY c2.nvl_permissao DESC, c2.sub_nivel DESC
  LIMIT 1;

  IF v_sup_nivel IS NULL THEN
    RETURN v_id_setor::text; -- é o par mais alto do setor
  END IF;

  SELECT array_agg(f3.id ORDER BY f3.id) INTO v_superiores
  FROM core.funcionarios f3
  JOIN core.cargos c3 ON c3.id = f3.id_cargo
  WHERE f3.id_setor = v_id_setor
    AND f3.data_desligamento IS NULL
    AND c3.nvl_permissao = v_sup_nivel
    AND c3.sub_nivel = v_sup_sub_nivel;

  SELECT count(*) INTO v_pos
  FROM core.funcionarios f4
  JOIN core.cargos c4 ON c4.id = f4.id_cargo
  WHERE f4.id_setor = v_id_setor
    AND f4.data_desligamento IS NULL
    AND c4.nvl_permissao = v_nivel
    AND c4.sub_nivel = v_sub_nivel
    AND f4.id < p_funcionario_id; -- posição determinística dentro do próprio grupo

  RETURN v_superiores[(v_pos % array_length(v_superiores, 1)) + 1]::text; -- array é 1-based
END;
$$;


--
-- TOC entry 7266 (class 0 OID 0)
-- Dependencies: 716
-- Name: FUNCTION fn_default_parent_pessoa(p_funcionario_id uuid); Type: COMMENT; Schema: core_organograma; Owner: -
--

COMMENT ON FUNCTION core_organograma.fn_default_parent_pessoa(p_funcionario_id uuid) IS 'parent_id calculado de uma pessoa de nível >= 4 quando não há override em core_organograma.node. Agrupa pelo par (nvl_permissao, sub_nivel) para suportar sub-níveis de mentoria. Devolve uuid puro (de setor ou de funcionário), sem prefixo — mesma convenção de node.id. ATENÇÃO: só age como rede de segurança; o av-hub grava override em node via recomputeSectorHierarchy, e o override sempre vence no COALESCE da vw_org_nodes.';


--
-- TOC entry 866 (class 1255 OID 20292)
-- Name: fn_definir_reporta_a(uuid, uuid, uuid); Type: FUNCTION; Schema: core_organograma; Owner: -
--

CREATE FUNCTION core_organograma.fn_definir_reporta_a(p_funcionario uuid, p_superior uuid, p_usuario uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_setor      uuid;
  v_sup_setor  uuid;
  v_sup_nome   text;
  v_sup_sit    text;
  v_auto       text;
  v_ciclo      boolean;
  v_usuario    uuid;
BEGIN
  PERFORM core_organograma.fn_travar_hierarquia();

  -- auditoria só com usuário que existe (senão null)
  SELECT u.id INTO v_usuario FROM auth.usuarios u WHERE u.id = p_usuario;

  SELECT f.id_setor INTO v_setor FROM core.funcionarios f WHERE f.id = p_funcionario;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Funcionário % não encontrado', p_funcionario USING ERRCODE = 'AV002';
  END IF;

  -- Sempre parte do automático: tira o override atual da pessoa (se houver).
  -- NÃO apaga a linha do nó: outras pessoas podem apontar para ela (FK).
  UPDATE core_organograma.node
     SET parent_id = NULL, updated_by = v_usuario
   WHERE id = p_funcionario::text AND parent_id IS NOT NULL;

  IF p_superior IS NULL THEN
    RETURN NULL;
  END IF;

  IF p_superior = p_funcionario THEN
    RAISE EXCEPTION 'Um funcionário não pode reportar a si mesmo'
      USING ERRCODE = 'AV001';
  END IF;

  SELECT f.id_setor, f.nome_completo, core.fn_funcionario_situacao(f.data_desligamento)
    INTO v_sup_setor, v_sup_nome, v_sup_sit
    FROM core.funcionarios f WHERE f.id = p_superior;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'O superior informado (%) não existe', p_superior USING ERRCODE = 'AV002';
  END IF;
  IF v_sup_setor IS DISTINCT FROM v_setor THEN
    RAISE EXCEPTION '% é de outro setor: o superior precisa ser do mesmo setor', v_sup_nome
      USING ERRCODE = 'AV002';
  END IF;
  IF v_sup_sit = 'desligado' THEN
    RAISE EXCEPTION '% está desligado e não pode ser superior', v_sup_nome
      USING ERRCODE = 'AV002';
  END IF;

  -- Escolha igual ao automático não é escolha manual: fica sem override.
  SELECT v.parent_id INTO v_auto
    FROM core_organograma.vw_org_nodes v
   WHERE v.id = p_funcionario::text AND v.is_sector = false;
  IF v_auto = p_superior::text THEN
    RETURN NULL;
  END IF;

  -- Ciclo: sobe a cadeia EFETIVA a partir do superior; se chegar na pessoa,
  -- fecharia um ciclo. O caminho em array corta ciclos pré-existentes.
  WITH RECURSIVE v AS MATERIALIZED (
         SELECT id, parent_id FROM core_organograma.vw_org_nodes
       ),
       sobe(id, caminho) AS (
         SELECT p_superior::text, ARRAY[p_superior::text]
       UNION ALL
         SELECT v.parent_id, s.caminho || v.parent_id
           FROM sobe s
           JOIN v ON v.id = s.id
          WHERE v.parent_id IS NOT NULL
            AND NOT v.parent_id = ANY (s.caminho)
            AND array_length(s.caminho, 1) < 200
       )
  SELECT EXISTS (SELECT 1 FROM sobe WHERE id = p_funcionario::text) INTO v_ciclo;

  IF v_ciclo THEN
    RAISE EXCEPTION 'Reportar a % criaria um ciclo na hierarquia', v_sup_nome
      USING ERRCODE = 'AV001';
  END IF;

  -- O pai precisa existir como nó (FK parent_id -> node.id). Nó sem parent_id
  -- não é override: vw_org_nodes cai no automático (COALESCE).
  INSERT INTO core_organograma.node (id, id_ent, parent_id, created_by)
  VALUES (p_superior::text, p_superior::text, NULL, v_usuario)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO core_organograma.node (id, id_ent, parent_id, created_by)
  VALUES (p_funcionario::text, p_funcionario::text, p_superior::text, v_usuario)
  ON CONFLICT (id) DO UPDATE
     SET parent_id  = EXCLUDED.parent_id,
         id_ent     = COALESCE(core_organograma.node.id_ent, EXCLUDED.id_ent),
         deleted_at = NULL,
         deleted_by = NULL,
         updated_by = v_usuario;

  RETURN p_superior::text;
END $$;


