--

CREATE FUNCTION core_organograma.fn_remover_do_organograma(p_funcionario uuid, p_usuario uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_n       integer;
  v_usuario uuid;
BEGIN
  PERFORM core_organograma.fn_travar_hierarquia();
  SELECT u.id INTO v_usuario FROM auth.usuarios u WHERE u.id = p_usuario;

  -- Quem reportava manualmente à pessoa (gente ou setor) volta ao automático.
  UPDATE core_organograma.node
     SET parent_id = NULL, updated_by = v_usuario
   WHERE parent_id = p_funcionario::text;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  DELETE FROM core_organograma.node
   WHERE id = p_funcionario::text
      OR (id_ent = p_funcionario::text AND is_sector = false);

  RETURN v_n;
END $$;


