COMMENT ON FUNCTION core_organograma.fn_remover_do_organograma(p_funcionario uuid, p_usuario uuid) IS 'Contrato 03: tira a pessoa do organograma e devolve ao automático todo override que apontava para ela. Chamar na MESMA transação do DELETE do funcionário.';


--
-- TOC entry 982 (class 1255 OID 17294)
-- Name: fn_set_is_sector(); Type: FUNCTION; Schema: core_organograma; Owner: -
--

CREATE FUNCTION core_organograma.fn_set_is_sector() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM core.setores WHERE id::text = NEW.id_ent) THEN
        NEW.is_sector := true;
    ELSIF EXISTS (SELECT 1 FROM core.funcionarios WHERE id::text = NEW.id_ent) THEN
        NEW.is_sector := false;
    ELSE
        RAISE EXCEPTION 'id_ent % não encontrado em core.setores nem em core.funcionarios', NEW.id_ent;
    END IF;

    RETURN NEW;
END;
$$;


