COMMENT ON FUNCTION core_vendas_faturamento.fn_aviso_mes_compra_registrar(p jsonb) IS 'LOG-58 R2/R5: grava o aviso do MES. id_aviso_mes repetido devolve o que já existe (criado = false). OC inexistente ou excluída: AV582. Item fora da OC: AV583. Sem unidade_medida, usa a do item.';


--
-- TOC entry 662 (class 1255 OID 25087)
-- Name: fn_aviso_mes_compra_tratar(uuid, text, text, uuid); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_aviso_mes_compra_tratar(p_id uuid, p_acao text, p_motivo text, p_usuario uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status text;
BEGIN
  IF p_acao IS NULL OR p_acao NOT IN ('SUBSTITUICAO', 'SEM_RECOMPRA') THEN
    RAISE EXCEPTION 'acao deve ser SUBSTITUICAO ou SEM_RECOMPRA (a recompra se resolve emitindo a OC com id_aviso_mes).'
      USING ERRCODE = 'AV586', DETAIL = 'acao';
  END IF;
  IF btrim(COALESCE(p_motivo, '')) = '' THEN
    RAISE EXCEPTION 'Escreva o motivo.' USING ERRCODE = 'AV587', DETAIL = 'motivo';
  END IF;

  SELECT a.status INTO v_status
    FROM core_vendas_faturamento.avisos_mes_compra a WHERE a.id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Aviso do MES não encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF v_status <> 'ABERTO' THEN
    RAISE EXCEPTION 'Este aviso do MES já foi tratado.' USING ERRCODE = 'AV581', DETAIL = v_status;
  END IF;

  UPDATE core_vendas_faturamento.avisos_mes_compra
     SET status = 'RESOLVIDO',
         acao_tratamento = p_acao,
         motivo_tratamento = btrim(p_motivo),
         tratado_por = p_usuario,
         tratado_em = now()
   WHERE id = p_id;
  RETURN p_id;
END $$;


