--
-- TOC entry 1033 (class 1255 OID 25071)
-- Name: fn_avisos_mes_compra_guardar(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_avisos_mes_compra_guardar() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'ABERTO' THEN
      RAISE EXCEPTION 'O aviso do MES nasce ABERTO.' USING ERRCODE = '23514';
    END IF;
    IF NEW.id_ordem_compra_item IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM core_vendas_faturamento.ordens_compra_itens i
          WHERE i.id = NEW.id_ordem_compra_item AND i.id_ordem_compra = NEW.id_ordem_compra) THEN
      RAISE EXCEPTION 'O item % não é da ordem de compra %.', NEW.id_ordem_compra_item, NEW.id_ordem_compra
        USING ERRCODE = 'AV583', DETAIL = 'id_ordem_compra_item';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE
  IF OLD.status = 'RESOLVIDO' THEN
    -- LOG-58b: a única volta é RESOLVIDO / RECOMPRA -> ABERTO, quando a OC de
    -- recompra foi cancelada ou excluída (trg_ordens_compra_aviso_mes_reabrir).
    IF NOT (NEW.status = 'ABERTO'
            AND OLD.acao_tratamento = 'RECOMPRA'
            AND OLD.id_ordem_compra_recompra IS NOT NULL
            AND EXISTS (SELECT 1 FROM core_vendas_faturamento.ordens_compra oc
                         WHERE oc.id = OLD.id_ordem_compra_recompra
                           AND (oc.status = 'cancelado' OR oc.deleted_at IS NOT NULL))) THEN
      RAISE EXCEPTION 'Este aviso do MES já foi tratado.'
        USING ERRCODE = 'AV581', DETAIL = OLD.status;
    END IF;
  END IF;
  IF (NEW.id_aviso_mes, NEW.tipo, NEW.id_ordem_compra, NEW.quantidade, NEW.unidade_medida, NEW.motivo,
      NEW.codigo_documento, NEW.codigo_lote, NEW.numero_pedido_venda, NEW.decidido_por, NEW.decidido_em,
      NEW.created_at)
     IS DISTINCT FROM
     (OLD.id_aviso_mes, OLD.tipo, OLD.id_ordem_compra, OLD.quantidade, OLD.unidade_medida, OLD.motivo,
      OLD.codigo_documento, OLD.codigo_lote, OLD.numero_pedido_venda, OLD.decidido_por, OLD.decidido_em,
      OLD.created_at)
     -- o item só pode virar nulo (FK ON DELETE SET NULL), nunca outro item
     OR (NEW.id_ordem_compra_item IS NOT NULL AND NEW.id_ordem_compra_item IS DISTINCT FROM OLD.id_ordem_compra_item) THEN
    RAISE EXCEPTION 'Os dados do aviso vêm do MES e não mudam no av-hub.' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- TOC entry 7272 (class 0 OID 0)
