COMMENT ON FUNCTION core_vendas_faturamento.fn_avisos_mes_compra_guardar() IS 'LOG-58: o aviso nasce ABERTO, com item da própria OC (AV583); os dados do MES não mudam; RESOLVIDO não volta (AV581, R3/R4). LOG-58b: exceção RESOLVIDO / RECOMPRA -> ABERTO quando a OC de recompra está cancelada ou excluída.';


--
-- TOC entry 575 (class 1255 OID 24834)
-- Name: fn_carteira_clientes(uuid, uuid, uuid, uuid[]); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_carteira_clientes(p_codigo_empresa uuid DEFAULT NULL::uuid, p_id_parceiro uuid DEFAULT NULL::uuid, p_ignorar_proposta uuid DEFAULT NULL::uuid, p_ids_parceiros uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(codigo_empresa uuid, id_parceiro uuid, codigo_cliente character varying, origem text, decidido_em date, codigo_vendedor_omie character varying, nome_vendedor character varying, id_usuario uuid, id_proposta uuid)
    LANGUAGE sql STABLE
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
  WITH par AS (
    SELECT pa.id, pa.codigo_empresa, pa.codigo_parceiro_omie
      FROM core.parceiros pa
     WHERE pa.deleted_at IS NULL
       AND (p_codigo_empresa IS NULL OR pa.codigo_empresa = p_codigo_empresa)
       AND (p_id_parceiro IS NULL OR pa.id = p_id_parceiro)
       AND (p_ids_parceiros IS NULL OR pa.id = ANY (p_ids_parceiros))
  ),
  vendas AS (
    -- Pedido válido = mesma regra do Acompanhamento de Clientes (fn_acompanhamento_clientes):
    -- principal (sequencial 0), vivo, sem etapa 0, fora da blacklist, sem cancelado/denegado.
    SELECT p.codigo_empresa, p.codigo_cliente::varchar AS codigo_cliente,
           btrim(p.codigo_vendedor_omie)::varchar AS codigo_vendedor,
           core_vendas_faturamento.fn_data_planilha(p.data_inclusao::text) AS data, 1 AS fonte
      FROM core_vendas_faturamento.pedidos_vendas p
      JOIN par ON par.codigo_empresa = p.codigo_empresa AND par.codigo_parceiro_omie = p.codigo_cliente
     WHERE p.deleted_at IS NULL
       AND (p.etapa IS NULL OR p.etapa <> 0)
       AND COALESCE(p.sequencial, 0) = 0
       AND NOT p.cancelado AND NOT p.denegado
       AND p.data_inclusao IS NOT NULL
       AND NULLIF(btrim(p.codigo_vendedor_omie), '') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.blacklist_pedidos bp
                        WHERE bp.codigo_empresa = p.codigo_empresa
                          AND bp.numero_pedido = p.numero_pedido::text
                          AND bp.deleted_at IS NULL)
    UNION ALL
    -- NF válida = viva e sem o pedido cancelado/denegado (§9.1 do Acompanhamento).
    SELECT n.codigo_empresa, n.codigo_cliente::varchar,
           btrim(n.codigo_vendedor_omie)::varchar,
           core_vendas_faturamento.fn_data_planilha(n.data_emissao::text), 2
      FROM core_vendas_faturamento.notas_fiscais n
      JOIN par ON par.codigo_empresa = n.codigo_empresa AND par.codigo_parceiro_omie = n.codigo_cliente
      LEFT JOIN core_vendas_faturamento.pedidos_vendas pv
        ON pv.codigo_empresa = n.codigo_empresa AND pv.codigo_pedido_omie = n.codigo_pedido_omie
     WHERE n.deleted_at IS NULL
       AND NOT COALESCE(pv.cancelado, false) AND NOT COALESCE(pv.denegado, false)
       AND n.data_emissao IS NOT NULL
       AND NULLIF(btrim(n.codigo_vendedor_omie), '') IS NOT NULL
  ),
  ultima AS (
    -- Só a última venda decide (regra 1). Mesmo dia: o pedido antes da NF; depois o código.
    SELECT DISTINCT ON (v.codigo_empresa, v.codigo_cliente)
           v.codigo_empresa, v.codigo_cliente, v.codigo_vendedor, v.data
      FROM vendas v
     ORDER BY v.codigo_empresa, v.codigo_cliente, v.data DESC, v.fonte, v.codigo_vendedor DESC
  ),
  dono_venda AS (
    -- Regras 1 e 2: dono só se o vendedor da última venda está ATIVO (o Omie manda).
    SELECT par.codigo_empresa, par.id AS id_parceiro, par.codigo_parceiro_omie::varchar AS codigo_cliente,
           'VENDA'::text AS origem, u.data AS decidido_em, vd.codigo_vendedor_omie, vd.nome AS nome_vendedor,
           COALESCE(vd.id_usuario,
                    (SELECT us.id FROM auth.usuarios us
                      WHERE vd.id_funcionario IS NOT NULL AND us.id_funcionario = vd.id_funcionario AND us.deleted_at IS NULL
                      ORDER BY us.ativo DESC, us.created_at, us.id LIMIT 1)) AS id_usuario,
           NULL::uuid AS id_proposta
      FROM ultima u
      JOIN par ON par.codigo_empresa = u.codigo_empresa AND par.codigo_parceiro_omie = u.codigo_cliente
      JOIN core_vendas_faturamento.vendedores vd
        ON vd.codigo_empresa = u.codigo_empresa AND vd.codigo_vendedor_omie = u.codigo_vendedor
       AND vd.deleted_at IS NULL AND vd.ativo IS TRUE
  ),
  prazo AS (
    SELECT COALESCE((SELECT pc.dias_reserva_proposta FROM core_comercial.parametros_carteira_clientes pc WHERE pc.id = 1), 30) AS dias
  ),
  reserva AS (
    -- Regra 3: cliente sem dono por venda fica com o responsável da proposta mais
    -- recente dos últimos N dias (não cancelada nem excluída; a revisão conta como
    -- data nova), entre as de responsável com vendedor ativo na unidade.
    SELECT DISTINCT ON (pr.id_cliente)
           pr.codigo_empresa, pr.id_cliente AS id_parceiro, par.codigo_parceiro_omie::varchar AS codigo_cliente,
           'PROPOSTA'::text AS origem, (d.em AT TIME ZONE 'America/Sao_Paulo')::date AS decidido_em,
           vv.cod AS codigo_vendedor_omie,
           (SELECT vd.nome FROM core_vendas_faturamento.vendedores vd
             WHERE vd.codigo_empresa = pr.codigo_empresa AND vd.codigo_vendedor_omie = vv.cod) AS nome_vendedor,
           pr.id_responsavel AS id_usuario, pr.id AS id_proposta
      FROM core_comercial.propostas pr
      JOIN par ON par.id = pr.id_cliente AND par.codigo_empresa = pr.codigo_empresa
      CROSS JOIN prazo
      CROSS JOIN LATERAL (
        SELECT GREATEST(pr.emitida_em,
                        (SELECT max(e.ocorrido_em) FROM core_comercial.propostas_eventos e
                          WHERE e.id_proposta = pr.id AND e.tipo = 'REVISADA')) AS em) d
      CROSS JOIN LATERAL (SELECT core_comercial.fn_pedido_venda_vendedor(pr.id_responsavel, pr.codigo_empresa) AS cod) vv
     WHERE pr.deleted_at IS NULL
       AND pr.status <> 'CANCELADA'
       AND (p_ignorar_proposta IS NULL OR pr.id <> p_ignorar_proposta)
       AND d.em >= now() - make_interval(days => prazo.dias)
       AND vv.cod IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM dono_venda dv WHERE dv.id_parceiro = par.id)
     ORDER BY pr.id_cliente, d.em DESC, pr.id DESC
  )
  SELECT dv.codigo_empresa, dv.id_parceiro, dv.codigo_cliente, dv.origem, dv.decidido_em,
         dv.codigo_vendedor_omie, dv.nome_vendedor, dv.id_usuario, dv.id_proposta
    FROM dono_venda dv
  UNION ALL
  SELECT r.codigo_empresa, r.id_parceiro, r.codigo_cliente, r.origem, r.decidido_em,
         r.codigo_vendedor_omie, r.nome_vendedor, r.id_usuario, r.id_proposta
    FROM reserva r;
$$;


--
-- TOC entry 7273 (class 0 OID 0)
-- Dependencies: 575
-- Name: FUNCTION fn_carteira_clientes(p_codigo_empresa uuid, p_id_parceiro uuid, p_ignorar_proposta uuid, p_ids_parceiros uuid[]); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_carteira_clientes(p_codigo_empresa uuid, p_id_parceiro uuid, p_ignorar_proposta uuid, p_ids_parceiros uuid[]) IS 'Pedido do Robert (11/11/2026, "Carteira de clientes na proposta"): o dono de cada cliente (core.parceiros, por unidade). Uma linha por cliente COM dono; quem não aparece é livre. origem VENDA = vendedor do pedido ou NF mais recente (mesma base do Acompanhamento de Clientes) se ATIVO em vendedores (Omie = fonte da verdade; vale mesmo sem usuário no Hub); origem PROPOSTA = cliente sem dono por venda, reservado pelo responsável da proposta mais recente dos últimos core_comercial.parametros_carteira_clientes.dias_reserva_proposta dias (não cancelada nem excluída; revisão = data nova; responsável com vendedor ativo na unidade). O dono é o par (codigo_empresa, codigo_vendedor_omie); id_usuario = usuário do vendedor (VENDA, pode ser NULL) ou o responsável (PROPOSTA). Filtros opcionais: unidade, parceiro, lista de parceiros (a busca passa só os candidatos: bem mais rápido que a unidade inteira) e uma proposta a ignorar (a própria proposta na revisão). Diligenciado não conta. A busca da proposta (GET /comercial/parceiros), a gravação (trigger trg_propostas_conferir_emissao) e o cadastro (POST /comercial/clientes) leem daqui.';


--
-- TOC entry 946 (class 1255 OID 24088)
-- Name: fn_carteira_pcp_linhas(boolean, uuid, text[], integer, date, date); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_carteira_pcp_linhas(p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_vendedor text[] DEFAULT NULL::text[], p_desvio_dias integer DEFAULT 10, p_inclusao_inicio date DEFAULT NULL::date, p_inclusao_fim date DEFAULT NULL::date) RETURNS TABLE(codigo_empresa uuid, numero_pedido text, codigo_pedido_omie bigint, sequencial integer, codigo_vendedor text, data_inclusao date, data_previsao date, valor numeric, aberta boolean, faturada boolean, dias_para_prazo integer, desvio boolean, avanco boolean)
    LANGUAGE sql STABLE
    AS $$
  WITH src AS (
    SELECT x.codigo_empresa, x.numero_pedido::text AS numero_pedido, x.codigo_pedido_omie,
           x.sequencial::integer AS sequencial, x.codigo_vendedor_omie::text AS codigo_vendedor,
           x.data_inclusao::text AS data_inclusao, x.data_previsao::text AS data_previsao,
           x.valor_total_pedido, x.faturado, x.cancelado, x.denegado, x.devolvido, x.encerrado
      FROM core_vendas_faturamento.pedidos_vendas x
     WHERE NOT COALESCE(p_is_track_record, false)
       AND x.deleted_at IS NULL
       AND (x.etapa IS NULL OR x.etapa <> 0)
       AND (p_codigo_empresa IS NULL OR x.codigo_empresa = p_codigo_empresa)
    UNION ALL
    SELECT x.codigo_empresa, x.numero_pedido::text, x.codigo_pedido_omie,
           x.sequencial::integer, x.codigo_vendedor_omie::text,
           x.data_inclusao::text, x.data_previsao::text,
           x.valor_total_pedido, x.faturado, x.cancelado, x.denegado, x.devolvido, x.encerrado
      FROM historico.hst_pedidos_vendas x
     WHERE COALESCE(p_is_track_record, false)
       AND x.deleted_at IS NULL
       AND (x.etapa IS NULL OR x.etapa <> 0)
       AND (p_codigo_empresa IS NULL OR x.codigo_empresa = p_codigo_empresa)
  ), lin AS (
    SELECT s.*,
           -- Parcela aberta (definição 1): valor > 0 e nenhuma flag de fechamento.
           (COALESCE(s.valor_total_pedido, 0) > 0
             AND NOT (COALESCE(s.faturado, false) OR COALESCE(s.cancelado, false) OR COALESCE(s.denegado, false)
                      OR COALESCE(s.devolvido, false) OR COALESCE(s.encerrado, false))) AS aberta,
           -- Parcela faturada que vale (NF não cancelada/denegada), como na SQL 014.
           (COALESCE(s.faturado, false) AND NOT COALESCE(s.cancelado, false)
             AND NOT COALESCE(s.denegado, false)) AS faturada,
           CASE WHEN s.data_previsao ~ '^\d{4}-\d{2}-\d{2}' THEN to_date(substr(s.data_previsao, 1, 10), 'YYYY-MM-DD') END AS previsao
      FROM src s
  ), fam AS (
    SELECT DISTINCT l.codigo_empresa, l.numero_pedido FROM lin l WHERE l.aberta
  ), cab AS (
    -- Cabeçalho (sequencial 0/nulo): dá o vendedor e a data de inclusão do pedido.
    SELECT DISTINCT ON (l.codigo_empresa, l.numero_pedido)
           l.codigo_empresa, l.numero_pedido, l.codigo_vendedor,
           CASE WHEN l.data_inclusao ~ '^\d{4}-\d{2}-\d{2}' THEN to_date(substr(l.data_inclusao, 1, 10), 'YYYY-MM-DD') END AS data_inclusao
      FROM lin l
      JOIN fam f ON f.codigo_empresa = l.codigo_empresa AND f.numero_pedido = l.numero_pedido
     WHERE COALESCE(l.sequencial, 0) = 0
     ORDER BY l.codigo_empresa, l.numero_pedido, l.sequencial NULLS FIRST, l.codigo_pedido_omie
  ), ped AS (
    SELECT c.*,
           EXISTS (SELECT 1 FROM core_vendas_faturamento.pedido_marcacao_pcp mk
                    WHERE mk.codigo_empresa = c.codigo_empresa AND mk.numero_pedido = c.numero_pedido
                      AND mk.marcacao = 'avanco' AND mk.removida_em IS NULL) AS avanco
      FROM cab c
     WHERE (p_codigo_vendedor IS NULL OR c.codigo_vendedor = ANY (p_codigo_vendedor))
       AND (p_inclusao_inicio IS NULL OR c.data_inclusao >= p_inclusao_inicio)
       AND (p_inclusao_fim IS NULL OR c.data_inclusao <= p_inclusao_fim)
       AND NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.blacklist_pedidos bp
                        WHERE bp.codigo_empresa = c.codigo_empresa AND bp.numero_pedido = c.numero_pedido
                          AND bp.deleted_at IS NULL)
  )
  SELECT l.codigo_empresa, l.numero_pedido, l.codigo_pedido_omie, l.sequencial,
         p.codigo_vendedor, p.data_inclusao, l.previsao,
         COALESCE(l.valor_total_pedido, 0)::numeric(15,2),
         l.aberta, l.faturada,
         CASE WHEN l.aberta THEN core_vendas_faturamento.fn_pedido_dias_para_prazo(
                l.data_previsao, false, false, false, false, false) END,
         (l.aberta AND l.previsao IS NOT NULL AND p.data_inclusao IS NOT NULL
           AND l.previsao <= p.data_inclusao + COALESCE(p_desvio_dias, 10)),
         p.avanco
    FROM lin l
    JOIN ped p ON p.codigo_empresa = l.codigo_empresa AND p.numero_pedido = l.numero_pedido
   WHERE l.aberta OR l.faturada
$$;


