CREATE FUNCTION core_vendas_faturamento.fn_carteira_pcp_previsao(p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_vendedor text[] DEFAULT NULL::text[], p_desvio_dias integer DEFAULT 10, p_inclusao_inicio date DEFAULT NULL::date, p_inclusao_fim date DEFAULT NULL::date) RETURNS TABLE(mes date, valor numeric, pedidos bigint, atrasados_valor numeric, atrasados_pedidos bigint)
    LANGUAGE sql STABLE
    AS $$
  WITH l AS (
    SELECT date_trunc('month', x.data_previsao)::date AS mes,
           x.codigo_empresa::text || '|' || x.numero_pedido AS chave,
           x.valor, x.dias_para_prazo
      FROM core_vendas_faturamento.fn_carteira_pcp_linhas(
             p_is_track_record, p_codigo_empresa, p_codigo_vendedor, p_desvio_dias,
             p_inclusao_inicio, p_inclusao_fim) x
     WHERE x.aberta
  )
  SELECT l.mes,
         COALESCE(sum(l.valor), 0)::numeric(15,2),
         count(DISTINCT l.chave),
         COALESCE(sum(l.valor) FILTER (WHERE l.dias_para_prazo < 0), 0)::numeric(15,2),
         count(DISTINCT l.chave) FILTER (WHERE l.dias_para_prazo < 0)
    FROM l
   GROUP BY l.mes
  HAVING COALESCE(sum(l.valor), 0) > 0
   ORDER BY l.mes NULLS LAST
$$;


