CREATE FUNCTION core_vendas_faturamento.fn_carteira_pcp_resumo(p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_vendedor text[] DEFAULT NULL::text[], p_desvio_dias integer DEFAULT 10, p_inclusao_inicio date DEFAULT NULL::date, p_inclusao_fim date DEFAULT NULL::date) RETURNS TABLE(carteira_valor numeric, carteira_pedidos bigint, no_prazo_valor numeric, no_prazo_pedidos bigint, atrasados_valor numeric, atrasados_pedidos bigint, sem_previsao_valor numeric, sem_previsao_pedidos bigint, desvio_valor numeric, desvio_pedidos bigint, avanco_valor numeric, avanco_pedidos bigint, avanco_faturado_valor numeric, vence_hoje_valor numeric, vence_hoje_pedidos bigint)
    LANGUAGE sql STABLE
    AS $$
  WITH l AS (
    SELECT x.*, x.codigo_empresa::text || '|' || x.numero_pedido AS chave
      FROM core_vendas_faturamento.fn_carteira_pcp_linhas(
             p_is_track_record, p_codigo_empresa, p_codigo_vendedor, p_desvio_dias,
             p_inclusao_inicio, p_inclusao_fim) x
  ), u AS (
    -- API-018: urgência do PEDIDO = menor dias_para_prazo das parcelas abertas
    -- (a mesma de prazo em fn_pedidos_venda): 0 = a parcela mais urgente vence
    -- hoje e nenhuma está atrasada.
    SELECT l.*, min(l.dias_para_prazo) FILTER (WHERE l.aberta) OVER (PARTITION BY l.chave) AS dias_pedido
      FROM l
  )
  SELECT COALESCE(sum(valor) FILTER (WHERE aberta), 0)::numeric(15,2),
         count(DISTINCT chave) FILTER (WHERE aberta),
         COALESCE(sum(valor) FILTER (WHERE aberta AND dias_para_prazo >= 0), 0)::numeric(15,2),
         count(DISTINCT chave) FILTER (WHERE aberta AND dias_para_prazo >= 0),
         COALESCE(sum(valor) FILTER (WHERE aberta AND dias_para_prazo < 0), 0)::numeric(15,2),
         count(DISTINCT chave) FILTER (WHERE aberta AND dias_para_prazo < 0),
         COALESCE(sum(valor) FILTER (WHERE aberta AND dias_para_prazo IS NULL), 0)::numeric(15,2),
         count(DISTINCT chave) FILTER (WHERE aberta AND dias_para_prazo IS NULL),
         COALESCE(sum(valor) FILTER (WHERE aberta AND desvio), 0)::numeric(15,2),
         count(DISTINCT chave) FILTER (WHERE aberta AND desvio),
         COALESCE(sum(valor) FILTER (WHERE aberta AND avanco), 0)::numeric(15,2),
         count(DISTINCT chave) FILTER (WHERE aberta AND avanco),
         COALESCE(sum(valor) FILTER (WHERE faturada AND avanco), 0)::numeric(15,2),
         -- API-018: vence hoje = parcelas abertas com previsão hoje dos pedidos cuja
         -- parcela mais urgente é a de hoje (= GET /pedidos_venda?carteira=true&prazo=vence-hoje).
         COALESCE(sum(valor) FILTER (WHERE aberta AND dias_para_prazo = 0 AND dias_pedido = 0), 0)::numeric(15,2),
         count(DISTINCT chave) FILTER (WHERE aberta AND dias_para_prazo = 0 AND dias_pedido = 0)
    FROM u
$$;


