COMMENT ON FUNCTION core_vendas_faturamento.fn_carteira_pcp_resumo(p_is_track_record boolean, p_codigo_empresa uuid, p_codigo_vendedor text[], p_desvio_dias integer, p_inclusao_inicio date, p_inclusao_fim date) IS 'SQL 015 / API-017 / API-018: totais da carteira do PCP (uma linha), sobre fn_carteira_pcp_linhas. carteira = parcelas abertas (valor > 0, sem faturado/cancelado/denegado/devolvido/encerrado); no_prazo = abertas com dias_para_prazo >= 0 (inclui vence hoje); atrasados = < 0; sem_previsao = sem data_previsao (carteira_valor = no_prazo + atrasados + sem_previsao); desvio = abertas com previsão até p_desvio_dias da inclusão do cabeçalho; avanco = abertas dos pedidos com a marca ''avanco'' e avanco_faturado_valor = parcelas já faturadas desses mesmos pedidos (pedido marcado sem parcela aberta, como o encerrado, fica fora). *_pedidos = pedidos distintos: um pedido com parcela no prazo e outra atrasada conta nos dois baldes. atrasados_pedidos = pedidos com alguma parcela aberta atrasada = total de GET /pedidos_venda?carteira=true&prazo=atrasado (a lista classifica o pedido pela parcela aberta COM VALOR mais urgente, API-018). API-018: vence_hoje_pedidos = pedidos cuja parcela aberta mais urgente vence hoje (nenhuma atrasada) = total de GET /pedidos_venda?carteira=true&prazo=vence-hoje; vence_hoje_valor = saldo das parcelas desses pedidos com previsão hoje (não o do pedido inteiro; recorte de dentro de no_prazo). Hoje = data de São Paulo. p_inclusao_inicio/fim (API-017, por_periodo da API): só pedidos incluídos no intervalo (data de inclusão do cabeçalho, inclusive); nulos = carteira inteira de qualquer data.';


--
-- TOC entry 980 (class 1255 OID 24257)
-- Name: fn_carteira_pcp_vendedores(boolean, uuid, text[], integer, date, date, date, date); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_carteira_pcp_vendedores(p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_vendedor text[] DEFAULT NULL::text[], p_desvio_dias integer DEFAULT 10, p_inicio date DEFAULT NULL::date, p_fim date DEFAULT NULL::date, p_inclusao_inicio date DEFAULT NULL::date, p_inclusao_fim date DEFAULT NULL::date) RETURNS TABLE(codigo_empresa uuid, codigo_vendedor text, vendedor text, pedidos_mes bigint, no_prazo_pedidos bigint, no_prazo_valor numeric, atrasados_pedidos bigint, atrasados_valor numeric, sem_previsao_pedidos bigint, sem_previsao_valor numeric, carteira_pedidos bigint, carteira_valor numeric, desvio_pedidos bigint, desvio_valor numeric, avanco_pedidos bigint, avanco_valor numeric, vence_hoje_pedidos bigint, vence_hoje_valor numeric)
    LANGUAGE sql STABLE
    AS $$
  WITH l AS (
    -- API-018: dias_pedido = urgência do pedido (menor dias_para_prazo das parcelas abertas).
    SELECT x.*, min(x.dias_para_prazo) OVER (PARTITION BY x.codigo_empresa, x.numero_pedido) AS dias_pedido
      FROM core_vendas_faturamento.fn_carteira_pcp_linhas(
             p_is_track_record, p_codigo_empresa, p_codigo_vendedor, p_desvio_dias,
             p_inclusao_inicio, p_inclusao_fim) x
     WHERE x.aberta
  ), cart AS (
    SELECT l.codigo_empresa, l.codigo_vendedor,
           count(DISTINCT l.numero_pedido) FILTER (WHERE l.dias_para_prazo >= 0) AS no_prazo_pedidos,
           COALESCE(sum(l.valor) FILTER (WHERE l.dias_para_prazo >= 0), 0)::numeric(15,2) AS no_prazo_valor,
           count(DISTINCT l.numero_pedido) FILTER (WHERE l.dias_para_prazo < 0) AS atrasados_pedidos,
           COALESCE(sum(l.valor) FILTER (WHERE l.dias_para_prazo < 0), 0)::numeric(15,2) AS atrasados_valor,
           count(DISTINCT l.numero_pedido) FILTER (WHERE l.dias_para_prazo IS NULL) AS sem_previsao_pedidos,
           COALESCE(sum(l.valor) FILTER (WHERE l.dias_para_prazo IS NULL), 0)::numeric(15,2) AS sem_previsao_valor,
           count(DISTINCT l.numero_pedido) AS carteira_pedidos,
           COALESCE(sum(l.valor), 0)::numeric(15,2) AS carteira_valor,
           count(DISTINCT l.numero_pedido) FILTER (WHERE l.desvio) AS desvio_pedidos,
           COALESCE(sum(l.valor) FILTER (WHERE l.desvio), 0)::numeric(15,2) AS desvio_valor,
           count(DISTINCT l.numero_pedido) FILTER (WHERE l.avanco) AS avanco_pedidos,
           COALESCE(sum(l.valor) FILTER (WHERE l.avanco), 0)::numeric(15,2) AS avanco_valor,
           count(DISTINCT l.numero_pedido) FILTER (WHERE l.dias_para_prazo = 0 AND l.dias_pedido = 0) AS vence_hoje_pedidos,
           COALESCE(sum(l.valor) FILTER (WHERE l.dias_para_prazo = 0 AND l.dias_pedido = 0), 0)::numeric(15,2) AS vence_hoje_valor
      FROM l
     GROUP BY l.codigo_empresa, l.codigo_vendedor
  ), src AS (
    -- Cabeçalhos incluídos no período (definição 6 da SQL 015), com as mesmas
    -- exclusões de fn_pedidos_venda (orçamento, excluídos, blacklist). Data no
    -- formato do Omie (AAAA-MM-DD), em que texto e data ordenam igual.
    SELECT x.codigo_empresa, x.numero_pedido::text AS numero_pedido, x.codigo_vendedor_omie::text AS codigo_vendedor
      FROM core_vendas_faturamento.pedidos_vendas x
     WHERE NOT COALESCE(p_is_track_record, false)
       AND p_inicio IS NOT NULL AND p_fim IS NOT NULL
       AND x.deleted_at IS NULL AND COALESCE(x.sequencial, 0) = 0
       AND (x.etapa IS NULL OR x.etapa <> 0)
       AND x.data_inclusao >= to_char(p_inicio, 'YYYY-MM-DD') AND x.data_inclusao <= to_char(p_fim, 'YYYY-MM-DD')
       AND (p_codigo_empresa IS NULL OR x.codigo_empresa = p_codigo_empresa)
       AND (p_codigo_vendedor IS NULL OR x.codigo_vendedor_omie = ANY (p_codigo_vendedor))
    UNION ALL
    SELECT x.codigo_empresa, x.numero_pedido::text, x.codigo_vendedor_omie::text
      FROM historico.hst_pedidos_vendas x
     WHERE COALESCE(p_is_track_record, false)
       AND p_inicio IS NOT NULL AND p_fim IS NOT NULL
       AND x.deleted_at IS NULL AND COALESCE(x.sequencial, 0) = 0
       AND (x.etapa IS NULL OR x.etapa <> 0)
       AND x.data_inclusao >= to_char(p_inicio, 'YYYY-MM-DD') AND x.data_inclusao <= to_char(p_fim, 'YYYY-MM-DD')
       AND (p_codigo_empresa IS NULL OR x.codigo_empresa = p_codigo_empresa)
       AND (p_codigo_vendedor IS NULL OR x.codigo_vendedor_omie = ANY (p_codigo_vendedor))
  ), mes AS (
    SELECT s.codigo_empresa, s.codigo_vendedor, count(DISTINCT s.numero_pedido) AS pedidos_mes
      FROM src s
     WHERE NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.blacklist_pedidos bp
                        WHERE bp.codigo_empresa = s.codigo_empresa AND bp.numero_pedido = s.numero_pedido
                          AND bp.deleted_at IS NULL)
     GROUP BY s.codigo_empresa, s.codigo_vendedor
  ), juntos AS (
    SELECT COALESCE(c.codigo_empresa, m.codigo_empresa) AS codigo_empresa,
           COALESCE(c.codigo_vendedor, m.codigo_vendedor) AS codigo_vendedor,
           COALESCE(m.pedidos_mes, 0) AS pedidos_mes,
           c.no_prazo_pedidos, c.no_prazo_valor, c.atrasados_pedidos, c.atrasados_valor,
           c.sem_previsao_pedidos, c.sem_previsao_valor, c.carteira_pedidos, c.carteira_valor,
           c.desvio_pedidos, c.desvio_valor, c.avanco_pedidos, c.avanco_valor,
           c.vence_hoje_pedidos, c.vence_hoje_valor
      FROM cart c
      FULL JOIN mes m ON m.codigo_empresa = c.codigo_empresa AND m.codigo_vendedor = c.codigo_vendedor
     -- API-017: com o recorte por inclusão, vendedor sem saldo no recorte não vem.
     WHERE (p_inclusao_inicio IS NULL AND p_inclusao_fim IS NULL) OR c.codigo_empresa IS NOT NULL
  )
  SELECT j.codigo_empresa, j.codigo_vendedor, v.nome::text AS vendedor, j.pedidos_mes,
         COALESCE(j.no_prazo_pedidos, 0), COALESCE(j.no_prazo_valor, 0)::numeric(15,2),
         COALESCE(j.atrasados_pedidos, 0), COALESCE(j.atrasados_valor, 0)::numeric(15,2),
         COALESCE(j.sem_previsao_pedidos, 0), COALESCE(j.sem_previsao_valor, 0)::numeric(15,2),
         COALESCE(j.carteira_pedidos, 0), COALESCE(j.carteira_valor, 0)::numeric(15,2),
         COALESCE(j.desvio_pedidos, 0), COALESCE(j.desvio_valor, 0)::numeric(15,2),
         COALESCE(j.avanco_pedidos, 0), COALESCE(j.avanco_valor, 0)::numeric(15,2),
         COALESCE(j.vence_hoje_pedidos, 0), COALESCE(j.vence_hoje_valor, 0)::numeric(15,2)
    FROM juntos j
    LEFT JOIN core_vendas_faturamento.vendedores v
      ON v.codigo_empresa = j.codigo_empresa AND v.codigo_vendedor_omie::text = j.codigo_vendedor AND v.deleted_at IS NULL
   ORDER BY COALESCE(j.carteira_valor, 0) DESC, j.pedidos_mes DESC, v.nome, j.codigo_vendedor, j.codigo_empresa
$$;


