-- Name: FUNCTION fn_carteira_pcp_vendedores(p_is_track_record boolean, p_codigo_empresa uuid, p_codigo_vendedor text[], p_desvio_dias integer, p_inicio date, p_fim date, p_inclusao_inicio date, p_inclusao_fim date); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
