--
-- TOC entry 948 (class 1255 OID 24278)
-- Name: fn_clientes_setor_definir(uuid[], jsonb, uuid); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_clientes_setor_definir(p_id_setores uuid[], p_alvos jsonb, p_usuario uuid DEFAULT NULL::uuid) RETURNS TABLE(atualizados integer, removidos integer, sem_mudanca integer)
    LANGUAGE plpgsql
    AS $$
#variable_conflict use_column
DECLARE
  v_setores  uuid[] := COALESCE(p_id_setores, '{}'::uuid[]);
  v_n        integer;
  v_i        integer;
  v_idx      integer;            -- índice (no corpo) do alvo em curso, para o EXCEPTION
  v_alvo     jsonb;
  v_grupo    uuid;
  v_emp      uuid;
  v_cli      text;
  v_chave    text;
  v_chaves   text[]    := '{}';  -- alvos sem repetição, na ordem do corpo
  v_pos      integer[] := '{}';  -- índice no corpo de cada um
  v_grupos   uuid[]    := '{}';
  v_emps     uuid[]    := '{}';
  v_clis     text[]    := '{}';
  v_s        uuid;
  v_ativo    boolean;
  v_atual    uuid[];
  v_entra    uuid[];
  v_sai      uuid[];
  v_atu      integer := 0;
  v_rem      integer := 0;
  v_igual    integer := 0;
BEGIN
  IF p_alvos IS NULL OR jsonb_typeof(p_alvos) <> 'array' THEN
    RAISE EXCEPTION 'alvos deve ser uma lista.' USING ERRCODE = '22023';
  END IF;
  v_n := jsonb_array_length(p_alvos);
  IF v_n < 1 OR v_n > 500 THEN
    RAISE EXCEPTION 'alvos deve ter de 1 a 500 itens (recebido %).', v_n USING ERRCODE = '22023';
  END IF;
  IF array_position(v_setores, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'id_setores não pode ter item nulo.' USING ERRCODE = '22023';
  END IF;
  IF cardinality(v_setores) > 20 THEN
    RAISE EXCEPTION 'id_setores deve ter no máximo 20 setores (recebido %).', cardinality(v_setores)
      USING ERRCODE = '22023';
  END IF;
  IF cardinality(v_setores) <> (SELECT count(DISTINCT x) FROM unnest(v_setores) x) THEN
    RAISE EXCEPTION 'id_setores tem setor repetido.' USING ERRCODE = '22023';
  END IF;

  -- Os setores existem? FOR SHARE: ninguém desativa no meio da gravação.
  FOREACH v_s IN ARRAY v_setores LOOP
    PERFORM 1 FROM core_vendas_faturamento.setores_clientes s WHERE s.id = v_s FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Setor % não existe.', v_s
        USING ERRCODE = 'AV141', DETAIL = json_build_object('id_setor', v_s)::text;
    END IF;
  END LOOP;

  -- 1ª passada: lê e confere cada alvo (o erro aponta o índice do corpo) e
  -- tira os repetidos (contam uma vez).
  FOR v_i IN 0 .. v_n - 1 LOOP
    v_idx  := v_i;
    v_alvo := p_alvos -> v_i;
    IF jsonb_typeof(v_alvo) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'alvos[%]: deve ser um objeto.', v_i
        USING ERRCODE = '22023', DETAIL = json_build_object('indice', v_i)::text;
    END IF;
    BEGIN
      v_grupo := NULLIF(v_alvo ->> 'id_grupo', '')::uuid;
      v_emp   := NULLIF(v_alvo ->> 'codigo_empresa', '')::uuid;
      v_cli   := NULLIF(btrim(v_alvo ->> 'codigo_cliente'), '');
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'alvos[%]: id_grupo e codigo_empresa devem ser uuid.', v_i
        USING ERRCODE = '22023', DETAIL = json_build_object('indice', v_i)::text;
    END;
    IF NOT ((v_grupo IS NOT NULL AND v_emp IS NULL AND v_cli IS NULL)
            OR (v_grupo IS NULL AND v_emp IS NOT NULL AND v_cli IS NOT NULL)) THEN
      RAISE EXCEPTION 'alvos[%]: informe id_grupo OU codigo_empresa + codigo_cliente.', v_i
        USING ERRCODE = '22023', DETAIL = json_build_object('indice', v_i)::text;
    END IF;
    IF length(v_cli) > 60 THEN
      RAISE EXCEPTION 'alvos[%]: codigo_cliente com mais de 60 caracteres.', v_i
        USING ERRCODE = '22023', DETAIL = json_build_object('indice', v_i)::text;
    END IF;
    IF v_grupo IS NOT NULL THEN
      PERFORM 1 FROM core_vendas_faturamento.grupos_clientes g WHERE g.id = v_grupo AND g.ativo FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'alvos[%]: grupo de clientes % não existe ou está inativo.', v_i, v_grupo
          USING ERRCODE = 'AV143', DETAIL = json_build_object('indice', v_i)::text;
      END IF;
      v_chave := 'g:' || v_grupo::text;
    ELSE
      v_chave := 'c:' || v_emp::text || ':' || v_cli;
    END IF;
    IF NOT (v_chave = ANY (v_chaves)) THEN
      v_chaves := array_append(v_chaves, v_chave);
      v_pos    := array_append(v_pos, v_i);
      v_grupos := array_append(v_grupos, v_grupo);
      v_emps   := array_append(v_emps, v_emp);
      v_clis   := array_append(v_clis, v_cli);
    END IF;
  END LOOP;

  -- 2ª passada: trava cada alvo até o fim da transação, em ordem de chave
  -- (duas gravações do mesmo alvo esperam uma pela outra; sem deadlock).
  PERFORM pg_advisory_xact_lock(hashtextextended('api014:clientes_setor:' || k, 0))
     FROM unnest(v_chaves) AS k
    ORDER BY k;

  -- 3ª passada: troca o conjunto de cada alvo.
  FOR v_i IN 1 .. cardinality(v_chaves) LOOP
    v_idx   := v_pos[v_i];
    v_grupo := v_grupos[v_i];
    v_emp   := v_emps[v_i];
    v_cli   := v_clis[v_i];

    SELECT COALESCE(array_agg(cs.id_setor), '{}'::uuid[]) INTO v_atual
      FROM core_vendas_faturamento.clientes_setor cs
     WHERE (v_grupo IS NOT NULL AND cs.id_grupo = v_grupo)
        OR (v_grupo IS NULL AND cs.id_grupo IS NULL AND cs.codigo_empresa = v_emp AND cs.codigo_cliente = v_cli);

    v_entra := ARRAY(SELECT unnest(v_setores) EXCEPT SELECT unnest(v_atual));
    v_sai   := ARRAY(SELECT unnest(v_atual) EXCEPT SELECT unnest(v_setores));

    IF cardinality(v_entra) = 0 AND cardinality(v_sai) = 0 THEN
      v_igual := v_igual + 1;
      CONTINUE;
    END IF;

    -- Setor desativado só não pode ENTRAR; o que o alvo já tem pode ficar.
    FOREACH v_s IN ARRAY v_entra LOOP
      SELECT s.ativo INTO v_ativo FROM core_vendas_faturamento.setores_clientes s WHERE s.id = v_s;
      IF NOT v_ativo THEN
        RAISE EXCEPTION 'alvos[%]: o setor % está desativado e não pode ser escolhido.', v_idx, v_s
          USING ERRCODE = 'AV142', DETAIL = json_build_object('indice', v_idx, 'id_setor', v_s)::text;
      END IF;
    END LOOP;

    IF cardinality(v_sai) > 0 THEN
      DELETE FROM core_vendas_faturamento.clientes_setor cs
       WHERE cs.id_setor = ANY (v_sai)
         AND ((v_grupo IS NOT NULL AND cs.id_grupo = v_grupo)
              OR (v_grupo IS NULL AND cs.id_grupo IS NULL AND cs.codigo_empresa = v_emp AND cs.codigo_cliente = v_cli));
    END IF;
    IF cardinality(v_entra) > 0 THEN
      INSERT INTO core_vendas_faturamento.clientes_setor
             (id_setor, id_grupo, codigo_empresa, codigo_cliente, created_by, updated_by)
      SELECT x, v_grupo, v_emp, v_cli, p_usuario, p_usuario
        FROM unnest(v_entra) AS x
      ON CONFLICT DO NOTHING;
    END IF;

    IF cardinality(v_setores) = 0 THEN
      v_rem := v_rem + 1;
    ELSE
      v_atu := v_atu + 1;
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_atu, v_rem, v_igual;
EXCEPTION
  -- FK de codigo_empresa (unidade que não existe): devolve o índice também.
  WHEN foreign_key_violation THEN
    RAISE EXCEPTION 'alvos[%]: codigo_empresa % não é uma unidade cadastrada.', v_idx, v_emp
      USING ERRCODE = '22023', DETAIL = json_build_object('indice', v_idx)::text;
END $$;


