--
-- TOC entry 1050 (class 1255 OID 24207)
-- Name: fn_clientes_setor_validar(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_clientes_setor_validar() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ativo boolean;
BEGIN
  IF TG_OP = 'INSERT' OR NEW.id_setor IS DISTINCT FROM OLD.id_setor THEN
    -- FOR SHARE: não deixa desativar o setor no meio da gravação.
    SELECT s.ativo INTO v_ativo
      FROM core_vendas_faturamento.setores_clientes s
     WHERE s.id = NEW.id_setor
       FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Setor % não existe.', NEW.id_setor USING ERRCODE = 'AV141';
    END IF;
    IF NOT v_ativo THEN
      RAISE EXCEPTION 'O setor % está desativado e não pode ser escolhido.', NEW.id_setor USING ERRCODE = 'AV142';
    END IF;
  END IF;
  IF NEW.id_grupo IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.id_grupo IS DISTINCT FROM OLD.id_grupo) THEN
    PERFORM 1 FROM core_vendas_faturamento.grupos_clientes g
      WHERE g.id = NEW.id_grupo AND g.ativo
      FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Grupo de clientes % não existe ou está inativo.', NEW.id_grupo USING ERRCODE = 'AV143';
    END IF;
  END IF;
  RETURN NEW;
END $$;


