CREATE FUNCTION core_vendas_faturamento.fn_comprador_da_sessao(p_id_usuario uuid, p_codigo_empresa uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT c.id
    FROM auth.usuarios us
    JOIN core_vendas_faturamento.compradores c
      ON c.id_funcionario = us.id_funcionario
     AND c.codigo_empresa = p_codigo_empresa
     AND c.ativo
     AND c.deleted_at IS NULL
   WHERE us.id = p_id_usuario
     AND us.id_funcionario IS NOT NULL
   -- O índice uq_compradores_funcionario_empresa garante no máximo uma linha;
   -- o ORDER BY só deixa o resultado determinístico se o índice sumir.
   ORDER BY c.updated_at DESC, c.id
   LIMIT 1;
$$;


