-- TOC entry 903 (class 1255 OID 20528)
-- Name: fn_conferencia_itens_parcela(boolean, uuid, text, date, date, text, boolean); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_conferencia_itens_parcela(p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_numero_pedido text DEFAULT NULL::text, p_inicio date DEFAULT NULL::date, p_fim date DEFAULT NULL::date, p_codigo_vendedor text DEFAULT NULL::text, p_so_divergentes boolean DEFAULT false) RETURNS TABLE(is_track_record boolean, codigo_empresa uuid, numero_pedido text, codigo_pedido_omie bigint, sequencial integer, total_pedido_venda numeric, qtd_itens integer, soma_itens numeric, diferenca numeric, situacao_conferencia text)
    LANGUAGE sql STABLE
    AS $_$
  -- Famílias com alguma parcela no filtro. A família inteira entra na conferência.
  WITH fam AS (
    SELECT DISTINCT s.is_track_record, s.codigo_empresa, s.numero_pedido
      FROM (
        SELECT false AS is_track_record, p.codigo_empresa, p.numero_pedido::text AS numero_pedido,
               p.data_inclusao, p.codigo_vendedor_omie
          FROM core_vendas_faturamento.pedidos_vendas p
         WHERE p.deleted_at IS NULL AND NOT COALESCE(p_is_track_record, false)
        UNION ALL
        SELECT true, h.codigo_empresa, h.numero_pedido::text, h.data_inclusao, h.codigo_vendedor_omie
          FROM historico.hst_pedidos_vendas h
         WHERE h.deleted_at IS NULL AND COALESCE(p_is_track_record, false)
      ) s
     WHERE (p_codigo_empresa IS NULL OR s.codigo_empresa = p_codigo_empresa)
       AND (p_numero_pedido  IS NULL OR s.numero_pedido = p_numero_pedido)
       AND (p_codigo_vendedor IS NULL OR s.codigo_vendedor_omie::text = p_codigo_vendedor)
       AND (p_inicio IS NULL OR (s.data_inclusao ~ '^\d{4}-\d{2}-\d{2}$' AND s.data_inclusao::date >= p_inicio))
       AND (p_fim    IS NULL OR (s.data_inclusao ~ '^\d{4}-\d{2}-\d{2}$' AND s.data_inclusao::date <= p_fim))
  )
  -- Tudo o mais é calculado POR FAMÍLIA (LATERAL): conjuntos pequenos, buscas
  -- por índice. Juntar parcelas x itens da janela inteira de uma vez fazia o
  -- planner escolher Nested Loop sobre CTEs (quadrático: ~1 min por mês).
  SELECT f.is_track_record, f.codigo_empresa, f.numero_pedido,
         l.codigo_pedido_omie, l.sequencial,
         l.total::numeric(15,2), l.qtd, l.soma::numeric(15,2),
         (CASE WHEN l.sem_parcela THEN l.soma ELSE l.soma - l.total END)::numeric(15,2),
         CASE WHEN l.sem_parcela       THEN 'itens_sem_parcela'
              WHEN l.soma = l.total    THEN 'confere'
              WHEN l.qtd = 0           THEN 'sem_itens'
              ELSE 'diverge' END
    FROM fam f
   CROSS JOIN LATERAL (
     WITH it AS (
       -- Itens exatamente como a view os entrega (mesma regra de item zerado).
       SELECT v.item_codigo_pedido_omie, v.item_parcela_encontrada,
              count(*)::int AS qtd, COALESCE(sum(v.valor_total), 0) AS soma
         FROM core_vendas_faturamento.vw_pedido_venda_itens v
        WHERE v.is_track_record = f.is_track_record
          AND v.codigo_empresa  = f.codigo_empresa
          AND v.numero_pedido::text = f.numero_pedido
          AND v.id_item IS NOT NULL
        GROUP BY 1, 2
     ), pa AS (
       SELECT p.codigo_pedido_omie, p.sequencial, p.valor_total_pedido
         FROM core_vendas_faturamento.pedidos_vendas p
        WHERE NOT f.is_track_record AND p.deleted_at IS NULL
          AND p.codigo_empresa = f.codigo_empresa AND p.numero_pedido::text = f.numero_pedido
       UNION ALL
       SELECT h.codigo_pedido_omie, h.sequencial, h.valor_total_pedido
         FROM historico.hst_pedidos_vendas h
        WHERE f.is_track_record AND h.deleted_at IS NULL
          AND h.codigo_empresa = f.codigo_empresa AND h.numero_pedido::text = f.numero_pedido
     )
     SELECT pa.codigo_pedido_omie, pa.sequencial::int AS sequencial,
            COALESCE(pa.valor_total_pedido, 0) AS total,
            COALESCE(it.qtd, 0) AS qtd, COALESCE(it.soma, 0) AS soma, false AS sem_parcela
       FROM pa
       LEFT JOIN it ON it.item_parcela_encontrada AND it.item_codigo_pedido_omie = pa.codigo_pedido_omie
     UNION ALL
     SELECT it.item_codigo_pedido_omie, NULL::int, NULL::numeric, it.qtd, it.soma, true
       FROM it
      WHERE NOT it.item_parcela_encontrada
   ) l
   WHERE NOT COALESCE(p_so_divergentes, false)
      OR l.sem_parcela OR l.soma <> l.total
   ORDER BY f.codigo_empresa, f.numero_pedido, l.sem_parcela, COALESCE(l.sequencial, -1), l.codigo_pedido_omie
$_$;


--
-- TOC entry 7283 (class 0 OID 0)
-- Dependencies: 903
-- Name: FUNCTION fn_conferencia_itens_parcela(p_is_track_record boolean, p_codigo_empresa uuid, p_numero_pedido text, p_inicio date, p_fim date, p_codigo_vendedor text, p_so_divergentes boolean); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_conferencia_itens_parcela(p_is_track_record boolean, p_codigo_empresa uuid, p_numero_pedido text, p_inicio date, p_fim date, p_codigo_vendedor text, p_so_divergentes boolean) IS 'Contrato 11 (§5.5). Para cada parcela (linha de pedidos_vendas / hst_pedidos_vendas) das famílias filtradas: soma de valor_total dos itens que vw_pedido_venda_itens atribui a ela (item_codigo_pedido_omie) contra valor_total_pedido (= total_pedido_venda de /vendas_planilha). Filtros escolhem FAMÍLIAS: basta uma parcela bater (unidade, número, vendedor, data_inclusao da parcela). situacao_conferencia: confere | diverge | sem_itens (total <> 0 e nenhum item) | itens_sem_parcela (linha extra, sequencial NULL: itens da família cujo codigo_pedido_omie é nulo ou não é parcela viva da família; codigo_pedido_omie = o do item). diferenca = soma_itens - total_pedido_venda. Divergência indica sync incompleto, ou frete/desconto de cabeçalho que não está nos itens. p_so_divergentes = true devolve só o que não confere. Consumida por GET /pedido_venda_itens/conferencia.';


--
-- TOC entry 645 (class 1255 OID 17295)
-- Name: fn_dashboard_mensal_faturamento(smallint, smallint, boolean, uuid); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
