-- TOC entry 708 (class 1255 OID 17302)
-- Name: fn_exige_vendedor_vivo(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_exige_vendedor_vivo() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_id_funcionario uuid;
  v_coluna         text;
BEGIN
  -- A coluna a validar vem como argumento, para a mesma função servir às três
  -- pontas (vendedor do diligenciador, auxiliar e titular).
  v_coluna := TG_ARGV[0];
  EXECUTE format('SELECT ($1).%I', v_coluna) INTO v_id_funcionario USING NEW;

  IF v_id_funcionario IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM core_vendas_faturamento.vendedores v
     WHERE v.id_funcionario = v_id_funcionario
       AND v.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION
      '% aponta para um funcionario sem cadastro de vendedor ativo (id_funcionario=%)',
      v_coluna, v_id_funcionario
      USING ERRCODE = '23514';   -- check_violation: a API já mapeia para 400
  END IF;

  RETURN NEW;
END $_$;


