CREATE FUNCTION core_vendas_faturamento.fn_faturamento_planilha_notas_classificadas(p_inicio date, p_fim date, p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_vendedor text[] DEFAULT NULL::text[]) RETURNS TABLE(codigo_empresa uuid, codigo_nf_omie bigint, nota_fiscal text, codigo_cliente text, codigo_vendedor text, data_emissao date, valor numeric, is_ypfb boolean, grupo text)
    LANGUAGE sql STABLE
    AS $$
  SELECT f.codigo_empresa,
         f.codigo_nf_omie,
         f.nota_fiscal::text,
         f.codigo_cliente::text,
         f.codigo_vendedor::text,
         f.data_emissao,
         f.total_nota_fiscal_ajustado,
         unaccent(upper(COALESCE(f.destinatario, '') || ' ' || COALESCE(f.nome_fantasia_destinatario, ''))) LIKE '%YPFB%',
         COALESCE(f.grupo, 'LIQUIDO')
    FROM core_vendas_faturamento.vw_faturamento_planilha f
   WHERE f.is_track_record = COALESCE(p_is_track_record, false)
     AND f.data_emissao BETWEEN p_inicio AND p_fim
     AND (p_codigo_empresa IS NULL OR f.codigo_empresa = p_codigo_empresa)
     AND (p_codigo_vendedor IS NULL OR f.codigo_vendedor = ANY (p_codigo_vendedor))
     AND core_vendas_faturamento.fn_nota_motivo_fora(f.deleted_at, f.tipo_nf::text,
           f.total_nota_fiscal_ajustado, f.pedido::text, f.manual_nf) IS NULL
$$;


