CREATE FUNCTION core_vendas_faturamento.fn_faturamento_planilha_resumo_periodo(p_inicio date, p_fim date, p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_vendedor text[] DEFAULT NULL::text[]) RETURNS TABLE(ordem integer, secao text, tipo text, rotulo text, grupo text, valor numeric, qtd_nfs bigint, pct_total numeric)
    LANGUAGE sql STABLE
    AS $$
  WITH cls AS (
    SELECT c.valor, c.is_ypfb, c.grupo
      FROM core_vendas_faturamento.fn_faturamento_planilha_notas_classificadas(
             p_inicio, p_fim, p_is_track_record, p_codigo_empresa, p_codigo_vendedor) c
  ), agg AS (
    SELECT COALESCE(sum(valor) FILTER (WHERE NOT is_ypfb), 0) AS bv, count(*) FILTER (WHERE NOT is_ypfb) AS bq,
           COALESCE(sum(valor) FILTER (WHERE grupo = 'G1'), 0) AS g1v,  count(*) FILTER (WHERE grupo = 'G1') AS g1q,
           COALESCE(sum(valor) FILTER (WHERE grupo = 'G2'), 0) AS g2v,  count(*) FILTER (WHERE grupo = 'G2') AS g2q,
           COALESCE(sum(valor) FILTER (WHERE grupo = 'G2P'), 0) AS g2pv, count(*) FILTER (WHERE grupo = 'G2P') AS g2pq,
           COALESCE(sum(valor) FILTER (WHERE grupo = 'G3'), 0) AS g3v,  count(*) FILTER (WHERE grupo = 'G3') AS g3q,
           COALESCE(sum(valor) FILTER (WHERE grupo = 'G4'), 0) AS g4v,  count(*) FILTER (WHERE grupo = 'G4') AS g4q,
           COALESCE(sum(valor) FILTER (WHERE grupo = 'G5'), 0) AS g5v,  count(*) FILTER (WHERE grupo = 'G5') AS g5q,
           COALESCE(sum(valor) FILTER (WHERE grupo = 'G6'), 0) AS g6v,  count(*) FILTER (WHERE grupo = 'G6') AS g6q
      FROM cls
  )
  SELECT q.ordem, q.secao, q.tipo, q.rotulo, q.grupo, q.valor, q.qtd, q.pct_total
    FROM agg a
   CROSS JOIN LATERAL core_vendas_faturamento.fn_quadro_deducoes('faturamento',
     a.bv, a.bq, a.g1v, a.g1q, a.g2v, a.g2q, a.g2pv, a.g2pq, a.g3v, a.g3q, a.g4v, a.g4q, a.g5v, a.g5q, a.g6v, a.g6q) q
$$;


