CREATE FUNCTION core_vendas_faturamento.fn_grupos_clientes_membros_validar() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.id_grupo IS DISTINCT FROM OLD.id_grupo THEN
    IF NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.grupos_clientes g
                    WHERE g.id = NEW.id_grupo AND g.ativo) THEN
      RAISE EXCEPTION 'Grupo de clientes % não existe ou está inativo.', NEW.id_grupo
        USING ERRCODE = 'AV481';
    END IF;
  END IF;
  RETURN NEW;
END $$;


