--
-- TOC entry 550 (class 1255 OID 22453)
-- Name: fn_grupos_clientes_sugestoes(uuid, text, boolean); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_grupos_clientes_sugestoes(p_codigo_empresa uuid DEFAULT NULL::uuid, p_busca text DEFAULT NULL::text, p_so_sem_grupo boolean DEFAULT true) RETURNS TABLE(raiz_cnpj text, nome_sugerido character varying, qtd_cnpjs integer, qtd_sem_grupo integer, grupos jsonb, clientes jsonb)
    LANGUAGE sql STABLE
    AS $$
  WITH clientes_com_venda AS (
    SELECT DISTINCT p.codigo_empresa, p.codigo_cliente::varchar AS codigo_cliente
      FROM core_vendas_faturamento.pedidos_vendas p
     WHERE p.deleted_at IS NULL AND p.codigo_cliente IS NOT NULL
    UNION
    SELECT n.codigo_empresa, n.codigo_cliente::varchar
      FROM core_vendas_faturamento.notas_fiscais n
     WHERE n.deleted_at IS NULL AND n.codigo_cliente IS NOT NULL
  ),
  cnpjs AS (
    SELECT c.codigo_empresa, c.codigo_cliente, pa.nome_fantasia, pa.razao_social, pa.cpf_cnpj,
           left(regexp_replace(pa.cpf_cnpj, '\D', '', 'g'), 8) AS raiz,
           g.id AS id_grupo, g.nome AS nome_grupo
      FROM clientes_com_venda c
      JOIN core.parceiros pa
        ON pa.codigo_empresa = c.codigo_empresa AND pa.codigo_parceiro_omie = c.codigo_cliente
       AND pa.deleted_at IS NULL
      LEFT JOIN core_vendas_faturamento.grupos_clientes_membros m
        ON m.codigo_empresa = c.codigo_empresa AND m.codigo_cliente = c.codigo_cliente
      LEFT JOIN core_vendas_faturamento.grupos_clientes g ON g.id = m.id_grupo AND g.ativo
     WHERE length(regexp_replace(pa.cpf_cnpj, '\D', '', 'g')) = 14
  ),
  raizes AS (
    SELECT c.raiz
      FROM cnpjs c
     GROUP BY c.raiz
    HAVING count(*) >= 2
       AND (p_codigo_empresa IS NULL OR bool_or(c.codigo_empresa = p_codigo_empresa))
       AND (NOT COALESCE(p_so_sem_grupo, true) OR bool_or(c.id_grupo IS NULL))
       AND (NULLIF(btrim(p_busca), '') IS NULL
            OR bool_or(c.raiz LIKE regexp_replace(p_busca, '\D', '', 'g') || '%'
                         AND regexp_replace(p_busca, '\D', '', 'g') <> '')
            OR bool_or(c.nome_fantasia ILIKE '%' || btrim(p_busca) || '%')
            OR bool_or(c.razao_social ILIKE '%' || btrim(p_busca) || '%'))
  )
  SELECT r.raiz,
         (SELECT c2.razao_social FROM cnpjs c2 WHERE c2.raiz = r.raiz
           GROUP BY c2.razao_social ORDER BY count(*) DESC, c2.razao_social LIMIT 1),
         count(*)::integer,
         (count(*) FILTER (WHERE c.id_grupo IS NULL))::integer,
         COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id_grupo', c.id_grupo, 'nome_grupo', c.nome_grupo))
                    FILTER (WHERE c.id_grupo IS NOT NULL), '[]'::jsonb),
         jsonb_agg(jsonb_build_object(
           'codigo_empresa', c.codigo_empresa, 'codigo_cliente', c.codigo_cliente,
           'nome_fantasia', c.nome_fantasia, 'razao_social', c.razao_social, 'cpf_cnpj', c.cpf_cnpj,
           'id_grupo', c.id_grupo, 'nome_grupo', c.nome_grupo)
           ORDER BY c.cpf_cnpj, c.codigo_empresa)
    FROM raizes r
    JOIN cnpjs c ON c.raiz = r.raiz
   GROUP BY r.raiz
   ORDER BY count(*) FILTER (WHERE c.id_grupo IS NULL) DESC, count(*) DESC, r.raiz;
$$;


