-- Name: FUNCTION fn_grupos_clientes_sugestoes(p_codigo_empresa uuid, p_busca text, p_so_sem_grupo boolean); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_grupos_clientes_sugestoes(p_codigo_empresa uuid, p_busca text, p_so_sem_grupo boolean) IS 'Contrato 48: sugestão de grupo de empresa — raízes de CNPJ (8 primeiros dígitos; só CNPJ de 14 dígitos, CPF fica fora) com 2 ou mais clientes que têm pedido ou NF (em qualquer unidade). p_codigo_empresa: só raízes com algum CNPJ dessa unidade. p_busca: começo da raiz (dígitos) ou parte do nome fantasia/razão social. p_so_sem_grupo (padrão true): só raízes com algum CNPJ ainda fora de grupo ativo. clientes (jsonb) traz todos os CNPJs da raiz com o grupo ativo de cada um.';


--
-- TOC entry 481 (class 1255 OID 22445)
-- Name: fn_grupos_clientes_vincular(uuid, uuid, text, uuid, boolean); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_grupos_clientes_vincular(p_id_grupo uuid, p_codigo_empresa uuid, p_codigo_cliente text, p_usuario uuid DEFAULT NULL::uuid, p_mover boolean DEFAULT false) RETURNS TABLE(id uuid, acao text, id_grupo_anterior uuid, nome_grupo_anterior character varying)
    LANGUAGE plpgsql
    AS $$
#variable_conflict use_column
DECLARE
  v_cliente text := btrim(p_codigo_cliente);
  v_atual   record;
  v_id      uuid;
BEGIN
  IF p_id_grupo IS NULL OR p_codigo_empresa IS NULL OR v_cliente IS NULL OR v_cliente = '' THEN
    RAISE EXCEPTION 'Informe o grupo, a unidade (codigo_empresa) e o cliente (codigo_cliente).'
      USING ERRCODE = '22023';
  END IF;

  -- Trava o grupo de destino: não deixa desativar no meio do vínculo.
  PERFORM 1 FROM core_vendas_faturamento.grupos_clientes g
    WHERE g.id = p_id_grupo AND g.ativo FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Grupo de clientes % não existe ou está inativo.', p_id_grupo
      USING ERRCODE = 'AV481';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM core.parceiros pa
                  WHERE pa.codigo_empresa = p_codigo_empresa AND pa.codigo_parceiro_omie = v_cliente)
     AND NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.pedidos_vendas pv
                      WHERE pv.codigo_empresa = p_codigo_empresa AND pv.codigo_cliente = v_cliente)
     AND NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.notas_fiscais nf
                      WHERE nf.codigo_empresa = p_codigo_empresa AND nf.codigo_cliente = v_cliente) THEN
    RAISE EXCEPTION 'Cliente % não encontrado na unidade % (core.parceiros, pedidos ou notas).', v_cliente, p_codigo_empresa
      USING ERRCODE = 'AV483';
  END IF;

  SELECT m.id, m.id_grupo, g.nome, g.ativo INTO v_atual
    FROM core_vendas_faturamento.grupos_clientes_membros m
    JOIN core_vendas_faturamento.grupos_clientes g ON g.id = m.id_grupo
   WHERE m.codigo_empresa = p_codigo_empresa AND m.codigo_cliente = v_cliente
   FOR UPDATE OF m;

  IF FOUND THEN
    IF v_atual.id_grupo = p_id_grupo THEN
      RETURN QUERY SELECT v_atual.id, 'ja_no_grupo'::text, NULL::uuid, NULL::varchar;
      RETURN;
    END IF;
    IF v_atual.ativo AND NOT COALESCE(p_mover, false) THEN
      RAISE EXCEPTION 'O cliente % já está no grupo "%".', v_cliente, v_atual.nome
        USING ERRCODE = 'AV482',
              DETAIL = json_build_object('id_grupo', v_atual.id_grupo, 'nome_grupo', v_atual.nome)::text,
              HINT = 'Remova do outro grupo ou peça para mover (mover = true).';
    END IF;
    UPDATE core_vendas_faturamento.grupos_clientes_membros m
       SET id_grupo = p_id_grupo, created_by = p_usuario, created_at = now()
     WHERE m.id = v_atual.id;
    RETURN QUERY SELECT v_atual.id, 'movido'::text, v_atual.id_grupo, v_atual.nome;
    RETURN;
  END IF;

  INSERT INTO core_vendas_faturamento.grupos_clientes_membros (id_grupo, codigo_empresa, codigo_cliente, created_by)
  VALUES (p_id_grupo, p_codigo_empresa, v_cliente, p_usuario)
  ON CONFLICT (codigo_empresa, codigo_cliente) DO NOTHING
  RETURNING grupos_clientes_membros.id INTO v_id;

  IF v_id IS NULL THEN
    -- Outra transação vinculou o mesmo CNPJ ao mesmo tempo.
    SELECT g.id, g.nome INTO v_atual
      FROM core_vendas_faturamento.grupos_clientes_membros m
      JOIN core_vendas_faturamento.grupos_clientes g ON g.id = m.id_grupo
     WHERE m.codigo_empresa = p_codigo_empresa AND m.codigo_cliente = v_cliente;
    RAISE EXCEPTION 'O cliente % acabou de ser vinculado ao grupo "%".', v_cliente, v_atual.nome
      USING ERRCODE = 'AV482',
            DETAIL = json_build_object('id_grupo', v_atual.id, 'nome_grupo', v_atual.nome)::text;
  END IF;

  RETURN QUERY SELECT v_id, 'incluido'::text, NULL::uuid, NULL::varchar;
END $$;


--
-- TOC entry 7298 (class 0 OID 0)
-- Dependencies: 481
