CREATE FUNCTION core_vendas_faturamento.fn_is_refaturamento_candidato(codigo_categoria text, obs text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT codigo_categoria = '1.01.96'
        OR obs ~* '(REFATURAMENTO|REAFTURAMENTO|REFATORAMENTO|REFATURO|REFATORO)'
$$;


