CREATE FUNCTION core_vendas_faturamento.fn_itens_pedido_custo_do_pedido(p_codigo_empresa uuid, p_numero_pedido text) RETURNS TABLE(codigo_produto_omie character varying, codigo_produto character varying, codigo_pedido_omie bigint, quantidade numeric, quantidade_com_custo numeric, custo_total numeric, custo_medio numeric, completo boolean, cotacao_a_conferir boolean, lotes jsonb, mes_alterado_em timestamp with time zone, atualizado_em timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
  SELECT c.codigo_produto_omie, c.codigo_produto, c.codigo_pedido_omie,
         c.quantidade, c.quantidade_com_custo, c.custo_total, c.custo_medio,
         c.completo, c.cotacao_a_conferir, c.lotes, c.mes_alterado_em, c.atualizado_em
    FROM core_vendas_faturamento.itens_pedido_custo c
   WHERE c.codigo_empresa = p_codigo_empresa
     AND c.numero_pedido = p_numero_pedido
   ORDER BY c.codigo_produto NULLS LAST, c.codigo_produto_omie;
$$;


