--
-- TOC entry 1048 (class 1255 OID 22395)
-- Name: fn_itens_pedido_custo_gravar(uuid, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_itens_pedido_custo_gravar(p_codigo_empresa uuid, p_alterado_desde timestamp with time zone, p_apos_id text, p_linhas jsonb) RETURNS TABLE(recebidas integer, inseridas integer, atualizadas integer, ignoradas jsonb, novo_cursor timestamp with time zone, novo_apos_id text)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_uuid_re   constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_recebidas int;
  v_ins       int;
  v_upd       int;
  v_ign       jsonb;
  v_pag_ts    timestamptz;
  v_pag_id    text;
  v_cur_ts    timestamptz;
  v_cur_id    text;
BEGIN
  IF p_codigo_empresa IS NULL OR p_alterado_desde IS NULL THEN
    RAISE EXCEPTION 'fn_itens_pedido_custo_gravar: unidade e alterado_desde são obrigatórios'
      USING ERRCODE = '22004';
  END IF;
  IF p_linhas IS NULL THEN
    p_linhas := '[]'::jsonb;
  END IF;
  IF jsonb_typeof(p_linhas) <> 'array' THEN
    RAISE EXCEPTION 'fn_itens_pedido_custo_gravar: linhas deve ser um array JSON (veio %)', jsonb_typeof(p_linhas)
      USING ERRCODE = '22023';
  END IF;
  v_recebidas := jsonb_array_length(p_linhas);
  p_apos_id := NULLIF(btrim(p_apos_id), '');

  -- Um só comando: normaliza e valida cada linha, grava as válidas e devolve
  -- contagens, inválidas e a maior (alterado_em, id) da página.
  WITH bruto AS (
    SELECT e.ord::int AS pos, e.l,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'codigo_empresa'), '') END       AS emp_txt,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'numero_pedido'), '') END        AS numero_pedido,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'codigo_produto_omie'), '') END  AS produto_omie,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'codigo_produto'), '') END       AS produto,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'codigo_pedido_omie'), '') END   AS pedido_omie_txt,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'quantidade'), '') END           AS qtd_txt,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'quantidade_com_custo'), '') END AS qcc_txt,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'custo_total'), '') END          AS total_txt,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'custo_medio'), '') END          AS medio_txt,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN e.l->'completo' END                                 AS completo_j,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN e.l->'cotacao_a_conferir' END                       AS conferir_j,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN e.l->'lotes' END                                    AS lotes_j,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'id'), '') END                   AS id_txt,
           CASE WHEN jsonb_typeof(e.l) = 'object' THEN NULLIF(btrim(e.l->>'alterado_em'), '') END          AS alterado_txt
      FROM jsonb_array_elements(p_linhas) WITH ORDINALITY AS e(l, ord)
  ),
  -- Pedido manual no hub (contrato 30): nunca entra no custo (008 D6).
  manuais AS (
    SELECT DISTINCT pv.numero_pedido::text AS numero_pedido
      FROM core_vendas_faturamento.pedidos_vendas pv
     WHERE pv.codigo_empresa = p_codigo_empresa
       AND pv.manual
       AND pv.numero_pedido::text IN (SELECT b.numero_pedido FROM bruto b WHERE b.numero_pedido IS NOT NULL)
  ),
  validado AS (
    SELECT b.*,
           CASE WHEN b.alterado_txt IS NOT NULL AND pg_input_is_valid(b.alterado_txt, 'timestamptz')
                 AND (b.id_txt IS NULL OR length(b.id_txt) <= 100)
                THEN b.alterado_txt::timestamptz END AS alterado_ok,
           CASE
             WHEN jsonb_typeof(b.l) <> 'object'                                   THEN 'linha não é objeto'
             WHEN b.alterado_txt IS NULL OR NOT pg_input_is_valid(b.alterado_txt, 'timestamptz')
                                                                                  THEN 'alterado_em ausente ou inválido'
             WHEN b.id_txt IS NOT NULL AND length(b.id_txt) > 100                 THEN 'id com mais de 100 caracteres'
             WHEN b.emp_txt IS NOT NULL
              AND CASE WHEN b.emp_txt ~ v_uuid_re THEN b.emp_txt::uuid <> p_codigo_empresa ELSE true END
                                                                                  THEN 'codigo_empresa diferente da unidade lida'
             WHEN b.numero_pedido IS NULL                                         THEN 'numero_pedido ausente'
             WHEN length(b.numero_pedido) > 40                                    THEN 'numero_pedido com mais de 40 caracteres'
             WHEN b.produto_omie IS NULL                                          THEN 'codigo_produto_omie ausente'
             WHEN length(b.produto_omie) > 60                                     THEN 'codigo_produto_omie com mais de 60 caracteres'
             WHEN b.produto IS NOT NULL AND length(b.produto) > 60                THEN 'codigo_produto com mais de 60 caracteres'
             WHEN b.pedido_omie_txt IS NOT NULL AND NOT pg_input_is_valid(b.pedido_omie_txt, 'bigint')
                                                                                  THEN 'codigo_pedido_omie não é número inteiro'
             WHEN (b.pedido_omie_txt IS NOT NULL AND b.pedido_omie_txt::bigint <= 0)
               OR EXISTS (SELECT 1 FROM manuais m WHERE m.numero_pedido = b.numero_pedido)
                                                                                  THEN 'pedido manual não entra no custo (008 D6)'
             WHEN CASE WHEN pg_input_is_valid(b.qtd_txt, 'numeric(15,4)') THEN b.qtd_txt::numeric < 0 ELSE true END
                                                                                  THEN 'quantidade ausente ou inválida'
             WHEN CASE WHEN pg_input_is_valid(b.qcc_txt, 'numeric(15,4)') THEN b.qcc_txt::numeric < 0 ELSE true END
                                                                                  THEN 'quantidade_com_custo ausente ou inválida'
             WHEN CASE WHEN pg_input_is_valid(b.total_txt, 'numeric(18,6)') THEN b.total_txt::numeric < 0 ELSE true END
                                                                                  THEN 'custo_total ausente ou inválido'
             WHEN b.medio_txt IS NOT NULL
              AND CASE WHEN pg_input_is_valid(b.medio_txt, 'numeric(18,6)') THEN b.medio_txt::numeric < 0 ELSE true END
                                                                                  THEN 'custo_medio inválido'
             WHEN b.completo_j IS NULL OR jsonb_typeof(b.completo_j) <> 'boolean' THEN 'completo ausente ou não é booleano'
             WHEN b.completo_j = 'true'::jsonb
              AND (b.qtd_txt::numeric(15,4) = 0 OR b.qcc_txt::numeric(15,4) <> b.qtd_txt::numeric(15,4))
                                                                                  THEN 'completo = true com quantidade_com_custo diferente de quantidade'
             WHEN b.conferir_j IS NOT NULL AND jsonb_typeof(b.conferir_j) NOT IN ('boolean', 'null')
                                                                                  THEN 'cotacao_a_conferir não é booleano'
             WHEN b.lotes_j IS NOT NULL AND jsonb_typeof(b.lotes_j) NOT IN ('array', 'null')
                                                                                  THEN 'lotes não é lista'
             WHEN jsonb_typeof(b.lotes_j) = 'array' AND EXISTS (
                    SELECT 1 FROM jsonb_array_elements(b.lotes_j) lt(x)
                     WHERE jsonb_typeof(lt.x) <> 'object'
                        OR (lt.x ? 'origem' AND jsonb_typeof(lt.x->'origem') <> 'null'
                            AND COALESCE(lt.x->>'origem', '') NOT IN ('CARGA_INICIAL', 'OC', 'MANUAL'))
                        OR (lt.x ? 'consumido' AND jsonb_typeof(lt.x->'consumido') NOT IN ('boolean', 'null')))
                                                                                  THEN 'lote inválido (não é objeto, origem fora de CARGA_INICIAL/OC/MANUAL ou consumido não booleano)'
           END AS motivo
      FROM bruto b
  ),
  -- O mesmo produto duas vezes na página fica com a de maior (alterado_em, id, posição).
  novas AS (
    SELECT DISTINCT ON (x.numero_pedido, x.produto_omie) x.*
      FROM (
        SELECT v.pos, v.numero_pedido, v.produto_omie, v.produto,
               v.pedido_omie_txt::bigint  AS pedido_omie,
               v.qtd_txt::numeric(15,4)   AS quantidade,
               v.qcc_txt::numeric(15,4)   AS qcc,
               v.total_txt::numeric(18,6) AS custo_total,
               COALESCE(v.medio_txt::numeric(18,6),
                        CASE WHEN v.qcc_txt::numeric(15,4) > 0
                             THEN round(v.total_txt::numeric(18,6) / v.qcc_txt::numeric(15,4), 6) END) AS custo_medio,
               (v.completo_j = 'true'::jsonb) AS completo,
               COALESCE(v.conferir_j = 'true'::jsonb, false) AS conferir,
               CASE WHEN jsonb_typeof(v.lotes_j) = 'array' THEN v.lotes_j ELSE '[]'::jsonb END AS lotes,
               v.id_txt, v.alterado_ok AS alterado_em
          FROM validado v
         WHERE v.motivo IS NULL
      ) x
     ORDER BY x.numero_pedido, x.produto_omie, x.alterado_em DESC, x.id_txt DESC NULLS LAST, x.pos DESC
  ),
  gravadas AS (
    INSERT INTO core_vendas_faturamento.itens_pedido_custo AS s
      (codigo_empresa, numero_pedido, codigo_produto_omie, codigo_produto, codigo_pedido_omie,
       quantidade, quantidade_com_custo, custo_total, custo_medio,
       completo, cotacao_a_conferir, lotes, id_mes, mes_alterado_em)
    SELECT p_codigo_empresa, n.numero_pedido, n.produto_omie, n.produto, n.pedido_omie,
           n.quantidade, n.qcc, n.custo_total, n.custo_medio,
           n.completo, n.conferir, n.lotes, n.id_txt, n.alterado_em
      FROM novas n
    ON CONFLICT ON CONSTRAINT uq_itens_pedido_custo DO UPDATE
       SET codigo_produto       = EXCLUDED.codigo_produto,
           codigo_pedido_omie   = EXCLUDED.codigo_pedido_omie,
           quantidade           = EXCLUDED.quantidade,
           quantidade_com_custo = EXCLUDED.quantidade_com_custo,
           custo_total          = EXCLUDED.custo_total,
           custo_medio          = EXCLUDED.custo_medio,
           completo             = EXCLUDED.completo,
           cotacao_a_conferir   = EXCLUDED.cotacao_a_conferir,
           lotes                = EXCLUDED.lotes,
           id_mes               = EXCLUDED.id_mes,
           mes_alterado_em      = EXCLUDED.mes_alterado_em,
           atualizado_em        = now()
     -- Linha mais velha que a gravada não sobrescreve; a mesma foto relida
     -- (o MES usa alterado_em >= sem apos_id) não grava de novo.
     WHERE EXCLUDED.mes_alterado_em >= s.mes_alterado_em
       AND (s.codigo_produto, s.codigo_pedido_omie, s.quantidade, s.quantidade_com_custo, s.custo_total,
            s.custo_medio, s.completo, s.cotacao_a_conferir, s.lotes, s.id_mes, s.mes_alterado_em)
           IS DISTINCT FROM
           (EXCLUDED.codigo_produto, EXCLUDED.codigo_pedido_omie, EXCLUDED.quantidade, EXCLUDED.quantidade_com_custo,
            EXCLUDED.custo_total, EXCLUDED.custo_medio, EXCLUDED.completo, EXCLUDED.cotacao_a_conferir,
            EXCLUDED.lotes, EXCLUDED.id_mes, EXCLUDED.mes_alterado_em)
    RETURNING (s.xmax = 0) AS inserida
  ),
  -- Cursor candidato: a maior (alterado_em, id) da página, também das linhas
  -- ignoradas que tinham alterado_em válido (senão o job pararia nelas).
  maior AS (
    SELECT v.alterado_ok AS ts, v.id_txt AS id
      FROM validado v
     WHERE v.alterado_ok IS NOT NULL
     ORDER BY v.alterado_ok DESC, v.id_txt DESC NULLS LAST
     LIMIT 1
  )
  SELECT (SELECT count(*) FILTER (WHERE g.inserida) FROM gravadas g)::int,
         (SELECT count(*) FILTER (WHERE NOT g.inserida) FROM gravadas g)::int,
         (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                    'posicao', v.pos, 'numero_pedido', v.numero_pedido,
                    'codigo_produto_omie', v.produto_omie, 'motivo', v.motivo)
                  ORDER BY v.pos), '[]'::jsonb)
            FROM validado v WHERE v.motivo IS NOT NULL),
         (SELECT m.ts FROM maior m),
         (SELECT m.id FROM maior m)
    INTO v_ins, v_upd, v_ign, v_pag_ts, v_pag_id;

  -- Cursor: o maior entre o gravado, o pedido (p_alterado_desde, p_apos_id) e
  -- a maior linha da página, comparando (alterado_em, id) com id NULL = menor.
  SELECT c.alterado_desde, c.apos_id INTO v_cur_ts, v_cur_id
    FROM core_vendas_faturamento.itens_pedido_custo_cursor c
   WHERE c.codigo_empresa = p_codigo_empresa
     FOR UPDATE;
  IF NOT FOUND OR (p_alterado_desde, COALESCE(p_apos_id, '')) > (v_cur_ts, COALESCE(v_cur_id, '')) THEN
    v_cur_ts := p_alterado_desde;
    v_cur_id := p_apos_id;
  END IF;
  IF v_pag_ts IS NOT NULL AND (v_pag_ts, COALESCE(v_pag_id, '')) > (v_cur_ts, COALESCE(v_cur_id, '')) THEN
    v_cur_ts := v_pag_ts;
    v_cur_id := v_pag_id;
  END IF;

  INSERT INTO core_vendas_faturamento.itens_pedido_custo_cursor AS c (codigo_empresa, alterado_desde, apos_id, atualizado_em)
  VALUES (p_codigo_empresa, v_cur_ts, v_cur_id, now())
  ON CONFLICT (codigo_empresa) DO UPDATE
     SET alterado_desde = EXCLUDED.alterado_desde,
         apos_id        = EXCLUDED.apos_id,
         atualizado_em  = now();

  RETURN QUERY SELECT v_recebidas, v_ins, v_upd, v_ign, v_cur_ts, v_cur_id;
END
$_$;


--
-- TOC entry 7302 (class 0 OID 0)
-- Dependencies: 1048
-- Name: FUNCTION fn_itens_pedido_custo_gravar(p_codigo_empresa uuid, p_alterado_desde timestamp with time zone, p_apos_id text, p_linhas jsonb); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_itens_pedido_custo_gravar(p_codigo_empresa uuid, p_alterado_desde timestamp with time zone, p_apos_id text, p_linhas jsonb) IS 'Contrato 47 §1 (migration 047b): grava UMA página de GET /itens/custo do MES (array JSON puro, 008 §5) para a unidade, numa só transação. Upsert por (codigo_empresa, numero_pedido, codigo_produto_omie): o item é o produto (008 A1/D7); o campo "item" não é mais lido. Linha inválida (sem numero_pedido/codigo_produto_omie/quantidades/custo_total/completo/alterado_em, valor negativo, outra unidade, completo = true com quantidade_com_custo <> quantidade, lotes que não é lista, lote com origem fora de CARGA_INICIAL/OC/MANUAL ou consumido não booleano) é ignorada e devolvida em "ignoradas". PEDIDO MANUAL (pedidos_vendas.manual ou codigo_pedido_omie <= 0) também é ignorado (008 D6). Linha mais velha que a gravada não muda nada; mesma foto relida também não. custo_medio ausente = custo_total / quantidade_com_custo. Custo sem impostos no Ciclo 1 (008 D5). Avança o cursor (alterado_desde, apos_id) para a maior (alterado_em, id) da página, nunca para trás, e marca a leitura (atualizado_em = now()), também com página vazia. Devolve recebidas, inseridas, atualizadas, ignoradas, novo_cursor e novo_apos_id.';


--
-- TOC entry 501 (class 1255 OID 21424)
-- Name: fn_itens_pedido_status_do_pedido(uuid, text, boolean); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_itens_pedido_status_do_pedido(p_codigo_empresa uuid, p_pedido_venda text, p_historico boolean DEFAULT false) RETURNS TABLE(id_item_parcial uuid, codigo_produto_omie character varying, codigo_produto character varying, ordem_producao character varying, etapa character varying, setor_codigo character varying, setor_nome character varying, setor_tipo character varying, status character varying, quantidade_na_etapa numeric, atendido_pelo_estoque boolean, ocorrido_em timestamp with time zone, mes_deleted_at timestamp with time zone, lido_em timestamp with time zone, atual boolean)
    LANGUAGE sql STABLE
    AS $$
  WITH linhas AS (
    SELECT s.*,
           row_number() OVER (PARTITION BY s.id_item_parcial
                              ORDER BY s.ocorrido_em DESC, s.mes_updated_at DESC, s.lido_em DESC, s.id DESC) = 1
             AS mais_recente,
           -- ordena cada parcial pelo produto da foto mais recente (as fotos
           -- de uma parcial ficam juntas mesmo se o código mudou no MES)
           first_value(s.codigo_produto) OVER (PARTITION BY s.id_item_parcial
                              ORDER BY s.ocorrido_em DESC, s.mes_updated_at DESC, s.lido_em DESC, s.id DESC)
             AS produto_ordem
      FROM core_vendas_faturamento.itens_pedido_status s
     WHERE s.codigo_empresa = p_codigo_empresa
       AND s.pedido_venda = p_pedido_venda
  )
  SELECT l.id_item_parcial, l.codigo_produto_omie, l.codigo_produto, l.ordem_producao, l.etapa,
         l.setor_codigo, l.setor_nome, l.setor_tipo, l.status, l.quantidade_na_etapa,
         l.atendido_pelo_estoque, l.ocorrido_em, l.mes_deleted_at, l.lido_em,
         (l.mais_recente AND l.mes_deleted_at IS NULL) AS atual
    FROM linhas l
   WHERE COALESCE(p_historico, false) OR (l.mais_recente AND l.mes_deleted_at IS NULL)
   ORDER BY l.produto_ordem NULLS LAST, l.id_item_parcial, l.ocorrido_em DESC, l.mes_updated_at DESC, l.lido_em DESC, l.id DESC;
$$;


--
-- TOC entry 7303 (class 0 OID 0)
-- Dependencies: 501
-- Name: FUNCTION fn_itens_pedido_status_do_pedido(p_codigo_empresa uuid, p_pedido_venda text, p_historico boolean); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_itens_pedido_status_do_pedido(p_codigo_empresa uuid, p_pedido_venda text, p_historico boolean) IS 'Contrato de API 005 / 006: status por item de UM pedido (unidade + número), para GET /itens_pedido_status. Sem histórico: a foto mais recente de cada parcial viva (mesma regra da vw_itens_pedido_status_atual). Com histórico: todas as fotos lidas, inclusive das parciais canceladas no MES, com atual = true só na que vale hoje. Ordem: codigo_produto, id_item_parcial, ocorrido_em decrescente.';


--
-- TOC entry 756 (class 1255 OID 21422)
-- Name: fn_itens_pedido_status_gravar(uuid, timestamp with time zone, jsonb); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_itens_pedido_status_gravar(p_codigo_empresa uuid, p_alterado_desde timestamp with time zone, p_linhas jsonb) RETURNS TABLE(recebidas integer, inseridas integer, atualizadas integer, ignoradas jsonb, novo_cursor timestamp with time zone)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_uuid_re  constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_recebidas int;
BEGIN
  IF p_codigo_empresa IS NULL OR p_alterado_desde IS NULL THEN
    RAISE EXCEPTION 'fn_itens_pedido_status_gravar: unidade e alterado_desde são obrigatórios'
      USING ERRCODE = '22004';
  END IF;
  IF p_linhas IS NULL THEN
    p_linhas := '[]'::jsonb;
  END IF;
  IF jsonb_typeof(p_linhas) <> 'array' THEN
    RAISE EXCEPTION 'fn_itens_pedido_status_gravar: linhas deve ser um array JSON (veio %)', jsonb_typeof(p_linhas)
      USING ERRCODE = '22023';
  END IF;
  v_recebidas := jsonb_array_length(p_linhas);

  -- Um só comando (sem tabela temporária): normaliza e valida cada linha,
  -- grava as válidas e avança o cursor. Texto vazio vira NULL; setor pode vir
  -- nulo.
  RETURN QUERY
  WITH bruto AS (
    SELECT e.ord::int AS pos, e.l,
           NULLIF(btrim(e.l->>'id_item_parcial'), '')     AS id_txt,
           NULLIF(btrim(e.l->>'codigo_empresa'), '')      AS emp_txt,
           NULLIF(btrim(e.l->>'pedido_venda'), '')        AS pedido_venda,
           NULLIF(btrim(e.l->>'ordem_producao'), '')      AS ordem_producao,
           NULLIF(btrim(e.l->>'codigo_produto_omie'), '') AS codigo_produto_omie,
           NULLIF(btrim(e.l->>'codigo_produto'), '')      AS codigo_produto,
           NULLIF(btrim(e.l->>'etapa'), '')               AS etapa,
           CASE WHEN jsonb_typeof(e.l->'setor') = 'object' THEN NULLIF(btrim(e.l->'setor'->>'codigo'), '') END AS setor_codigo,
           CASE WHEN jsonb_typeof(e.l->'setor') = 'object' THEN NULLIF(btrim(e.l->'setor'->>'nome'), '')   END AS setor_nome,
           CASE WHEN jsonb_typeof(e.l->'setor') = 'object' THEN NULLIF(btrim(e.l->'setor'->>'tipo'), '')   END AS setor_tipo,
           NULLIF(btrim(e.l->>'status'), '')              AS status,
           NULLIF(btrim(e.l->>'quantidade_na_etapa'), '') AS qtd_txt,
           e.l->'atendido_pelo_estoque'                   AS atendido_j,
           NULLIF(btrim(e.l->>'ocorrido_em'), '')         AS ocorrido_txt,
           NULLIF(btrim(e.l->>'updated_at'), '')          AS updated_txt,
           NULLIF(btrim(e.l->>'deleted_at'), '')          AS deleted_txt
      FROM jsonb_array_elements(p_linhas) WITH ORDINALITY AS e(l, ord)
  ),
  validado AS (
    SELECT b.*,
           CASE WHEN jsonb_typeof(b.l) = 'object' AND b.updated_txt IS NOT NULL
                 AND pg_input_is_valid(b.updated_txt, 'timestamptz')
                THEN b.updated_txt END AS updated_ok,
           CASE
             WHEN jsonb_typeof(b.l) <> 'object'                         THEN 'linha não é objeto'
             WHEN b.id_txt IS NULL OR b.id_txt !~ v_uuid_re             THEN 'id_item_parcial ausente ou não é uuid'
             WHEN b.updated_txt IS NULL OR NOT pg_input_is_valid(b.updated_txt, 'timestamptz') THEN 'updated_at ausente ou inválido'
             WHEN b.emp_txt IS NOT NULL AND (b.emp_txt !~ v_uuid_re OR b.emp_txt::uuid <> p_codigo_empresa)
                                                                        THEN 'codigo_empresa diferente da unidade lida'
             WHEN b.pedido_venda IS NULL                                THEN 'pedido_venda ausente'
             WHEN length(b.pedido_venda) > 40                           THEN 'pedido_venda com mais de 40 caracteres'
             WHEN b.etapa IS NULL                                       THEN 'etapa ausente'
             WHEN length(b.etapa) > 60                                  THEN 'etapa com mais de 60 caracteres'
             WHEN b.status IS NULL                                      THEN 'status ausente'
             WHEN length(b.status) > 30                                 THEN 'status com mais de 30 caracteres'
             WHEN b.qtd_txt IS NULL OR NOT pg_input_is_valid(b.qtd_txt, 'numeric(15,4)') THEN 'quantidade_na_etapa ausente ou inválida'
             WHEN b.ocorrido_txt IS NOT NULL AND NOT pg_input_is_valid(b.ocorrido_txt, 'timestamptz') THEN 'ocorrido_em inválido'
             WHEN b.deleted_txt IS NOT NULL AND NOT pg_input_is_valid(b.deleted_txt, 'timestamptz')   THEN 'deleted_at inválido'
             WHEN b.atendido_j IS NOT NULL AND jsonb_typeof(b.atendido_j) NOT IN ('boolean', 'null')  THEN 'atendido_pelo_estoque não é booleano'
             WHEN length(b.ordem_producao) > 40 OR length(b.codigo_produto_omie) > 40 OR length(b.codigo_produto) > 100
               OR length(b.setor_codigo) > 60 OR length(b.setor_nome) > 200 OR length(b.setor_tipo) > 30
                                                                        THEN 'campo de texto maior que a coluna'
           END AS motivo
      FROM bruto b
  ),
  -- A mesma chave duas vezes na página (não deveria acontecer: o MES manda uma
  -- foto por parcial) fica com a de maior updated_at.
  novas AS (
    SELECT DISTINCT ON (x.id, x.etapa, x.ocorrido_em) x.*
      FROM (
        SELECT v.pos, v.id_txt::uuid AS id, v.pedido_venda, v.ordem_producao, v.codigo_produto_omie,
               v.codigo_produto, v.etapa, v.setor_codigo, v.setor_nome, v.setor_tipo, v.status,
               v.qtd_txt::numeric(15,4) AS quantidade,
               COALESCE((v.atendido_j #>> '{}')::boolean, false) AS atendido,
               COALESCE(v.ocorrido_txt, v.updated_txt)::timestamptz AS ocorrido_em,
               v.updated_txt::timestamptz AS updated_at,
               v.deleted_txt::timestamptz AS deleted_at
          FROM validado v
         WHERE v.motivo IS NULL
      ) x
     ORDER BY x.id, x.etapa, x.ocorrido_em, x.updated_at DESC, x.pos DESC
  ),
  gravadas AS (
    INSERT INTO core_vendas_faturamento.itens_pedido_status AS s
      (codigo_empresa, id_item_parcial, pedido_venda, ordem_producao, codigo_produto_omie, codigo_produto,
       etapa, setor_codigo, setor_nome, setor_tipo, status, quantidade_na_etapa, atendido_pelo_estoque,
       ocorrido_em, mes_updated_at, mes_deleted_at)
    SELECT p_codigo_empresa, n.id, n.pedido_venda, n.ordem_producao, n.codigo_produto_omie, n.codigo_produto,
           n.etapa, n.setor_codigo, n.setor_nome, n.setor_tipo, n.status, n.quantidade, n.atendido,
           n.ocorrido_em, n.updated_at, n.deleted_at
      FROM novas n
    -- A única mudança numa linha já gravada: a parcial foi cancelada (ou
    -- reaberta) no MES sem mudar etapa nem updated_at.
    ON CONFLICT ON CONSTRAINT uq_itens_pedido_status DO UPDATE
       SET mes_deleted_at = EXCLUDED.mes_deleted_at,
           mes_updated_at = GREATEST(s.mes_updated_at, EXCLUDED.mes_updated_at)
     WHERE s.mes_deleted_at IS DISTINCT FROM EXCLUDED.mes_deleted_at
    RETURNING (s.xmax = 0) AS inserida
  ),
  -- Cursor: maior updated_at da página (também das linhas ignoradas que tinham
  -- updated_at válido, senão o job pararia nelas para sempre), nunca para trás.
  -- Página vazia: só marca a leitura (atualizado_em).
  cur AS (
    INSERT INTO core_vendas_faturamento.itens_pedido_status_cursor AS c (codigo_empresa, alterado_desde, atualizado_em)
    SELECT p_codigo_empresa,
           GREATEST(p_alterado_desde, (SELECT max(v.updated_ok::timestamptz) FROM validado v)),
           now()
    ON CONFLICT (codigo_empresa) DO UPDATE
       SET alterado_desde = GREATEST(c.alterado_desde, EXCLUDED.alterado_desde),
           atualizado_em  = now()
    RETURNING c.alterado_desde
  )
  SELECT v_recebidas,
         (SELECT count(*) FILTER (WHERE g.inserida) FROM gravadas g)::int,
         (SELECT count(*) FILTER (WHERE NOT g.inserida) FROM gravadas g)::int,
         (SELECT COALESCE(jsonb_agg(jsonb_build_object('posicao', v.pos, 'id_item_parcial', v.id_txt, 'motivo', v.motivo)
                                    ORDER BY v.pos), '[]'::jsonb)
            FROM validado v WHERE v.motivo IS NOT NULL),
         (SELECT k.alterado_desde FROM cur k);
END
$_$;


--
-- TOC entry 7304 (class 0 OID 0)
-- Dependencies: 756
-- Name: FUNCTION fn_itens_pedido_status_gravar(p_codigo_empresa uuid, p_alterado_desde timestamp with time zone, p_linhas jsonb); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_itens_pedido_status_gravar(p_codigo_empresa uuid, p_alterado_desde timestamp with time zone, p_linhas jsonb) IS 'Contrato de API 005 / 006: grava UMA página de GET /itens/status do MES (array JSON, como o MES devolve) para a unidade, numa só transação. Linha inválida (id não uuid, outra unidade, sem pedido_venda/etapa/status/quantidade, data inválida, texto maior que a coluna) é ignorada e devolvida em "ignoradas". INSERT por (codigo_empresa, id_item_parcial, etapa, ocorrido_em): foto repetida não grava; numa linha existente só muda mes_deleted_at (cancelada/reaberta). Avança o cursor da unidade para o maior updated_at da página (nunca volta) e marca a leitura (atualizado_em = now()), também com página vazia. Devolve recebidas, inseridas, atualizadas (mes_deleted_at), ignoradas e novo_cursor.';


--
-- TOC entry 1019 (class 1255 OID 17305)
-- Name: fn_limpa_produto_vendas_orfaos(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_limpa_produto_vendas_orfaos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM core_vendas_faturamento.produto_vendas pv
    WHERE EXISTS (
        SELECT 1
        FROM deleted_rows dr
        WHERE dr.codigo_pedido_omie = pv.codigo_pedido_omie
          AND dr.codigo_empresa = pv.codigo_empresa
    );
    RETURN NULL;
END;
$$;


--
-- TOC entry 798 (class 1255 OID 22572)
-- Name: fn_movimento_cliente_mes(integer, integer, uuid, text, uuid, text[]); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_movimento_cliente_mes(p_mes integer, p_ano integer, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_cliente text DEFAULT NULL::text, p_id_grupo uuid DEFAULT NULL::uuid, p_vendedores text[] DEFAULT NULL::text[]) RETURNS TABLE(tipo text, numero character varying, data date, codigo_empresa uuid, codigo_cliente character varying, cliente character varying, codigo_vendedor character varying, vendedor character varying, valor numeric, situacao text, codigo_omie bigint, numero_pedido character varying, conta_no_total boolean)
    LANGUAGE plpgsql STABLE
    AS $$
#variable_conflict use_column
DECLARE
  v_ini date;
  v_fim date;
  v_cli text := NULLIF(btrim(p_codigo_cliente), '');
BEGIN
  IF p_mes IS NULL OR p_mes NOT BETWEEN 1 AND 12 THEN
    RAISE EXCEPTION 'p_mes deve ser de 1 a 12 (recebido %).', p_mes USING ERRCODE = '22023';
  END IF;
  IF p_ano IS NULL OR p_ano NOT BETWEEN 2000 AND 2100 THEN
    RAISE EXCEPTION 'p_ano deve ser de 2000 a 2100 (recebido %).', p_ano USING ERRCODE = '22023';
  END IF;
  IF (v_cli IS NULL) = (p_id_grupo IS NULL) THEN
    RAISE EXCEPTION 'Informe o cliente (p_codigo_cliente + p_codigo_empresa) OU o grupo (p_id_grupo), um dos dois.'
      USING ERRCODE = '22023';
  END IF;
  IF v_cli IS NOT NULL AND p_codigo_empresa IS NULL THEN
    RAISE EXCEPTION 'p_codigo_cliente exige p_codigo_empresa (o código do cliente só é único dentro da unidade).'
      USING ERRCODE = '22023';
  END IF;
  v_ini := make_date(p_ano, p_mes, 1);
  v_fim := (v_ini + interval '1 month')::date;

  RETURN QUERY
  WITH alvo AS (
    SELECT p_codigo_empresa AS codigo_empresa, v_cli::varchar AS codigo_cliente
     WHERE v_cli IS NOT NULL
    UNION
    SELECT m.codigo_empresa, m.codigo_cliente
      FROM core_vendas_faturamento.grupos_clientes_membros m
      JOIN core_vendas_faturamento.grupos_clientes g ON g.id = m.id_grupo AND g.ativo
     WHERE p_id_grupo IS NOT NULL AND m.id_grupo = p_id_grupo
       AND (p_codigo_empresa IS NULL OR m.codigo_empresa = p_codigo_empresa)
  ),
  pv_linhas AS (
    SELECT p.codigo_empresa, p.numero_pedido, COALESCE(p.sequencial, 0) AS seq, p.codigo_pedido_omie,
           p.codigo_cliente, p.codigo_vendedor_omie, p.etapa, p.situacao,
           core_vendas_faturamento.fn_data_planilha(p.data_inclusao::text) AS data_inclusao,
           COALESCE(p.valor_total_pedido, 0) AS valor, p.cancelado, p.denegado
      FROM core_vendas_faturamento.pedidos_vendas p
      JOIN alvo a ON a.codigo_empresa = p.codigo_empresa AND a.codigo_cliente = p.codigo_cliente
     WHERE p.deleted_at IS NULL
       AND (p.etapa IS NULL OR p.etapa <> 0)
       AND NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.blacklist_pedidos bp
                        WHERE bp.codigo_empresa = p.codigo_empresa
                          AND bp.numero_pedido = p.numero_pedido::text
                          AND bp.deleted_at IS NULL)
  ),
  filhos AS (
    SELECT l.codigo_empresa, l.numero_pedido, sum(l.valor) AS valor_filhos
      FROM pv_linhas l WHERE l.seq > 0
     GROUP BY l.codigo_empresa, l.numero_pedido
  ),
  movimento AS (
    SELECT 'pedido'::text AS tipo, m.numero_pedido::varchar AS numero, m.data_inclusao AS data,
           m.codigo_empresa, m.codigo_cliente::varchar AS codigo_cliente,
           m.codigo_vendedor_omie::varchar AS codigo_vendedor,
           m.valor + COALESCE(f.valor_filhos, 0) AS valor,
           COALESCE(ef.descricao, ef.descricao_padrao, m.situacao)::text AS situacao,
           m.codigo_pedido_omie AS codigo_omie, m.numero_pedido::varchar AS numero_pedido,
           true AS conta_no_total
      FROM pv_linhas m
      LEFT JOIN filhos f ON f.codigo_empresa = m.codigo_empresa AND f.numero_pedido = m.numero_pedido
      LEFT JOIN core.etapas_faturamento ef
        ON ef.codigo_empresa = m.codigo_empresa AND ef.codigo_operacao::text = '11'
       AND ef.codigo_etapa::numeric = m.etapa AND ef.deleted_at IS NULL
     WHERE m.seq = 0 AND NOT m.cancelado AND NOT m.denegado
       AND m.data_inclusao >= v_ini AND m.data_inclusao < v_fim
    UNION ALL
    SELECT 'nf'::text, n.numero_nf::varchar,
           core_vendas_faturamento.fn_data_planilha(n.data_emissao::text),
           n.codigo_empresa, n.codigo_cliente::varchar, n.codigo_vendedor_omie::varchar,
           COALESCE(n.valor_nf, 0),
           CASE WHEN pv.denegado THEN 'Denegado' WHEN pv.cancelado THEN 'Cancelado'
                WHEN pv.devolvido THEN 'Devolvido' WHEN pv.devolucao_parcial THEN 'Dev. Parcial'
                ELSE 'Autorizado' END,
           n.codigo_nf_omie, pv.numero_pedido::varchar,
           NOT COALESCE(pv.cancelado, false) AND NOT COALESCE(pv.denegado, false)
      FROM core_vendas_faturamento.notas_fiscais n
      JOIN alvo a ON a.codigo_empresa = n.codigo_empresa AND a.codigo_cliente = n.codigo_cliente
      LEFT JOIN core_vendas_faturamento.pedidos_vendas pv
        ON pv.codigo_empresa = n.codigo_empresa AND pv.codigo_pedido_omie = n.codigo_pedido_omie
     WHERE n.deleted_at IS NULL
       AND core_vendas_faturamento.fn_data_planilha(n.data_emissao::text) >= v_ini
       AND core_vendas_faturamento.fn_data_planilha(n.data_emissao::text) < v_fim
  )
  SELECT mv.tipo, mv.numero, mv.data, mv.codigo_empresa, mv.codigo_cliente,
         COALESCE(NULLIF(pa.nome_fantasia, ''), pa.razao_social)::varchar,
         mv.codigo_vendedor,
         COALESCE(ve.nome_exibicao, ve.nome)::varchar,
         mv.valor::numeric(15,2), mv.situacao, mv.codigo_omie, mv.numero_pedido, mv.conta_no_total
    FROM movimento mv
    LEFT JOIN core.parceiros pa
      ON pa.codigo_empresa = mv.codigo_empresa AND pa.codigo_parceiro_omie = mv.codigo_cliente
    LEFT JOIN core_vendas_faturamento.vendedores ve
      ON ve.codigo_empresa = mv.codigo_empresa AND ve.codigo_vendedor_omie = mv.codigo_vendedor
     AND ve.deleted_at IS NULL
   WHERE core_vendas_faturamento.fn_vendedor_na_lista(mv.codigo_empresa, mv.codigo_vendedor, p_vendedores)
   ORDER BY mv.data DESC NULLS LAST, mv.tipo DESC, mv.numero DESC, mv.codigo_empresa;
END $$;


