CREATE FUNCTION core_vendas_faturamento.fn_no_vinculo(p_codigo_empresa uuid, p_cod_vendedor text, p_vinc_empresa uuid[], p_vinc_vendedor text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_vinc_vendedor IS NULL
      OR EXISTS (SELECT 1 FROM unnest(p_vinc_empresa, p_vinc_vendedor) AS v(emp, cod)
                  WHERE v.cod = p_cod_vendedor AND (v.emp IS NULL OR v.emp = p_codigo_empresa))
$$;


