--
-- TOC entry 671 (class 1255 OID 20521)
-- Name: fn_nome_cliente(uuid, text); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_nome_cliente(p_codigo_empresa uuid, p_codigo_cliente text) RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT COALESCE(NULLIF(btrim(par.nome_fantasia), ''), NULLIF(btrim(par.razao_social), ''))
    FROM core.parceiros par
   WHERE par.codigo_empresa = p_codigo_empresa
     AND par.codigo_parceiro_omie::text = p_codigo_cliente
     AND par.deleted_at IS NULL
   LIMIT 1
$$;


