CREATE FUNCTION core_vendas_faturamento.fn_nome_vendedor(p_codigo_empresa uuid, p_codigo_vendedor text) RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT NULLIF(btrim(v.nome), '')
    FROM core_vendas_faturamento.vendedores v
   WHERE v.codigo_empresa = p_codigo_empresa
     AND v.codigo_vendedor_omie::text = p_codigo_vendedor
     AND v.deleted_at IS NULL
   LIMIT 1
$$;


