-- Name: fn_nota_motivo_fora(timestamp with time zone, text, numeric, text, boolean); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_nota_motivo_fora(p_deleted_at timestamp with time zone, p_tipo_nf text, p_total_ajustado numeric, p_pedido text, p_manual_nf boolean) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
           WHEN p_deleted_at IS NOT NULL THEN 'excluida'
           WHEN p_tipo_nf IS DISTINCT FROM '1' THEN 'nao_e_nota_de_saida'
           WHEN p_pedido IS NULL AND NOT COALESCE(p_manual_nf, false) THEN 'sem_pedido_venda'
           WHEN COALESCE(p_total_ajustado, 0) <= 0 THEN 'valor_zerado'
           ELSE NULL
         END
$$;


