CREATE FUNCTION core_vendas_faturamento.fn_nota_motivo_fora_texto(p_motivo text, p_oppedido text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_motivo
           WHEN 'sem_pedido_venda' THEN
             'Nota de outra operação' || COALESCE(' (operação ' || p_oppedido || ' no Omie)', '')
             || ', sem pedido de venda em nenhum mês. Aparece na lista, mas fica fora dos números e não tem página de pedido.'
           WHEN 'nao_e_nota_de_saida' THEN 'Não é nota de saída: fica fora dos números do faturamento.'
           WHEN 'valor_zerado' THEN 'Valor ajustado zerado: fica fora dos números do faturamento.'
           WHEN 'excluida' THEN 'Nota excluída.'
         END
$$;


