CREATE FUNCTION core_vendas_faturamento.fn_notas_fiscais_manuais_historico_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- pg_trigger_depth() > 1: veio em cascata da FK (unidade/nota que mudou de
  -- chave ou foi expurgada), não de um comando direto na tabela.
  IF current_setting('avhub.nf_manual_expurgo', true) = 'on' OR pg_trigger_depth() > 1 THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  RAISE EXCEPTION 'O histórico da nota fiscal manual não pode ser alterado nem apagado.'
    USING ERRCODE = '23514';
END $$;


