-- TOC entry 559 (class 1255 OID 20759)
-- Name: fn_notas_fiscais_manual_historico(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_notas_fiscais_manual_historico() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  c_campos CONSTANT text[] := ARRAY[
    'numero_nf', 'tipo_nf', 'chave_nf', 'data_emissao', 'hora_emissao',
    'codigo_cliente', 'codigo_vendedor_omie', 'codigo_comprador_omie', 'codigo_categoria',
    'codigo_pedido_omie', 'oppedido',
    'valor_mercadorias', 'valor_nf', 'valor_ipi', 'descontos', 'averbado'];
  v_new     jsonb := to_jsonb(NEW);
  v_old     jsonb;
  v_alt     jsonb := '{}'::jsonb;
  v_campo   text;
  v_op      text;
  v_usuario uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_op := 'cadastro';
    v_usuario := NEW.created_by;
    FOREACH v_campo IN ARRAY c_campos LOOP
      IF COALESCE(v_new -> v_campo, 'null'::jsonb) <> 'null'::jsonb THEN
        v_alt := v_alt || jsonb_build_object(v_campo, jsonb_build_object('de', NULL, 'para', v_new -> v_campo));
      END IF;
    END LOOP;
  ELSE
    v_old := to_jsonb(OLD);
    FOREACH v_campo IN ARRAY c_campos LOOP
      IF (v_old -> v_campo) IS DISTINCT FROM (v_new -> v_campo) THEN
        v_alt := v_alt || jsonb_build_object(v_campo, jsonb_build_object('de', v_old -> v_campo, 'para', v_new -> v_campo));
      END IF;
    END LOOP;
    IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
      v_op := 'exclusao';
      v_usuario := NEW.deleted_by;
    ELSIF OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL THEN
      v_op := 'restauracao';
      v_usuario := NEW.updated_by;
    ELSIF v_alt = '{}'::jsonb THEN
      RETURN NULL;   -- só autoria/updated_at mudou: nada a registrar
    ELSE
      v_op := 'alteracao';
      v_usuario := NEW.updated_by;
    END IF;
  END IF;

  INSERT INTO core_vendas_faturamento.notas_fiscais_manuais_historico
         (codigo_empresa, codigo_nf_omie, numero_nf, operacao, alteracoes, alterado_por)
  VALUES (NEW.codigo_empresa, NEW.codigo_nf_omie, NEW.numero_nf, v_op, v_alt,
          CASE WHEN EXISTS (SELECT 1 FROM auth.usuarios WHERE id = v_usuario) THEN v_usuario END);
  RETURN NULL;
END $$;


