--
-- TOC entry 767 (class 1255 OID 20713)
-- Name: fn_notas_fiscais_manual_validar(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_notas_fiscais_manual_validar() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  -- INSERT, ou linha que acabou de virar manual: confere tudo.
  v_tudo boolean := TG_OP = 'INSERT' OR NOT COALESCE(OLD.manual, false);
  v_hoje date    := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_data date;
  v_numero_existente text;
BEGIN
  IF NOT NEW.manual THEN
    RETURN NEW;
  END IF;

  IF v_tudo OR NEW.numero_nf IS DISTINCT FROM OLD.numero_nf THEN
    IF NULLIF(btrim(NEW.numero_nf), '') IS NULL THEN
      RAISE EXCEPTION 'NF manual: numero_nf é obrigatório.' USING ERRCODE = '23514';
    END IF;
    -- O Omie grava com zeros à esquerda ("00051705"); quem digita à mão
    -- costuma mandar "51705". O UNIQUE (codigo_empresa, numero_nf) não pega
    -- esse caso e a mesma nota contaria duas vezes no faturamento.
    -- A trava serializa dois cadastros manuais simultâneos do mesmo número
    -- ("777" e "0777"): o segundo espera o primeiro terminar e então o enxerga.
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'notas_fiscais_manual:' || NEW.codigo_empresa::text || ':' || ltrim(btrim(NEW.numero_nf), '0'), 0));
    SELECT n.numero_nf INTO v_numero_existente
      FROM core_vendas_faturamento.notas_fiscais n
     WHERE n.codigo_empresa = NEW.codigo_empresa
       AND n.deleted_at IS NULL
       AND n.codigo_nf_omie IS DISTINCT FROM NEW.codigo_nf_omie
       AND ltrim(btrim(n.numero_nf), '0') = ltrim(btrim(NEW.numero_nf), '0')
     LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'NF manual: já existe a NF % nesta unidade.', v_numero_existente
        USING ERRCODE = '23505';
    END IF;
  END IF;

  IF v_tudo OR NEW.tipo_nf IS DISTINCT FROM OLD.tipo_nf THEN
    IF NEW.tipo_nf IS DISTINCT FROM '1' THEN
      RAISE EXCEPTION 'NF manual precisa ser de saída (tipo_nf = 1): com outro tipo ela não entra no faturamento.'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_tudo OR NEW.data_emissao IS DISTINCT FROM OLD.data_emissao THEN
    IF NEW.data_emissao IS NULL OR NEW.data_emissao !~ '^\d{4}-\d{2}-\d{2}$' THEN
      RAISE EXCEPTION 'NF manual: data_emissao é obrigatória, no formato AAAA-MM-DD (recebido: %).',
        COALESCE(NEW.data_emissao, 'nulo') USING ERRCODE = '23514';
    END IF;
    BEGIN
      v_data := NEW.data_emissao::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'NF manual: data_emissao % não é uma data válida.', NEW.data_emissao
        USING ERRCODE = '23514';
    END;
    IF v_data > v_hoje THEN
      RAISE EXCEPTION 'NF manual: data_emissao % está no futuro.', NEW.data_emissao
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_tudo OR NEW.hora_emissao IS DISTINCT FROM OLD.hora_emissao THEN
    IF NEW.hora_emissao IS NULL OR NEW.hora_emissao !~ '^([01]\d|2[0-3]):[0-5]\d:[0-5]\d$' THEN
      RAISE EXCEPTION 'NF manual: hora_emissao é obrigatória, no formato HH:MM:SS (recebido: %).',
        COALESCE(NEW.hora_emissao, 'nulo') USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_tudo
     OR NEW.valor_nf          IS DISTINCT FROM OLD.valor_nf
     OR NEW.descontos         IS DISTINCT FROM OLD.descontos
     OR NEW.valor_ipi         IS DISTINCT FROM OLD.valor_ipi
     OR NEW.valor_mercadorias IS DISTINCT FROM OLD.valor_mercadorias THEN
    IF NEW.valor_nf IS NULL OR NEW.valor_nf <= 0 THEN
      RAISE EXCEPTION 'NF manual: valor_nf é obrigatório e maior que zero.' USING ERRCODE = '23514';
    END IF;
    IF COALESCE(NEW.descontos, 0) < 0 OR COALESCE(NEW.valor_ipi, 0) < 0
       OR COALESCE(NEW.valor_mercadorias, 0) < 0 THEN
      RAISE EXCEPTION 'NF manual: descontos, valor_ipi e valor_mercadorias não podem ser negativos.'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.valor_nf - COALESCE(NEW.descontos, 0) <= 0 THEN
      RAISE EXCEPTION 'NF manual: descontos (%) consomem todo o valor_nf (%): a nota não entraria no faturamento.',
        NEW.descontos, NEW.valor_nf USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_tudo OR NEW.codigo_cliente IS DISTINCT FROM OLD.codigo_cliente
     OR NEW.codigo_empresa IS DISTINCT FROM OLD.codigo_empresa THEN
    IF NULLIF(btrim(NEW.codigo_cliente), '') IS NULL THEN
      RAISE EXCEPTION 'NF manual: codigo_cliente é obrigatório.' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM core.parceiros p
                    WHERE p.codigo_empresa = NEW.codigo_empresa
                      AND p.codigo_parceiro_omie = NEW.codigo_cliente
                      AND p.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'NF manual: cliente % não está cadastrado nesta unidade.', NEW.codigo_cliente
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_tudo OR NEW.codigo_vendedor_omie IS DISTINCT FROM OLD.codigo_vendedor_omie
     OR NEW.codigo_empresa IS DISTINCT FROM OLD.codigo_empresa THEN
    IF NULLIF(btrim(NEW.codigo_vendedor_omie), '') IS NULL THEN
      RAISE EXCEPTION 'NF manual: codigo_vendedor_omie é obrigatório.' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.vendedores v
                    WHERE v.codigo_empresa = NEW.codigo_empresa
                      AND v.codigo_vendedor_omie = NEW.codigo_vendedor_omie
                      AND v.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'NF manual: vendedor % não está cadastrado nesta unidade.', NEW.codigo_vendedor_omie
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.codigo_pedido_omie IS NOT NULL
     AND (v_tudo OR NEW.codigo_pedido_omie IS DISTINCT FROM OLD.codigo_pedido_omie
                 OR NEW.codigo_empresa IS DISTINCT FROM OLD.codigo_empresa) THEN
    IF NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.pedidos_vendas pv
                    WHERE pv.codigo_empresa = NEW.codigo_empresa
                      AND pv.codigo_pedido_omie = NEW.codigo_pedido_omie
                      AND pv.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'NF manual: pedido % não existe nesta unidade.', NEW.codigo_pedido_omie
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.chave_nf IS NOT NULL
     AND (v_tudo OR NEW.chave_nf IS DISTINCT FROM OLD.chave_nf)
     AND NEW.chave_nf !~ '^\d{44}$' THEN
    RAISE EXCEPTION 'NF manual: chave_nf precisa ter 44 dígitos.' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END $_$;


