-- Name: fn_oc_acompanhamento_exigir_aprovada(uuid); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_acompanhamento_exigir_aprovada(p_id_oc uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status text;
  v_numero text;
BEGIN
  SELECT oc.status, oc.numero_pedido INTO v_status, v_numero
    FROM core_vendas_faturamento.ordens_compra oc
   WHERE oc.id = p_id_oc AND oc.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ordem de compra % não encontrada (ou apagada)', p_id_oc
      USING ERRCODE = '23503';
  END IF;
  IF v_status <> 'aprovado' THEN
    RAISE EXCEPTION 'Só OC aprovada tem acompanhamento do CCP (OC % está em %)', v_numero, v_status
      USING ERRCODE = '23514';
  END IF;
END $$;


