--
-- TOC entry 979 (class 1255 OID 21143)
-- Name: fn_oc_acompanhamento_validar(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_acompanhamento_validar() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status_ant text := CASE WHEN TG_OP = 'UPDATE' THEN OLD.confirmacao_status ELSE 'pendente' END;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.id_ordem_compra IS DISTINCT FROM OLD.id_ordem_compra THEN
    RAISE EXCEPTION 'O acompanhamento não muda de OC' USING ERRCODE = '23514';
  END IF;

  PERFORM core_vendas_faturamento.fn_oc_acompanhamento_exigir_aprovada(NEW.id_ordem_compra);

  IF NEW.confirmacao_status IS DISTINCT FROM v_status_ant THEN
    IF NEW.confirmacao_status = 'pendente' THEN
      RAISE EXCEPTION 'A confirmação do fornecedor não volta a pendente (atual: %)', v_status_ant
        USING ERRCODE = '23514';
    END IF;
    IF NEW.confirmacao_status = 'contraproposta'
       AND NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.ordens_compra_ocorrencias o
                        WHERE o.id_ordem_compra = NEW.id_ordem_compra AND o.status = 'aberta') THEN
      RAISE EXCEPTION 'Contraproposta exige uma ocorrência aberta na OC: registre a ocorrência (o que o fornecedor propôs) antes ou junto'
        USING ERRCODE = '23514';
    END IF;
    NEW.confirmado_em  := now();
    NEW.confirmado_por := NEW.updated_by;
  ELSIF TG_OP = 'UPDATE' THEN
    -- carimbos só o banco escreve
    NEW.confirmado_em  := OLD.confirmado_em;
    NEW.confirmado_por := OLD.confirmado_por;
  ELSE
    NEW.confirmado_em  := NULL;
    NEW.confirmado_por := NULL;
  END IF;

  IF NEW.despachado_em IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.despachado_em IS DISTINCT FROM OLD.despachado_em)
     AND NEW.despachado_em > core_vendas_faturamento.fn_hoje_sp() THEN
    RAISE EXCEPTION 'despachado_em (%) não pode ser futuro (hoje em São Paulo: %)',
      NEW.despachado_em, core_vendas_faturamento.fn_hoje_sp() USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    NEW.created_by := COALESCE(NEW.created_by, NEW.updated_by);
  ELSE
    NEW.created_at := OLD.created_at;
    NEW.created_by := OLD.created_by;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;


--
-- TOC entry 7319 (class 0 OID 0)
