--
-- TOC entry 509 (class 1255 OID 21341)
-- Name: fn_oc_comprador_do_omie(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_comprador_do_omie() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_oc        record;
  v_comprador uuid;
  v_marca     text;
BEGIN
  IF NEW.codigo_pedido_integracao IS NULL OR NEW.deleted_at IS NOT NULL THEN
    RETURN NULL;
  END IF;

  SELECT oc.id, oc.id_comprador
    INTO v_oc
    FROM core_vendas_faturamento.ordens_compra oc
   WHERE oc.codigo_empresa = NEW.codigo_empresa
     AND oc.numero_pedido  = NEW.codigo_pedido_integracao
     AND oc.deleted_at IS NULL
     FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NULL;  -- pedido feito direto no Omie: não é OC do av-hub
  END IF;

  -- 0/NULL no Omie = sem comprador.
  IF COALESCE(NEW.codigo_comprador, 0) <> 0 THEN
    SELECT c.id INTO v_comprador
      FROM core_vendas_faturamento.compradores c
     WHERE c.codigo_empresa = NEW.codigo_empresa
       AND c.codigo_comprador_omie = NEW.codigo_comprador::text
     ORDER BY (c.deleted_at IS NULL) DESC, c.deleted_at DESC
     LIMIT 1;
    IF NOT FOUND THEN
      -- Cadastro de compradores atrasado: não apaga o comprador da OC.
      RAISE NOTICE 'Contrato 36: comprador % do Omie não está no cadastro da unidade; OC % não foi alterada',
        NEW.codigo_comprador, NEW.codigo_pedido_integracao;
      RETURN NULL;
    END IF;
  END IF;

  IF v_comprador IS NOT DISTINCT FROM v_oc.id_comprador THEN
    RETURN NULL;  -- mesmo comprador: nada muda, nada vai ao histórico
  END IF;

  -- Só a coluna id_comprador. A marca libera a trava do A3a e volta ao valor
  -- anterior logo depois do UPDATE.
  v_marca := current_setting('avhub.oc_comprador_origem', true);
  PERFORM set_config('avhub.oc_comprador_origem', 'omie', true);
  UPDATE core_vendas_faturamento.ordens_compra
     SET id_comprador = v_comprador
   WHERE id = v_oc.id;
  PERFORM set_config('avhub.oc_comprador_origem', COALESCE(v_marca, ''), true);

  INSERT INTO core_vendas_faturamento.ordens_compra_comprador_historico
    (id_ordem_compra, origem, id_comprador_anterior, id_comprador_novo, numero_pedido_omie)
  VALUES (v_oc.id, 'omie', v_oc.id_comprador, v_comprador, NEW.numero_pedido);
  RETURN NULL;
END $$;


--
-- TOC entry 7321 (class 0 OID 0)
-- Dependencies: 509
-- Name: FUNCTION fn_oc_comprador_do_omie(); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_oc_comprador_do_omie() IS '[Contrato 36, P4] AFTER INSERT/UPDATE no espelho pedidos_compras: se o pedido é de uma OC do av-hub (codigo_pedido_integracao = ordens_compra.numero_pedido, mesma unidade, OC não apagada) e o comprador do Omie (codigo_comprador -> compradores.codigo_comprador_omie da unidade; 0/NULL = sem comprador) é outro, troca ordens_compra.id_comprador e grava a linha origem = omie no histórico. Mesmo comprador: nada. Código que não está no cadastro da unidade: a OC não é mexida (NOTICE). SECURITY DEFINER: a pipeline grava o espelho sem precisar de UPDATE em ordens_compra.';


