CREATE FUNCTION core_vendas_faturamento.fn_oc_contatos_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF core_vendas_faturamento.fn_oc_acompanhamento_delete_por_cascade(OLD.id_ordem_compra) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'Contato com o fornecedor é histórico: não se apaga (registre um novo contato para corrigir)'
      USING ERRCODE = '23514';
  END IF;
