--
-- TOC entry 622 (class 1255 OID 21176)
-- Name: fn_oc_contatos_inserir(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_contatos_inserir() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_atual date;
BEGIN
  PERFORM core_vendas_faturamento.fn_oc_acompanhamento_exigir_aprovada(NEW.id_ordem_compra);
  NEW.previsao_anterior := NULL;

  IF NEW.previsao_nova IS NOT NULL THEN
    IF NEW.previsao_nova < core_vendas_faturamento.fn_hoje_sp() THEN
      RAISE EXCEPTION 'previsao_nova (%) não pode ser anterior a hoje (São Paulo: %)',
        NEW.previsao_nova, core_vendas_faturamento.fn_hoje_sp() USING ERRCODE = '23514';
    END IF;

    -- Trava a OC: dois contatos ao mesmo tempo gravam previsao_anterior certa.
    SELECT oc.data_previsao_chegada INTO v_atual
      FROM core_vendas_faturamento.ordens_compra oc
     WHERE oc.id = NEW.id_ordem_compra
       FOR UPDATE;
    NEW.previsao_anterior := v_atual;

    IF NEW.previsao_nova IS DISTINCT FROM v_atual THEN
      -- A5: a trigger de parcelas lê esta chave e não regera (só nesta UPDATE).
      PERFORM set_config('avhub.oc_previsao_pelo_acompanhamento', 'on', true);
      UPDATE core_vendas_faturamento.ordens_compra
         SET data_previsao_chegada = NEW.previsao_nova,
             updated_by = COALESCE(NEW.created_by, updated_by)
       WHERE id = NEW.id_ordem_compra;
      PERFORM set_config('avhub.oc_previsao_pelo_acompanhamento', 'off', true);
    END IF;
  END IF;
  -- clock_timestamp (e não now()): com a OC travada, a ordem dos contatos é a
  -- ordem em que foram aplicados, mesmo com transações que começaram juntas.
  NEW.created_at := clock_timestamp();
  RETURN NEW;
END $$;


