--
-- TOC entry 1008 (class 1255 OID 20600)
-- Name: fn_oc_itens_requisicao(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_itens_requisicao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_req record;
  v_oc  uuid;
BEGIN
  -- Libera a requisição anterior (DELETE, ou UPDATE que trocou/tirou).
  IF TG_OP IN ('DELETE', 'UPDATE') AND OLD.id_requisicao IS NOT NULL
     AND (TG_OP = 'DELETE' OR OLD.id_requisicao IS DISTINCT FROM NEW.id_requisicao) THEN
    UPDATE core_vendas_faturamento.requisicoes_compra r
       SET status = 'aberta', id_ordem_compra = NULL
     WHERE r.id = OLD.id_requisicao
       AND r.id_ordem_compra = OLD.id_ordem_compra
       AND NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.ordens_compra o
                        WHERE o.id = OLD.id_ordem_compra AND o.id_requisicao = OLD.id_requisicao)
       AND NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.ordens_compra_itens i
                        WHERE i.id_ordem_compra = OLD.id_ordem_compra
                          AND i.id_requisicao = OLD.id_requisicao
                          AND i.id <> OLD.id);
  END IF;

  IF TG_OP = 'DELETE' OR NEW.id_requisicao IS NULL
     OR (TG_OP = 'UPDATE' AND NEW.id_requisicao IS NOT DISTINCT FROM OLD.id_requisicao) THEN
    RETURN NULL;
  END IF;

  SELECT r.status, r.numero_requisicao, r.codigo_empresa, r.id_ordem_compra, u.id_unidade_compra
    INTO v_req
    FROM core_vendas_faturamento.requisicoes_compra r
    JOIN core.unidades u ON u.id = r.codigo_empresa
   WHERE r.id = NEW.id_requisicao AND r.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'A requisição % não existe', NEW.id_requisicao USING ERRCODE = '23514';
  END IF;

  SELECT o.codigo_empresa INTO v_oc
    FROM core_vendas_faturamento.ordens_compra o WHERE o.id = NEW.id_ordem_compra;

  IF v_req.codigo_empresa <> v_oc AND v_req.id_unidade_compra IS DISTINCT FROM v_oc THEN
    RAISE EXCEPTION 'A requisição % é de outra unidade', v_req.numero_requisicao USING ERRCODE = '23514';
  END IF;

  IF v_req.status = 'atendida' AND v_req.id_ordem_compra = NEW.id_ordem_compra THEN
    RETURN NULL;  -- já atendida por esta OC (requisição do cabeçalho)
  END IF;
  IF v_req.status NOT IN ('aberta', 'em_cotacao') THEN
    RAISE EXCEPTION 'A requisição % está %, não pode entrar numa OC', v_req.numero_requisicao, v_req.status
      USING ERRCODE = '23514';
  END IF;

  UPDATE core_vendas_faturamento.requisicoes_compra
     SET status = 'atendida', id_ordem_compra = NEW.id_ordem_compra
   WHERE id = NEW.id_requisicao;
  RETURN NULL;
END $$;


