-- Name: fn_oc_ocorrencia_decisor(uuid, uuid); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_ocorrencia_decisor(p_usuario uuid, p_id_oc uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  WITH u AS (
    SELECT us.id, us.id_funcionario
      FROM auth.usuarios us
     WHERE us.id = p_usuario AND us.ativo AND us.deleted_at IS NULL
  )
  SELECT CASE
    WHEN EXISTS (
      SELECT 1
        FROM u
        JOIN core_vendas_faturamento.ordens_compra oc ON oc.id = p_id_oc
        LEFT JOIN core_vendas_faturamento.compradores c ON c.id = oc.id_comprador
       WHERE oc.codigo_comprador = u.id
          OR (u.id_funcionario IS NOT NULL AND c.id_funcionario = u.id_funcionario))
      THEN 'comprador'
    WHEN EXISTS (
      SELECT 1
        FROM u
        JOIN auth.usuarios_perfis up ON up.id_usuario = u.id
        JOIN auth.perfis p ON p.id = up.id_perfil AND p.deleted_at IS NULL
        LEFT JOIN auth.permissoes pm ON pm.id_perfil = p.id AND pm.deleted_at IS NULL AND pm.pode_aprovar
        LEFT JOIN auth.telas t ON t.id = pm.id_tela AND t.slug = 'compras'
                              AND t.deleted_at IS NULL AND t.ativo
       WHERE p.nome = 'Admin (Dev)' OR t.id IS NOT NULL)
      THEN 'admin'
  END
$$;


