--
-- TOC entry 718 (class 1255 OID 21219)
-- Name: fn_oc_ocorrencias_validar(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_ocorrencias_validar() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF core_vendas_faturamento.fn_oc_acompanhamento_delete_por_cascade(OLD.id_ordem_compra) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'Ocorrência do acompanhamento é histórico: não se apaga'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'INSERT' THEN
    PERFORM core_vendas_faturamento.fn_oc_acompanhamento_exigir_aprovada(NEW.id_ordem_compra);
    IF NEW.status <> 'aberta' THEN
      RAISE EXCEPTION 'Ocorrência nasce aberta (a decisão é do comprador da OC)' USING ERRCODE = '23514';
    END IF;
    NEW.decidido_por := NULL;
    NEW.decidido_em := NULL;
    NEW.decisao_observacao := NULL;
    NEW.created_at := clock_timestamp();
    RETURN NEW;
  END IF;

  -- UPDATE: só a decisão, uma vez.
  IF OLD.status <> 'aberta' THEN
    RAISE EXCEPTION 'Só ocorrência aberta pode ser decidida (esta já está %)', OLD.status
      USING ERRCODE = '23514';
  END IF;
  IF NEW.id_ordem_compra IS DISTINCT FROM OLD.id_ordem_compra
     OR NEW.tipo IS DISTINCT FROM OLD.tipo
     OR NEW.descricao IS DISTINCT FROM OLD.descricao
     OR NEW.proposta_fornecedor IS DISTINCT FROM OLD.proposta_fornecedor
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Ocorrência registrada não muda (só a decisão: status, decidido_por, decisao_observacao)'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'aberta' THEN
    RAISE EXCEPTION 'A decisão da ocorrência deve ser aprovada, recusada ou resolvida'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.decidido_por IS NULL THEN
    RAISE EXCEPTION 'Decidir a ocorrência exige quem decidiu (decidido_por)' USING ERRCODE = '23514';
  END IF;
  NEW.decidido_em := now();
  RETURN NEW;
END $$;


