COMMENT ON FUNCTION core_vendas_faturamento.fn_oc_ocorrencias_validar() IS 'Contrato 32: ocorrência só em OC aprovada, nasce aberta; decisão uma vez (aberta → aprovada/recusada/resolvida) com decidido_por; decidido_em carimbado pelo banco; resto imutável; DELETE só pelo cascade da OC.';


--
-- TOC entry 705 (class 1255 OID 21307)
-- Name: fn_oc_ocorrencias_zz_eventos(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_ocorrencias_zz_eventos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_req uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NULL; END IF;
  FOR v_req IN SELECT core_vendas_faturamento.fn_oc_requisicoes(NEW.id_ordem_compra) LOOP
    PERFORM core_vendas_faturamento.fn_req_evento(v_req, 'ocorrencia',
      CASE WHEN TG_OP = 'INSERT' THEN NEW.created_at ELSE NEW.decidido_em END, NEW.id_ordem_compra,
      jsonb_build_object('id_ocorrencia', NEW.id, 'tipo', NEW.tipo, 'status', NEW.status),
      CASE WHEN TG_OP = 'INSERT' THEN NEW.created_by ELSE NEW.decidido_por END);
  END LOOP;
  RETURN NULL;
END $$;


