--
-- TOC entry 776 (class 1255 OID 21360)
-- Name: fn_oc_referencia_mes_marcar(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_referencia_mes_marcar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF TG_TABLE_NAME = 'ordens_compra' THEN
    IF TG_OP <> 'DELETE' THEN
      v_ids := ARRAY[NEW.id];
    END IF;

  ELSIF TG_TABLE_NAME IN ('ordens_compra_itens', 'ordens_compra_itens_vinculos') THEN
    IF TG_OP <> 'DELETE' THEN
      v_ids := v_ids || NEW.id_ordem_compra;
    END IF;
    IF TG_OP <> 'INSERT' THEN
      v_ids := v_ids || OLD.id_ordem_compra;
    END IF;

  ELSIF TG_TABLE_NAME = 'requisicoes_compra' THEN
    SELECT COALESCE(array_agg(DISTINCT x.id), ARRAY[]::uuid[]) INTO v_ids
      FROM (
        SELECT i.id_ordem_compra AS id
          FROM core_vendas_faturamento.ordens_compra_itens i
         WHERE i.id_requisicao = NEW.id
        UNION ALL
        SELECT oc.id
          FROM core_vendas_faturamento.ordens_compra oc
         WHERE oc.id_requisicao = NEW.id
      ) x;
  END IF;

  -- Só OC que existe: num DELETE da OC, o CASCADE apaga itens e vínculos
  -- (disparando esta trigger) depois de a OC já ter saído.
  INSERT INTO core_vendas_faturamento.ordens_compra_referencia_mes AS t (id_ordem_compra, alterado_em)
  SELECT oc.id, clock_timestamp()
    FROM core_vendas_faturamento.ordens_compra oc
   WHERE oc.id = ANY (v_ids)
  ON CONFLICT (id_ordem_compra)
  DO UPDATE SET alterado_em = GREATEST(EXCLUDED.alterado_em, t.alterado_em);

  RETURN NULL;
END
$$;


