-- TOC entry 587 (class 1255 OID 20544)
-- Name: fn_oc_situacao_omie(text, text, bigint); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_situacao_omie(p_status text, p_status_sinc text, p_codigo_pedido_omie bigint) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN p_status = 'cancelado' AND p_codigo_pedido_omie IS NULL THEN 'nao_enviada'
    WHEN p_status_sinc = 'erro' AND p_status = 'cancelado'       THEN 'erro_exclusao'
    WHEN p_status_sinc = 'erro'                                  THEN 'erro_envio'
    WHEN p_status = 'cancelado' AND p_status_sinc = 'pendente'   THEN 'na_fila_exclusao'
    WHEN p_status = 'cancelado'                                  THEN 'excluida_no_omie'
    WHEN p_status = 'aprovado'  AND p_status_sinc = 'pendente'   THEN 'na_fila_envio'
    WHEN p_status = 'aprovado'                                   THEN 'sincronizada'
    WHEN p_status = 'aguardando_aprovacao'                       THEN 'aguardando_aprovacao'
    WHEN p_status = 'rascunho'                                   THEN 'rascunho'
    ELSE 'desconhecida'
  END
$$;


--
-- TOC entry 7334 (class 0 OID 0)
-- Dependencies: 587
-- Name: FUNCTION fn_oc_situacao_omie(p_status text, p_status_sinc text, p_codigo_pedido_omie bigint); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_oc_situacao_omie(p_status text, p_status_sinc text, p_codigo_pedido_omie bigint) IS 'Contrato 15 (C6, aceite "nenhuma OC fica pendente sem explicação"). Traduz (status, status_sincronizacao_omie, codigo_pedido_omie) da OC num código de situação no Omie:
  na_fila_envio        aprovada + pendente: a pipeline vai enviar (GET /compras/ordens/fila-omie, acao "enviar");
  sincronizada         aprovada + sincronizado: está no Omie (numero_pedido_omie);
  aguardando_aprovacao só vai ao Omie depois de aprovada (decisão de 24/09);
  rascunho             ainda não emitida;
  na_fila_exclusao     cancelada com pedido no Omie + pendente: a pipeline vai excluir lá (acao "excluir");
  excluida_no_omie     cancelada + sincronizado: o pedido foi excluído no Omie;
  nao_enviada          cancelada antes de chegar ao Omie (sem codigo_pedido_omie): nada a enviar nem excluir — é a OC que antes ficava "pendente para sempre";
  erro_envio           o Omie recusou o envio (erro_sincronizacao_omie); "Reenviar ao Omie" devolve à fila;
  erro_exclusao        o Omie recusou a exclusão; o pedido continua vivo no Omie;
  desconhecida         combinação que não deveria existir (status fora do CHECK).
Usada por GET /compras/ordens (campo situacao_omie, filtro ?situacao_omie=), pelo detalhe, pela fila e por GET /compras/ordens/resumo.';


--
-- TOC entry 633 (class 1255 OID 20545)
-- Name: fn_oc_situacao_omie_descricao(text, text, bigint, text, text); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_oc_situacao_omie_descricao(p_status text, p_status_sinc text, p_codigo_pedido_omie bigint, p_numero_pedido_omie text, p_erro text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE core_vendas_faturamento.fn_oc_situacao_omie(p_status, p_status_sinc, p_codigo_pedido_omie)
    WHEN 'na_fila_envio' THEN
      'Aprovada. Na fila de envio ao Omie: a integração envia em alguns minutos.'
    WHEN 'sincronizada' THEN
      'No Omie' || COALESCE(': pedido nº ' || NULLIF(btrim(p_numero_pedido_omie), ''), '') || '.'
    WHEN 'aguardando_aprovacao' THEN
      'Aguardando aprovação. Só vai ao Omie depois de aprovada.'
    WHEN 'rascunho' THEN
      'Rascunho. Só vai ao Omie depois de emitida e aprovada.'
    WHEN 'na_fila_exclusao' THEN
      'Cancelada. Na fila para excluir o pedido'
      || COALESCE(' nº ' || NULLIF(btrim(p_numero_pedido_omie), ''), '') || ' no Omie.'
    WHEN 'excluida_no_omie' THEN
      'Cancelada e excluída no Omie.'
    WHEN 'nao_enviada' THEN
      'Cancelada antes de ir ao Omie. Não há nada a enviar.'
    WHEN 'erro_envio' THEN
      'O Omie recusou o envio: ' || COALESCE(NULLIF(btrim(p_erro), ''), 'sem mensagem')
      || '. Corrija e use "Reenviar ao Omie".'
    WHEN 'erro_exclusao' THEN
      'O Omie recusou a exclusão: ' || COALESCE(NULLIF(btrim(p_erro), ''), 'sem mensagem')
      || '. O pedido' || COALESCE(' nº ' || NULLIF(btrim(p_numero_pedido_omie), ''), '')
      || ' continua no Omie até ser resolvido lá ou reenviado.'
    ELSE
      'Situação no Omie não reconhecida (status ' || COALESCE(p_status, '-')
      || ', sincronização ' || COALESCE(p_status_sinc, '-') || ').'
  END
$$;


