CREATE FUNCTION core_vendas_faturamento.fn_ordens_compra_aviso_mes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_aviso   record;
  v_empresa uuid;
BEGIN
  SELECT a.id, a.status, a.id_ordem_compra
    INTO v_aviso
    FROM core_vendas_faturamento.avisos_mes_compra a
   WHERE a.id = NEW.id_aviso_mes
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Aviso do MES % não encontrado.', NEW.id_aviso_mes
      USING ERRCODE = 'AV584', DETAIL = 'id_aviso_mes';
  END IF;
  IF v_aviso.status <> 'ABERTO' THEN
    RAISE EXCEPTION 'Este aviso do MES já foi tratado.'
      USING ERRCODE = 'AV581', DETAIL = v_aviso.status;
  END IF;

  SELECT oc.codigo_empresa INTO v_empresa
    FROM core_vendas_faturamento.ordens_compra oc WHERE oc.id = v_aviso.id_ordem_compra;
  IF v_empresa IS DISTINCT FROM NEW.codigo_empresa THEN
    RAISE EXCEPTION 'A OC de recompra tem de ser da mesma unidade da OC do aviso.'
      USING ERRCODE = 'AV585', DETAIL = 'codigo_empresa';
  END IF;
  RETURN NEW;
END $$;


