-- TOC entry 620 (class 1255 OID 20542)
-- Name: fn_ordens_compra_comprador(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_ordens_compra_comprador() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_empresa uuid;
  v_excluido timestamptz;
  v_nome text;
  -- [Contrato 36, P4] Só fn_oc_comprador_do_omie liga esta marca, e só
  -- durante o próprio UPDATE.
  v_do_omie boolean := current_setting('avhub.oc_comprador_origem', true) IS NOT DISTINCT FROM 'omie';
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.id_comprador IS NOT NULL
     AND NEW.id_comprador IS DISTINCT FROM OLD.id_comprador
     AND NOT v_do_omie THEN
    RAISE EXCEPTION 'O comprador da OC é gravado na emissão e não muda depois (OC %)', OLD.numero_pedido
      USING ERRCODE = '23514';
  END IF;

  IF NEW.id_comprador IS NOT NULL THEN
    SELECT c.codigo_empresa, c.deleted_at, COALESCE(c.nome_exibicao, c.nome)
      INTO v_empresa, v_excluido, v_nome
      FROM core_vendas_faturamento.compradores c
     WHERE c.id = NEW.id_comprador
       FOR SHARE;
    -- Comprador inexistente fica para a FK responder.
    IF FOUND AND v_empresa IS DISTINCT FROM NEW.codigo_empresa THEN
      RAISE EXCEPTION 'O comprador da OC precisa ser da mesma unidade da OC: o código de comprador só vale na conta Omie dele'
        USING ERRCODE = '23514';
    END IF;
    -- [Contrato 28] Só quando o comprador é GRAVADO agora (emissão): OC antiga
    -- de comprador excluído depois (DBA/pipeline) continua editável.
    -- [Contrato 36] A troca vinda do Omie acompanha o Omie mesmo com o
    -- comprador excluído no av-hub.
    IF FOUND AND v_excluido IS NOT NULL
       AND (TG_OP = 'INSERT' OR OLD.id_comprador IS NULL)
       AND NOT v_do_omie THEN
      RAISE EXCEPTION 'O comprador % foi excluído e não pode emitir OC', v_nome
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


