--
-- TOC entry 562 (class 1255 OID 19817)
-- Name: fn_ordens_compra_parcelas(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_ordens_compra_parcelas() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_lista    text;
  v_condicao boolean;
  v_dias     integer[];
  v_n        integer;
  v_valor    numeric(15,2);
  v_resto    numeric(15,2);
  v_base     date;
  i          integer;
BEGIN
  DELETE FROM core_vendas_faturamento.ordens_compra_parcelas WHERE id_ordem_compra = NEW.id;

  IF NEW.valor_total IS NULL OR NEW.valor_total = 0 THEN
    RETURN NULL;
  END IF;

  v_base := COALESCE(NEW.data_previsao_chegada, CURRENT_DATE);

  SELECT c.lista_dias INTO v_lista
    FROM core_vendas_faturamento.condicoes_pagamento_compras c
   WHERE c.codigo_empresa = NEW.codigo_empresa
     AND c.codigo_omie = NEW.codigo_condicao_pagamento
     AND c.ativo;
  v_condicao := FOUND;

  IF v_condicao THEN
    -- "30,40,50,60,70"; vazio = à vista na data base ("000" A Vista)
    v_dias := COALESCE(
      (SELECT array_agg(btrim(d)::integer ORDER BY ord)
         FROM unnest(string_to_array(v_lista, ',')) WITH ORDINALITY AS t(d, ord)
        WHERE btrim(d) ~ '^\d+$'),
      ARRAY[0]);
  ELSE
    v_n := GREATEST(COALESCE(NEW.quantidade_parcelas, 1), 1);
    SELECT array_agg(k * 30 ORDER BY k) INTO v_dias FROM generate_series(1, v_n) AS k;
  END IF;

  v_n     := array_length(v_dias, 1);
  v_valor := round(NEW.valor_total / v_n, 2);
  v_resto := NEW.valor_total - (v_valor * v_n);

  FOR i IN 1..v_n LOOP
    INSERT INTO core_vendas_faturamento.ordens_compra_parcelas
      (id_ordem_compra, numero_parcela, data_vencimento, valor, percentual, calculo_provisorio)
    VALUES (NEW.id, i, v_base + v_dias[i],
            CASE WHEN i = v_n THEN v_valor + v_resto ELSE v_valor END,
            round(100.0 / v_n, 3),
            NOT v_condicao);
  END LOOP;

  RETURN NULL;
END $_$;


--
-- TOC entry 1046 (class 1255 OID 19807)
-- Name: fn_ordens_compra_recalcular(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_ordens_compra_recalcular() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_oc      uuid;
  v_merc    numeric(15,2);
  v_desc    numeric(15,2);
  v_total   numeric(15,2);
  v_brl     numeric(15,2);
  v_limite  numeric(15,2);
  v_cotacao numeric(15,6);
  v_empresa uuid;
  v_segurar boolean;
BEGIN
  v_oc := COALESCE(NEW.id_ordem_compra, OLD.id_ordem_compra);

  SELECT o.codigo_empresa, COALESCE(o.cotacao_moeda, 1)
    INTO v_empresa, v_cotacao
    FROM core_vendas_faturamento.ordens_compra o
   WHERE o.id = v_oc;

  SELECT COALESCE(sum(round(i.quantidade * i.valor_unitario, 2)), 0),
         COALESCE(sum(i.valor_desconto), 0),
         COALESCE(sum(i.valor_total_item), 0)
    INTO v_merc, v_desc, v_total
    FROM core_vendas_faturamento.ordens_compra_itens i
   WHERE i.id_ordem_compra = v_oc;

  v_brl := round(v_total * v_cotacao, 2);

  SELECT COALESCE(max(p.limite_aprovacao), 30000.00)
    INTO v_limite
    FROM core_vendas_faturamento.parametros_compras p
   WHERE p.codigo_empresa = v_empresa;

  -- [LOG-57 R3] Não aprova sozinha: (a) durante a emissão (a API liga
  -- avhub.oc_segurar_aprovacao na transação do POST e, no fim, chama
  -- core_comercial.fn_divergencias_compra_gerar, que libera ou segura);
  -- (b) com divergência PENDENTE ou REPROVADO. A OC fica aguardando_aprovacao.
  v_segurar := COALESCE(current_setting('avhub.oc_segurar_aprovacao', true), '') = 'on'
               OR core_comercial.fn_oc_divergencia_aberta(v_oc);

  UPDATE core_vendas_faturamento.ordens_compra o
     SET valor_mercadorias = v_merc,
         valor_descontos   = v_desc,
         valor_total       = v_total,
         valor_total_brl   = v_brl,
         status = CASE
                    WHEN o.status IN ('cancelado', 'rascunho') THEN o.status
                    WHEN o.status = 'aprovado'
                         AND v_brl > v_limite AND v_brl > o.valor_total_brl THEN 'aguardando_aprovacao'
                    WHEN o.status = 'aprovado' THEN o.status
                    WHEN v_brl > v_limite THEN 'aguardando_aprovacao'
                    WHEN v_segurar THEN o.status                       -- LOG-57 R3
                    ELSE 'aprovado'
                  END
   WHERE o.id = v_oc;

  RETURN NULL;
END $$;


--
-- TOC entry 483 (class 1255 OID 19813)
-- Name: fn_ordens_compra_requisicao(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_ordens_compra_requisicao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- OC nasceu de uma requisição (cabeçalho) -> a requisição sai da fila.
  IF TG_OP = 'INSERT' AND NEW.id_requisicao IS NOT NULL THEN
    UPDATE core_vendas_faturamento.requisicoes_compra
       SET status = 'atendida', id_ordem_compra = NEW.id
     WHERE id = NEW.id_requisicao;
    RETURN NEW;
  END IF;

  -- OC cancelada -> TODAS as requisições dela (cabeçalho e itens) voltam para
  -- a fila. É o "nenhum estado é beco sem saída".
  IF TG_OP = 'UPDATE' AND NEW.status = 'cancelado' AND OLD.status <> 'cancelado' THEN
    UPDATE core_vendas_faturamento.requisicoes_compra
       SET status = 'aberta', id_ordem_compra = NULL
     WHERE id_ordem_compra = NEW.id;
  END IF;

  RETURN NEW;
END $$;


