-- Name: FUNCTION fn_ordens_compra_requisicao(); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_ordens_compra_requisicao() IS 'Emitir a OC com requisição no cabeçalho a marca atendida; cancelar a OC devolve TODAS as
requisições dela (cabeçalho e itens) para aberta (contrato 24, V3).';


--
-- TOC entry 804 (class 1255 OID 19811)
-- Name: fn_ordens_compra_status(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_ordens_compra_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_limite numeric(15,2);
BEGIN
  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;

  -- B13: cancelada é final — não volta a aguardar nem é aprovada depois.
  IF OLD.status = 'cancelado' THEN
    RAISE EXCEPTION 'OC cancelada não muda de status (tentativa: %)', NEW.status
      USING ERRCODE = '23514';
  END IF;

  -- [LOG-57 R3] Compra acima do cotado espera o vendedor (N16-61, escolha 1
  -- do Nathan): com divergência PENDENTE ou REPROVADO a OC não vai a aprovado
  -- (nem ao Omie, cuja fila só pega aprovado). A API responde 409 DIVERGENCIA_PENDENTE.
  IF NEW.status = 'aprovado' AND core_comercial.fn_oc_divergencia_aberta(NEW.id) THEN
    RAISE EXCEPTION 'A OC espera o vendedor aprovar a compra acima do cotado'
      USING ERRCODE = 'AV572';
  END IF;

  SELECT COALESCE(max(p.limite_aprovacao), 30000.00)
    INTO v_limite
    FROM core_vendas_faturamento.parametros_compras p
   WHERE p.codigo_empresa = NEW.codigo_empresa;

  -- Aprovar uma OC acima do limite exige que ela TENHA PASSADO por
  -- aguardando_aprovacao (sem isso, bastaria criar já como 'aprovado').
  IF NEW.status = 'aprovado'
     AND NEW.valor_total_brl > v_limite
     AND OLD.status <> 'aguardando_aprovacao' THEN
    RAISE EXCEPTION
      'OC de % (limite %) só pode ser aprovada a partir de aguardando_aprovacao; status atual: %',
      NEW.valor_total_brl, v_limite, OLD.status
      USING ERRCODE = '23514';
  END IF;

  -- Carimbos vêm do BANCO, não do cliente.
  IF NEW.status = 'aprovado' THEN
    NEW.aprovado_em := now();
  END IF;
  IF NEW.status = 'aguardando_aprovacao' AND OLD.status = 'aprovado' THEN
    NEW.aprovado_por := NULL;       -- voltou a depender de decisão
    NEW.aprovado_em  := NULL;
  END IF;
  IF NEW.status = 'cancelado' THEN
    NEW.cancelado_em := now();
    -- B4 (decisão 24/09): cancelar uma OC que JÁ ESTÁ no Omie volta para a fila, e a
    -- pipeline exclui lá (ExcluirPedCompra: o Omie não tem "cancelar" pedido de compra).
    IF OLD.status_sincronizacao_omie = 'sincronizado' THEN
      NEW.status_sincronizacao_omie := 'pendente';
      NEW.erro_sincronizacao_omie   := NULL;
    END IF;
    -- só se updated_by for um usuário de verdade (senão a FK derrubaria o cancelamento)
    NEW.cancelado_por := COALESCE(NEW.cancelado_por,
      (SELECT u.id FROM auth.usuarios u WHERE u.id = NEW.updated_by));
  END IF;

  RETURN NEW;
END $$;


--
-- TOC entry 593 (class 1255 OID 21301)
-- Name: fn_ordens_compra_zz_eventos(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_ordens_compra_zz_eventos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_req uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.id_requisicao IS NOT NULL THEN
      PERFORM core_vendas_faturamento.fn_req_evento_ligar(NEW.id_requisicao, NEW.id, NEW.created_by);
    END IF;
    RETURN NULL;
  END IF;
  FOR v_req IN SELECT core_vendas_faturamento.fn_oc_requisicoes(NEW.id) LOOP
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      IF NEW.status = 'aguardando_aprovacao' THEN
        PERFORM core_vendas_faturamento.fn_req_evento(v_req, 'oc_enviada_aprovacao', NULL, NEW.id, NULL, NEW.updated_by);
      ELSIF NEW.status = 'aprovado' THEN
        PERFORM core_vendas_faturamento.fn_req_evento(v_req, 'oc_aprovada', NEW.aprovado_em, NEW.id,
          jsonb_build_object('data_previsao_chegada', NEW.data_previsao_chegada), NEW.aprovado_por);
      ELSIF NEW.status = 'cancelado' THEN
        PERFORM core_vendas_faturamento.fn_req_evento(v_req, 'oc_cancelada', NEW.cancelado_em, NEW.id,
          jsonb_build_object('motivo', NEW.motivo_reprovacao, 'status_anterior', OLD.status), NEW.cancelado_por);
      END IF;
    END IF;
    IF NEW.numero_pedido_omie IS NOT NULL AND OLD.numero_pedido_omie IS NULL THEN
      PERFORM core_vendas_faturamento.fn_req_evento(v_req, 'oc_no_omie', NULL, NEW.id,
        jsonb_build_object('numero_pedido_omie', NEW.numero_pedido_omie), NULL);
    END IF;
  END LOOP;
  RETURN NULL;
END $$;


