--
-- TOC entry 657 (class 1255 OID 20396)
-- Name: fn_painel_classificacao(date, date, boolean, uuid, uuid[], text[]); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_painel_classificacao(p_inicio date, p_fim date, p_is_track_record boolean, p_codigo_empresa uuid, p_vinc_empresa uuid[], p_vinc_vendedor text[]) RETURNS TABLE(tipo_contrato text, vendas numeric, qtd_pedidos bigint, percentual_vendas numeric, percentual_qtd_pedidos numeric)
    LANGUAGE sql STABLE
    AS $$
  WITH base AS (
    SELECT COALESCE(vb.tipo_contrato, 'SEM CLASSIFICAÇÃO') AS tipo_contrato,
           sum(vb.total_pedido) AS vendas,
           count(DISTINCT vb.codigo_empresa::text || ':' || vb.numero_pedido::text) AS qtd_pedidos
      FROM core_vendas_faturamento.vw_vendas_base vb
     WHERE vb.grupo = 'LIQUIDO' AND vb.data_inclusao IS NOT NULL
       AND vb.is_track_record = COALESCE(p_is_track_record, false)
       AND (p_codigo_empresa IS NULL OR vb.codigo_empresa = p_codigo_empresa)
       AND vb.data_inclusao BETWEEN p_inicio AND p_fim
       AND core_vendas_faturamento.fn_no_vinculo(vb.codigo_empresa, vb.cod_vendedor, p_vinc_empresa, p_vinc_vendedor)
     GROUP BY 1
  )
  SELECT t.tipo, COALESCE(b.vendas, 0), COALESCE(b.qtd_pedidos, 0),
         COALESCE(round(b.vendas / NULLIF(sum(b.vendas) OVER (), 0) * 100, 2), 0),
         COALESCE(round(b.qtd_pedidos::numeric / NULLIF(sum(b.qtd_pedidos) OVER (), 0) * 100, 2), 0)
    FROM (VALUES ('SPOT', 1), ('CONTRATO', 2), ('SEM CLASSIFICAÇÃO', 3)) AS t(tipo, ord)
    LEFT JOIN base b ON b.tipo_contrato = t.tipo
   ORDER BY t.ord
$$;


