CREATE FUNCTION core_vendas_faturamento.fn_painel_clientes_inativos(p_dias_sem_comprar integer, p_codigo_empresa uuid, p_vinc_empresa uuid[], p_vinc_vendedor text[], p_limite integer DEFAULT 50) RETURNS TABLE(codigo_empresa uuid, cod_vendedor text, vendedor text, codigo_cliente text, cliente text, ultima_compra date, dias_sem_comprar integer, valor_ultima_compra numeric, qtd_pedidos bigint, valor_total_historico numeric)
    LANGUAGE sql STABLE
    AS $$
  SELECT ci.codigo_empresa, ci.cod_vendedor,
         COALESCE(NULLIF(v.nome_exibicao, ''), ci.vendedor)::text,
         ci.codigo_cliente::text, ci.cliente::text, ci.ultima_compra, ci.dias_sem_comprar,
         ci.valor_ultima_compra, ci.qtd_pedidos, ci.valor_total_historico
    FROM core_vendas_faturamento.vw_clientes_inativos ci
    LEFT JOIN core_vendas_faturamento.vendedores v
      ON v.codigo_empresa = ci.codigo_empresa AND v.codigo_vendedor_omie::text = ci.cod_vendedor AND v.deleted_at IS NULL
   WHERE ci.dias_sem_comprar >= COALESCE(p_dias_sem_comprar, 90)
     AND (p_codigo_empresa IS NULL OR ci.codigo_empresa = p_codigo_empresa)
     AND core_vendas_faturamento.fn_no_vinculo(ci.codigo_empresa, ci.cod_vendedor, p_vinc_empresa, p_vinc_vendedor)
   ORDER BY ci.dias_sem_comprar, ci.cliente
   LIMIT COALESCE(p_limite, 50)
$$;


