--
-- TOC entry 850 (class 1255 OID 20399)
-- Name: fn_painel_proximos_vencimentos(date, date, boolean, uuid, uuid[], text[], integer); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_painel_proximos_vencimentos(p_inicio date, p_fim date, p_is_track_record boolean, p_codigo_empresa uuid, p_vinc_empresa uuid[], p_vinc_vendedor text[], p_limite integer DEFAULT 5) RETURNS TABLE(codigo_empresa uuid, codigo_pedido_omie bigint, numero_pedido text, cliente text, codigo_cliente text, data_previsao text, dias_para_prazo integer, prazo text, total_pedido numeric, etapa_descricao text, cod_vendedor text, vendedor text)
    LANGUAGE sql STABLE
    AS $$
  SELECT vb.codigo_empresa, vb.codigo_pedido_omie, vb.numero_pedido::text,
         COALESCE(vb.nome_cliente, vb.razao_social_cliente, vb.codigo_cliente)::text,
         vb.codigo_cliente::text,
         vb.previsao_faturamento::text,
         d.dias, core_vendas_faturamento.fn_pedido_prazo(d.dias),
         COALESCE(vb.total_pedido, 0), vb.etapa_descricao::text,
         vb.cod_vendedor, COALESCE(NULLIF(vb.nome_exibicao_vendedor, ''), vb.vendedor)::text
    FROM core_vendas_faturamento.vw_vendas_base vb
   CROSS JOIN LATERAL (
     SELECT core_vendas_faturamento.fn_pedido_dias_para_prazo(vb.previsao_faturamento, vb.faturado, vb.cancelado,
              vb.denegado, vb.devolvido, vb.encerrado) AS dias
   ) d
   WHERE vb.is_track_record = COALESCE(p_is_track_record, false)
     AND vb.data_inclusao BETWEEN p_inicio AND p_fim
     AND NOT COALESCE(vb.faturado, false)
     -- Só pedido em aberto (mesma regra do prazo): cancelado, denegado,
     -- devolvido e encerrado não vencem mais.
     AND d.dias IS NOT NULL
     AND (p_codigo_empresa IS NULL OR vb.codigo_empresa = p_codigo_empresa)
     AND core_vendas_faturamento.fn_no_vinculo(vb.codigo_empresa, vb.cod_vendedor, p_vinc_empresa, p_vinc_vendedor)
   ORDER BY vb.previsao_faturamento, vb.numero_pedido
   LIMIT COALESCE(p_limite, 5)
$$;


