--
-- TOC entry 525 (class 1255 OID 20397)
-- Name: fn_painel_top_clientes(smallint, smallint, boolean, uuid, uuid[], text[], integer); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_painel_top_clientes(p_mes smallint, p_ano smallint, p_is_track_record boolean, p_codigo_empresa uuid, p_vinc_empresa uuid[], p_vinc_vendedor text[], p_limite integer DEFAULT 20) RETURNS TABLE(posicao bigint, codigo_empresa uuid, codigo_cliente text, cpf_cnpj text, cliente text, vendas numeric, qtd_pedidos bigint, empresas uuid[])
    LANGUAGE sql STABLE
    AS $$
  WITH r AS (
    -- Equipe: o ranking da empresa. Vendedor: o ranking de cada vínculo (unidade + código).
    SELECT x.*, NULL::uuid AS vinc_emp
      FROM core_vendas_faturamento.fn_ranking_clientes_vendas(p_mes, p_ano, p_is_track_record, p_codigo_empresa, NULL) x
     WHERE p_vinc_vendedor IS NULL
    UNION ALL
    SELECT x.*, v.emp
      FROM unnest(p_vinc_empresa, p_vinc_vendedor) AS v(emp, cod)
     CROSS JOIN LATERAL core_vendas_faturamento.fn_ranking_clientes_vendas(
             p_mes, p_ano, p_is_track_record, COALESCE(v.emp, p_codigo_empresa), v.cod) x
     WHERE p_vinc_vendedor IS NOT NULL
  ), agg AS (
    -- Soma os tipos de contrato do mesmo cliente. No painel do vendedor, cliente
    -- de unidades diferentes fica em linhas separadas (vendas diferentes).
    SELECT CASE WHEN p_vinc_vendedor IS NULL THEN NULL ELSE r.codigo_empresa END AS chave_emp,
           r.cpf_cnpj::text AS cpf_cnpj,
           (array_agg(r.codigo_empresa ORDER BY r.vendas DESC))[1] AS codigo_empresa,
           (array_agg(r.codigo_cliente::text ORDER BY r.vendas DESC))[1] AS codigo_cliente,
           (array_agg(r.cliente::text ORDER BY r.vendas DESC))[1] AS cliente,
           sum(r.vendas) AS vendas,
           sum(r.qtd_pedidos)::bigint AS qtd_pedidos,
           array(SELECT DISTINCT e FROM unnest(array_agg(r.codigo_empresa)) e ORDER BY e) AS empresas
      FROM r
     GROUP BY 1, 2
  )
  SELECT rank() OVER (ORDER BY a.vendas DESC), a.codigo_empresa, a.codigo_cliente, a.cpf_cnpj, a.cliente,
         a.vendas, a.qtd_pedidos, a.empresas
    FROM agg a
   ORDER BY a.vendas DESC, a.cliente
   LIMIT COALESCE(p_limite, 20)
$$;


