--
-- TOC entry 618 (class 1255 OID 20398)
-- Name: fn_painel_top_produtos(date, date, boolean, uuid, uuid[], text[], boolean, integer); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_painel_top_produtos(p_inicio date, p_fim date, p_is_track_record boolean, p_codigo_empresa uuid, p_vinc_empresa uuid[], p_vinc_vendedor text[], p_por_unidade boolean DEFAULT false, p_limite integer DEFAULT 20) RETURNS TABLE(posicao bigint, codigo_empresa uuid, codigo_produto text, descricao text, quantidade numeric, valor numeric)
    LANGUAGE sql STABLE
    AS $$
  WITH itens AS (
    SELECT i.codigo_empresa, i.codigo_produto::text AS codigo_produto, i.descricao::text AS descricao,
           COALESCE(i.quantidade, 0)::numeric AS quantidade, COALESCE(i.valor_total, 0) AS valor
      FROM core_vendas_faturamento.vw_pedido_venda_itens i
     WHERE i.is_track_record = COALESCE(p_is_track_record, false)
       AND i.data_inclusao BETWEEN p_inicio AND p_fim
       AND i.codigo_produto IS NOT NULL
       AND (p_codigo_empresa IS NULL OR i.codigo_empresa = p_codigo_empresa)
       AND core_vendas_faturamento.fn_no_vinculo(i.codigo_empresa, i.codigo_vendedor_omie, p_vinc_empresa, p_vinc_vendedor)
  ), agg AS (
    SELECT CASE WHEN p_por_unidade THEN it.codigo_empresa END AS codigo_empresa,
           it.codigo_produto,
           COALESCE((array_agg(it.descricao ORDER BY it.valor DESC) FILTER (WHERE it.descricao IS NOT NULL))[1], it.codigo_produto) AS descricao,
           sum(it.quantidade) AS quantidade,
           sum(it.valor) AS valor
      FROM itens it
     GROUP BY 1, 2
  )
  SELECT rank() OVER (ORDER BY a.valor DESC), a.codigo_empresa, a.codigo_produto, a.descricao, a.quantidade, a.valor
    FROM agg a
   ORDER BY a.valor DESC, a.codigo_produto
   LIMIT COALESCE(p_limite, 20)
$$;


