--
-- TOC entry 606 (class 1255 OID 20395)
-- Name: fn_painel_vendedor_totais(smallint, smallint, boolean, uuid[], text[]); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_painel_vendedor_totais(p_mes smallint, p_ano smallint, p_is_track_record boolean, p_vinc_empresa uuid[], p_vinc_vendedor text[]) RETURNS TABLE(lado text, valor numeric, quantidade bigint, meta_individual numeric, meta_total numeric, perc_meta numeric, perc_participacao numeric, valor_anterior numeric, quantidade_anterior bigint, variacao_pct numeric, variacao_quantidade_pct numeric)
    LANGUAGE sql STABLE
    AS $$
  WITH per AS (
    SELECT make_date(p_ano, p_mes, 1) AS ini,
           (make_date(p_ano, p_mes, 1) - interval '1 month')::date AS ini_ant
  ), vendas AS (
    SELECT (vb.data_inclusao >= per.ini) AS atual,
           sum(vb.total_pedido) AS valor,
           count(DISTINCT vb.codigo_empresa::text || ':' || vb.numero_pedido) AS qtd
      FROM core_vendas_faturamento.vw_vendas_base vb CROSS JOIN per
     WHERE vb.grupo = 'LIQUIDO'
       AND vb.is_track_record = COALESCE(p_is_track_record, false)
       AND vb.data_inclusao >= per.ini_ant AND vb.data_inclusao < per.ini + interval '1 month'
       AND core_vendas_faturamento.fn_no_vinculo(vb.codigo_empresa, vb.cod_vendedor, p_vinc_empresa, p_vinc_vendedor)
     GROUP BY 1
  ), fat AS (
    SELECT (nf.data_emissao >= per.ini) AS atual,
           sum(nf.valor_nf) AS valor,
           count(*) AS qtd
      FROM core_vendas_faturamento.vw_nf_classified nf CROSS JOIN per
     WHERE nf.grupo_deducao = 'LIQUIDO'
       AND nf.is_track_record = COALESCE(p_is_track_record, false)
       AND nf.data_emissao >= per.ini_ant AND nf.data_emissao < per.ini + interval '1 month'
       AND core_vendas_faturamento.fn_no_vinculo(nf.codigo_empresa, nf.cod_vendedor, p_vinc_empresa, p_vinc_vendedor)
     GROUP BY 1
  ), metas AS (
    SELECT (SELECT r.meta_individual FROM core_vendas_faturamento.fn_ranking_vendedores_vendas(p_mes, p_ano, p_is_track_record, NULL) r LIMIT 1) AS mi_vendas,
           (SELECT r.meta_individual FROM core_vendas_faturamento.fn_ranking_vendedores_faturamento(p_mes, p_ano, p_is_track_record, NULL) r LIMIT 1) AS mi_fat,
           (SELECT m.meta FROM core_vendas_faturamento.metas_mensais m WHERE m.mes = p_mes AND m.ano = p_ano AND m.tipo = 'venda' AND m.deleted_at IS NULL) AS mt_vendas,
           (SELECT m.meta FROM core_vendas_faturamento.metas_mensais m WHERE m.mes = p_mes AND m.ano = p_ano AND m.tipo = 'faturamento' AND m.deleted_at IS NULL) AS mt_fat
  ), lados AS (
    SELECT 'vendas'::text AS lado,
           COALESCE((SELECT valor FROM vendas WHERE atual), 0) AS valor,
           COALESCE((SELECT qtd FROM vendas WHERE atual), 0) AS qtd,
           COALESCE((SELECT valor FROM vendas WHERE NOT atual), 0) AS valor_ant,
           COALESCE((SELECT qtd FROM vendas WHERE NOT atual), 0) AS qtd_ant,
           COALESCE(m.mi_vendas, 0) AS mi, COALESCE(m.mt_vendas, 0) AS mt
      FROM metas m
    UNION ALL
    SELECT 'faturamento',
           COALESCE((SELECT valor FROM fat WHERE atual), 0),
           COALESCE((SELECT qtd FROM fat WHERE atual), 0),
           COALESCE((SELECT valor FROM fat WHERE NOT atual), 0),
           COALESCE((SELECT qtd FROM fat WHERE NOT atual), 0),
           COALESCE(m.mi_fat, 0), COALESCE(m.mt_fat, 0)
      FROM metas m
  )
  SELECT l.lado, l.valor::numeric(15,2), l.qtd, l.mi, l.mt,
         CASE WHEN l.mi > 0 THEN round(l.valor / l.mi * 100, 2) ELSE 0 END,
         CASE WHEN l.mt > 0 THEN round(l.valor / l.mt * 100, 2) ELSE 0 END,
         l.valor_ant::numeric(15,2), l.qtd_ant,
         core_vendas_faturamento.fn_variacao_pct(l.valor, l.valor_ant),
         core_vendas_faturamento.fn_variacao_pct(l.qtd, l.qtd_ant)
    FROM lados l
$$;


