--
-- TOC entry 631 (class 1255 OID 20629)
-- Name: fn_pedido_compra_etapa_descricao(text); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_pedido_compra_etapa_descricao(p_etapa text) RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT CASE
           WHEN NULLIF(btrim(p_etapa), '') IS NULL THEN 'Sem etapa no Omie'
           ELSE COALESCE(
                  (SELECT e.descricao::text
                     FROM core_vendas_faturamento.pedidos_compras_etapas e
                    WHERE e.etapa = btrim(p_etapa)),
