CREATE FUNCTION core_vendas_faturamento.fn_pedido_dias_para_prazo(p_data_previsao text, p_faturado boolean, p_cancelado boolean, p_denegado boolean, p_devolvido boolean, p_encerrado boolean) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE
           WHEN COALESCE(p_faturado, false) OR COALESCE(p_cancelado, false) OR COALESCE(p_denegado, false)
                OR COALESCE(p_devolvido, false) OR COALESCE(p_encerrado, false) THEN NULL
           WHEN p_data_previsao IS NULL OR p_data_previsao !~ '^\d{4}-\d{2}-\d{2}' THEN NULL
           ELSE to_date(substr(p_data_previsao, 1, 10), 'YYYY-MM-DD')
                - (now() AT TIME ZONE 'America/Sao_Paulo')::date
         END
$$;


