--
-- TOC entry 981 (class 1255 OID 24140)
-- Name: fn_pedido_item_observacao_pcp_regras(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_pedido_item_observacao_pcp_regras() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Observação do PCP não é apagada do banco: use a exclusão lógica (deleted_at/deleted_by).'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.numero_pedido := btrim(NEW.numero_pedido);
    IF NEW.deleted_at IS NOT NULL OR NEW.deleted_by IS NOT NULL THEN
      RAISE EXCEPTION 'Observação do PCP nasce viva (sem deleted_at/deleted_by).'
        USING ERRCODE = '23514';
    END IF;
    IF NOT core_vendas_faturamento.fn_pedido_item_existe(NEW.codigo_empresa, NEW.numero_pedido, NEW.codigo_item_omie) THEN
      RAISE EXCEPTION 'Item % não existe no pedido % desta unidade.', NEW.codigo_item_omie, NEW.numero_pedido
        USING ERRCODE = 'AV161';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE: só a exclusão lógica de uma observação viva.
  IF OLD.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Observação do PCP já apagada não muda.'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.codigo_empresa IS DISTINCT FROM OLD.codigo_empresa
     OR NEW.numero_pedido IS DISTINCT FROM OLD.numero_pedido
     OR NEW.codigo_item_omie IS DISTINCT FROM OLD.codigo_item_omie
     OR NEW.texto IS DISTINCT FROM OLD.texto OR NEW.tags IS DISTINCT FROM OLD.tags
     OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'Observação do PCP é log: não se edita. Apague e escreva outra.'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.deleted_at IS NULL AND NEW.deleted_by IS NOT NULL THEN
    RAISE EXCEPTION 'deleted_by só junto com deleted_at.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- TOC entry 7355 (class 0 OID 0)
-- Dependencies: 981
-- Name: FUNCTION fn_pedido_item_observacao_pcp_regras(); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_pedido_item_observacao_pcp_regras() IS 'API-016: trigger de pedido_item_observacao_pcp. INSERT: apara numero_pedido e exige o item no pedido vivo (fn_pedido_item_existe; senão AV161, que a API devolve como 404). UPDATE: só preencher deleted_at/deleted_by de uma observação viva (23514 no resto). DELETE físico: 23514 (é log).';


--
-- TOC entry 788 (class 1255 OID 24082)
-- Name: fn_pedido_marcacao_pcp_definir(uuid, text, text, uuid); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_pedido_marcacao_pcp_definir(p_codigo_empresa uuid, p_numero_pedido text, p_marcacao text, p_usuario uuid) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_marc    text := NULLIF(lower(btrim(p_marcacao)), '');
  v_escopo  text;
  v_tirou   integer := 0;
  v_pos     integer := 0;
BEGIN
  IF p_usuario IS NULL OR NOT EXISTS (
       SELECT 1 FROM auth.usuarios u WHERE u.id = p_usuario AND u.ativo AND u.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Usuário não encontrado ou inativo.' USING ERRCODE = 'AV151';
  END IF;
  -- Quem marca e desmarca: tela Pedidos PCP com pode_editar (regra 3 do contrato).
  IF NOT EXISTS (
       SELECT 1
         FROM auth.usuarios_perfis up
         JOIN auth.perfis p      ON p.id = up.id_perfil AND p.deleted_at IS NULL
         JOIN auth.permissoes pm ON pm.id_perfil = p.id AND pm.deleted_at IS NULL AND pm.pode_editar
         JOIN auth.telas t       ON t.id = pm.id_tela AND t.deleted_at IS NULL AND t.ativo AND t.slug = 'pcp-pedidos'
        WHERE up.id_usuario = p_usuario) THEN
    RAISE EXCEPTION 'Usuário sem permissão para classificar o pedido (tela Pedidos PCP, editar).' USING ERRCODE = 'AV151';
  END IF;
  IF v_marc IS NOT NULL AND v_marc NOT IN ('avanco') THEN
    RAISE EXCEPTION 'marcacao inválida: use "avanco" ou null (desmarca).' USING ERRCODE = '22023';
  END IF;
  IF p_codigo_empresa IS NULL OR p_numero_pedido IS NULL OR NOT EXISTS (
       SELECT 1 FROM core_vendas_faturamento.pedidos_vendas x
        WHERE x.codigo_empresa = p_codigo_empresa AND x.numero_pedido = p_numero_pedido
          AND x.deleted_at IS NULL AND COALESCE(x.sequencial, 0) = 0
          AND (x.etapa IS NULL OR x.etapa <> 0)) THEN
    RAISE EXCEPTION 'Pedido não encontrado.' USING ERRCODE = 'AV153';
  END IF;
  -- Escopo: o mesmo do GET /pedidos_venda nas telas do PCP (perfil sem "todos" só
  -- mexe em pedido de vendedor vinculado; qualquer parcela viva conta como dono).
  v_escopo := auth.fn_escopo_vendedores_usuario(p_usuario);
  IF v_escopo IS DISTINCT FROM 'todos' AND NOT EXISTS (
       SELECT 1
         FROM core_vendas_faturamento.pedidos_vendas x
         JOIN auth.fn_vendedores_do_usuario(p_usuario) v
           ON v.codigo_empresa = x.codigo_empresa AND v.codigo_vendedor_omie::text = x.codigo_vendedor_omie::text
        WHERE x.codigo_empresa = p_codigo_empresa AND x.numero_pedido = p_numero_pedido
          AND x.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Pedido não é de um vendedor do seu escopo.' USING ERRCODE = 'AV152';
  END IF;

  -- Duas marcações do mesmo pedido ao mesmo tempo esperam uma pela outra.
  PERFORM pg_advisory_xact_lock(hashtextextended('pedido_marcacao_pcp|' || p_codigo_empresa::text || '|' || p_numero_pedido, 0));

  -- O dropdown tem um valor por vez: marcar um valor tira o outro vigente.
  UPDATE core_vendas_faturamento.pedido_marcacao_pcp m
     SET removida_por = p_usuario, removida_em = now()
   WHERE m.codigo_empresa = p_codigo_empresa AND m.numero_pedido = p_numero_pedido
     AND m.removida_em IS NULL
     AND (v_marc IS NULL OR m.marcacao <> v_marc);
  GET DIAGNOSTICS v_tirou = ROW_COUNT;

  IF v_marc IS NOT NULL THEN
    INSERT INTO core_vendas_faturamento.pedido_marcacao_pcp (codigo_empresa, numero_pedido, marcacao, marcada_por)
    VALUES (p_codigo_empresa, p_numero_pedido, v_marc, p_usuario)
    ON CONFLICT (codigo_empresa, numero_pedido, marcacao) WHERE removida_em IS NULL DO NOTHING;
    GET DIAGNOSTICS v_pos = ROW_COUNT;
  END IF;

  RETURN CASE WHEN v_pos > 0 THEN 'marcado' WHEN v_tirou > 0 THEN 'desmarcado' ELSE 'sem_mudanca' END;
END $$;


