--
-- TOC entry 688 (class 1255 OID 20376)
-- Name: fn_pedido_prazo(integer); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_pedido_prazo(p_dias integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
           WHEN p_dias IS NULL THEN NULL
           WHEN p_dias < 0 THEN 'atrasado'
           WHEN p_dias = 0 THEN 'vence_hoje'
           WHEN p_dias <= 3 THEN 'vai_vencer'
           ELSE 'em_dia'
         END
$$;


