--

CREATE FUNCTION core_vendas_faturamento.fn_pedido_situacao_parcial(p_cancelado boolean, p_devolvido boolean, p_devolucao_parcial boolean, p_denegado boolean, p_encerrado boolean, p_faturado boolean, p_manual boolean, p_autorizado boolean) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
           WHEN COALESCE(p_cancelado, false)         THEN 'cancelado'
           WHEN COALESCE(p_devolvido, false)         THEN 'devolvido'
           WHEN COALESCE(p_devolucao_parcial, false) THEN 'devolucao_parcial'
           WHEN COALESCE(p_denegado, false)          THEN 'denegado'
           WHEN COALESCE(p_encerrado, false)         THEN 'encerrado'
           WHEN COALESCE(p_faturado, false)          THEN 'faturado'
           WHEN COALESCE(p_manual, false)            THEN 'manual'
           WHEN COALESCE(p_autorizado, false)        THEN 'autorizado'
           ELSE 'aberto'
         END
$$;


