--

CREATE FUNCTION core_vendas_faturamento.fn_pedidos_venda(p_inicio date, p_fim date, p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_vendedor text[] DEFAULT NULL::text[], p_pedido_venda text DEFAULT NULL::text, p_excluir_orcamento boolean DEFAULT true, p_q text DEFAULT NULL::text, p_situacao text DEFAULT NULL::text, p_etapa integer DEFAULT NULL::integer, p_prazo text DEFAULT NULL::text, p_grupo text DEFAULT NULL::text, p_em_blacklist boolean DEFAULT NULL::boolean, p_encerrar_por_saldo boolean DEFAULT true, p_desvio boolean DEFAULT NULL::boolean, p_avanco boolean DEFAULT NULL::boolean, p_carteira boolean DEFAULT NULL::boolean, p_desvio_dias integer DEFAULT 10) RETURNS TABLE(codigo_empresa uuid, is_track_record boolean, pedido_venda text, codigo_pedido_omie bigint, data_inclusao date, codigo_cliente text, cliente text, destinatario text, razao_social_destinatario text, cnpj_cpf_destinatario text, cidade_destinatario text, estado_destinatario text, codigo_vendedor text, vendedor text, numero_contrato text, tipo_contrato text, codigo_categoria text, categoria text, grupo text, valor_total numeric, qtd_parciais integer, parciais_faturadas integer, faturado boolean, situacao text, etapa_atual integer, etapa_atual_descricao text, data_previsao_mais_urgente text, dias_para_prazo integer, prazo text, precisa_atencao boolean, em_blacklist boolean, motivo_blacklist text, eh_ypfb boolean, parciais jsonb, saldo_zerado boolean, encerrado_por_saldo boolean, data_encerramento_calculada text, encerrado_em_atraso boolean, dias_atraso_no_encerramento integer, desvio_previsao boolean, dias_previsao_inclusao integer, valor_carteira numeric, em_carteira boolean, avanco boolean, avanco_marcado_por uuid, avanco_marcado_por_nome text, avanco_marcado_em timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
  WITH l AS (
    SELECT l0.*,
           -- Linha faturada que vale para o encerramento (NF cancelada/denegada não).
           (COALESCE(l0.faturado, false) AND NOT COALESCE(l0.cancelado, false)
             AND NOT COALESCE(l0.denegado, false)) AS fat_valido,
           -- Linha com valor ainda aberta: nenhuma das flags que fecham o prazo
           -- (as mesmas de fn_pedido_dias_para_prazo).
           (COALESCE(l0.total_pedido_venda, 0) > 0
             AND NOT (COALESCE(l0.faturado, false) OR COALESCE(l0.cancelado, false)
                      OR COALESCE(l0.denegado, false) OR COALESCE(l0.devolvido, false)
                      OR COALESCE(l0.encerrado, false))) AS aberta_com_valor,
           CASE WHEN l0.data_faturamento ~ '^\d{4}-\d{2}-\d{2}' THEN substr(l0.data_faturamento, 1, 10) END AS data_fat10
      FROM core_vendas_faturamento.fn_pedidos_venda_linhas(
             p_inicio, p_fim, p_is_track_record, p_codigo_empresa, p_codigo_vendedor, p_pedido_venda, p_excluir_orcamento,
             -- SQL 015: carteira (ou desvio, que só existe com parcela aberta) sem exigir período.
             COALESCE(p_carteira, false) OR COALESCE(p_desvio, false)) l0
  ), cab AS (
    SELECT DISTINCT ON (l.codigo_empresa, l.pedido_venda) l.*
      FROM l
     WHERE l.eh_cabecalho
     ORDER BY l.codigo_empresa, l.pedido_venda, l.sequencial NULLS FIRST
  ), agg AS (
    SELECT l.codigo_empresa, l.pedido_venda,
           COALESCE(sum(l.total_pedido_venda), 0)::numeric(15,2) AS valor_total,
           count(*)::integer AS qtd_parciais,
           count(*) FILTER (WHERE l.situacao = 'faturado')::integer AS parciais_faturadas,
           bool_or(COALESCE(l.faturado, false)) AS algum_faturado,
           count(DISTINCT l.situacao) AS n_situacoes,
           min(l.situacao) AS uma_situacao,
           array_agg(DISTINCT l.etapa) FILTER (WHERE l.etapa IS NOT NULL) AS etapas,
           array_remove(ARRAY[
             CASE WHEN bool_or(l.autorizado) THEN 'autorizado' END,
             CASE WHEN bool_or(l.denegado) THEN 'denegado' END,
             CASE WHEN bool_or(l.faturado) THEN 'faturado' END,
             CASE WHEN bool_or(l.cancelado) THEN 'cancelado' END,
             CASE WHEN bool_or(l.devolvido) THEN 'devolvido' END,
             CASE WHEN bool_or(l.devolucao_parcial) THEN 'devolucao_parcial' END,
             CASE WHEN bool_or(l.encerrado) THEN 'encerrado' END,
             CASE WHEN bool_or(l.manual) THEN 'manual' END
           ], NULL) AS flags,
           (array_agg(l.etapa ORDER BY l.sequencial NULLS FIRST)
              FILTER (WHERE NOT COALESCE(l.faturado, false) AND l.etapa IS NOT NULL))[1] AS etapa_aberta,
           (array_agg(l.etapa_descricao ORDER BY l.sequencial NULLS FIRST)
              FILTER (WHERE NOT COALESCE(l.faturado, false) AND l.etapa IS NOT NULL))[1] AS etapa_aberta_desc,
           -- SQL 014d: a mesma escolha sem o ORIGINAL zerado (cabeçalho com valor 0):
           -- todo o valor dele foi para as parciais, então ele não é "parcial aberta".
           (array_agg(l.etapa ORDER BY l.sequencial NULLS FIRST)
              FILTER (WHERE NOT COALESCE(l.faturado, false) AND l.etapa IS NOT NULL
                        AND NOT (l.eh_cabecalho AND COALESCE(l.total_pedido_venda, 0) = 0)))[1] AS etapa_aberta_sz,
           (array_agg(l.etapa_descricao ORDER BY l.sequencial NULLS FIRST)
              FILTER (WHERE NOT COALESCE(l.faturado, false) AND l.etapa IS NOT NULL
                        AND NOT (l.eh_cabecalho AND COALESCE(l.total_pedido_venda, 0) = 0)))[1] AS etapa_aberta_sz_desc,
           -- SQL 014d: etapa da última parcial faturada (NF não cancelada/denegada).
           (array_agg(l.etapa ORDER BY l.sequencial DESC NULLS LAST)
              FILTER (WHERE l.fat_valido AND l.etapa IS NOT NULL))[1] AS etapa_ultima_fat,
           (array_agg(l.etapa_descricao ORDER BY l.sequencial DESC NULLS LAST)
              FILTER (WHERE l.fat_valido AND l.etapa IS NOT NULL))[1] AS etapa_ultima_fat_desc,
           (array_agg(l.etapa ORDER BY l.sequencial DESC NULLS LAST)
              FILTER (WHERE l.etapa IS NOT NULL))[1] AS etapa_ultima,
           (array_agg(l.etapa_descricao ORDER BY l.sequencial DESC NULLS LAST)
              FILTER (WHERE l.etapa IS NOT NULL))[1] AS etapa_ultima_desc,
           -- API-018: com parcela aberta COM VALOR, a urgência (prazo, dias_para_prazo,
           -- data_previsao_mais_urgente) vem só delas, a mesma "parcela aberta" da
           -- carteira do PCP (fn_carteira_pcp_linhas): linha de valor 0, como o
           -- original zerado (SQL 014d), não deixa o pedido atrasado nem vencendo
           -- hoje. Sem nenhuma parcela aberta com valor, como antes (todas as linhas).
           CASE WHEN bool_or(l.aberta_com_valor)
                THEN min(l.dias_para_prazo) FILTER (WHERE l.aberta_com_valor)
                ELSE min(l.dias_para_prazo) END AS dias_urgente,
           CASE WHEN bool_or(l.aberta_com_valor)
                THEN (array_agg(l.data_previsao ORDER BY l.dias_para_prazo, l.sequencial NULLS FIRST)
                        FILTER (WHERE l.dias_para_prazo IS NOT NULL AND l.aberta_com_valor))[1]
                ELSE (array_agg(l.data_previsao ORDER BY l.dias_para_prazo, l.sequencial NULLS FIRST)
                        FILTER (WHERE l.dias_para_prazo IS NOT NULL))[1] END AS previsao_urgente,
           (array_agg(l.cidade_destinatario ORDER BY l.sequencial NULLS FIRST)
              FILTER (WHERE l.cidade_destinatario IS NOT NULL))[1] AS cidade,
           (array_agg(l.estado_destinatario ORDER BY l.sequencial NULLS FIRST)
              FILTER (WHERE l.cidade_destinatario IS NOT NULL))[1] AS estado,
           -- SQL 014: o que decide o encerramento por saldo.
           count(*) FILTER (WHERE COALESCE(l.sequencial, 0) > 0)::integer AS qtd_parciais_reais,
           bool_or(l.aberta_com_valor) AS alguma_aberta_com_valor,
           bool_or(l.fat_valido) AS algum_fat_valido,
           max(l.data_fat10) FILTER (WHERE l.fat_valido) AS ultimo_faturamento,
           -- Previsão de referência (Q7 revista em 21/10): a do original; sem ela,
           -- a mais antiga das parciais (o original entra pelo cabeçalho, em ped).
           min(substr(l.data_previsao, 1, 10))
             FILTER (WHERE COALESCE(l.sequencial, 0) > 0 AND l.data_previsao ~ '^\d{4}-\d{2}-\d{2}') AS previsao_parciais_min,
           -- SQL 015: carteira do pedido = parcelas abertas com valor; a previsão mais
           -- cedo entre elas decide o desvio.
           COALESCE(sum(l.total_pedido_venda) FILTER (WHERE l.aberta_com_valor), 0)::numeric(15,2) AS valor_carteira,
           min(substr(l.data_previsao, 1, 10))
             FILTER (WHERE l.aberta_com_valor AND l.data_previsao ~ '^\d{4}-\d{2}-\d{2}') AS previsao_aberta_min,
           jsonb_agg(jsonb_build_object(
             'codigo_pedido_omie', l.codigo_pedido_omie,
             'sequencial', l.sequencial,
             'data_inclusao', l.data_inclusao,
             'total_pedido_venda', l.total_pedido_venda,
             'etapa', l.etapa,
             'etapa_descricao', l.etapa_descricao,
             'etapa_posicao', l.etapa_posicao,
             'situacao', l.situacao,
             'situacao_omie', l.situacao_omie,
             'autorizado', l.autorizado, 'denegado', l.denegado, 'faturado', l.faturado,
             'cancelado', l.cancelado, 'devolvido', l.devolvido,
             'devolucao_parcial', l.devolucao_parcial, 'encerrado', l.encerrado, 'manual', l.manual,
             'data_previsao', l.data_previsao,
             'prazo', l.prazo,
             'dias_para_prazo', l.dias_para_prazo,
             'data_faturamento', l.data_faturamento,
             'nota_fiscal', l.nota_fiscal,
             'categoria', l.categoria,
             'codigo_categoria', l.codigo_categoria,
             'obs_pedido', l.obs_pedido,
             'grupo', l.grupo,
             'status_refaturamento', l.status_refaturamento
           ) ORDER BY l.sequencial NULLS FIRST, l.codigo_pedido_omie) AS parciais
      FROM l
     GROUP BY l.codigo_empresa, l.pedido_venda
  ), ped AS (
    SELECT c.codigo_empresa,
           c.is_track_record,
           c.pedido_venda,
           c.codigo_pedido_omie,
           c.data_inclusao,
           c.codigo_cliente,
           COALESCE(c.razao_social_destinatario, c.destinatario, c.codigo_cliente) AS cliente,
           c.destinatario,
           c.razao_social_destinatario,
           c.cnpj_cpf_destinatario,
           a.cidade AS cidade_destinatario,
           a.estado AS estado_destinatario,
           c.codigo_vendedor,
           c.vendedor,
           c.numero_contrato,
           c.tipo_contrato,
           c.codigo_categoria,
           c.categoria,
           c.grupo,
           a.valor_total,
           a.qtd_parciais,
           a.parciais_faturadas,
           a.algum_faturado AS faturado,
           CASE WHEN a.n_situacoes = 1 THEN a.uma_situacao
                WHEN a.parciais_faturadas > 0 THEN 'faturado_parcial'
                ELSE 'misto' END AS situacao_base,
           -- Etapa atual do pedido em aberto: 1ª linha não faturada (senão a última).
           -- Com p_encerrar_por_saldo (padrão), o original zerado não conta (SQL 014d);
           -- com false, o cálculo antigo.
           CASE WHEN COALESCE(p_encerrar_por_saldo, false)
                THEN COALESCE(a.etapa_aberta_sz, a.etapa_ultima)
                ELSE COALESCE(a.etapa_aberta, a.etapa_ultima) END AS etapa_base,
           CASE WHEN COALESCE(p_encerrar_por_saldo, false)
                THEN CASE WHEN a.etapa_aberta_sz IS NOT NULL THEN a.etapa_aberta_sz_desc ELSE a.etapa_ultima_desc END
                ELSE CASE WHEN a.etapa_aberta IS NOT NULL THEN a.etapa_aberta_desc ELSE a.etapa_ultima_desc END
           END AS etapa_base_descricao,
           -- Pedido encerrado por saldo: a etapa da última parcial faturada (SQL 014d).
           COALESCE(a.etapa_ultima_fat, a.etapa_ultima) AS etapa_encerrado,
           CASE WHEN a.etapa_ultima_fat IS NOT NULL THEN a.etapa_ultima_fat_desc ELSE a.etapa_ultima_desc END AS etapa_encerrado_desc,
           a.previsao_urgente,
           a.dias_urgente,
           bp.numero_pedido IS NOT NULL AS em_blacklist,
           bp.motivo AS motivo_blacklist,
           unaccent(upper(COALESCE(c.destinatario, '') || ' ' || COALESCE(c.razao_social_destinatario, ''))) LIKE '%YPFB%' AS eh_ypfb,
           a.etapas,
           a.flags,
           a.parciais,
           (COALESCE(c.total_pedido_venda, 0) = 0 AND a.valor_total > 0 AND a.qtd_parciais_reais > 0) AS saldo_zerado,
           COALESCE(c.faturado, false) AS cab_faturado,
           COALESCE(c.encerrado, false) AS cab_encerrado,
           COALESCE(a.alguma_aberta_com_valor, false) AS alguma_aberta_com_valor,
           COALESCE(a.algum_fat_valido, false) AS algum_fat_valido,
           a.ultimo_faturamento,
           COALESCE(CASE WHEN c.data_previsao ~ '^\d{4}-\d{2}-\d{2}' THEN substr(c.data_previsao, 1, 10) END,
                    a.previsao_parciais_min) AS previsao_referencia,
           -- SQL 015: desvio de previsão e marca "Avanço" do diligenciador.
           a.valor_carteira,
           (to_date(a.previsao_aberta_min, 'YYYY-MM-DD') - c.data_inclusao)::integer AS dias_previsao_inclusao,
           mk.marcada_por AS avanco_marcado_por,
           mk.marcada_em AS avanco_marcado_em
      FROM cab c
      JOIN agg a ON a.codigo_empresa = c.codigo_empresa AND a.pedido_venda = c.pedido_venda
      LEFT JOIN core_vendas_faturamento.blacklist_pedidos bp
        ON bp.codigo_empresa = c.codigo_empresa
       AND bp.numero_pedido = c.pedido_venda
       AND bp.deleted_at IS NULL
      LEFT JOIN core_vendas_faturamento.pedido_marcacao_pcp mk
        ON mk.codigo_empresa = c.codigo_empresa
       AND mk.numero_pedido = c.pedido_venda
       AND mk.marcacao = 'avanco'
       AND mk.removida_em IS NULL
  ), enc AS (
    SELECT p.*,
           (p.valor_total > 0
            AND (p.saldo_zerado OR p.cab_faturado)
            AND p.algum_fat_valido
            AND NOT p.alguma_aberta_com_valor
            AND NOT p.cab_encerrado
            AND p.situacao_base NOT IN ('cancelado', 'devolvido', 'devolucao_parcial', 'denegado', 'encerrado')
           ) AS encerrado_por_saldo
      FROM ped p
  ), fin AS (
    SELECT e.*,
           (e.encerrado_por_saldo AND COALESCE(p_encerrar_por_saldo, false)) AS fecha,
           CASE WHEN e.encerrado_por_saldo THEN e.ultimo_faturamento END AS data_encerramento_calculada,
           CASE WHEN e.encerrado_por_saldo AND e.ultimo_faturamento IS NOT NULL AND e.previsao_referencia IS NOT NULL
                     AND e.ultimo_faturamento > e.previsao_referencia
                THEN (to_date(e.ultimo_faturamento, 'YYYY-MM-DD') - to_date(e.previsao_referencia, 'YYYY-MM-DD'))::integer
           END AS dias_atraso_no_encerramento
      FROM enc e
  ), res AS (
    SELECT f.codigo_empresa, f.is_track_record, f.pedido_venda, f.codigo_pedido_omie, f.data_inclusao,
           f.codigo_cliente, f.cliente, f.destinatario, f.razao_social_destinatario, f.cnpj_cpf_destinatario,
           f.cidade_destinatario, f.estado_destinatario, f.codigo_vendedor, f.vendedor,
           f.numero_contrato, f.tipo_contrato, f.codigo_categoria, f.categoria, f.grupo,
           f.valor_total, f.qtd_parciais, f.parciais_faturadas, f.faturado,
           CASE WHEN f.fecha THEN 'faturado_encerrado' ELSE f.situacao_base END AS situacao,
           CASE WHEN f.fecha THEN f.etapa_encerrado ELSE f.etapa_base END AS etapa_atual,
           CASE WHEN f.fecha THEN f.etapa_encerrado_desc ELSE f.etapa_base_descricao END AS etapa_atual_descricao,
           CASE WHEN f.fecha THEN NULL ELSE f.previsao_urgente END AS data_previsao_mais_urgente,
           CASE WHEN f.fecha THEN NULL ELSE f.dias_urgente END AS dias_para_prazo,
           CASE WHEN f.fecha THEN NULL ELSE core_vendas_faturamento.fn_pedido_prazo(f.dias_urgente) END AS prazo,
           f.em_blacklist, f.motivo_blacklist, f.eh_ypfb,
           CASE WHEN f.fecha THEN
             (SELECT jsonb_agg(CASE WHEN x.e->'dias_para_prazo' <> 'null'::jsonb
                                    THEN x.e || jsonb_build_object('prazo', NULL, 'dias_para_prazo', NULL)
                                    ELSE x.e END ORDER BY x.i)
                FROM jsonb_array_elements(f.parciais) WITH ORDINALITY AS x(e, i))
           ELSE f.parciais END AS parciais,
           f.saldo_zerado,
           f.encerrado_por_saldo,
           f.data_encerramento_calculada,
           (f.dias_atraso_no_encerramento IS NOT NULL) AS encerrado_em_atraso,
           f.dias_atraso_no_encerramento,
           COALESCE(f.dias_previsao_inclusao <= COALESCE(p_desvio_dias, 10), false) AS desvio_previsao,
           f.dias_previsao_inclusao,
           f.valor_carteira,
           (f.valor_carteira > 0 AND NOT f.em_blacklist) AS em_carteira,
           (f.avanco_marcado_em IS NOT NULL) AS avanco,
           f.avanco_marcado_por,
           f.avanco_marcado_em,
           f.etapas,
           f.flags
      FROM fin f
  )
  SELECT r.codigo_empresa, r.is_track_record, r.pedido_venda, r.codigo_pedido_omie, r.data_inclusao,
         r.codigo_cliente, r.cliente, r.destinatario, r.razao_social_destinatario, r.cnpj_cpf_destinatario,
         r.cidade_destinatario, r.estado_destinatario, r.codigo_vendedor, r.vendedor,
         r.numero_contrato, r.tipo_contrato, r.codigo_categoria, r.categoria, r.grupo,
         r.valor_total, r.qtd_parciais, r.parciais_faturadas, r.faturado, r.situacao,
         r.etapa_atual, r.etapa_atual_descricao, r.data_previsao_mais_urgente, r.dias_para_prazo, r.prazo,
         -- Pedido sem preço (rascunho) não conta como atrasado nem como "atenção";
         -- pedido encerrado (p_encerrar_por_saldo, padrão true) tem prazo NULL, logo também não.
         COALESCE(r.valor_total > 0 AND r.prazo IN ('atrasado', 'vence_hoje'), false) AS precisa_atencao,
         r.em_blacklist, r.motivo_blacklist, r.eh_ypfb, r.parciais,
         r.saldo_zerado, r.encerrado_por_saldo, r.data_encerramento_calculada,
         r.encerrado_em_atraso, r.dias_atraso_no_encerramento,
         r.desvio_previsao, r.dias_previsao_inclusao, r.valor_carteira, r.em_carteira,
         r.avanco, r.avanco_marcado_por,
         CASE WHEN r.avanco_marcado_por IS NOT NULL THEN auth.fn_nome_usuario(r.avanco_marcado_por) END,
         r.avanco_marcado_em
    FROM res r
   WHERE (p_em_blacklist IS NULL OR r.em_blacklist = p_em_blacklist)
     AND (p_desvio IS NULL OR r.desvio_previsao = p_desvio)
     AND (p_avanco IS NULL OR r.avanco = p_avanco)
     AND (p_carteira IS NULL OR r.em_carteira = p_carteira)
     AND (p_prazo IS NULL OR r.prazo IS NOT DISTINCT FROM NULLIF(p_prazo, 'sem_prazo'))
     AND (p_etapa IS NULL OR p_etapa = ANY (r.etapas))
     AND (p_grupo IS NULL
          OR (p_grupo = 'LIQUIDO' AND r.grupo IS NULL)
          OR r.grupo = p_grupo)
     AND (p_situacao IS NULL
          OR (p_situacao IN ('faturado_parcial', 'misto', 'aberto', 'faturado_encerrado') AND r.situacao = p_situacao)
          OR (p_situacao NOT IN ('faturado_parcial', 'misto', 'aberto', 'faturado_encerrado') AND p_situacao = ANY (r.flags)))
     AND (p_q IS NULL OR btrim(p_q) = ''
          OR r.pedido_venda ILIKE '%' || btrim(p_q) || '%'
          OR unaccent(COALESCE(r.cliente, '') || ' ' || COALESCE(r.destinatario, '') || ' '
                      || COALESCE(r.vendedor, '')) ILIKE '%' || unaccent(btrim(p_q)) || '%'
          OR (regexp_replace(p_q, '\D', '', 'g') <> ''
              AND regexp_replace(COALESCE(r.cnpj_cpf_destinatario, ''), '\D', '', 'g')
                  LIKE '%' || regexp_replace(p_q, '\D', '', 'g') || '%'))
$$;


--
-- TOC entry 7360 (class 0 OID 0)
-- Dependencies: 640
-- Name: FUNCTION fn_pedidos_venda(p_inicio date, p_fim date, p_is_track_record boolean, p_codigo_empresa uuid, p_codigo_vendedor text[], p_pedido_venda text, p_excluir_orcamento boolean, p_q text, p_situacao text, p_etapa integer, p_prazo text, p_grupo text, p_em_blacklist boolean, p_encerrar_por_saldo boolean, p_desvio boolean, p_avanco boolean, p_carteira boolean, p_desvio_dias integer); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_pedidos_venda(p_inicio date, p_fim date, p_is_track_record boolean, p_codigo_empresa uuid, p_codigo_vendedor text[], p_pedido_venda text, p_excluir_orcamento boolean, p_q text, p_situacao text, p_etapa integer, p_prazo text, p_grupo text, p_em_blacklist boolean, p_encerrar_por_saldo boolean, p_desvio boolean, p_avanco boolean, p_carteira boolean, p_desvio_dias integer) IS 'Contrato 05 (P1–P5), SQL 014, SQL 015 e API-018: 1 linha por pedido (codigo_empresa, pedido_venda) com parciais[] (jsonb, por sequencial). valor_total = soma dos sequenciais (sem orçamento). situacao: a das parciais, ou faturado_parcial / misto. etapa_atual: 1ª parcial não faturada (senão a última); com p_encerrar_por_saldo (padrão), o original zerado (cabeçalho com valor 0) não conta como aberto (014d). prazo: o da parcial mais urgente; com parcela aberta COM VALOR (valor > 0, sem faturado/cancelado/denegado/devolvido/encerrado), só entre elas (API-018: linha de valor 0, como o original zerado, não conta), a mesma definição da carteira do PCP: atrasado = alguma parcela aberta com previsão antes de hoje, vence_hoje = a mais urgente vence hoje (= atrasados_pedidos / vence_hoje_pedidos de fn_carteira_pcp_resumo com p_carteira); sem parcela aberta com valor, a mais urgente entre todas as linhas sem flag de fechamento, como antes. Filtros: p_situacao = flag de alguma parcial (faturado, cancelado...) ou faturado_parcial/misto/aberto/faturado_encerrado; p_etapa = alguma parcial; p_prazo inclui sem_prazo; p_grupo inclui LIQUIDO; p_q em número, cliente, vendedor e CNPJ. SQL 014 (sempre calculado): saldo_zerado = original (cabeçalho) com valor 0, pedido com valor > 0 e ao menos uma parcial; encerrado_por_saldo = valor > 0 e (saldo_zerado ou original faturado) e ao menos uma linha faturada (sem cancelado/denegado) e nenhuma linha com valor aberta (sem faturado/cancelado/denegado/devolvido/encerrado) e original sem a flag encerrado do Omie e situação fora de cancelado/devolvido/devolucao_parcial/denegado/encerrado; data_encerramento_calculada = última data_faturamento das linhas faturadas (AAAA-MM-DD); encerrado_em_atraso / dias_atraso_no_encerramento = encerramento depois da previsão de referência: a data_previsao do original (sequencial 0/cabeçalho); sem ela, a mais antiga das parciais (Q7 revista em 21/10, migration 014c). p_encerrar_por_saldo (padrão true desde a 014b; false = cálculo antigo): o pedido encerrado_por_saldo vira situacao faturado_encerrado, sem prazo (prazo, dias_para_prazo, data_previsao_mais_urgente NULL, precisa_atencao false), etapa_atual = a da última parcial faturada (014d), e a linha de valor 0 que ainda tinha prazo fica sem prazo em parciais[]. SQL 015: valor_carteira = soma das parcelas abertas (valor > 0, sem faturado/cancelado/denegado/devolvido/encerrado); em_carteira = valor_carteira > 0 e fora da blacklist; dias_previsao_inclusao = menor data_previsao das parcelas abertas menos a data_inclusao do cabeçalho (NULL sem parcela aberta com previsão; negativo = previsão antes da inclusão); desvio_previsao = dias_previsao_inclusao <= p_desvio_dias (padrão 10 dias corridos); avanco / avanco_marcado_por(_nome) / avanco_marcado_em = marca vigente ''avanco'' de pedido_marcacao_pcp. Filtros p_desvio, p_avanco, p_carteira (true/false; NULL = todos). Com p_carteira ou p_desvio = true o período (p_inicio/p_fim) é opcional. Cálculo ao vivo.';


--
-- TOC entry 884 (class 1255 OID 24083)
-- Name: fn_pedidos_venda_linhas(date, date, boolean, uuid, text[], text, boolean, boolean); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_pedidos_venda_linhas(p_inicio date, p_fim date, p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_vendedor text[] DEFAULT NULL::text[], p_pedido_venda text DEFAULT NULL::text, p_excluir_orcamento boolean DEFAULT true, p_so_carteira boolean DEFAULT false) RETURNS TABLE(codigo_empresa uuid, is_track_record boolean, pedido_venda text, codigo_pedido_omie bigint, sequencial integer, eh_cabecalho boolean, data_inclusao date, hora_inclusao text, etapa integer, etapa_descricao text, etapa_posicao integer, situacao text, situacao_omie text, autorizado boolean, denegado boolean, faturado boolean, cancelado boolean, devolvido boolean, devolucao_parcial boolean, encerrado boolean, manual boolean, data_previsao text, dias_para_prazo integer, prazo text, data_faturamento text, nota_fiscal text, total_pedido_venda numeric, codigo_categoria text, categoria text, obs_pedido text, numero_contrato text, tipo_contrato text, grupo text, status_refaturamento text, codigo_cliente text, destinatario text, razao_social_destinatario text, cnpj_cpf_destinatario text, cidade_destinatario text, estado_destinatario text, codigo_vendedor text, vendedor text, manifestacao_destinatario text, codigo_projeto text)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  v_ini  text := to_char(p_inicio, 'YYYY-MM-DD');
  v_fim  text := to_char(p_fim, 'YYYY-MM-DD');
  v_pe   uuid[];   -- pares (empresa, pedido) dos cabeçalhos
  v_pp   text[];
  v_emps uuid[];
  v_peds text[];
  v_chaves text[];
  v_sql  text;
BEGIN
  -- SQL 015: com p_so_carteira o período pode faltar (a carteira não depende da
  -- data de inclusão; "tem parcela aberta" já limita os pedidos).
  IF p_pedido_venda IS NULL AND (p_inicio IS NULL OR p_fim IS NULL) AND NOT COALESCE(p_so_carteira, false) THEN
    RAISE EXCEPTION 'fn_pedidos_venda_linhas: informe o período (p_inicio e p_fim), o pedido ou p_so_carteira.'
      USING ERRCODE = '22023';
  END IF;

  -- 1) Cabeçalhos do período, direto na tabela (usa o índice de data_inclusao;
  --    data no formato do Omie, AAAA-MM-DD, em que texto e data ordenam igual).
  IF COALESCE(p_is_track_record, false) THEN
    SELECT array_agg(h.e), array_agg(h.p) INTO v_pe, v_pp
      FROM (SELECT DISTINCT x.codigo_empresa AS e, x.numero_pedido::text AS p
              FROM historico.hst_pedidos_vendas x
             WHERE x.deleted_at IS NULL
               AND COALESCE(x.sequencial, 0) = 0
               AND (NOT p_excluir_orcamento OR x.etapa IS NULL OR x.etapa <> 0)
               AND (v_ini IS NULL OR x.data_inclusao >= v_ini)
               AND (v_fim IS NULL OR x.data_inclusao <= v_fim)
               AND (p_codigo_empresa IS NULL OR x.codigo_empresa = p_codigo_empresa)
               AND (p_codigo_vendedor IS NULL OR x.codigo_vendedor_omie = ANY (p_codigo_vendedor))
               AND (p_pedido_venda IS NULL OR x.numero_pedido = p_pedido_venda)
               -- SQL 015: só pedidos com parcela aberta com valor (carteira).
               AND (NOT COALESCE(p_so_carteira, false) OR EXISTS (
                     SELECT 1 FROM historico.hst_pedidos_vendas y
                      WHERE y.codigo_empresa = x.codigo_empresa AND y.numero_pedido = x.numero_pedido
                        AND y.deleted_at IS NULL
                        AND (NOT p_excluir_orcamento OR y.etapa IS NULL OR y.etapa <> 0)
                        AND COALESCE(y.valor_total_pedido, 0) > 0
                        AND NOT (y.faturado OR y.cancelado OR y.denegado OR y.devolvido OR y.encerrado)))) h;
  ELSE
    SELECT array_agg(h.e), array_agg(h.p) INTO v_pe, v_pp
      FROM (SELECT DISTINCT x.codigo_empresa AS e, x.numero_pedido::text AS p
              FROM core_vendas_faturamento.pedidos_vendas x
             WHERE x.deleted_at IS NULL
               AND COALESCE(x.sequencial, 0) = 0
               AND (NOT p_excluir_orcamento OR x.etapa IS NULL OR x.etapa <> 0)
               AND (v_ini IS NULL OR x.data_inclusao >= v_ini)
               AND (v_fim IS NULL OR x.data_inclusao <= v_fim)
               AND (p_codigo_empresa IS NULL OR x.codigo_empresa = p_codigo_empresa)
               AND (p_codigo_vendedor IS NULL OR x.codigo_vendedor_omie = ANY (p_codigo_vendedor))
               AND (p_pedido_venda IS NULL OR x.numero_pedido = p_pedido_venda)
               -- SQL 015: só pedidos com parcela aberta com valor (carteira).
               AND (NOT COALESCE(p_so_carteira, false) OR EXISTS (
                     SELECT 1 FROM core_vendas_faturamento.pedidos_vendas y
                      WHERE y.codigo_empresa = x.codigo_empresa AND y.numero_pedido = x.numero_pedido
                        AND y.deleted_at IS NULL
                        AND (NOT p_excluir_orcamento OR y.etapa IS NULL OR y.etapa <> 0)
                        AND COALESCE(y.valor_total_pedido, 0) > 0
                        AND NOT (y.faturado OR y.cancelado OR y.denegado OR y.devolvido OR y.encerrado)))) h;
  END IF;

  IF v_pe IS NULL THEN
    RETURN;
  END IF;

  -- 2) As famílias inteiras, pela vw_vendas_planilha (mesma classificação `grupo`,
  --    etapa_descricao etc.). O filtro por empresa/pedido_venda desce até as
  --    tabelas (são as colunas de partição da view). SQL dinâmico para o plano
  --    sair com os valores reais (arrays grandes viram busca por hash).
  v_sql := $q$
  SELECT v.codigo_empresa,
         v.is_track_record,
         v.pedido_venda::text,
         v.codigo_pedido_omie,
         v.sequencial::integer,
         COALESCE(v.sequencial, 0) = 0,
         v.data_inclusao,
         v.hora_inclusao::text,
         v.etapa::integer,
         v.etapa_descricao::text,
         (SELECT ef.posicao FROM core_vendas_faturamento.vw_etapas_fluxo_pedido ef
           WHERE ef.codigo_empresa = v.codigo_empresa AND ef.codigo_etapa = v.etapa
           LIMIT 1),
         core_vendas_faturamento.fn_pedido_situacao_parcial(v.cancelado, v.devolvido, v.devolucao_parcial,
           v.denegado, v.encerrado, v.faturado, v.manual, v.autorizado),
         v.situacao::text,
         v.autorizado, v.denegado, v.faturado, v.cancelado,
         v.devolvido, v.devolucao_parcial, v.encerrado, v.manual,
         v.data_previsao::text,
         d.dias,
         core_vendas_faturamento.fn_pedido_prazo(d.dias),
         v.data_faturamento::text,
         v.nota_fiscal::text,
         v.total_pedido_venda::numeric,
         v.codigo_categoria::text,
         v.categoria::text,
         v.obs_pedido::text,
         v.numero_contrato::text,
         v.tipo_contrato::text,
         v.grupo::text,
         v.status_refaturamento::text,
         v.codigo_cliente::text,
         v.destinatario::text,
         v.razao_social_destinatario::text,
         v.cnpj_cpf_destinatario::text,
         v.cidade_destinatario::text,
         v.estado_destinatario::text,
         v.codigo_vendedor::text,
         v.vendedor::text,
         v.manifestacao_destinatario::text,
         v.codigo_projeto::text
    FROM core_vendas_faturamento.vw_vendas_planilha v
   CROSS JOIN LATERAL (
     SELECT core_vendas_faturamento.fn_pedido_dias_para_prazo(v.data_previsao, v.faturado, v.cancelado,
              v.denegado, v.devolvido, v.encerrado) AS dias
   ) d
   WHERE v.is_track_record = $1
     AND v.deleted_at IS NULL
     AND (NOT $2 OR v.etapa IS NULL OR v.etapa <> 0)
  $q$;

  SELECT array_agg(DISTINCT x) INTO v_emps FROM unnest(v_pe) x;
  SELECT array_agg(DISTINCT x) INTO v_peds FROM unnest(v_pp) x;
  SELECT array_agg(e::text || '|' || p) INTO v_chaves FROM unnest(v_pe, v_pp) AS h(e, p);
  RETURN QUERY EXECUTE v_sql
    || ' AND v.codigo_empresa = ANY ($3) AND v.pedido_venda = ANY ($4)'
    || ' AND (v.codigo_empresa::text || ''|'' || v.pedido_venda::text) = ANY ($5)'
    USING COALESCE(p_is_track_record, false), p_excluir_orcamento, v_emps, v_peds, v_chaves;
END $_$;


