--

COMMENT ON FUNCTION core_vendas_faturamento.fn_pedidos_venda_linhas(p_inicio date, p_fim date, p_is_track_record boolean, p_codigo_empresa uuid, p_codigo_vendedor text[], p_pedido_venda text, p_excluir_orcamento boolean, p_so_carteira boolean) IS 'Contrato 05 (P1/P2) e SQL 015: parciais dos PEDIDOS cujo cabeçalho (sequencial 0/nulo, não excluído, fora de orçamento) foi incluído entre p_inicio e p_fim — ou do pedido p_pedido_venda, em qualquer data. Traz a família inteira, com situacao, prazo e posição da etapa. Filtro de vendedor/empresa vale para o cabeçalho. SQL 015: p_so_carteira = só pedidos com alguma parcela aberta com valor (valor > 0, sem faturado/cancelado/denegado/devolvido/encerrado); com ele o período é opcional (a carteira não depende da data de inclusão).';


--
-- TOC entry 883 (class 1255 OID 24087)
-- Name: fn_pedidos_venda_resumo(date, date, boolean, uuid, text[], boolean, text, text, integer, text, text, boolean, boolean, boolean, boolean, boolean, integer); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_pedidos_venda_resumo(p_inicio date, p_fim date, p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_vendedor text[] DEFAULT NULL::text[], p_excluir_orcamento boolean DEFAULT true, p_q text DEFAULT NULL::text, p_situacao text DEFAULT NULL::text, p_etapa integer DEFAULT NULL::integer, p_prazo text DEFAULT NULL::text, p_grupo text DEFAULT NULL::text, p_incluir_blacklist boolean DEFAULT false, p_encerrar_por_saldo boolean DEFAULT true, p_desvio boolean DEFAULT NULL::boolean, p_avanco boolean DEFAULT NULL::boolean, p_carteira boolean DEFAULT NULL::boolean, p_desvio_dias integer DEFAULT 10) RETURNS TABLE(pedidos bigint, faturados bigint, atrasados bigint, vence_hoje bigint, vai_vencer bigint, em_dia bigint, valor_total numeric, valor_bruto numeric, valor_deducoes numeric, valor_liquido numeric, pedidos_em_blacklist bigint, faturados_encerrados bigint, encerrados_em_atraso bigint)
    LANGUAGE sql STABLE
    AS $$
  WITH p AS (
    SELECT x.*, (COALESCE(p_incluir_blacklist, false) OR NOT x.em_blacklist) AS conta
      FROM core_vendas_faturamento.fn_pedidos_venda(
             p_inicio, p_fim, p_is_track_record, p_codigo_empresa, p_codigo_vendedor, NULL, p_excluir_orcamento,
             p_q, p_situacao, p_etapa, p_prazo, p_grupo, NULL, p_encerrar_por_saldo,
             p_desvio, p_avanco, p_carteira, p_desvio_dias) x
  )
  -- Uma passada só. `conta` = entra nos números (blacklist fora, salvo pedido).
  SELECT count(*) FILTER (WHERE conta),
         count(*) FILTER (WHERE conta AND faturado),
         count(*) FILTER (WHERE conta AND valor_total > 0 AND prazo = 'atrasado'),
         count(*) FILTER (WHERE conta AND valor_total > 0 AND prazo = 'vence_hoje'),
         count(*) FILTER (WHERE conta AND valor_total > 0 AND prazo = 'vai_vencer'),
         count(*) FILTER (WHERE conta AND valor_total > 0 AND prazo = 'em_dia'),
         COALESCE(sum(valor_total) FILTER (WHERE conta), 0)::numeric(15,2),
         -- Mesma conta da vw_vendas_planilha_resumo: bruto sem YPFB; deduções = grupos G*.
         COALESCE(sum(valor_total) FILTER (WHERE conta AND NOT eh_ypfb), 0)::numeric(15,2),
         COALESCE(sum(valor_total) FILTER (WHERE conta AND grupo IS NOT NULL), 0)::numeric(15,2),
         (COALESCE(sum(valor_total) FILTER (WHERE conta AND NOT eh_ypfb), 0)
          - COALESCE(sum(valor_total) FILTER (WHERE conta AND grupo IS NOT NULL), 0))::numeric(15,2),
         count(*) FILTER (WHERE em_blacklist),
         count(*) FILTER (WHERE conta AND encerrado_por_saldo),
         count(*) FILTER (WHERE conta AND encerrado_em_atraso)
    FROM p
$$;


