--
-- TOC entry 800 (class 1255 OID 20697)
-- Name: fn_pedidos_vendas_liberacao_regras(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_pedidos_vendas_liberacao_regras() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.liberado_em := now();                                -- sempre do servidor
  ELSE
    NEW.liberado_por := OLD.liberado_por;
    NEW.liberado_em  := OLD.liberado_em;
    IF OLD.importado_mes_em IS NOT NULL THEN
      IF NEW.acompanhamento_qualidade IS DISTINCT FROM OLD.acompanhamento_qualidade THEN
        RAISE EXCEPTION 'Pedido % já foi importado pelo PCP (MES) em %: o acompanhamento da Qualidade não pode mais ser alterado pelo vendedor.',
          OLD.numero_pedido, to_char(OLD.importado_mes_em AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI')
          USING ERRCODE = '23514';
      END IF;
      -- LOG-56: o faturamento em partes segue a mesma trava.
      IF NEW.faturar_em_partes IS DISTINCT FROM OLD.faturar_em_partes THEN
        RAISE EXCEPTION 'Pedido % já foi importado pelo PCP (MES) em %: o faturamento em partes não pode mais ser alterado pelo vendedor.',
          OLD.numero_pedido, to_char(OLD.importado_mes_em AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI')
          USING ERRCODE = '23514';
      END IF;
      NEW.importado_mes_em := OLD.importado_mes_em;          -- não desfaz nem reescreve
      NEW.importado_mes_referencia := OLD.importado_mes_referencia;
    END IF;
  END IF;
  NEW.updated_at := date_trunc('milliseconds', now());
  RETURN NEW;
END $$;


