--

CREATE FUNCTION core_vendas_faturamento.fn_pedidos_vendas_manuais_historico_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- pg_trigger_depth() > 1: cascata da FK (unidade/pedido que mudou de chave
  -- ou foi expurgado), não um comando direto na tabela.
  IF current_setting('avhub.pv_manual_expurgo', true) = 'on' OR pg_trigger_depth() > 1 THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  RAISE EXCEPTION 'O histórico do pedido de venda manual não pode ser alterado nem apagado.'
    USING ERRCODE = '23514';
END $$;


