CREATE FUNCTION core_vendas_faturamento.fn_pedidos_vendas_manual_autoria() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.created_by IS NULL THEN
      RAISE EXCEPTION 'Pedido manual: informe quem cadastrou (created_by ou token do usuário).'
        USING ERRCODE = '23514';
    END IF;
  ELSIF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
    IF NEW.deleted_by IS NULL THEN
      RAISE EXCEPTION 'Pedido manual: informe quem excluiu (deleted_by ou token do usuário).'
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.updated_by IS NULL THEN
    RAISE EXCEPTION 'Pedido manual: informe quem alterou (updated_by ou token do usuário).'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


