CREATE FUNCTION core_vendas_faturamento.fn_pedidos_vendas_manual_historico() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  c_campos CONSTANT text[] := ARRAY[
    'numero_pedido', 'etapa', 'data_inclusao', 'hora_inclusao', 'data_previsao',
    'codigo_cliente', 'codigo_vendedor_omie', 'codigo_categoria', 'codigo_projeto',
    'numero_contrato', 'obs_venda', 'valor_total_pedido'];
  v_new     jsonb := to_jsonb(NEW);
  v_old     jsonb;
  v_alt     jsonb := '{}'::jsonb;
  v_campo   text;
  v_op      text;
  v_usuario uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_op := 'cadastro';
    v_usuario := NEW.created_by;
    FOREACH v_campo IN ARRAY c_campos LOOP
      IF COALESCE(v_new -> v_campo, 'null'::jsonb) <> 'null'::jsonb THEN
        v_alt := v_alt || jsonb_build_object(v_campo, jsonb_build_object('de', NULL, 'para', v_new -> v_campo));
      END IF;
    END LOOP;
  ELSE
    v_old := to_jsonb(OLD);
    FOREACH v_campo IN ARRAY c_campos LOOP
      IF (v_old -> v_campo) IS DISTINCT FROM (v_new -> v_campo) THEN
        v_alt := v_alt || jsonb_build_object(v_campo, jsonb_build_object('de', v_old -> v_campo, 'para', v_new -> v_campo));
      END IF;
    END LOOP;
    IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
      v_op := 'exclusao';
      v_usuario := NEW.deleted_by;
    ELSIF OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL THEN
      v_op := 'restauracao';
      v_usuario := NEW.updated_by;
    ELSIF v_alt = '{}'::jsonb THEN
      RETURN NULL;   -- só autoria/updated_at/situação mudou: nada a registrar
    ELSE
      v_op := 'alteracao';
      v_usuario := NEW.updated_by;
    END IF;
  END IF;

  INSERT INTO core_vendas_faturamento.pedidos_vendas_manuais_historico
         (codigo_empresa, codigo_pedido_omie, numero_pedido, operacao, alteracoes, alterado_por)
  VALUES (NEW.codigo_empresa, NEW.codigo_pedido_omie, NEW.numero_pedido, v_op, v_alt,
          CASE WHEN EXISTS (SELECT 1 FROM auth.usuarios WHERE id = v_usuario) THEN v_usuario END);
  RETURN NULL;
END $$;


