--
-- TOC entry 933 (class 1255 OID 20780)
-- Name: fn_pedidos_vendas_manual_validar(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_pedidos_vendas_manual_validar() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  -- INSERT, ou linha que acabou de virar manual: confere tudo.
  v_tudo boolean := TG_OP = 'INSERT' OR NOT COALESCE(OLD.manual, false);
  v_hoje date    := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_data date;
BEGIN
  IF NOT NEW.manual THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' AND NEW.codigo_pedido_omie >= 0 THEN
    RAISE EXCEPTION 'Pedido manual precisa do código negativo de seq_pedidos_vendas_manual (recebido: %).', NEW.codigo_pedido_omie
      USING ERRCODE = '23514';
  END IF;

  IF NEW.sequencial IS NOT NULL THEN
    RAISE EXCEPTION 'Pedido manual não tem parcelas: sequencial deve ficar vazio.' USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.manual AND NEW.numero_pedido IS DISTINCT FROM OLD.numero_pedido THEN
    RAISE EXCEPTION 'O número do pedido manual (%) é gerado pelo sistema e não muda.', OLD.numero_pedido
      USING ERRCODE = '23514';
  END IF;

  IF v_tudo OR NEW.data_inclusao IS DISTINCT FROM OLD.data_inclusao THEN
    IF NEW.data_inclusao IS NULL OR NEW.data_inclusao !~ '^\d{4}-\d{2}-\d{2}$' THEN
      RAISE EXCEPTION 'Pedido manual: data_inclusao é obrigatória, no formato AAAA-MM-DD (recebido: %).',
        COALESCE(NEW.data_inclusao, 'nulo') USING ERRCODE = '23514';
    END IF;
    BEGIN
      v_data := NEW.data_inclusao::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'Pedido manual: data_inclusao % não é uma data válida.', NEW.data_inclusao
        USING ERRCODE = '23514';
    END;
    IF v_data > v_hoje THEN
      RAISE EXCEPTION 'Pedido manual: data_inclusao % está no futuro.', NEW.data_inclusao
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_tudo OR NEW.hora_inclusao IS DISTINCT FROM OLD.hora_inclusao THEN
    IF NEW.hora_inclusao IS NULL OR NEW.hora_inclusao !~ '^([01]\d|2[0-3]):[0-5]\d:[0-5]\d$' THEN
      RAISE EXCEPTION 'Pedido manual: hora_inclusao é obrigatória, no formato HH:MM:SS (recebido: %).',
        COALESCE(NEW.hora_inclusao, 'nulo') USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.data_previsao IS NOT NULL AND (v_tudo OR NEW.data_previsao IS DISTINCT FROM OLD.data_previsao) THEN
    IF NEW.data_previsao !~ '^\d{4}-\d{2}-\d{2}$' THEN
      RAISE EXCEPTION 'Pedido manual: data_previsao deve estar no formato AAAA-MM-DD (recebido: %).', NEW.data_previsao
        USING ERRCODE = '23514';
    END IF;
    BEGIN
      v_data := NEW.data_previsao::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'Pedido manual: data_previsao % não é uma data válida.', NEW.data_previsao
        USING ERRCODE = '23514';
    END;
  END IF;

  IF v_tudo OR NEW.valor_total_pedido IS DISTINCT FROM OLD.valor_total_pedido THEN
    IF NEW.valor_total_pedido IS NULL OR NEW.valor_total_pedido <= 0 THEN
      RAISE EXCEPTION 'Pedido manual: valor_total_pedido é obrigatório e maior que zero.' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_tudo OR NEW.codigo_cliente IS DISTINCT FROM OLD.codigo_cliente
     OR NEW.codigo_empresa IS DISTINCT FROM OLD.codigo_empresa THEN
    IF NULLIF(btrim(NEW.codigo_cliente), '') IS NULL THEN
      RAISE EXCEPTION 'Pedido manual: codigo_cliente é obrigatório.' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM core.parceiros p
                    WHERE p.codigo_empresa = NEW.codigo_empresa
                      AND p.codigo_parceiro_omie = NEW.codigo_cliente
                      AND p.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'Pedido manual: cliente % não está cadastrado nesta unidade.', NEW.codigo_cliente
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_tudo OR NEW.codigo_vendedor_omie IS DISTINCT FROM OLD.codigo_vendedor_omie
     OR NEW.codigo_empresa IS DISTINCT FROM OLD.codigo_empresa THEN
    IF NULLIF(btrim(NEW.codigo_vendedor_omie), '') IS NULL THEN
      RAISE EXCEPTION 'Pedido manual: codigo_vendedor_omie é obrigatório.' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.vendedores v
                    WHERE v.codigo_empresa = NEW.codigo_empresa
                      AND v.codigo_vendedor_omie = NEW.codigo_vendedor_omie
                      AND v.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'Pedido manual: vendedor % não está cadastrado nesta unidade.', NEW.codigo_vendedor_omie
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.etapa IS NOT NULL
     AND (v_tudo OR NEW.etapa IS DISTINCT FROM OLD.etapa OR NEW.codigo_empresa IS DISTINCT FROM OLD.codigo_empresa) THEN
    IF NEW.etapa = 0 THEN
      RAISE EXCEPTION 'Pedido manual: etapa 0 é orçamento — o pedido não entraria nas vendas.' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM core.etapas_faturamento ef
                    WHERE ef.codigo_empresa = NEW.codigo_empresa
                      AND ef.codigo_operacao = '11'
                      AND ef.codigo_etapa::numeric = NEW.etapa
                      AND ef.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'Pedido manual: etapa % não existe nesta unidade (etapas de faturamento, operação 11).', NEW.etapa
        USING ERRCODE = '23514';
    END IF;
  END IF;

  -- Número = MAN- + código (sem o sinal), 6 dígitos no mínimo. Ignora o que
  -- vier no INSERT: o número do pedido manual é sempre do sistema.
  IF TG_OP = 'INSERT' THEN
    NEW.numero_pedido := 'MAN-' || lpad((-NEW.codigo_pedido_omie)::text, 6, '0');
  END IF;

  RETURN NEW;
END $_$;


