-- Name: FUNCTION fn_pedidos_vendas_manual_validar(); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_pedidos_vendas_manual_validar() IS 'Contrato 30. Trigger BEFORE INSERT/UPDATE de pedidos_vendas, só manual = true: exige código negativo e gera o número no cadastro (MAN- + código: -1 → MAN-000001, único entre as unidades) e não deixa mudá-lo; sem parcela (sequencial nulo); data_inclusao AAAA-MM-DD não futura, hora_inclusao HH:MM:SS, data_previsao válida, valor_total_pedido > 0, cliente e vendedor cadastrados na unidade, etapa (se vier) existente na unidade e diferente de 0. No UPDATE só confere o que mudou (tudo, se a linha acabou de virar manual). Erro 23514 com a mensagem.';


--
-- TOC entry 807 (class 1255 OID 20082)
-- Name: fn_proximo_numero_documento(uuid, character varying, character varying); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_proximo_numero_documento(p_empresa uuid, p_tipo character varying, p_prefixo character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE v_n bigint;
BEGIN
  -- INSERT ... ON CONFLICT DO UPDATE em um único statement: atômico, e cria a
  -- linha do contador na primeira emissão da unidade sem precisar de seed.
  INSERT INTO core_vendas_faturamento.contadores_documento AS c
         (codigo_empresa, tipo, ultimo_numero)
  VALUES (p_empresa, p_tipo, 1)
  ON CONFLICT (codigo_empresa, tipo)
  DO UPDATE SET ultimo_numero = c.ultimo_numero + 1,
                updated_at    = now()
  RETURNING ultimo_numero INTO v_n;

  -- 6 dígitos: OC-000001. Cabe folgado no cCodIntPed (20) do Omie mesmo
  -- quando passar de 1 milhão de documentos.
  RETURN p_prefixo || lpad(v_n::text, 6, '0');
END $$;


--
-- TOC entry 739 (class 1255 OID 20383)
-- Name: fn_quadro_deducoes(text, numeric, bigint, numeric, bigint, numeric, bigint, numeric, bigint, numeric, bigint, numeric, bigint, numeric, bigint, numeric, bigint); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_quadro_deducoes(p_lado text, p_bruto_valor numeric, p_bruto_qtd bigint, p_g1_valor numeric, p_g1_qtd bigint, p_g2_valor numeric, p_g2_qtd bigint, p_g2p_valor numeric, p_g2p_qtd bigint, p_g3_valor numeric, p_g3_qtd bigint, p_g4_valor numeric, p_g4_qtd bigint, p_g5_valor numeric, p_g5_qtd bigint, p_g6_valor numeric, p_g6_qtd bigint) RETURNS TABLE(ordem integer, secao text, tipo text, rotulo text, grupo text, valor numeric, qtd bigint, pct_total numeric)
    LANGUAGE sql IMMUTABLE
    AS $$
  WITH t AS (
    SELECT COALESCE(p_bruto_valor, 0)::numeric(15,2) AS bruto,
           (COALESCE(p_g1_valor,0) + COALESCE(p_g2_valor,0) + COALESCE(p_g2p_valor,0) + COALESCE(p_g3_valor,0)
            + COALESCE(p_g4_valor,0) + COALESCE(p_g5_valor,0) + COALESCE(p_g6_valor,0))::numeric(15,2) AS ded_valor,
           (COALESCE(p_g1_qtd,0) + COALESCE(p_g2_qtd,0) + COALESCE(p_g2p_qtd,0) + COALESCE(p_g3_qtd,0)
            + COALESCE(p_g4_qtd,0) + COALESCE(p_g5_qtd,0) + COALESCE(p_g6_qtd,0))::bigint AS ded_qtd
  )
  SELECT l.ordem, l.secao, l.tipo, l.rotulo, l.grupo, l.valor::numeric(15,2), l.qtd,
         round(100::numeric * l.valor / NULLIF(t.bruto, 0::numeric), 1)
    FROM t
   CROSS JOIN LATERAL (VALUES
     (1, CASE WHEN p_lado = 'faturamento' THEN '1 · COMPOSIÇÃO DO FATURAMENTO BRUTO' ELSE '1 · COMPOSIÇÃO DAS VENDAS BRUTAS' END,
         'bruto', 'Total Bruto (sem YPFB)', NULL::text, t.bruto, COALESCE(p_bruto_qtd, 0)),
     (2, '2 · DEDUÇÕES', 'deducao', '(−) Cancelado', 'G1', COALESCE(p_g1_valor,0), COALESCE(p_g1_qtd,0)),
     (3, '2 · DEDUÇÕES', 'deducao', '(−) Devolvido', 'G2', COALESCE(p_g2_valor,0), COALESCE(p_g2_qtd,0)),
     (4, '2 · DEDUÇÕES', 'deducao', '(−) Devolvido parcialmente', 'G2P', COALESCE(p_g2p_valor,0), COALESCE(p_g2p_qtd,0)),
     (5, '2 · DEDUÇÕES', 'deducao', '(−) Recusado (denegado ou manifestação não realizada)', 'G3', COALESCE(p_g3_valor,0), COALESCE(p_g3_qtd,0)),
     (6, '2 · DEDUÇÕES', 'deducao', '(−) Aços Vital Chile (operações no exterior) e Aços Vital', 'G4', COALESCE(p_g4_valor,0), COALESCE(p_g4_qtd,0)),
     (7, '2 · DEDUÇÕES', 'deducao', '(−) Aços Vital Vendedor (operações internas)', 'G5', COALESCE(p_g5_valor,0), COALESCE(p_g5_qtd,0)),
     (8, '2 · DEDUÇÕES', 'deducao', '(−) Refaturamento', 'G6', COALESCE(p_g6_valor,0), COALESCE(p_g6_qtd,0)),
     (9, '2 · DEDUÇÕES', 'total_deducoes', 'TOTAL DE DEDUÇÕES', NULL::text, t.ded_valor, t.ded_qtd),
     (10, '3 · RESULTADO', 'liquido',
         CASE WHEN p_lado = 'faturamento' THEN 'FATURAMENTO LÍQUIDO' ELSE 'VENDAS LÍQUIDAS' END,
         NULL::text, t.bruto - t.ded_valor, NULL::bigint)
   ) AS l(ordem, secao, tipo, rotulo, grupo, valor, qtd)
   ORDER BY l.ordem
$$;


