CREATE FUNCTION core_vendas_faturamento.fn_quadro_deducoes_jsonb(p_lado text, p_bruto_valor numeric, p_bruto_qtd bigint, p_g1_valor numeric, p_g1_qtd bigint, p_g2_valor numeric, p_g2_qtd bigint, p_g2p_valor numeric, p_g2p_qtd bigint, p_g3_valor numeric, p_g3_qtd bigint, p_g4_valor numeric, p_g4_qtd bigint, p_g5_valor numeric, p_g5_qtd bigint, p_g6_valor numeric, p_g6_qtd bigint, p_rotulo_bruto text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_agg(jsonb_build_object(
           'ordem', q.ordem, 'secao', q.secao, 'tipo', q.tipo,
           'rotulo', CASE WHEN q.tipo = 'bruto' AND p_rotulo_bruto IS NOT NULL THEN p_rotulo_bruto ELSE q.rotulo END,
           'grupo', q.grupo, 'valor', q.valor,
           CASE WHEN p_lado = 'faturamento' THEN 'qtd_nfs' ELSE 'qtd_pedidos' END, q.qtd,
           'pct_total', q.pct_total)
         ORDER BY q.ordem)
    FROM core_vendas_faturamento.fn_quadro_deducoes(p_lado,
           p_bruto_valor, p_bruto_qtd, p_g1_valor, p_g1_qtd, p_g2_valor, p_g2_qtd, p_g2p_valor, p_g2p_qtd,
           p_g3_valor, p_g3_qtd, p_g4_valor, p_g4_qtd, p_g5_valor, p_g5_qtd, p_g6_valor, p_g6_qtd) q
$$;


