CREATE FUNCTION core_vendas_faturamento.fn_quadro_deducoes_somar(p_lado text, p_quadros jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  WITH l AS (
    SELECT x->>'tipo' AS tipo, x->>'grupo' AS grupo,
           COALESCE((x->>'valor')::numeric, 0) AS valor,
           COALESCE((x->>'qtd_pedidos')::bigint, (x->>'qtd_nfs')::bigint, 0) AS qtd
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_quadros) = 'array' THEN p_quadros ELSE '[]'::jsonb END) q(quadro)
     CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(q.quadro) = 'array' THEN q.quadro ELSE '[]'::jsonb END) x
  ), s AS (
    SELECT COALESCE(sum(valor) FILTER (WHERE tipo = 'bruto'), 0) AS bv, COALESCE(sum(qtd) FILTER (WHERE tipo = 'bruto'), 0)::bigint AS bq,
           COALESCE(sum(valor) FILTER (WHERE grupo = 'G1'), 0) AS g1v,  COALESCE(sum(qtd) FILTER (WHERE grupo = 'G1'), 0)::bigint AS g1q,
