CREATE FUNCTION core_vendas_faturamento.fn_req_eventos_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.id_ordem_compra IS NULL AND OLD.id_ordem_compra IS NOT NULL
     AND (to_jsonb(NEW) - 'id_ordem_compra') = (to_jsonb(OLD) - 'id_ordem_compra') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'requisicoes_compra_eventos é histórico: só inserção' USING ERRCODE = '23514';
END $$;


