--
-- TOC entry 957 (class 1255 OID 23668)
-- Name: fn_req_referencia_mes_marcar(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_req_referencia_mes_marcar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF TG_TABLE_NAME = 'requisicoes_compra' THEN
    v_ids := ARRAY[NEW.id];

  ELSIF TG_TABLE_NAME = 'ordens_compra' THEN
    -- A OC mudou (aprovada, cancelada, excluída, renumerada): marca as
    -- requisições atendidas por ela e a do cabeçalho (a nova e a anterior).
    SELECT COALESCE(array_agg(DISTINCT x.id), ARRAY[]::uuid[]) INTO v_ids
      FROM (
        SELECT r.id
          FROM core_vendas_faturamento.requisicoes_compra r
         WHERE r.id_ordem_compra = NEW.id
        UNION ALL
        SELECT NEW.id_requisicao WHERE NEW.id_requisicao IS NOT NULL
        UNION ALL
        SELECT OLD.id_requisicao WHERE OLD.id_requisicao IS NOT NULL
      ) x;
  END IF;

  IF cardinality(v_ids) = 0 THEN
    RETURN NULL;
  END IF;

  INSERT INTO core_vendas_faturamento.requisicoes_compra_referencia_mes AS t (id_requisicao, alterado_em)
  SELECT r.id, clock_timestamp()
    FROM core_vendas_faturamento.requisicoes_compra r
   WHERE r.id = ANY (v_ids)
     AND (
           -- entra: do av-hub (a do MES o MES já conhece) e com pedido de venda
           (r.id_origem IS NULL AND r.numero_pedido_venda IS NOT NULL)
           -- já entrou: marca também a saída (pedido retirado, cancelada,
           -- excluída, ganhou id_origem)
           OR EXISTS (SELECT 1 FROM core_vendas_faturamento.requisicoes_compra_referencia_mes m
                       WHERE m.id_requisicao = r.id)
         )
  ON CONFLICT (id_requisicao)
  DO UPDATE SET alterado_em = GREATEST(EXCLUDED.alterado_em, t.alterado_em);

  RETURN NULL;
END
$$;


