--
-- TOC entry 851 (class 1255 OID 19815)
-- Name: fn_requisicoes_compra_status(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_requisicoes_compra_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;

  -- 'atendida' é decidida SÓ pela trigger da OC (4.3), que roda como
  -- superusuário do banco e não passa por aqui. Qualquer outro caminho que
  -- tente marcar/desmarcar atendida é rejeitado.
  IF pg_trigger_depth() = 1 THEN
    IF NEW.status = 'atendida' OR OLD.status = 'atendida' THEN
      RAISE EXCEPTION
        'status "atendida" é definido automaticamente ao emitir/cancelar uma ordem de compra, não por alteração direta'
        USING ERRCODE = '23514';
    END IF;

    -- aberta <-> em_cotacao <-> cancelada, em qualquer direção (cancelada
    -- reabre). O que NÃO existe é atravessar para/de atendida.
    IF NOT (OLD.status IN ('aberta','em_cotacao','cancelada')
            AND NEW.status IN ('aberta','em_cotacao','cancelada')) THEN
      RAISE EXCEPTION 'transição de % para % não é permitida', OLD.status, NEW.status
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- TOC entry 532 (class 1255 OID 21297)
-- Name: fn_requisicoes_compra_zz_eventos(); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_requisicoes_compra_zz_eventos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM core_vendas_faturamento.fn_req_evento(NEW.id, 'requisicao_recebida', NEW.created_at, NULL,
      jsonb_build_object('numero_requisicao', NEW.numero_requisicao), NEW.created_by);
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'cancelada' THEN
      PERFORM core_vendas_faturamento.fn_req_evento(NEW.id, 'requisicao_cancelada', NULL, NULL,
        jsonb_build_object('origem', NEW.cancelada_por_origem, 'motivo', NEW.motivo_cancelamento), NEW.updated_by);
    ELSIF OLD.status = 'cancelada' THEN
      PERFORM core_vendas_faturamento.fn_req_evento(NEW.id, 'requisicao_reaberta', NULL, NULL, NULL, NEW.updated_by);
    ELSIF OLD.status = 'aberta' AND NEW.status = 'em_cotacao' THEN
      PERFORM core_vendas_faturamento.fn_req_evento(NEW.id, 'em_cotacao', NULL, NULL, NULL, NEW.updated_by);
    END IF;
  END IF;
  RETURN NULL;
END $$;


