--
-- TOC entry 952 (class 1255 OID 17313)
-- Name: fn_resolver_refaturamento(date); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_resolver_refaturamento(p_periodo date) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_candidato      RECORD;
    v_match          text[];
    v_tipo_ref       text;
    v_num_ref        text;
    v_aponta_totvs   boolean;
    v_status         text;
    v_motivo         text;
    v_nivel          smallint;
    v_visitados      bigint[];
    v_origem         RECORD;
    v_encontrado     boolean;
    v_cnt_novos      integer := 0;
    v_cnt_permitido  integer := 0;
    v_cnt_proibido   integer := 0;
    v_cnt_sem_ref    integer := 0;
    v_cnt_duplicado  integer := 0;
    v_mes_ref        date := date_trunc('month', p_periodo)::date;
    -- v9 (2026-08): multi-empresa. v_regex e v_padrao_gatilho INTACTOS.
    v_padrao_gatilho text := 'refat|reaft';
    v_regex          text := '(?:REFATURAMENTO|REAFTURAMENTO|REFATORAMENTO|REFATURO|REFATORO)\s+(?:\S+\s+){0,3}(PV|NF|PARCIAL)\.?\s*n?[°º]?\.?\s*(\d{4,6})(?:[/-]\d+)?';
BEGIN
    FOR v_candidato IN
        SELECT pv.codigo_pedido_omie,
               pv.obs_venda,
               pv.codigo_empresa                                     -- [2]
        FROM core_vendas_faturamento.pedidos_vendas pv
        WHERE pv.deleted_at IS NULL
          AND to_date(pv.data_inclusao, 'YYYY-MM-DD') >= v_mes_ref
          AND to_date(pv.data_inclusao, 'YYYY-MM-DD') < (v_mes_ref + INTERVAL '1 month')
          AND (
                pv.codigo_categoria = '1.01.96'
                OR pv.obs_venda ~* v_padrao_gatilho
              )
          AND NOT EXISTS (
                SELECT 1 FROM core_vendas_faturamento.refaturamentos r
                WHERE r.codigo_pedido_omie = pv.codigo_pedido_omie
                  AND r.codigo_empresa     = pv.codigo_empresa       -- [3]
              )
    LOOP
        v_cnt_novos    := v_cnt_novos + 1;
        v_aponta_totvs := COALESCE(v_candidato.obs_venda ~* 'TOTVS|TOTUS', false);
        v_nivel        := 0;
        v_match        := regexp_match(v_candidato.obs_venda, v_regex, 'i');

        IF v_match IS NULL THEN
            v_status   := 'Sem Referência';
            v_motivo   := 'Nenhum padrão PV/NF/PARCIAL reconhecido em obs_pedido';
            v_tipo_ref := NULL;
            v_num_ref  := NULL;
            v_cnt_sem_ref := v_cnt_sem_ref + 1;

        ELSIF v_aponta_totvs THEN
            v_tipo_ref := upper(v_match[1]);
            v_num_ref  := v_match[2];
            v_status   := 'Proibido';
            v_motivo   := 'Referência aponta para sistema legado TOTVS/TOTUS';
            v_cnt_proibido := v_cnt_proibido + 1;

        ELSE
            v_tipo_ref  := upper(v_match[1]);
            v_num_ref   := v_match[2];
            v_visitados := ARRAY[v_candidato.codigo_pedido_omie];
            v_status    := NULL;

            -- A cadeia é resolvida DENTRO da empresa do candidato: um
            -- refaturamento da empresa A referencia um pedido da empresa A.
            WHILE v_status IS NULL AND v_nivel < 5 LOOP
                v_nivel      := v_nivel + 1;
                v_origem     := NULL;
                v_encontrado := false;

                IF v_tipo_ref = 'NF' THEN
                    SELECT n.codigo_pedido_omie, pv2.obs_venda, pv2.codigo_categoria
                    INTO v_origem
                    FROM core_vendas_faturamento.notas_fiscais n
                    LEFT JOIN core_vendas_faturamento.pedidos_vendas pv2
                           ON pv2.codigo_pedido_omie = n.codigo_pedido_omie
                          AND pv2.codigo_empresa     = n.codigo_empresa        -- [4]
                    WHERE n.numero_nf LIKE '%' || v_num_ref
                      AND n.codigo_empresa = v_candidato.codigo_empresa        -- [4]
                      AND n.deleted_at IS NULL
                      AND to_date(n.data_emissao, 'YYYY-MM-DD') >= v_mes_ref
                      AND to_date(n.data_emissao, 'YYYY-MM-DD') < (v_mes_ref + INTERVAL '1 month')
                    LIMIT 1;
                    v_encontrado := FOUND;

                ELSE
                    IF EXISTS (
                        SELECT 1 FROM core_vendas_faturamento.pedidos_vendas pv2
                        WHERE pv2.numero_pedido LIKE '%' || v_num_ref
                          AND pv2.codigo_empresa = v_candidato.codigo_empresa  -- [4]
                          AND pv2.deleted_at IS NULL
                          AND pv2.data_faturamento IS NOT NULL
                          AND to_date(pv2.data_faturamento, 'YYYY-MM-DD') < v_mes_ref
                    ) THEN
                        v_status := 'Proibido';
                        v_motivo := format('%s %s faturado em mês anterior — sempre inválido, mesmo com entregas correntes', v_tipo_ref, v_num_ref);
                    ELSE
                        SELECT pv2.codigo_pedido_omie, pv2.obs_venda, pv2.codigo_categoria
                        INTO v_origem
                        FROM core_vendas_faturamento.pedidos_vendas pv2
                        WHERE pv2.numero_pedido LIKE '%' || v_num_ref
                          AND pv2.codigo_empresa = v_candidato.codigo_empresa  -- [4]
                          AND pv2.deleted_at IS NULL
                          AND (
                                (pv2.data_faturamento IS NOT NULL
                                 AND to_date(pv2.data_faturamento, 'YYYY-MM-DD') >= v_mes_ref
                                 AND to_date(pv2.data_faturamento, 'YYYY-MM-DD') < (v_mes_ref + INTERVAL '1 month'))
                                OR (
                                    (pv2.cancelado OR pv2.devolvido)
                                    AND EXISTS (
                                        SELECT 1 FROM core_vendas_faturamento.notas_fiscais nf2
                                        WHERE nf2.codigo_pedido_omie = pv2.codigo_pedido_omie
                                          AND nf2.codigo_empresa     = pv2.codigo_empresa   -- [4]
                                          AND nf2.deleted_at IS NULL
                                          AND to_date(nf2.data_emissao, 'YYYY-MM-DD') >= v_mes_ref
                                          AND to_date(nf2.data_emissao, 'YYYY-MM-DD') < (v_mes_ref + INTERVAL '1 month')
                                    )
                                )
                              )
                        LIMIT 1;
                        v_encontrado := FOUND;

                        IF NOT v_encontrado AND v_tipo_ref = 'PARCIAL' THEN
                            SELECT n.codigo_pedido_omie, pv2.obs_venda, pv2.codigo_categoria
                            INTO v_origem
                            FROM core_vendas_faturamento.notas_fiscais n
                            LEFT JOIN core_vendas_faturamento.pedidos_vendas pv2
                                   ON pv2.codigo_pedido_omie = n.codigo_pedido_omie
                                  AND pv2.codigo_empresa     = n.codigo_empresa             -- [4]
                            WHERE n.numero_nf LIKE '%' || v_num_ref
                              AND n.codigo_empresa = v_candidato.codigo_empresa             -- [4]
                              AND n.deleted_at IS NULL
                              AND to_date(n.data_emissao, 'YYYY-MM-DD') >= v_mes_ref
                              AND to_date(n.data_emissao, 'YYYY-MM-DD') < (v_mes_ref + INTERVAL '1 month')
                            LIMIT 1;
                            v_encontrado := FOUND;
                        END IF;
                    END IF;
                END IF;

                IF v_status IS NOT NULL THEN
                    EXIT;

                ELSIF NOT v_encontrado THEN
                    v_status := 'Proibido';
                    v_motivo := format('Referência %s %s não encontrada/inválida no período', v_tipo_ref, v_num_ref);

                ELSIF v_origem.codigo_pedido_omie IS NOT NULL AND v_origem.codigo_pedido_omie = ANY (v_visitados) THEN
                    v_status := 'Proibido';
                    v_motivo := 'Cadeia cíclica detectada';

                ELSE
                    IF v_origem.codigo_pedido_omie IS NOT NULL THEN
                        v_visitados := array_append(v_visitados, v_origem.codigo_pedido_omie);
                    END IF;

                    IF v_origem.codigo_pedido_omie IS NOT NULL
                       AND (v_origem.codigo_categoria = '1.01.96' OR v_origem.obs_venda ~* v_padrao_gatilho) THEN
                        IF v_origem.obs_venda ~* 'TOTVS|TOTUS' THEN
                            v_status := 'Proibido';
                            v_motivo := 'Referência da cadeia aponta para sistema legado TOTVS/TOTUS';
                        ELSE
                            v_match := regexp_match(v_origem.obs_venda, v_regex, 'i');
                            IF v_match IS NULL THEN
                                v_status := 'Proibido';
                                v_motivo := 'Origem também é refaturamento, mas sem referência própria';
                            ELSE
                                v_tipo_ref := upper(v_match[1]);
                                v_num_ref  := v_match[2];
                            END IF;
                        END IF;
                    ELSE
                        v_status := 'Permitido';
                        v_motivo := format('Referência resolvida até venda genuína em %s nível(is)', v_nivel);
                    END IF;
                END IF;
            END LOOP;

            IF v_status IS NULL THEN
                v_status := 'Proibido';
                v_motivo := 'Excedeu 5 níveis de profundidade na cadeia';
            END IF;

            IF v_status = 'Permitido' THEN
                v_cnt_permitido := v_cnt_permitido + 1;
            ELSE
                v_cnt_proibido := v_cnt_proibido + 1;
            END IF;
        END IF;

        INSERT INTO core_vendas_faturamento.refaturamentos (
            codigo_pedido_omie, codigo_empresa, tipo_ref, num_ref, aponta_totvs,
            nivel_cadeia, status_refaturamento, motivo, periodo, computed_at
        ) VALUES (
            v_candidato.codigo_pedido_omie,
            v_candidato.codigo_empresa,                               -- [1] a causa do erro
            v_tipo_ref, v_num_ref, v_aponta_totvs,
            v_nivel, v_status, v_motivo, v_mes_ref, now()
        );
    END LOOP;

    -- Duplicidade agora é POR EMPRESA.
    WITH duplicados AS (
        SELECT codigo_empresa, tipo_ref, num_ref                      -- [5]
        FROM core_vendas_faturamento.refaturamentos
        WHERE periodo = v_mes_ref
          AND tipo_ref IS NOT NULL
          AND num_ref IS NOT NULL
        GROUP BY codigo_empresa, tipo_ref, num_ref                    -- [5]
        HAVING count(*) > 1
    )
    UPDATE core_vendas_faturamento.refaturamentos r
    SET status_refaturamento = 'Proibido',
        motivo       = 'Referência duplicada: mais de um pedido aponta para a mesma origem',
        computed_at  = now()
    FROM duplicados d
    WHERE r.periodo        = v_mes_ref
      AND r.codigo_empresa = d.codigo_empresa                         -- [5]
      AND r.tipo_ref       = d.tipo_ref
      AND r.num_ref        = d.num_ref
      AND r.status_refaturamento IS DISTINCT FROM 'Proibido';
    GET DIAGNOSTICS v_cnt_duplicado = ROW_COUNT;

    RETURN jsonb_build_object(
        'periodo',                   v_mes_ref,
        'candidatos_novos',          v_cnt_novos,
        'permitido',                 v_cnt_permitido,
        'proibido',                  v_cnt_proibido,
        'sem_referencia',            v_cnt_sem_ref,
        'marcados_duplicados_agora', v_cnt_duplicado
    );
END;
$$;


