-- TOC entry 7387 (class 0 OID 0)
-- Dependencies: 952
-- Name: FUNCTION fn_resolver_refaturamento(p_periodo date); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_resolver_refaturamento(p_periodo date) IS 'Resolve status_refaturamento para pedidos candidatos NOVOS do período informado (incremental — não reprocessa quem já tem linha em refaturamentos). Regex de extração é v1, calibrar com obs_pedido real. Chamar antes de consultar vw_nf_classified/fechar o mês. v8: v_padrao_gatilho (detecção de candidato) alinhado com o lado vendas -- padrão aberto refat|reaft, não mais lista fechada. v_regex (extração) inalterado.';


--
-- TOC entry 774 (class 1255 OID 17315)
-- Name: fn_resolver_refaturamento_lote(integer); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_resolver_refaturamento_lote(p_meses_atras integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado  jsonb := '[]'::jsonb;
    v_i          integer;
    v_periodo    date;
    v_item       jsonb;
BEGIN
    FOR v_i IN 0..p_meses_atras LOOP
        v_periodo := (date_trunc('month', CURRENT_DATE) - (v_i || ' months')::interval)::date;
        v_item := core_vendas_faturamento.fn_resolver_refaturamento(v_periodo);
        v_resultado := v_resultado || jsonb_build_array(v_item);
    END LOOP;

    RETURN jsonb_build_object(
        'executado_em',       now(),
        'meses_cobertos',     p_meses_atras + 1,   -- [6] era +3
        'resultados_por_mes', v_resultado
    );
END;
$$;


