COMMENT ON FUNCTION core_vendas_faturamento.fn_resolver_refaturamento_lote(p_meses_atras integer) IS 'Roda fn_resolver_refaturamento pro mês corrente + p_meses_atras anteriores (default 2, cobrindo 3 meses). Pensada pra agendamento diário via pg_cron -- mantém os meses recentes sempre resolvidos, sem precisar de trigger em tempo real (risco de "Proibido" permanente por chegar cedo demais, ver motivo completo no histórico da conversa). Não cobre backlog histórico grande sozinha.';


--
-- TOC entry 971 (class 1255 OID 17316)
-- Name: fn_ritmo_meta_faturamento(smallint, smallint, boolean); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_ritmo_meta_faturamento(p_mes smallint, p_ano smallint, p_is_track_record boolean DEFAULT false) RETURNS TABLE(mes smallint, ano smallint, meta numeric, dias_uteis_mes bigint, dias_uteis_decorridos bigint, fat_acumulado numeric, meta_diaria_ideal numeric, meta_diaria_atual numeric, status_ritmo text)
    LANGUAGE sql STABLE
    AS $$
    WITH alvo AS (
        SELECT make_date(p_ano::integer, p_mes::integer, 1) AS ref_date
    ), dias_uteis_mes AS (
        SELECT count(*) FILTER (WHERE EXTRACT(dow FROM d.d) BETWEEN 1 AND 5) AS total_uteis
        FROM alvo, generate_series(alvo.ref_date, alvo.ref_date + INTERVAL '1 month - 1 day', '1 day') d(d)
    ), dias_uteis_decorridos AS (
        SELECT count(*) FILTER (WHERE EXTRACT(dow FROM d.d) BETWEEN 1 AND 5 AND d.d::date <= CURRENT_DATE) AS uteis_decorridos
        FROM alvo, generate_series(alvo.ref_date, alvo.ref_date + INTERVAL '1 month - 1 day', '1 day') d(d)
    ), fat_acumulado AS (
        SELECT sum(valor_nf) AS fat_acumulado
        FROM core_vendas_faturamento.vw_nf_classified, alvo
        WHERE grupo_deducao = 'LIQUIDO'
          AND is_track_record = p_is_track_record
          AND data_emissao >= alvo.ref_date
          AND data_emissao <  (alvo.ref_date + INTERVAL '1 month')
    )
    SELECT p_mes, p_ano, COALESCE(mt.meta, 0),
        COALESCE(du.total_uteis, 0), COALESCE(dd.uteis_decorridos, 0), COALESCE(fa.fat_acumulado, 0),
        CASE WHEN COALESCE(du.total_uteis, 0) = 0 THEN NULL ELSE round(mt.meta / du.total_uteis::numeric, 2) END,
        CASE WHEN COALESCE(dd.uteis_decorridos, 0) = 0 THEN NULL ELSE round(COALESCE(fa.fat_acumulado, 0) / dd.uteis_decorridos::numeric, 2) END,
        CASE
            WHEN COALESCE(du.total_uteis, 0) = 0 OR COALESCE(dd.uteis_decorridos, 0) = 0 THEN 'SEM DADOS'
            WHEN (COALESCE(fa.fat_acumulado, 0) / dd.uteis_decorridos::numeric) < (mt.meta / du.total_uteis::numeric * 0.95) THEN 'ABAIXO'
            WHEN (COALESCE(fa.fat_acumulado, 0) / dd.uteis_decorridos::numeric) > (mt.meta / du.total_uteis::numeric * 1.05) THEN 'ADIANTADO'
            ELSE 'NO RITMO'
        END
    FROM dias_uteis_mes du, dias_uteis_decorridos dd, fat_acumulado fa
    LEFT JOIN core_vendas_faturamento.metas_mensais mt ON mt.mes = p_mes AND mt.ano = p_ano AND mt.tipo = 'faturamento';
$$;


