        CASE WHEN COALESCE(du.total_uteis, 0) = 0 THEN NULL ELSE round(mt.meta / du.total_uteis::numeric, 2) END,
        CASE WHEN COALESCE(dd.uteis_decorridos, 0) = 0 THEN NULL ELSE round(COALESCE(va.vendas_acumulado, 0) / dd.uteis_decorridos::numeric, 2) END,
        CASE
            WHEN COALESCE(du.total_uteis, 0) = 0 OR COALESCE(dd.uteis_decorridos, 0) = 0 THEN 'SEM DADOS'
            WHEN (COALESCE(va.vendas_acumulado, 0) / dd.uteis_decorridos::numeric) < (mt.meta / du.total_uteis::numeric * 0.95) THEN 'ABAIXO'
            WHEN (COALESCE(va.vendas_acumulado, 0) / dd.uteis_decorridos::numeric) > (mt.meta / du.total_uteis::numeric * 1.05) THEN 'ADIANTADO'
            ELSE 'NO RITMO'
        END
    FROM dias_uteis_mes du, dias_uteis_decorridos dd, vendas_acumulado va
    LEFT JOIN core_vendas_faturamento.metas_mensais mt ON mt.mes = p_mes AND mt.ano = p_ano AND mt.tipo = 'venda';
$$;


