--
-- TOC entry 900 (class 1255 OID 17319)
-- Name: fn_snapshot_mensal(text, date); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_snapshot_mensal(p_motivo text DEFAULT 'cron_mensal'::text, p_mes_ref date DEFAULT (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_snapshot_em   timestamptz := now();
    v_mes_ref       date := date_trunc('month', p_mes_ref)::date;
    v_prox_mes      date := (v_mes_ref + INTERVAL '1 month')::date;

    v_cols_nf       text;  -- colunas em comum: notas_fiscais <-> hst_notas_fiscais
    v_cols_pv       text;  -- colunas em comum: pedidos_vendas <-> hst_pedidos_vendas
    v_cols_pvd      text;  -- colunas em comum: produto_vendas <-> hst_produto_vendas (bare)
    v_cols_pvd_src  text;  -- mesmas colunas, qualificadas "i.col" (produto_vendas aliased i)

    v_cnt_nf        bigint;
    v_cnt_pv        bigint;
    v_cnt_pvd       bigint;

    v_resultado     jsonb;
BEGIN
    -- -----------------------------------------------------------------
    -- 1) Descobre colunas em comum (por NOME) entre tabela viva e hst_.
    -- -----------------------------------------------------------------
    SELECT string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position)
      INTO v_cols_nf
      FROM information_schema.columns c
     WHERE c.table_schema = 'core_vendas_faturamento' AND c.table_name = 'notas_fiscais'
       AND EXISTS (
            SELECT 1 FROM information_schema.columns h
             WHERE h.table_schema = 'historico' AND h.table_name = 'hst_notas_fiscais'
               AND h.column_name = c.column_name
       );

    SELECT string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position)
      INTO v_cols_pv
      FROM information_schema.columns c
     WHERE c.table_schema = 'core_vendas_faturamento' AND c.table_name = 'pedidos_vendas'
       AND EXISTS (
            SELECT 1 FROM information_schema.columns h
             WHERE h.table_schema = 'historico' AND h.table_name = 'hst_pedidos_vendas'
               AND h.column_name = c.column_name
       );

    SELECT
        string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position),
        string_agg('i.' || quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position)
      INTO v_cols_pvd, v_cols_pvd_src
      FROM information_schema.columns c
     WHERE c.table_schema = 'core_vendas_faturamento' AND c.table_name = 'produto_vendas'
       AND EXISTS (
            SELECT 1 FROM information_schema.columns h
             WHERE h.table_schema = 'historico' AND h.table_name = 'hst_produto_vendas'
               AND h.column_name = c.column_name
       );

    IF v_cols_nf IS NULL THEN
        RAISE EXCEPTION 'fn_snapshot_mensal: nenhuma coluna em comum entre core_vendas_faturamento.notas_fiscais e historico.hst_notas_fiscais. Confira se as duas tabelas existem e têm nomes de coluna compatíveis.';
    END IF;
    IF v_cols_pv IS NULL THEN
        RAISE EXCEPTION 'fn_snapshot_mensal: nenhuma coluna em comum entre core_vendas_faturamento.pedidos_vendas e historico.hst_pedidos_vendas.';
    END IF;
    IF v_cols_pvd IS NULL THEN
        RAISE EXCEPTION 'fn_snapshot_mensal: nenhuma coluna em comum entre core_vendas_faturamento.produto_vendas e historico.hst_produto_vendas.';
    END IF;

    -- -----------------------------------------------------------------
    -- 2) Idempotência: apaga o mês antes de regravar.
    --    ORDEM IMPORTA: hst_produto_vendas primeiro, porque seu filtro
    --    depende de hst_notas_fiscais ainda ter as linhas do mês.
    -- -----------------------------------------------------------------
    EXECUTE format(
        'DELETE FROM historico.hst_produto_vendas pv
          WHERE EXISTS (
                SELECT 1 FROM historico.hst_notas_fiscais n
                 WHERE n.codigo_nf_omie = pv.codigo_nf_omie
                   AND n.codigo_empresa = pv.codigo_empresa
                   AND to_date(n.data_emissao::text, %L) >= %L
                   AND to_date(n.data_emissao::text, %L) <  %L)',
        'YYYY-MM-DD', v_mes_ref, 'YYYY-MM-DD', v_prox_mes
    );

    EXECUTE format(
        'DELETE FROM historico.hst_notas_fiscais
          WHERE to_date(data_emissao::text, %L) >= %L
            AND to_date(data_emissao::text, %L) <  %L',
        'YYYY-MM-DD', v_mes_ref, 'YYYY-MM-DD', v_prox_mes
    );

    EXECUTE format(
        'DELETE FROM historico.hst_pedidos_vendas
          WHERE to_date(data_inclusao::text, %L) >= %L
            AND to_date(data_inclusao::text, %L) <  %L',
        'YYYY-MM-DD', v_mes_ref, 'YYYY-MM-DD', v_prox_mes
    );

    -- -----------------------------------------------------------------
    -- 3) Congela notas_fiscais do mês.
    -- -----------------------------------------------------------------
    EXECUTE format(
        'INSERT INTO historico.hst_notas_fiscais (%1$s)
         SELECT %1$s
           FROM core_vendas_faturamento.notas_fiscais
          WHERE to_date(data_emissao::text, %2$L) >= %3$L
            AND to_date(data_emissao::text, %2$L) <  %4$L',
        v_cols_nf, 'YYYY-MM-DD', v_mes_ref, v_prox_mes
    );
    GET DIAGNOSTICS v_cnt_nf = ROW_COUNT;

    -- -----------------------------------------------------------------
    -- 4) Congela pedidos_vendas do mês.
    -- -----------------------------------------------------------------
    EXECUTE format(
        'INSERT INTO historico.hst_pedidos_vendas (%1$s)
         SELECT %1$s
           FROM core_vendas_faturamento.pedidos_vendas
          WHERE to_date(data_inclusao::text, %2$L) >= %3$L
            AND to_date(data_inclusao::text, %2$L) <  %4$L',
        v_cols_pv, 'YYYY-MM-DD', v_mes_ref, v_prox_mes
    );
    GET DIAGNOSTICS v_cnt_pv = ROW_COUNT;

    -- -----------------------------------------------------------------
    -- 5) Congela produto_vendas ligado às NFs do mês (via NF viva, já
    --    que a linha de produto não carrega data própria).
    -- -----------------------------------------------------------------
    EXECUTE format(
        'INSERT INTO historico.hst_produto_vendas (%1$s)
         SELECT %2$s
           FROM core_vendas_faturamento.produto_vendas i
           JOIN core_vendas_faturamento.notas_fiscais n
             ON n.codigo_nf_omie = i.codigo_nf_omie
            AND n.codigo_empresa = i.codigo_empresa
          WHERE to_date(n.data_emissao::text, %3$L) >= %4$L
            AND to_date(n.data_emissao::text, %3$L) <  %5$L',
        v_cols_pvd, v_cols_pvd_src, 'YYYY-MM-DD', v_mes_ref, v_prox_mes
    );
    GET DIAGNOSTICS v_cnt_pvd = ROW_COUNT;

    -- -----------------------------------------------------------------
    -- 6) Preenche snapshot_em/snapshot_mes/snapshot_motivo, SE essas
    --    colunas existirem na respectiva hst_ (checagem dinâmica --
    --    não é erro se não existirem).
    -- -----------------------------------------------------------------
    IF EXISTS (SELECT 1 FROM information_schema.columns
                WHERE table_schema='historico' AND table_name='hst_notas_fiscais'
                  AND column_name IN ('snapshot_em','snapshot_mes','snapshot_motivo')
                GROUP BY table_name HAVING count(*) = 3) THEN
        EXECUTE format(
            'UPDATE historico.hst_notas_fiscais
                SET snapshot_em = %L, snapshot_mes = %L, snapshot_motivo = %L
              WHERE to_date(data_emissao::text, %L) >= %L
                AND to_date(data_emissao::text, %L) <  %L',
            v_snapshot_em, v_mes_ref, p_motivo, 'YYYY-MM-DD', v_mes_ref, 'YYYY-MM-DD', v_prox_mes
        );
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
                WHERE table_schema='historico' AND table_name='hst_pedidos_vendas'
                  AND column_name IN ('snapshot_em','snapshot_mes','snapshot_motivo')
                GROUP BY table_name HAVING count(*) = 3) THEN
        EXECUTE format(
            'UPDATE historico.hst_pedidos_vendas
                SET snapshot_em = %L, snapshot_mes = %L, snapshot_motivo = %L
              WHERE to_date(data_inclusao::text, %L) >= %L
                AND to_date(data_inclusao::text, %L) <  %L',
            v_snapshot_em, v_mes_ref, p_motivo, 'YYYY-MM-DD', v_mes_ref, 'YYYY-MM-DD', v_prox_mes
        );
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
                WHERE table_schema='historico' AND table_name='hst_produto_vendas'
                  AND column_name IN ('snapshot_em','snapshot_mes','snapshot_motivo')
                GROUP BY table_name HAVING count(*) = 3) THEN
        EXECUTE format(
            'UPDATE historico.hst_produto_vendas pv
                SET snapshot_em = %L, snapshot_mes = %L, snapshot_motivo = %L
              WHERE EXISTS (
                    SELECT 1 FROM historico.hst_notas_fiscais n
                     WHERE n.codigo_nf_omie = pv.codigo_nf_omie
                       AND n.codigo_empresa = pv.codigo_empresa
                       AND to_date(n.data_emissao::text, %L) >= %L
                       AND to_date(n.data_emissao::text, %L) <  %L)',
            v_snapshot_em, v_mes_ref, p_motivo, 'YYYY-MM-DD', v_mes_ref, 'YYYY-MM-DD', v_prox_mes
        );
    END IF;

    -- -----------------------------------------------------------------
    v_resultado := jsonb_build_object(
        'snapshot_em',     v_snapshot_em,
        'snapshot_mes',    v_mes_ref,
        'snapshot_motivo', p_motivo,
        'rows_hst_notas_fiscais',  v_cnt_nf,
        'rows_hst_pedidos_vendas', v_cnt_pv,
        'rows_hst_produto_vendas', v_cnt_pvd
    );

    RAISE NOTICE 'Snapshot mensal (congelamento das 3 fontes): %', v_resultado;
    RETURN v_resultado;
END;
$_$;


--
-- TOC entry 7393 (class 0 OID 0)
-- Dependencies: 900
-- Name: FUNCTION fn_snapshot_mensal(p_motivo text, p_mes_ref date); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_snapshot_mensal(p_motivo text, p_mes_ref date) IS 'Único snapshot do schema. Congela notas_fiscais, pedidos_vendas e produto_vendas do mês de p_mes_ref (default: mês corrente) para historico.hst_notas_fiscais/hst_pedidos_vendas/hst_produto_vendas -- nada mais. Os relatórios pré-agregados que existiam antes (ranking, dashboard, ritmo_meta, detalhe_vendedor, situacao_pedidos etc.) foram descontinuados: qualquer fn_relatorio_x já lê o histórico sob demanda via p_is_track_record = true direto dessas 3 tabelas. Idempotente (apaga o mês antes de regravar). Colunas copiadas são descobertas em tempo de execução por NOME (interseção entre tabela viva e hst_ via information_schema) -- não assume SELECT * nem ordem posicional. produto_vendas não tem data própria: herda o mês pela NF (codigo_nf_omie + codigo_empresa). deleted_at não é filtrado na cópia -- o snapshot fotografa o estado exato de cada linha no momento do freeze.';


--
-- TOC entry 497 (class 1255 OID 20541)
-- Name: fn_sugestoes_comprador(uuid); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_sugestoes_comprador(p_id_comprador uuid) RETURNS TABLE(id_funcionario uuid, nome_funcionario text, codigo_empresa_origem uuid, nome_unidade_origem text, id_comprador_origem uuid, codigo_comprador_omie_origem text)
    LANGUAGE sql STABLE
    AS $$
  WITH alvo AS (
    SELECT c.id, c.codigo_empresa,
           regexp_replace(lower(public.unaccent(btrim(c.nome))), '\s+', ' ', 'g') AS nome_norm
      FROM core_vendas_faturamento.compradores c
     WHERE c.id = p_id_comprador
       AND c.id_funcionario IS NULL      -- já vinculado: nada a sugerir
       AND c.deleted_at IS NULL
  ),
  cand AS (
    SELECT DISTINCT ON (c2.id_funcionario)
           c2.id_funcionario,
           f.nome_completo::text        AS nome_funcionario,
           c2.codigo_empresa            AS codigo_empresa_origem,
           u.nome_fantasia::text        AS nome_unidade_origem,
           c2.id                        AS id_comprador_origem,
           c2.codigo_comprador_omie::text AS codigo_comprador_omie_origem
      FROM alvo a
      JOIN core_vendas_faturamento.compradores c2
        ON c2.codigo_empresa <> a.codigo_empresa
       AND c2.id_funcionario IS NOT NULL
       AND c2.deleted_at IS NULL
       AND regexp_replace(lower(public.unaccent(btrim(c2.nome))), '\s+', ' ', 'g') = a.nome_norm
      JOIN core.funcionarios f ON f.id = c2.id_funcionario
      LEFT JOIN core.unidades u ON u.id = c2.codigo_empresa
     -- Quem já é comprador NA UNIDADE DO ALVO não serve: o PUT daria 409
     -- (uq_compradores_funcionario_empresa).
     WHERE NOT EXISTS (
             SELECT 1 FROM core_vendas_faturamento.compradores c3
              WHERE c3.id_funcionario = c2.id_funcionario
                AND c3.codigo_empresa = a.codigo_empresa
                AND c3.deleted_at IS NULL)
     ORDER BY c2.id_funcionario, c2.ativo DESC, c2.updated_at DESC
  )
  SELECT * FROM cand ORDER BY nome_funcionario, id_funcionario;
$$;


