--

CREATE FUNCTION core_vendas_faturamento.fn_tipo_contrato(numero_contrato text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT CASE
        WHEN numero_contrato ILIKE '%SPOT%' THEN 'SPOT'
        WHEN numero_contrato ILIKE '%CONTRATO%' THEN 'CONTRATO'
        ELSE NULL
    END
$$;


