--

CREATE FUNCTION core_vendas_faturamento.fn_variacao_pct(p_atual numeric, p_anterior numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN p_anterior IS NULL OR p_anterior <= 0 THEN NULL
              ELSE round((COALESCE(p_atual, 0) - p_anterior) / p_anterior * 100, 1) END
$$;


