CREATE FUNCTION core_vendas_faturamento.fn_vendas_planilha_pedidos_classificados(p_inicio date, p_fim date, p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid, p_codigo_vendedor text[] DEFAULT NULL::text[]) RETURNS TABLE(codigo_empresa uuid, pedido_venda text, codigo_cliente text, codigo_vendedor text, data_inclusao date, valor numeric, is_ypfb boolean, grupo text)
    LANGUAGE sql STABLE
    AS $$
  WITH l AS (
    SELECT l.*
      FROM core_vendas_faturamento.fn_pedidos_venda_linhas(
             p_inicio, p_fim, p_is_track_record, p_codigo_empresa, p_codigo_vendedor, NULL, true) l
     WHERE NOT EXISTS (SELECT 1 FROM core_vendas_faturamento.blacklist_pedidos bp
                        WHERE bp.codigo_empresa = l.codigo_empresa
                          AND bp.numero_pedido = l.pedido_venda
                          AND bp.deleted_at IS NULL)
  ), familia AS (
    SELECT l.codigo_empresa, l.pedido_venda, sum(l.total_pedido_venda)::numeric(15,2) AS total_familia
      FROM l GROUP BY l.codigo_empresa, l.pedido_venda
  )
  -- Uma linha por cabeçalho, com o valor da família (igual à vw_vendas_planilha_resumo).
  SELECT l.codigo_empresa,
         l.pedido_venda,
         l.codigo_cliente,
         l.codigo_vendedor,
         l.data_inclusao,
         f.total_familia,
         unaccent(upper(COALESCE(l.destinatario, '') || ' ' || COALESCE(l.razao_social_destinatario, ''))) LIKE '%YPFB%',
         COALESCE(l.grupo, 'LIQUIDO')
    FROM l
    JOIN familia f ON f.codigo_empresa = l.codigo_empresa AND f.pedido_venda = l.pedido_venda
   WHERE l.eh_cabecalho
     AND l.data_inclusao BETWEEN p_inicio AND p_fim
$$;


