-- Name: FUNCTION fn_vendas_por_tipo_contrato(p_mes smallint, p_ano smallint, p_is_track_record boolean, p_codigo_empresa uuid); Type: COMMENT; Schema: core_vendas_faturamento; Owner: -
--

COMMENT ON FUNCTION core_vendas_faturamento.fn_vendas_por_tipo_contrato(p_mes smallint, p_ano smallint, p_is_track_record boolean, p_codigo_empresa uuid) IS 'Contrato 33 (migration 033): o filtro p_codigo_empresa é a UNIDADE DE ORIGEM do vendedor (fn_unidade_do_vendedor), com toda a venda/faturamento dele em qualquer Omie; sem filtro, nada muda.';


--
-- TOC entry 896 (class 1255 OID 17325)
-- Name: fn_vendas_realizadas_por_tipo(smallint, smallint, boolean, uuid); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_vendas_realizadas_por_tipo(p_mes smallint, p_ano smallint, p_is_track_record boolean DEFAULT false, p_codigo_empresa uuid DEFAULT NULL::uuid) RETURNS TABLE(mes smallint, ano smallint, tipo_contrato text, valor_vendas numeric, qtd_pedidos bigint, percentual_valor_vendas numeric, percentual_qtd_pedidos numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH alvo AS (
        SELECT make_date(p_ano::integer, p_mes::integer, 1) AS ref_date
    ),
    base AS (
        SELECT p_mes AS mes, p_ano AS ano, COALESCE(tipo_contrato, 'SEM CLASSIFICAÇÃO') AS tipo_contrato,
            sum(total_pedido) AS valor_vendas, count(DISTINCT numero_pedido) AS qtd_pedidos
        FROM core_vendas_faturamento.vw_vendas_base, alvo
        WHERE grupo = 'LIQUIDO'
          AND is_track_record = p_is_track_record
      AND (p_codigo_empresa IS NULL OR core_vendas_faturamento.fn_unidade_do_vendedor(codigo_empresa, cod_vendedor) = p_codigo_empresa)
          AND data_inclusao >= alvo.ref_date
          AND data_inclusao <  (alvo.ref_date + INTERVAL '1 month')
        GROUP BY 1, 2, COALESCE(tipo_contrato, 'SEM CLASSIFICAÇÃO')
    )
    SELECT mes, ano, tipo_contrato, valor_vendas, qtd_pedidos,
        ROUND(valor_vendas / NULLIF(SUM(valor_vendas) OVER (), 0) * 100, 2) AS percentual_valor_vendas,
        ROUND(qtd_pedidos::numeric / NULLIF(SUM(qtd_pedidos) OVER (), 0)::numeric * 100, 2) AS percentual_qtd_pedidos
    FROM base
    ORDER BY tipo_contrato;
$$;


