--
-- TOC entry 786 (class 1255 OID 22446)
-- Name: fn_vendedor_na_lista(uuid, text, text[]); Type: FUNCTION; Schema: core_vendas_faturamento; Owner: -
--

CREATE FUNCTION core_vendas_faturamento.fn_vendedor_na_lista(p_codigo_empresa uuid, p_codigo_vendedor text, p_vendedores text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT p_vendedores IS NULL
      OR EXISTS (SELECT 1 FROM unnest(p_vendedores) AS x(v)
                  WHERE btrim(x.v) = p_codigo_vendedor
                     OR lower(btrim(x.v)) = p_codigo_empresa::text || ':' || p_codigo_vendedor);
$$;


