-- TOC entry 523 (class 1255 OID 17326)
-- Name: fn_sync_nvl_permissao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_nvl_permissao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.nvl_manual = TRUE THEN
        RETURN NEW;
    END IF;
 
    SELECT nvl_permissao INTO NEW.nvl_permissao
    FROM core.cargos
    WHERE id = NEW.id_cargo;
 
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cargo ID "%" não encontrado na tabela core.cargos.', NEW.id_cargo;
    END IF;
 
    RETURN NEW;
END;
$$;


--
-- TOC entry 873 (class 1255 OID 23725)
-- Name: fn_updated_at_se_mudou(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_updated_at_se_mudou() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Quem gravou mandou updated_at: respeita o valor.
  IF NEW.updated_at IS DISTINCT FROM OLD.updated_at THEN
    RETURN NEW;
  END IF;
  -- Nada mudou além de updated_at/updated_by (ex.: upsert da pipeline com os
  -- mesmos valores): mantém o updated_at de antes.
  IF (to_jsonb(NEW) - 'updated_at' - 'updated_by') IS NOT DISTINCT FROM (to_jsonb(OLD) - 'updated_at' - 'updated_by') THEN
    RETURN NEW;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;


--
-- TOC entry 7406 (class 0 OID 0)
-- Dependencies: 873
-- Name: FUNCTION fn_updated_at_se_mudou(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_updated_at_se_mudou() IS 'Contrato 51 (S18): trigger BEFORE UPDATE. Se quem gravou mandou updated_at, mantém; se a linha não mudou (fora updated_at/updated_by), mantém o updated_at anterior; senão updated_at = now(). Diferente de public.set_updated_at(), não move updated_at em UPDATE sem mudança (upsert diário da pipeline), para o ?alterado_desde= não devolver a tabela inteira. Não preenche updated_by.';


