-- Name: vw_permissoes_usuario; Type: VIEW; Schema: auth; Owner: -
--

CREATE VIEW auth.vw_permissoes_usuario AS
 SELECT u.id AS id_usuario,
    u.email,
    u.username,
    p.id AS id_perfil,
    p.nome AS perfil_nome,
    t.id AS id_tela,
    t.nome AS tela_nome,
    t.slug,
    t.id_parent,
    t.ordem,
    pm.pode_visualizar,
    pm.pode_criar,
    pm.pode_editar,
    pm.pode_deletar,
    pm.pode_aprovar,
    pm.pode_exportar
   FROM ((((auth.usuarios u
     JOIN auth.usuarios_perfis up ON ((up.id_usuario = u.id)))
     JOIN auth.perfis p ON (((p.id = up.id_perfil) AND (p.deleted_at IS NULL))))
     JOIN auth.permissoes pm ON (((pm.id_perfil = p.id) AND (pm.deleted_at IS NULL))))
     JOIN auth.telas t ON (((t.id = pm.id_tela) AND (t.deleted_at IS NULL) AND (t.ativo = true))))
  WHERE ((u.ativo = true) AND (u.deleted_at IS NULL));


