--
-- TOC entry 372 (class 1259 OID 20281)
-- Name: vw_funcionarios_lista; Type: VIEW; Schema: core; Owner: -
--

CREATE VIEW core.vw_funcionarios_lista AS
 SELECT f.id,
    f.nome_completo,
    f.id_cargo,
    c.nome AS nome_cargo,
    f.id_setor,
    s.nome AS nome_setor,
    f.codigo_empresa,
    u.nome_fantasia AS nome_unidade,
    f.email,
    f.photo_url,
    f.contrato_tipo,
    f.data_admissao,
    f.data_desligamento,
    f.telefone,
    f.celular,
    core.fn_funcionario_situacao(f.data_desligamento) AS situacao,
    core.fn_funcionario_pendencias((f.email)::text, (f.telefone)::text, (f.celular)::text, f.data_admissao, (f.contrato_tipo)::text, f.photo_url) AS pendencias
   FROM (((core.funcionarios f
     LEFT JOIN core.cargos c ON ((c.id = f.id_cargo)))
     LEFT JOIN core.setores s ON ((s.id = f.id_setor)))
     LEFT JOIN core.unidades u ON ((u.id = f.codigo_empresa)));


