--

COMMENT ON VIEW core.vw_funcionarios_lista IS 'Contrato 02 (Funcionários): visão "lista" de GET /funcionarios e base de GET /funcionarios/resumo. Nunca contém cpf, rg, cnpj, data_nascimento, endereço nem created_by/updated_by.';


--
-- TOC entry 469 (class 1259 OID 24787)
-- Name: vw_unidades_cabecalho; Type: VIEW; Schema: core; Owner: -
--

CREATE VIEW core.vw_unidades_cabecalho AS
 SELECT id,
    sigla,
    razao_social,
    nome_fantasia,
    COALESCE(NULLIF(btrim((nome_documento)::text), ''::text), upper((nome_fantasia)::text)) AS nome_documento,
    NULLIF(regexp_replace(upper((COALESCE(cnpj, ''::character varying))::text), '[^0-9A-Z]'::text, ''::text, 'g'::text), ''::text) AS cnpj,
    inscricao_estadual AS ie,
    (concat_ws(', '::text, NULLIF((logradouro)::text, ''::text), NULLIF((numero)::text, ''::text), NULLIF((complemento)::text, ''::text)) || COALESCE((' - '::text || NULLIF((bairro)::text, ''::text)), ''::text)) AS endereco_linha1,
    (concat_ws(' - '::text, cidade, estado) || COALESCE((', '::text || NULLIF((cep)::text, ''::text)), ''::text)) AS endereco_linha2,
    estado AS uf,
    COALESCE(NULLIF(btrim((telefone_documento)::text), ''::text), (telefone)::text) AS telefone,
    COALESCE(NULLIF(btrim((email_documento)::text), ''::text), (email)::text) AS email,
    COALESCE(NULLIF(btrim((site_documento)::text), ''::text), (homepage)::text) AS site,
    logo_url,
    tipo_unidade,
    ordem_exibicao,
    updated_at
   FROM core.unidades u
  WHERE (deleted_at IS NULL);


