--
-- TOC entry 377 (class 1259 OID 20365)
-- Name: vw_vagas; Type: VIEW; Schema: core_aprovacao_de_vagas; Owner: -
--

CREATE VIEW core_aprovacao_de_vagas.vw_vagas AS
 SELECT v.id,
    v.data_solicitacao,
    v.solicitante,
    v.id_setor,
    s.nome AS setor_nome,
    v.cargo_vaga,
    v.observacao_motivo,
    v.quantidade,
    v.tipo_vaga,
    v.salario,
    v.insalubridade,
    v.vr,
    v.custo_total,
    v.observacao,
    v.situacao,
    v.observacao_situacao,
    v.decidido_por,
    (COALESCE(NULLIF(btrim((f.nome_completo)::text), ''::text), (u.username)::text))::character varying(255) AS decidido_por_nome,
    v.decidido_em,
        CASE
            WHEN ((v.situacao)::text = 'pendente'::text) THEN (((now() AT TIME ZONE 'America/Sao_Paulo'::text))::date - v.data_solicitacao)
            ELSE NULL::integer
        END AS dias_pendente,
    COALESCE((((v.situacao)::text = 'pendente'::text) AND ((((now() AT TIME ZONE 'America/Sao_Paulo'::text))::date - v.data_solicitacao) > lim.dias)), false) AS atencao,
    lim.dias AS dias_limite_atencao,
    v.created_at,
    v.updated_at,
    v.deleted_at
   FROM ((((core_aprovacao_de_vagas.vaga v
     CROSS JOIN LATERAL ( SELECT core_aprovacao_de_vagas.fn_dias_pendente_atencao() AS dias) lim)
     LEFT JOIN core.setores s ON ((s.id = v.id_setor)))
     LEFT JOIN auth.usuarios u ON ((u.id = v.decidido_por)))
     LEFT JOIN core.funcionarios f ON ((f.id = u.id_funcionario)));


