--

CREATE VIEW core_comercial.vw_divergencias_compra AS
 SELECT d.id,
    d.tipo,
    d.estado,
    d.codigo_empresa,
    un.nome_fantasia AS nome_unidade,
    d.codigo_empresa_pv,
    d.numero_pedido_venda,
    d.id_pedido_hub,
    hub.numero_pedido AS numero_pedido_hub,
    hub.numero_proposta,
    d.id_ordem_compra,
    o.numero_pedido AS numero_ordem_compra,
    o.status AS status_ordem_compra,
    d.id_ordem_compra_item,
    i.ordem AS ordem_item,
    COALESCE(prd.codigo_produto, i.codigo_produto) AS codigo_produto,
    i.codigo_produto AS codigo_produto_omie,
    d.codigo_produto_pv,
    i.descricao_produto,
    d.unidade_medida,
    d.valor_cotado,
    d.valor_compra,
    ((d.valor_compra - d.valor_cotado))::numeric(15,4) AS diferenca,
        CASE
            WHEN (d.valor_cotado > (0)::numeric) THEN round((((d.valor_compra - d.valor_cotado) / d.valor_cotado) * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS diferenca_pct,
    d.quantidade,
    round(((d.valor_compra - d.valor_cotado) * COALESCE(d.quantidade, (0)::numeric)), 2) AS diferenca_total,
    d.margem_proposta_pct,
    d.margem_considerada_pct,
    o.codigo_fornecedor,
    COALESCE(NULLIF(btrim((par.nome_fantasia)::text), ''::text), (par.razao_social)::text) AS fornecedor,
    o.codigo_condicao_pagamento,
    COALESCE(cp.descricao, o.codigo_condicao_pagamento) AS condicao_pagamento,
    o.data_previsao_chegada,
    d.motivo_compras,
    d.id_vendedor,
    ( SELECT COALESCE(f.nome_completo, u.username, u.email) AS "coalesce"
           FROM (auth.usuarios u
             LEFT JOIN core.funcionarios f ON ((f.id = u.id_funcionario)))
          WHERE (u.id = d.id_vendedor)) AS nome_vendedor,
    o.id_comprador,
    COALESCE(NULLIF(btrim((cmp.nome_exibicao)::text), ''::text), (cmp.nome)::text) AS nome_comprador,
    o.created_by AS emitido_por,
    d.decidido_por,
    ( SELECT COALESCE(f.nome_completo, u.username, u.email) AS "coalesce"
           FROM (auth.usuarios u
             LEFT JOIN core.funcionarios f ON ((f.id = u.id_funcionario)))
          WHERE (u.id = d.decidido_por)) AS nome_decidido_por,
    d.decidido_em,
    d.comentario_vendedor,
    d.solucao_tipo,
    d.solucao_motivo,
    d.resolvido_por,
    ( SELECT COALESCE(f.nome_completo, u.username, u.email) AS "coalesce"
           FROM (auth.usuarios u
             LEFT JOIN core.funcionarios f ON ((f.id = u.id_funcionario)))
          WHERE (u.id = d.resolvido_por)) AS nome_resolvido_por,
    d.resolvido_em,
    d.created_at AS criado_em,
    d.updated_at,
    ev.estado_desde,
    (((now() AT TIME ZONE 'America/Sao_Paulo'::text))::date - ((ev.estado_desde AT TIME ZONE 'America/Sao_Paulo'::text))::date) AS dias_no_estado
   FROM (((((((((core_comercial.divergencias_compra d
     JOIN core_vendas_faturamento.ordens_compra o ON ((o.id = d.id_ordem_compra)))
     JOIN core_vendas_faturamento.ordens_compra_itens i ON ((i.id = d.id_ordem_compra_item)))
     LEFT JOIN core.unidades un ON ((un.id = d.codigo_empresa)))
     LEFT JOIN core_comercial.pedidos_venda hub ON ((hub.id = d.id_pedido_hub)))
     LEFT JOIN core_vendas_faturamento.compradores cmp ON ((cmp.id = o.id_comprador)))
     LEFT JOIN LATERAL ( SELECT p.codigo_produto
           FROM core.produtos p
          WHERE ((p.codigo_empresa = o.codigo_empresa) AND ((p.codigo_produto_omie)::text = (i.codigo_produto)::text) AND (p.deleted_at IS NULL))
         LIMIT 1) prd ON (true))
     LEFT JOIN LATERAL ( SELECT p.nome_fantasia,
            p.razao_social
           FROM core.parceiros p
          WHERE ((p.codigo_empresa = o.codigo_empresa) AND ((p.codigo_parceiro_omie)::text = (o.codigo_fornecedor)::text) AND (p.deleted_at IS NULL))
         LIMIT 1) par ON (true))
     LEFT JOIN LATERAL ( SELECT c.descricao
           FROM core_vendas_faturamento.condicoes_pagamento_compras c
          WHERE ((c.codigo_empresa = o.codigo_empresa) AND ((c.codigo_omie)::text = (o.codigo_condicao_pagamento)::text))
         LIMIT 1) cp ON (true))
     LEFT JOIN LATERAL ( SELECT max(e.em) AS estado_desde
           FROM core_comercial.divergencias_compra_eventos e
          WHERE ((e.id_divergencia = d.id) AND ((e.para_estado)::text = (d.estado)::text))) ev ON (true));


