CREATE VIEW core_comercial.vw_pedido_venda_compra_proposta AS
 SELECT pv.id AS id_pedido_hub,
    pv.numero_pedido AS numero_pedido_hub,
    pv.codigo_empresa,
    pv.codigo_empresa_omie,
    pv.numero_pedido_omie,
    NULLIF(ltrim(btrim((pv.numero_pedido_omie)::text), '0'::text), ''::text) AS numero_pedido_omie_sem_zeros,
    pv.codigo_pedido_omie,
    pv.status AS status_pedido_hub,
    pv.created_at AS pedido_hub_criado_em,
    pv.id_proposta,
    pv.numero_proposta,
    p.frete_compra_tipo,
    p.frete_compra_valor,
    i.id AS id_pedido_hub_item,
    i.ordem,
    i.codigo_produto_omie,
    i.id_proposta_item,
    ((pi.preco_unit_compra IS NOT NULL) OR (NULLIF(btrim((pi.fornecedor)::text), ''::text) IS NOT NULL)) AS tem_cotacao,
    NULLIF(btrim((pi.fornecedor)::text), ''::text) AS fornecedor,
    NULLIF(btrim((pi.origem_compra)::text), ''::text) AS origem_compra,
    pi.qtd_compra,
    NULLIF(btrim((pi.unidade_compra)::text), ''::text) AS unidade_compra,
    pi.preco_unit_compra,
    pi.ipi_compra_pct,
    pi.st_compra_valor,
    pi.frete_compra_valor AS frete_compra_valor_item,
    pi.custo_liquido_unit
   FROM (((core_comercial.pedidos_venda pv
     LEFT JOIN core_comercial.propostas p ON ((p.id = pv.id_proposta)))
     LEFT JOIN core_comercial.pedidos_venda_itens i ON ((i.id_pedido = pv.id)))
     LEFT JOIN core_comercial.propostas_itens pi ON ((pi.id = i.id_proposta_item)))
  WHERE ((pv.deleted_at IS NULL) AND (pv.numero_pedido_omie IS NOT NULL));


