    p.numero_requisicao,
    p.finalidade,
    p.tipo_venda,
    p.moeda,
    p.incoterm,
    p.validade,
    p.total_geral,
    p.valor_aberto,
    (( SELECT count(*) AS count
           FROM core_comercial.propostas_itens i
          WHERE (i.id_proposta = p.id)))::integer AS qtd_itens,
    p.margem_liquida_pct,
    p.letra,
