            (COALESCE(sum(itens_src.valor_total) FILTER (WHERE (replace((itens_src.cfop)::text, '.'::text, ''::text) <> ALL (ARRAY['5101'::text, '5102'::text, '5123'::text, '5124'::text, '5401'::text, '5405'::text, '6101'::text, '6102'::text, '6107'::text, '6108'::text, '6119'::text, '6123'::text, '6401'::text, '6403'::text, '6404'::text, '6922'::text, '7101'::text, '7102'::text]))), (0)::numeric))::numeric(15,2) AS valor_nao_permitido
           FROM itens_src
