    rf.status_refaturamento,
    COALESCE(ia.valor_nao_permitido, (0)::numeric) AS valor_nao_permitido,
    (GREATEST(((COALESCE(n.valor_nf, (0)::numeric) - COALESCE(ia.valor_nao_permitido, (0)::numeric)) - COALESCE(n.descontos, (0)::numeric)), (0)::numeric))::numeric(15,2) AS total_nota_fiscal_ajustado,
    ia.valor_itens,
    par.nome_fantasia AS nome_fantasia_destinatario,
