    pv.denegado,
    pv.faturado,
    pv.encerrado,
    n.manual AS manual_nf,
    pv.manual AS manual_pedido,
    n.deleted_at,
    n.created_at,
    n.updated_at,
    n.codigo_empresa,
    n.is_track_record,
    ( SELECT COALESCE(ef.descricao, ef.descricao_padrao) AS "coalesce"
           FROM core.etapas_faturamento ef
          WHERE ((ef.codigo_empresa = n.codigo_empresa) AND ((ef.codigo_operacao)::text = '11'::text) AND ((ef.codigo_etapa)::numeric = pv.etapa) AND (ef.deleted_at IS NULL))
         LIMIT 1) AS etapa_descricao,
        CASE
            WHEN (COALESCE(n.manual, false) OR COALESCE(pv.manual, false)) THEN NULL::text
            WHEN pv.cancelado THEN 'G1'::text
            WHEN pv.devolvido THEN 'G2'::text
            WHEN pv.devolucao_parcial THEN 'G2P'::text
            WHEN (pv.denegado OR (public.unaccent(upper((COALESCE(mf.manifestacao, ''::character varying))::text)) ~ 'DESCONHEC|NAO REALIZ'::text)) THEN 'G3'::text
            WHEN (EXISTS ( SELECT 1
               FROM core_vendas_faturamento.blacklist_destinatarios bd
              WHERE ((bd.deleted_at IS NULL) AND (bd.escopo = ANY (ARRAY['faturamento'::text, 'ambos'::text])) AND (public.unaccent((((COALESCE(par.nome_fantasia, ''::character varying))::text || ' '::text) || (COALESCE(par.razao_social, ''::character varying))::text)) ~* public.unaccent(bd.termo))))) THEN 'G4'::text
            WHEN (EXISTS ( SELECT 1
               FROM core_vendas_faturamento.blacklist_vendedor_g5 bv5
              WHERE ((bv5.deleted_at IS NULL) AND (bv5.escopo = ANY (ARRAY['faturamento'::text, 'ambos'::text])) AND (public.unaccent((COALESCE(v.nome, ''::character varying))::text) ~* public.unaccent(bv5.termo))))) THEN 'G5'::text
            WHEN ((pv.obs_venda ~* 'refat|reaft'::text) AND ((rf.status_refaturamento IS NULL) OR ((rf.status_refaturamento)::text = ANY (ARRAY['Proibido'::text, 'Sem Referência'::text])))) THEN 'G6'::text
            WHEN (((pv.obs_venda IS NULL) OR (pv.obs_venda !~* 'refat|reaft'::text)) AND ((pv.codigo_categoria)::text = '1.01.96'::text)) THEN 'G6'::text
            ELSE NULL::text
        END AS grupo,
    pv.sequencial,
        CASE
            WHEN ((pv.numero_contrato)::text ~~* '%SPOT%'::text) THEN 'SPOT'::text
            WHEN ((pv.numero_contrato)::text ~~* '%CONTRATO%'::text) THEN 'CONTRATO'::text
            ELSE NULL::text
        END AS tipo_contrato
   FROM ((((((((nf_src n
     LEFT JOIN pv_src pv ON (((pv.is_track_record = n.is_track_record) AND (pv.codigo_pedido_omie = n.codigo_pedido_omie) AND (pv.codigo_empresa = n.codigo_empresa))))
     LEFT JOIN itens_agg ia ON (((ia.is_track_record = n.is_track_record) AND (ia.codigo_nf_omie = n.codigo_nf_omie) AND (ia.codigo_empresa = n.codigo_empresa))))
     LEFT JOIN core.parceiros par ON ((((par.codigo_parceiro_omie)::text = (n.codigo_cliente)::text) AND (par.codigo_empresa = n.codigo_empresa) AND (par.deleted_at IS NULL))))
     LEFT JOIN core.categorias cat_nf ON ((((cat_nf.codigo_categoria)::text = (n.codigo_categoria)::text) AND (cat_nf.codigo_empresa = n.codigo_empresa) AND (cat_nf.deleted_at IS NULL))))
     LEFT JOIN core.categorias cat_pv ON ((((cat_pv.codigo_categoria)::text = (pv.codigo_categoria)::text) AND (cat_pv.codigo_empresa = pv.codigo_empresa) AND (cat_pv.deleted_at IS NULL))))
     LEFT JOIN core_vendas_faturamento.vendedores v ON ((((v.codigo_vendedor_omie)::text = (n.codigo_vendedor_omie)::text) AND (v.codigo_empresa = n.codigo_empresa) AND (v.deleted_at IS NULL))))
     LEFT JOIN core_vendas_faturamento.refaturamentos rf ON (((rf.codigo_pedido_omie = n.codigo_pedido_omie) AND (rf.codigo_empresa = n.codigo_empresa))))
