CREATE VIEW core_compras.orc_vw_categorias AS
 SELECT c.id,
    c.nome,
    c.ordem,
    c.ativo,
    (count(v.id))::integer AS qtd_vinculos,
    (count(v.id) FILTER (WHERE (NOT v.sem_cadastro)))::integer AS qtd_com_cadastro,
    (count(v.id) FILTER (WHERE v.sem_cadastro))::integer AS qtd_sem_cadastro
   FROM (core_compras.orc_categorias c
     LEFT JOIN core_compras.orc_vinculos v ON ((v.id_categoria = c.id)))
  GROUP BY c.id, c.nome, c.ordem, c.ativo;


