-- Name: orc_vw_fornecedores_vinculos; Type: VIEW; Schema: core_compras; Owner: -
--

CREATE VIEW core_compras.orc_vw_fornecedores_vinculos AS
 SELECT x.codigo,
    array_agg(DISTINCT (c.nome)::text ORDER BY (c.nome)::text) AS categorias,
    (count(DISTINCT x.id_vinculo))::integer AS qtd_vinculos,
    bool_or(vi.sem_cadastro) AS tem_vinculo_sem_cadastro
   FROM ((( SELECT f.codigo,
            vi_1.id AS id_vinculo
           FROM (core_compras.orc_fornecedores f
             JOIN core_compras.orc_vinculos vi_1 ON ((vi_1.cnpj_digitos = f.cnpj_digitos)))
          WHERE (f.cnpj_digitos <> ''::text)
        UNION
         SELECT f.codigo,
            vi_1.id
           FROM (core_compras.orc_fornecedores f
             JOIN core_compras.orc_vinculos vi_1 ON ((vi_1.nome_fantasia_norm = f.nome_fantasia_norm)))
          WHERE (f.nome_fantasia_norm <> ''::text)
        UNION
         SELECT f.codigo,
            vi_1.id
           FROM (core_compras.orc_fornecedores f
             JOIN core_compras.orc_vinculos vi_1 ON ((vi_1.razao_social_norm = f.razao_social_norm)))
          WHERE (f.razao_social_norm <> ''::text)) x
     JOIN core_compras.orc_vinculos vi ON ((vi.id = x.id_vinculo)))
     JOIN core_compras.orc_categorias c ON ((c.id = vi.id_categoria)))
  GROUP BY x.codigo;


