    COALESCE(f.email, p.fornecedor_email) AS email,
    COALESCE(f.telefone, p.fornecedor_telefone) AS telefone,
    COALESCE(f.cidade, p.fornecedor_cidade) AS cidade,
    COALESCE(f.logradouro, p.fornecedor_logradouro) AS logradouro,
    COALESCE(f.numero, p.fornecedor_numero) AS numero,
    p.texto_busca
   FROM ((core_compras.orc_produtos p
     LEFT JOIN core_compras.orc_familias fa ON (((fa.codigo)::text = (p.codigo_familia)::text)))
     LEFT JOIN core_compras.orc_fornecedores f ON (((f.codigo)::text = (p.codigo_fornecedor_recente)::text)));


