--
-- TOC entry 319 (class 1259 OID 18186)
-- Name: vw_catalogo_de_produtos; Type: VIEW; Schema: core_compras; Owner: -
--

CREATE VIEW core_compras.vw_catalogo_de_produtos AS
 WITH cotacoes_numeradas AS (
         SELECT pp.id_produto,
            pp.id_parceiro,
            pp.valor_unidade,
            pp.data_cotacao,
            pp.created_at,
            row_number() OVER (PARTITION BY pp.id_produto, pp.id_parceiro ORDER BY pp.data_cotacao DESC, pp.created_at DESC) AS rn
           FROM core.parceiros_produtos pp
          WHERE ((pp.deleted_at IS NULL) AND (pp.valor_unidade IS NOT NULL))
        ), ultima_cotacao AS (
         SELECT cn.id_produto,
            cn.id_parceiro,
            cn.valor_unidade AS cotacao_mais_recente,
            cn.data_cotacao AS data_cotacao_mais_recente
           FROM cotacoes_numeradas cn
          WHERE (cn.rn = 1)
        ), media_produto AS (
         SELECT pp.id_produto,
            round(avg(pp.valor_unidade), 2) AS preco_medio_ultimas_cotacoes,
            count(*) AS total_cotacoes
           FROM ((core.parceiros_produtos pp
             JOIN core.parceiros par_1 ON (((par_1.codigo_parceiro_omie)::text = (pp.id_parceiro)::text)))
             JOIN core.parceiros_tipos pt_1 ON ((pt_1.id_parceiro = par_1.id)))
          WHERE ((pp.deleted_at IS NULL) AND (pp.valor_unidade IS NOT NULL) AND (pt_1.id_tipo_parceiro = 'f60c9ca0-3e20-4012-a845-32de0c256c34'::uuid))
          GROUP BY pp.id_produto
        )
 SELECT p.codigo_produto_omie,
    p.codigo_produto,
    p.descricao,
    fp.nome AS familia,
    p.unidade_medida,
    p.ativo,
    (par.codigo_parceiro_omie)::character varying(40) AS id_parceiro_mais_recente,
    par.nome_fantasia,
    par.email,
    par.telefone,
    par.logradouro,
    par.numero,
    par.complemento,
    par.bairro,
    par.cidade,
    par.estado,
    par.cep,
    uc.cotacao_mais_recente,
    uc.data_cotacao_mais_recente,
    mp.preco_medio_ultimas_cotacoes,
    mp.total_cotacoes
   FROM (((((core.produtos p
     LEFT JOIN ultima_cotacao uc ON (((uc.id_produto)::text = (p.codigo_produto_omie)::text)))
     LEFT JOIN core.parceiros par ON (((par.codigo_parceiro_omie)::text = (uc.id_parceiro)::text)))
     LEFT JOIN core.parceiros_tipos pt ON ((pt.id_parceiro = par.id)))
     LEFT JOIN core.familia_produtos fp ON (((fp.codigo_fprodutos)::text = (p.familias_produtos)::text)))
     LEFT JOIN media_produto mp ON (((mp.id_produto)::text = (p.codigo_produto_omie)::text)))
  WHERE ((p.deleted_at IS NULL) AND (pt.id_tipo_parceiro = 'f60c9ca0-3e20-4012-a845-32de0c256c34'::uuid) AND (fp.ativo = true))
  ORDER BY fp.nome, p.descricao, par.nome_fantasia;


