CREATE VIEW core_compras.vw_fornecedores_com_produtos AS
 SELECT DISTINCT p.codigo_parceiro_omie,
    p.nome_fantasia,
    p.email,
    p.telefone,
    p.estado
   FROM (((core.parceiros p
     JOIN core.parceiros_tipos pt ON (((pt.id_parceiro = p.id) AND (pt.deleted_at IS NULL))))
     JOIN core.tipos_parceiro tp ON (((tp.id = pt.id_tipo_parceiro) AND (tp.deleted_at IS NULL))))
     JOIN core.parceiros_produtos pp ON ((((pp.id_parceiro)::text = (p.codigo_parceiro_omie)::text) AND (pp.deleted_at IS NULL))))
  WHERE ((p.deleted_at IS NULL) AND (upper((tp.tipo)::text) = 'FORNECEDOR'::text));


