--
-- TOC entry 386 (class 1259 OID 20532)
-- Name: vw_produto_fornecedores; Type: VIEW; Schema: core_compras; Owner: -
--

CREATE VIEW core_compras.vw_produto_fornecedores AS
 WITH cotacoes AS (
         SELECT p_1.id AS id_produto,
            par_1.id AS id_fornecedor,
            (count(*))::integer AS total_cotacoes,
            (array_agg(pp.valor_unidade ORDER BY pp.data_cotacao DESC NULLS LAST, pp.created_at DESC, pp.id DESC) FILTER (WHERE (pp.valor_unidade IS NOT NULL)))[1] AS ultima_cotacao,
            (array_agg(pp.data_cotacao ORDER BY pp.data_cotacao DESC NULLS LAST, pp.created_at DESC, pp.id DESC) FILTER (WHERE (pp.valor_unidade IS NOT NULL)))[1] AS data_ultima_cotacao
           FROM ((core.parceiros_produtos pp
             JOIN core.produtos p_1 ON (((p_1.codigo_empresa = pp.codigo_empresa) AND ((p_1.codigo_produto_omie)::text = (pp.id_produto)::text) AND (p_1.deleted_at IS NULL))))
             JOIN core.parceiros par_1 ON (((par_1.codigo_empresa = pp.codigo_empresa) AND ((par_1.codigo_parceiro_omie)::text = (pp.id_parceiro)::text) AND (par_1.deleted_at IS NULL))))
          WHERE (pp.deleted_at IS NULL)
          GROUP BY p_1.id, par_1.id
        ), itens_compra AS (
         SELECT p_1.id AS id_produto,
            par_1.id AS id_fornecedor,
            pc.id AS id_pedido_compra,
            pc.codigo_pedido_compra_omie,
            i.ordem,
            i.valor_unitario,
            ((pc.incluido_em_omie AT TIME ZONE 'America/Sao_Paulo'::text))::date AS data_compra
           FROM (((core_vendas_faturamento.pedidos_compras_itens i
             JOIN core.produtos p_1 ON (((p_1.codigo_empresa = i.codigo_empresa) AND ((p_1.codigo_produto_omie)::text = (i.codigo_produto_omie)::text) AND (p_1.deleted_at IS NULL))))
             JOIN core_vendas_faturamento.pedidos_compras pc ON (((pc.id = i.id_pedido_compra) AND (pc.codigo_empresa = i.codigo_empresa) AND (pc.deleted_at IS NULL) AND (upper((COALESCE(pc.etapa, ''::character varying))::text) <> 'CA'::text))))
             JOIN core.parceiros par_1 ON (((par_1.codigo_empresa = pc.codigo_empresa) AND ((par_1.codigo_parceiro_omie)::text = (pc.codigo_fornecedor)::text) AND (par_1.deleted_at IS NULL))))
        ), compras AS (
         SELECT ic.id_produto,
            ic.id_fornecedor,
            (count(DISTINCT ic.id_pedido_compra))::integer AS total_compras,
            (array_agg(ic.valor_unitario ORDER BY ic.data_compra DESC NULLS LAST, ic.codigo_pedido_compra_omie DESC, ic.ordem) FILTER (WHERE (ic.valor_unitario IS NOT NULL)))[1] AS valor_ultima_compra,
            max(ic.data_compra) AS data_ultima_compra
           FROM itens_compra ic
          GROUP BY ic.id_produto, ic.id_fornecedor
        ), fontes AS (
         SELECT cotacoes.id_produto,
            cotacoes.id_fornecedor,
            cotacoes.total_cotacoes,
            cotacoes.ultima_cotacao,
            cotacoes.data_ultima_cotacao,
            NULL::integer AS total_compras,
            NULL::numeric AS valor_ultima_compra,
            NULL::date AS data_ultima_compra
           FROM cotacoes
        UNION ALL
         SELECT compras.id_produto,
            compras.id_fornecedor,
            NULL::integer AS int4,
            NULL::numeric AS "numeric",
            NULL::date AS date,
            compras.total_compras,
            compras.valor_ultima_compra,
            compras.data_ultima_compra
           FROM compras
        ), relacao AS (
         SELECT fontes.id_produto,
            fontes.id_fornecedor,
            max(fontes.total_cotacoes) AS total_cotacoes,
            max(fontes.ultima_cotacao) AS ultima_cotacao,
            max(fontes.data_ultima_cotacao) AS data_ultima_cotacao,
            max(fontes.total_compras) AS total_compras,
            max(fontes.valor_ultima_compra) AS valor_ultima_compra,
            max(fontes.data_ultima_compra) AS data_ultima_compra
           FROM fontes
          GROUP BY fontes.id_produto, fontes.id_fornecedor
        )
 SELECT r.id_produto,
    p.codigo_empresa,
    p.codigo_produto_omie,
    r.id_fornecedor,
    par.codigo_parceiro_omie AS codigo_fornecedor,
    par.nome_fantasia,
    par.razao_social,
    par.cpf_cnpj AS cnpj,
    par.inativo,
    r.ultima_cotacao,
    r.data_ultima_cotacao,
    COALESCE(r.total_cotacoes, 0) AS total_cotacoes,
    r.valor_ultima_compra,
    r.data_ultima_compra,
    COALESCE(r.total_compras, 0) AS total_compras,
        CASE
            WHEN ((r.total_cotacoes > 0) AND (r.total_compras > 0)) THEN 'cotacao_e_compra'::text
            WHEN (r.total_cotacoes > 0) THEN 'cotacao'::text
            ELSE 'compra'::text
        END AS origem,
    GREATEST(r.data_ultima_cotacao, r.data_ultima_compra) AS data_ultima_movimentacao
   FROM ((relacao r
     JOIN core.produtos p ON ((p.id = r.id_produto)))
     JOIN core.parceiros par ON ((par.id = r.id_fornecedor)));


