--
-- TOC entry 330 (class 1259 OID 18280)
-- Name: vw_org_nodes; Type: VIEW; Schema: core_organograma; Owner: -
--

CREATE VIEW core_organograma.vw_org_nodes AS
 WITH cargos_data AS (
         SELECT cargos.id,
            cargos.nome,
            cargos.nvl_permissao AS nivel
           FROM core.cargos
        ), primary_director AS (
         SELECT f.id
           FROM (core.funcionarios f
             JOIN cargos_data c ON ((f.id_cargo = c.id)))
          WHERE ((c.nivel = 0) AND (f.data_desligamento IS NULL))
          ORDER BY f.diretor_principal DESC, f.id
         LIMIT 1
        ), gm_unique AS (
         SELECT f.id
           FROM (core.funcionarios f
             JOIN cargos_data c ON ((f.id_cargo = c.id)))
          WHERE ((c.nivel = 1) AND (f.data_desligamento IS NULL))
          ORDER BY f.id
         LIMIT 1
        ), pessoas_nodes AS (
         SELECT (f.id)::text AS id,
            f.nome_completo AS name,
            c.nome AS role,
                CASE
                    WHEN ((c.nivel = 0) AND (f.id = ( SELECT primary_director.id
                       FROM primary_director))) THEN 0
                    WHEN (c.nivel = 0) THEN 4
                    ELSE GREATEST(0, LEAST(13, (c.nivel)::integer))
                END AS level,
            COALESCE(ov.parent_id,
                CASE
                    WHEN ((c.nivel = 0) AND (f.id = ( SELECT primary_director.id
                       FROM primary_director))) THEN NULL::text
                    WHEN (c.nivel = 0) THEN (f.id_setor)::text
                    WHEN (c.nivel = 1) THEN ( SELECT (primary_director.id)::text AS id
                       FROM primary_director)
                    WHEN (c.nivel = 13) THEN ( SELECT (primary_director.id)::text AS id
                       FROM primary_director)
                    ELSE core_organograma.fn_default_parent_pessoa(f.id)
                END) AS parent_id,
            false AS is_sector,
            f.photo_url,
            NULL::text AS sector_color,
                CASE
                    WHEN (
                    CASE
                        WHEN ((c.nivel = 0) AND (f.id = ( SELECT primary_director.id
                           FROM primary_director))) THEN 0
                        WHEN (c.nivel = 0) THEN 4
                        ELSE GREATEST(0, LEAST(13, (c.nivel)::integer))
                    END = 4) THEN COALESCE(ov.parent_id, core_organograma.fn_default_parent_pessoa(f.id))
                    ELSE NULL::text
                END AS sector_director_of,
            (f.id)::text AS id_ent
           FROM ((core.funcionarios f
             JOIN cargos_data c ON ((c.id = f.id_cargo)))
             LEFT JOIN core_organograma.node ov ON (((ov.id_ent = (f.id)::text) AND (ov.is_sector = false) AND (ov.deleted_at IS NULL))))
          WHERE (f.data_desligamento IS NULL)
        ), setores_nodes AS (
         SELECT (s.id)::text AS id,
            s.nome AS name,
            COALESCE(s.sigla, ''::character varying) AS role,
            s.nivel AS level,
            COALESCE(ov.parent_id, (s.parent_id)::text, ( SELECT (gm_unique.id)::text AS id
                   FROM gm_unique), ( SELECT (primary_director.id)::text AS id
                   FROM primary_director)) AS parent_id,
            true AS is_sector,
            NULL::text AS photo_url,
            s.cor_setor AS sector_color,
            NULL::text AS sector_director_of,
            (s.id)::text AS id_ent
           FROM (core.setores s
             LEFT JOIN core_organograma.node ov ON (((ov.id_ent = (s.id)::text) AND (ov.is_sector = true) AND (ov.deleted_at IS NULL))))
          WHERE (s.ativo = true)
        )
 SELECT pessoas_nodes.id,
    pessoas_nodes.name,
    pessoas_nodes.role,
    pessoas_nodes.level,
    pessoas_nodes.parent_id,
    pessoas_nodes.is_sector,
    pessoas_nodes.photo_url,
    pessoas_nodes.sector_color,
    pessoas_nodes.sector_director_of,
    pessoas_nodes.id_ent
   FROM pessoas_nodes
UNION ALL
 SELECT setores_nodes.id,
    setores_nodes.name,
    setores_nodes.role,
    setores_nodes.level,
    setores_nodes.parent_id,
    setores_nodes.is_sector,
    setores_nodes.photo_url,
    setores_nodes.sector_color,
    setores_nodes.sector_director_of,
    setores_nodes.id_ent
   FROM setores_nodes
  ORDER BY 4, 6 DESC, 2;


--
-- TOC entry 7783 (class 0 OID 0)
-- Dependencies: 330
-- Name: VIEW vw_org_nodes; Type: COMMENT; Schema: core_organograma; Owner: -
--

COMMENT ON VIEW core_organograma.vw_org_nodes IS 'Nós do organograma (pessoas + setores). parent_id = override manual de core_organograma.node ou, sem override, o automático: Diretoria principal = raiz; nível 1 (Gerência Geral) e nível 13 (Diretoria Executiva, global a todas as empresas) = filhos da Diretoria principal; nível 0 secundário = setor; demais = fn_default_parent_pessoa. level = nvl_permissao do cargo (0 a 13; o 13 é identificador, a posição na hierarquia vem de nivel_hierarquico.ordem). parent_id é uuid puro, sem prefixo.';


--
-- TOC entry 373 (class 1259 OID 20287)
-- Name: vw_hierarquia_pessoas; Type: VIEW; Schema: core_organograma; Owner: -
--

CREATE VIEW core_organograma.vw_hierarquia_pessoas AS
 SELECT f.id AS id_funcionario,
    ov.parent_id AS reporta_a_id,
    v.parent_id AS reporta_a_efetivo_id,
        CASE
            WHEN (v.parent_id IS NULL) THEN NULL::text
            WHEN (EXISTS ( SELECT 1
               FROM core.setores s
              WHERE ((s.id)::text = v.parent_id))) THEN 'setor'::text
            ELSE 'funcionario'::text
        END AS reporta_a_efetivo_tipo,
    (ov.parent_id IS NOT NULL) AS reporta_a_manual
   FROM ((core.funcionarios f
     LEFT JOIN core_organograma.node ov ON (((ov.id_ent = (f.id)::text) AND (ov.is_sector = false) AND (ov.deleted_at IS NULL))))
     LEFT JOIN core_organograma.vw_org_nodes v ON (((v.id = (f.id)::text) AND (v.is_sector = false))));


