--
-- TOC entry 477 (class 1259 OID 25088)
-- Name: vw_avisos_mes_compra; Type: VIEW; Schema: core_vendas_faturamento; Owner: -
--

CREATE VIEW core_vendas_faturamento.vw_avisos_mes_compra AS
 SELECT a.id,
    a.id_aviso_mes,
    a.tipo,
    a.status,
    oc.codigo_empresa,
    u.nome_fantasia AS nome_unidade,
    a.id_ordem_compra,
    oc.numero_pedido AS numero_ordem_compra,
    oc.status AS status_ordem_compra,
    a.id_ordem_compra_item,
    it.ordem AS ordem_item,
    it.codigo_produto,
    it.descricao_produto,
    a.quantidade,
    a.unidade_medida,
    a.motivo,
    a.codigo_documento,
    a.codigo_lote,
    a.numero_pedido_venda,
    a.decidido_por,
    a.decidido_em,
    a.acao_tratamento,
    a.id_ordem_compra_recompra,
    rec.numero_pedido AS numero_ordem_compra_recompra,
    a.motivo_tratamento,
    a.tratado_por,
    COALESCE(f.nome_completo, us.username, us.email) AS nome_tratado_por,
    a.tratado_em,
    a.created_at AS criado_em,
    a.updated_at AS atualizado_em,
    (((COALESCE(a.tratado_em, now()) AT TIME ZONE 'America/Sao_Paulo'::text))::date - ((a.created_at AT TIME ZONE 'America/Sao_Paulo'::text))::date) AS dias_aberto
   FROM ((((((core_vendas_faturamento.avisos_mes_compra a
     JOIN core_vendas_faturamento.ordens_compra oc ON ((oc.id = a.id_ordem_compra)))
     LEFT JOIN core.unidades u ON ((u.id = oc.codigo_empresa)))
     LEFT JOIN core_vendas_faturamento.ordens_compra_itens it ON ((it.id = a.id_ordem_compra_item)))
     LEFT JOIN core_vendas_faturamento.ordens_compra rec ON ((rec.id = a.id_ordem_compra_recompra)))
     LEFT JOIN auth.usuarios us ON ((us.id = a.tratado_por)))
     LEFT JOIN core.funcionarios f ON ((f.id = us.id_funcionario)));


