--

CREATE VIEW core_vendas_faturamento.vw_clientes_inativos AS
 WITH pedidos AS (
         SELECT b.codigo_empresa,
            b.cod_vendedor,
            b.vendedor,
            b.codigo_cliente,
            b.nome_cliente,
            b.razao_social_cliente,
            b.data_inclusao,
            b.total_pedido
           FROM core_vendas_faturamento.vw_vendas_base b
          WHERE ((b.is_track_record = false) AND (b.data_inclusao IS NOT NULL) AND (b.codigo_cliente IS NOT NULL) AND (NOT b.cancelado) AND (NOT b.denegado))
        ), ranked AS (
         SELECT p.codigo_empresa,
            p.cod_vendedor,
            p.vendedor,
            p.codigo_cliente,
            p.nome_cliente,
            p.razao_social_cliente,
            p.data_inclusao,
            p.total_pedido,
            row_number() OVER (PARTITION BY p.codigo_empresa, p.cod_vendedor, p.codigo_cliente ORDER BY p.data_inclusao DESC) AS rn,
            count(*) OVER (PARTITION BY p.codigo_empresa, p.cod_vendedor, p.codigo_cliente) AS qtd_pedidos,
            sum(p.total_pedido) OVER (PARTITION BY p.codigo_empresa, p.cod_vendedor, p.codigo_cliente) AS valor_total_historico
           FROM pedidos p
        )
 SELECT codigo_empresa,
    cod_vendedor,
    vendedor,
    codigo_cliente,
    COALESCE(nome_cliente, razao_social_cliente) AS cliente,
    data_inclusao AS ultima_compra,
    (CURRENT_DATE - data_inclusao) AS dias_sem_comprar,
    total_pedido AS valor_ultima_compra,
    qtd_pedidos,
    valor_total_historico
   FROM ranked r
  WHERE (rn = 1);


