    'grupo'::text AS setor_origem,
    m.id_grupo
   FROM (((core_vendas_faturamento.grupos_clientes_membros m
     JOIN core_vendas_faturamento.grupos_clientes g ON (((g.id = m.id_grupo) AND g.ativo)))
     JOIN core_vendas_faturamento.clientes_setor cs ON ((cs.id_grupo = m.id_grupo)))
     JOIN core_vendas_faturamento.setores_clientes s ON ((s.id = cs.id_setor)))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM core_vendas_faturamento.clientes_setor p
          WHERE ((p.id_grupo IS NULL) AND (p.codigo_empresa = m.codigo_empresa) AND ((p.codigo_cliente)::text = (m.codigo_cliente)::text)))));


