CREATE VIEW core_vendas_faturamento.vw_compras_acompanhamento AS
 SELECT oc.id AS id_ordem_compra,
    (oc.numero_pedido)::text AS numero_pedido,
    oc.codigo_empresa,
    (oc.codigo_fornecedor)::text AS codigo_fornecedor,
    forn.nome_fornecedor,
    oc.id_comprador,
    ( SELECT COALESCE(c.nome_exibicao, c.nome) AS "coalesce"
           FROM core_vendas_faturamento.compradores c
          WHERE (c.id = oc.id_comprador)) AS nome_comprador,
    oc.valor_total_brl,
    (oc.tipo_frete)::text AS tipo_frete,
    (oc.numero_pedido_fornecedor)::text AS numero_pedido_fornecedor,
    (oc.numero_pedido_omie)::text AS numero_pedido_omie,
    oc.aprovado_em,
    oc.data_previsao_chegada,
        CASE
            WHEN (oc.data_previsao_chegada IS NOT NULL) THEN GREATEST((par.hoje - oc.data_previsao_chegada), 0)
            ELSE NULL::integer
        END AS dias_atraso,
    (COALESCE(a.confirmacao_status, 'pendente'::character varying))::text AS confirmacao_status,
    a.confirmado_em,
    a.despachado_em,
    (a.despachado_em IS NOT NULL) AS despachada,
    (a.nf_fornecedor)::text AS nf_fornecedor,
    (a.transportadora)::text AS transportadora,
    COALESCE(oco.abertas, 0) AS ocorrencias_abertas,
    uc.created_at AS ultimo_contato_em,
    uc.resumo AS ultimo_contato_resumo,
    esp.id AS id_pedido_compra,
        CASE
            WHEN (esp.id IS NULL) THEN 'sem_espelho'::text
            WHEN (it.itens = 0) THEN 'sem_itens'::text
            WHEN (it.pendentes > 0) THEN 'pendente'::text
            ELSE 'recebido'::text
        END AS recebimento,
    COALESCE(it.pendentes, 0) AS itens_pendentes,
    ((COALESCE(a.confirmacao_status, 'pendente'::character varying))::text = 'pendente'::text) AS sem_confirmacao,
    (oc.data_previsao_chegada < par.hoje) AS atrasada,
    ((oc.data_previsao_chegada >= par.hoje) AND (oc.data_previsao_chegada <= (par.hoje + 7))) AS chega_7_dias,
    (oc.data_previsao_chegada >= par.hoje) AS no_prazo,
    (COALESCE(oco.abertas, 0) > 0) AS com_ocorrencia_aberta,
    oc.created_at
   FROM (((((((core_vendas_faturamento.ordens_compra oc
     CROSS JOIN LATERAL ( SELECT core_vendas_faturamento.fn_hoje_sp() AS hoje) par)
     LEFT JOIN core_vendas_faturamento.ordens_compra_acompanhamento a ON ((a.id_ordem_compra = oc.id)))
     LEFT JOIN LATERAL ( SELECT COALESCE(NULLIF(btrim((p.nome_fantasia)::text), ''::text), (p.razao_social)::text) AS nome_fornecedor
           FROM core.parceiros p
          WHERE ((p.codigo_empresa = oc.codigo_empresa) AND ((p.codigo_parceiro_omie)::text = (oc.codigo_fornecedor)::text) AND (p.deleted_at IS NULL))
          ORDER BY p.created_at
         LIMIT 1) forn ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS abertas
           FROM core_vendas_faturamento.ordens_compra_ocorrencias o
          WHERE ((o.id_ordem_compra = oc.id) AND ((o.status)::text = 'aberta'::text))) oco ON (true))
     LEFT JOIN LATERAL ( SELECT ct.created_at,
            ct.resumo
           FROM core_vendas_faturamento.ordens_compra_contatos ct
          WHERE (ct.id_ordem_compra = oc.id)
          ORDER BY ct.created_at DESC, ct.id DESC
         LIMIT 1) uc ON (true))
     LEFT JOIN LATERAL ( SELECT pc.id
           FROM core_vendas_faturamento.pedidos_compras pc
          WHERE ((pc.codigo_empresa = oc.codigo_empresa) AND ((pc.codigo_pedido_integracao)::text = (oc.numero_pedido)::text) AND (pc.deleted_at IS NULL))
          ORDER BY pc.incluido_em_omie DESC NULLS LAST, pc.created_at DESC
         LIMIT 1) esp ON (true))
     LEFT JOIN LATERAL ( SELECT (count(*))::integer AS itens,
            (count(*) FILTER (WHERE (i.quantidade > COALESCE(i.quantidade_recebida, (0)::numeric))))::integer AS pendentes
           FROM core_vendas_faturamento.pedidos_compras_itens i
          WHERE (i.id_pedido_compra = esp.id)) it ON ((esp.id IS NOT NULL)))
  WHERE ((oc.deleted_at IS NULL) AND ((oc.status)::text = 'aprovado'::text) AND (NOT ((esp.id IS NOT NULL) AND (it.itens > 0) AND (it.pendentes = 0))));


