    (array_agg(s.nome ORDER BY (core_vendas_faturamento.fn_setor_nome_chave((s.nome)::text)), cs.id_setor))[1] AS setor,
    (array_agg(s.ativo ORDER BY (core_vendas_faturamento.fn_setor_nome_chave((s.nome)::text)), cs.id_setor))[1] AS setor_ativo
   FROM (core_vendas_faturamento.clientes_setor cs
     JOIN core_vendas_faturamento.setores_clientes s ON ((s.id = cs.id_setor)))
  WHERE (cs.id_grupo IS NOT NULL)
  GROUP BY cs.id_grupo;


