CREATE VIEW core_vendas_faturamento.vw_ordens_compra_historico AS
 SELECT 'av-hub'::text AS origem,
    oc.id,
    (oc.numero_pedido)::text AS numero_pedido,
    oc.codigo_empresa,
    (oc.codigo_fornecedor)::text AS codigo_fornecedor,
    oc.valor_total_brl,
    oc.data_previsao_chegada,
    (oc.status)::text AS status,
    NULL::text AS etapa_omie,
    NULL::text AS etapa_omie_descricao,
    (oc.status_sincronizacao_omie)::text AS status_sincronizacao_omie,
    core_vendas_faturamento.fn_oc_situacao_omie((oc.status)::text, (oc.status_sincronizacao_omie)::text, oc.codigo_pedido_omie) AS situacao_omie,
    core_vendas_faturamento.fn_oc_situacao_omie_descricao((oc.status)::text, (oc.status_sincronizacao_omie)::text, oc.codigo_pedido_omie, (oc.numero_pedido_omie)::text, oc.erro_sincronizacao_omie) AS situacao_omie_descricao,
    oc.erro_sincronizacao_omie,
    oc.codigo_pedido_omie,
    (oc.numero_pedido_omie)::text AS numero_pedido_omie,
    (oc.numero_pedido_fornecedor)::text AS numero_pedido_fornecedor,
    (oc.finalidade)::text AS finalidade,
    oc.id_requisicao,
    oc.id_comprador,
    NULL::text AS codigo_comprador_omie,
    (oc.contato)::text AS contato,
    oc.aprovado_por,
    oc.aprovado_em,
    false AS somente_leitura,
    oc.created_at,
    oc.updated_at
   FROM core_vendas_faturamento.ordens_compra oc
  WHERE (oc.deleted_at IS NULL)
UNION ALL
 SELECT 'omie'::text AS origem,
    pc.id,
    (pc.numero_pedido)::text AS numero_pedido,
    pc.codigo_empresa,
    (pc.codigo_fornecedor)::text AS codigo_fornecedor,
    (COALESCE(( SELECT sum(pci.valor_total) AS sum
           FROM core_vendas_faturamento.pedidos_compras_itens pci
          WHERE (pci.id_pedido_compra = pc.id)), pc.valor_total_pedido))::numeric(15,2) AS valor_total_brl,
    pc.data_previsao AS data_previsao_chegada,
    (COALESCE(e.status_equivalente, 'aprovado'::character varying))::text AS status,
    (pc.etapa)::text AS etapa_omie,
    core_vendas_faturamento.fn_pedido_compra_etapa_descricao((pc.etapa)::text) AS etapa_omie_descricao,
    NULL::text AS status_sincronizacao_omie,
    NULL::text AS situacao_omie,
    NULL::text AS situacao_omie_descricao,
    NULL::text AS erro_sincronizacao_omie,
    pc.codigo_pedido_compra_omie AS codigo_pedido_omie,
    (pc.numero_pedido)::text AS numero_pedido_omie,
    (pc.numero_pedido_fornecedor)::text AS numero_pedido_fornecedor,
    NULL::text AS finalidade,
    NULL::uuid AS id_requisicao,
    NULL::uuid AS id_comprador,
    (pc.codigo_comprador)::text AS codigo_comprador_omie,
    (pc.contato)::text AS contato,
    NULL::uuid AS aprovado_por,
    NULL::timestamp with time zone AS aprovado_em,
    true AS somente_leitura,
    COALESCE(pc.incluido_em_omie, pc.created_at) AS created_at,
    pc.updated_at
   FROM (core_vendas_faturamento.pedidos_compras pc
     LEFT JOIN core_vendas_faturamento.pedidos_compras_etapas e ON (((e.etapa)::text = (pc.etapa)::text)))
  WHERE ((pc.deleted_at IS NULL) AND (NOT (EXISTS ( SELECT 1
           FROM core_vendas_faturamento.ordens_compra oc
          WHERE ((oc.codigo_empresa = pc.codigo_empresa) AND ((oc.numero_pedido)::text = (pc.codigo_pedido_integracao)::text) AND (oc.deleted_at IS NULL))))));


