            (COALESCE(sum(pv.quantidade) FILTER (WHERE ((p.situacao)::text = 'Pendente'::text)), ((0)::numeric)::double precision))::numeric(15,4) AS quantidade_pendente
           FROM ((core_vendas_faturamento.produto_vendas pv
             JOIN core_vendas_faturamento.pedidos_vendas p ON (((p.codigo_empresa = pv.codigo_empresa) AND (p.codigo_pedido_omie = pv.codigo_pedido_omie) AND (p.deleted_at IS NULL))))
             LEFT JOIN core.produtos pr ON (((pr.codigo_empresa = pv.codigo_empresa) AND ((pr.codigo_produto_omie)::text = (pv.codigo_produto_omie)::text))))
          WHERE (pv.deleted_at IS NULL)
          GROUP BY pv.codigo_empresa, pv.numero_pedido, pv.codigo_produto_omie
        ), compras AS (
         SELECT v.codigo_empresa_pv,
            v.numero_pedido_venda,
            v.codigo_produto_pv,
