                  WHERE ((bd.deleted_at IS NULL) AND (bd.escopo = ANY (ARRAY['vendas'::text, 'ambos'::text])) AND (public.unaccent((((COALESCE(par.nome_fantasia, ''::character varying))::text || ' '::text) || (COALESCE(par.razao_social, ''::character varying))::text)) ~* public.unaccent(bd.termo))))) THEN 'G4'::text
                WHEN (EXISTS ( SELECT 1
                   FROM core_vendas_faturamento.blacklist_vendedor_g5 bv5
                  WHERE ((bv5.deleted_at IS NULL) AND (bv5.escopo = ANY (ARRAY['vendas'::text, 'ambos'::text])) AND (public.unaccent((COALESCE(v.nome, ''::character varying))::text) ~* public.unaccent(bv5.termo))))) THEN 'G5'::text
                WHEN ((p.obs_venda ~* 'refat|reaft'::text) OR ((p.codigo_categoria)::text = '1.01.96'::text)) THEN 'G6'::text
                ELSE NULL::text
            END) OVER (PARTITION BY p.codigo_empresa, p.is_track_record, p.numero_pedido ORDER BY COALESCE(p.sequencial, (0)::numeric)),
            CASE
                WHEN bool_or((((p.codigo_categoria)::text = '1.01.96'::text) OR (p.obs_venda ~* 'refat|reaft'::text))) FILTER (WHERE ((p.deleted_at IS NULL) AND ((p.etapa IS NULL) OR (p.etapa <> (0)::numeric)) AND (COALESCE(p.sequencial, (0)::numeric) > (0)::numeric))) OVER (PARTITION BY p.codigo_empresa, p.is_track_record, p.numero_pedido) THEN 'G6'::text
                ELSE NULL::text
            END)
        END AS grupo,
        CASE
            WHEN ((p.numero_contrato)::text ~~* '%SPOT%'::text) THEN 'SPOT'::text
            WHEN ((p.numero_contrato)::text ~~* '%CONTRATO%'::text) THEN 'CONTRATO'::text
            ELSE NULL::text
        END AS tipo_contrato
   FROM ((((pv_src p
     LEFT JOIN core.parceiros par ON ((((par.codigo_parceiro_omie)::text = (p.codigo_cliente)::text) AND (par.codigo_empresa = p.codigo_empresa) AND (par.deleted_at IS NULL))))
     LEFT JOIN core.categorias cat ON ((((cat.codigo_categoria)::text = (p.codigo_categoria)::text) AND (cat.codigo_empresa = p.codigo_empresa) AND (cat.deleted_at IS NULL))))
     LEFT JOIN core_vendas_faturamento.vendedores v ON ((((v.codigo_vendedor_omie)::text = (p.codigo_vendedor_omie)::text) AND (v.codigo_empresa = p.codigo_empresa) AND (v.deleted_at IS NULL))))
     LEFT JOIN LATERAL ( SELECT m.numero_nf,
            m.manifestacao
           FROM core_vendas_faturamento.manifestos m
          WHERE (((m.numero_pedido)::text = (p.numero_pedido)::text) AND (m.codigo_empresa = p.codigo_empresa) AND (m.deleted_at IS NULL))
          ORDER BY m.created_at DESC
         LIMIT 1) mf ON (true));


