        CASE
            WHEN (l.importado_mes_em IS NOT NULL) THEN 'importado'::text
            WHEN (l.numero_pedido IS NOT NULL) THEN 'liberado'::text
            ELSE 'pendente'::text
        END AS status_liberacao,
    l.acompanhamento_qualidade,
    l.liberado_em,
