   FROM (((core_vendas_faturamento.vw_vendas_planilha p
     LEFT JOIN core_vendas_faturamento.pedidos_vendas_liberacao l ON (((l.codigo_empresa = p.codigo_empresa) AND ((l.numero_pedido)::text = (p.pedido_venda)::text))))
     LEFT JOIN core.unidades u ON ((u.id = p.codigo_empresa)))
     LEFT JOIN LATERAL ( SELECT pv.qualidade_acompanha,
            pv.faturar_em_partes
           FROM core_comercial.pedidos_venda pv
          WHERE ((pv.codigo_empresa_omie = p.codigo_empresa) AND (pv.codigo_pedido_omie = p.codigo_pedido_omie) AND (pv.deleted_at IS NULL))
          ORDER BY pv.created_at DESC
         LIMIT 1) hub ON (true))
  WHERE ((p.sequencial = (0)::numeric) AND (NOT p.is_track_record) AND (p.deleted_at IS NULL) AND (p.grupo IS NULL) AND (p.etapa <> (0)::numeric) AND (p.pedido_venda IS NOT NULL) AND (p.data_inclusao >= ( SELECT parametros_vendas.data_inicio_liberacao
           FROM core_vendas_faturamento.parametros_vendas
          WHERE (parametros_vendas.id = 1))) AND ((l.numero_pedido IS NOT NULL) OR ((p.situacao)::text = 'Pendente'::text)));


