    cp.nome AS nome_comprador
   FROM ((((core_vendas_faturamento.requisicoes_compra_eventos e
     LEFT JOIN core_vendas_faturamento.ordens_compra oc ON ((oc.id = e.id_ordem_compra)))
     LEFT JOIN auth.usuarios au ON ((au.id = COALESCE(e.criado_por,
        CASE
            WHEN ((e.tipo)::text = ANY ((ARRAY['oc_criada'::character varying, 'oc_enviada_aprovacao'::character varying])::text[])) THEN oc.created_by
            ELSE NULL::uuid
        END))))
     LEFT JOIN LATERAL ( SELECT a.id_ordem_compra,
            a.codigo_empresa,
            COALESCE(a.criado_por,
                CASE
                    WHEN ((a.tipo)::text = ANY ((ARRAY['oc_criada'::character varying, 'oc_enviada_aprovacao'::character varying])::text[])) THEN ( SELECT o.created_by
                       FROM core_vendas_faturamento.ordens_compra o
                      WHERE (o.id = a.id_ordem_compra))
                    ELSE NULL::uuid
                END) AS autor
           FROM core_vendas_faturamento.requisicoes_compra_eventos a
          WHERE ((a.id_requisicao = e.id_requisicao) AND (((a.tipo)::text = 'em_cotacao'::text) OR (a.id_ordem_compra IS NOT NULL)) AND (ROW(a.registrado_em, a.id) <= ROW(e.registrado_em, e.id)))
          ORDER BY a.registrado_em DESC, a.id DESC
         LIMIT 1) an ON (true))
     LEFT JOIN LATERAL ( SELECT x.id_comprador,
            x.id_funcionario,
            x.nome
           FROM ( SELECT 1 AS prio,
                    c.id AS id_comprador,
                    c.id_funcionario,
                    COALESCE(NULLIF(btrim((c.nome_exibicao)::text), ''::text), (c.nome)::text) AS nome
                   FROM (core_vendas_faturamento.ordens_compra ao
                     JOIN core_vendas_faturamento.compradores c ON ((c.id = ao.id_comprador)))
                  WHERE (ao.id = an.id_ordem_compra)
                UNION ALL
                 SELECT 2,
                    c.id,
                    c.id_funcionario,
                    COALESCE(NULLIF(btrim((c.nome_exibicao)::text), ''::text), (c.nome)::text) AS "coalesce"
                   FROM core_vendas_faturamento.compradores c
                  WHERE (c.id = core_vendas_faturamento.fn_comprador_da_sessao(an.autor, an.codigo_empresa))
                UNION ALL
                 SELECT 3,
                    NULL::uuid AS uuid,
                    u.id_funcionario,
                    auth.fn_nome_usuario(u.id) AS fn_nome_usuario
                   FROM auth.usuarios u
                  WHERE ((u.id = an.autor) AND (u.id_funcionario IS NOT NULL))) x
          ORDER BY x.prio
         LIMIT 1) cp ON (true))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM core_vendas_faturamento.requisicoes_compra rx
          WHERE ((rx.id = e.id_requisicao) AND (rx.deleted_at IS NOT NULL)))));


