    oc.numero_pedido AS numero_ordem_compra,
        CASE
            WHEN (oc.id IS NULL) THEN NULL::character varying
            WHEN (oc.deleted_at IS NOT NULL) THEN 'cancelado'::character varying
            ELSE oc.status
        END AS situacao_ordem_compra,
    ((r.deleted_at IS NULL) AND (r.id_origem IS NULL) AND (r.numero_pedido_venda IS NOT NULL) AND ((r.finalidade)::text = ANY ((ARRAY['pedidos_venda'::character varying, 'recompra'::character varying])::text[])) AND ((r.status)::text <> 'cancelada'::text)) AS visivel_ao_pcp,
    m.alterado_em,
    to_char((m.alterado_em AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'::text) AS alterado_em_utc
   FROM (((core_vendas_faturamento.requisicoes_compra_referencia_mes m
     JOIN core_vendas_faturamento.requisicoes_compra r ON ((r.id = m.id_requisicao)))
     LEFT JOIN core.produtos p ON (((p.codigo_empresa = r.codigo_empresa) AND ((p.codigo_produto)::text = btrim((r.material)::text)) AND (p.deleted_at IS NULL))))
     LEFT JOIN core_vendas_faturamento.ordens_compra oc ON ((oc.id = r.id_ordem_compra)));


